// === REFUSAL STYLE REGISTRY ================================================
// Per-agent refusal style preferences with simple inference fallback.
const _REFUSAL_STYLE = new Map(); // agentId -> 'firm'|'soft'|'sarcastic'|'blunt'

export function setRefusalStyleForAgent(agentId, style) {
  const s = String(style || '').toLowerCase();
  if (!['firm', 'soft', 'sarcastic', 'blunt'].includes(s)) throw new Error('invalid_style');
  _REFUSAL_STYLE.set(String(agentId || 'default'), s);
  return s;
}

export function getRefusalStyleForAgent(agentId) {
  return _REFUSAL_STYLE.get(String(agentId || 'default')) || null;
}

// Prefer explicit style; else infer from personality/trust
export function resolveRefusalStyle({ agentId, personality, trust }) {
  const explicit = getRefusalStyleForAgent(agentId);
  if (explicit) return explicit;
  const p = String(personality || '').toLowerCase();
  if (p.includes('sarcas')) return 'sarcastic';
  if (p.includes('blunt')) return 'blunt';
  if (Number(trust) < 0.15) return 'firm';
  return 'soft';
}

// === LOOPGUARD STYLE TOKEN NUDGE ===========================================
// When a guard fires, we want rerolls in a different style than the last reply.
export function nextLoopStyleToken(lastToken, envList) {
  const list = (envList || process.env.LOOP_GUARD_STYLE_TOKENS || 'descriptive,poetic,terse,inner-thought,cinematic')
    .split(',').map((s) => s.trim()).filter(Boolean);
  if (!list.length) return null;
  if (!lastToken) return list[0];
  const i = list.findIndex((x) => x === lastToken);
  return list[(i >= 0 ? i + 1 : 0) % list.length];
}

// -- Memory injection helper -----------------------------------------------
function formatMemoryPrefix(prefix, style) {
  if (!prefix) return '';
  const s = (style || process.env.MEMORY_INJECT_STYLE || 'ic').toLowerCase();
  if (s === 'system') return `[context recap]\n${prefix}\n`;
  if (s === 'bracket') return `«Memory» ${prefix}\n`;
  return `${prefix}\n`;
}

function applyMemoryPrefix(ctx, text, model) {
  try {
    const prefix = ctx?.vars?.__memory_prefix || '';
    if (!prefix) return text;
    const budget = Number(process.env.MEMORY_INJECT_BUDGET_TOKENS || 120);
    const style  = process.env.MEMORY_INJECT_STYLE || 'ic';
    const rec    = formatMemoryPrefix(prefix, style);
    const candidate = rec + (text || '');
    const n = TokenCounter.estimate(candidate, { model: model || 'o200k_base' });
    if (n <= budget) return candidate;
    let low = 0, high = rec.length, best = '';
    while (low <= high) {
      const mid = (low + high) >> 1;
      const sub = rec.slice(0, mid) + (text || '');
      const m = TokenCounter.estimate(sub, { model: model || 'o200k_base' });
      if (m <= budget) { best = sub; low = mid + 1; } else { high = mid - 1; }
    }
    return best || text;
  } catch { return text; }
}

export const MessageClock = (() => {
  let count = 0;
  let nextId = 1;
  const timers = new Map(); // id -> { at, fn, repeat }

  function runDue() {
    for (const [id, t] of Array.from(timers.entries())) {
      if (t.at <= count) {
        try { t.fn(); } catch (err) { Logger.error('MessageClock task error', err && err.stack || err); }
        if (t.repeat && t.interval > 0) {
          t.at = count + t.interval;
        } else {
          timers.delete(id);
        }
      }
    }
  }

  function tick(n = 1) {
    if (n <= 0) return count;
    count += n;
    runDue();
    return count;
  }

  function setTimeoutCounts(fn, counts = 1) {
    const id = nextId++;
    timers.set(id, { at: count + Math.max(1, counts|0), fn, repeat: false, interval: 0 });
    return id;
  }

  function setIntervalCounts(fn, counts = 1) {
    const id = nextId++;
    const interval = Math.max(1, counts|0);
    timers.set(id, { at: count + interval, fn, repeat: true, interval });
    return id;
  }

  function clear(id) { timers.delete(id); }

  async function sleepCounts(counts = 1, signal) {
    const target = count + Math.max(1, counts|0);
    return new Promise((res, rej) => {
      let cleared = false;
      const id = setIntervalCounts(() => {
        if (count >= target) { clear(id); cleared = true; res(); }
      }, 1);
      if (signal) {
        signal.addEventListener('abort', () => {
          if (!cleared) { clear(id); rej(signal.reason || new Error('aborted')); }
        }, { once: true });
      }
    });
  }

  return {
    tick, // call per incoming/outgoing message
    now: () => count,
    setTimeoutCounts,
    setIntervalCounts,
    clearTimeout: clear,
    clearInterval: clear,
    sleepCounts,
  };
})();
