// Mirror log level to internal logger for consistency (fail fast on error)
(() => {
  try {
    if (!logger || typeof logger.setLevel !== 'function') {
      throw new Error('Logger unavailable or setLevel not a function');
    }
    logger.setLevel(CONFIG.logging.level);
  } catch (err) {
    // Emit clear diagnostic and rethrow to avoid continuing in a partial state
    try { console.error('[fatal] logger.setLevel failed', err && (err.stack || err)); } catch {}
    throw err;
  }
})();
// Optional developer trace for classifier modes
try {
  if (CONFIG.debug?.enabled && Number(CONFIG.debug?.level) > 1) {
    Logger.debug(
      `[URGA DEBUG] Classifier: ${CONFIG.intentClassifier?.classifierMode}, DryRun: ${CONFIG.dryRun?.classifierMode}` 
    );
  }
} catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }

const VALIDATION_CACHE = new WeakMap();

// Early helper definitions: ensure availability before deepFreeze and other callers
const safeLog = (fn) => {
  try {
    fn();
  } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
};
const handleError = (context, err, message = "Unspecified error", level = "WARN", shouldThrow) => {
  try {
    const msg = String(message || "Unspecified error");
    const stack = err?.stack || err;
    if (typeof logger?.log === "function") {
      logger.log(level, msg, stack);
    } else {
      console.error(`[${level}]`, msg, stack);
    }
    if (shouldThrow) {
      throw err;
    }
  } catch (e) {
    try {
      process.stderr.write(`[DEBUG] catch.empty handleError early: ${e?.stack || e}\n`); 
    } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
  }
};
const logAtLevel = (levelIndex, fn) => {
  try {
    const levelMap = { DEBUG: 0, INFO: 1, WARN: 2, ERROR: 3 };
    const effective = String(
      CONFIG?.logging?.level || process?.env?.LOG_LEVEL || "INFO"
    ).toUpperCase();
    const threshold = levelMap[effective] ?? levelMap.INFO;
    if (typeof fn === "function" && levelIndex <= threshold) {
      fn();
    }
  } catch (err) {
    safeLog(() => handleError(undefined, err, "logAtLevel", "DEBUG"));
  }
};

