// ---- Alerting module (budgets + synthetic alerts) ---------------------------
const Alerting = (() => {
  let budgets = {
    respond_ms: { p50: 200, p95: 1000, p99: 3000 },
    handler_latency_ms: { p50: 100, p95: 500, p99: 2000 }
  };
  function setBudgets(b) {
    budgets = { ...budgets, ...b };
  }
  function maybeAlertLatency(ctx, type, ms) {
    try {
      const thr = budgets[type] || budgets.handler_latency_ms;
      if (!thr) return;
      if (ms > thr.p99) {
        Logger.warn('alert_latency_p99_exceeded', { type, ms });
        const M = resolveDep('Metrics', Metrics);
        M?.count?.(ctx || {}, 'alert_latency_p99_exceeded_total', 1, { type });
      } else if (ms > thr.p95) {
        const M = resolveDep('Metrics', Metrics);
        M?.count?.(ctx || {}, 'alert_latency_p95_exceeded_total', 1, { type });
      }
    } catch {}
  }
  function circuitOpened(ctx) {
    try {
      Logger.warn('circuit_open_alert');
      const M = resolveDep('Metrics', Metrics);
      M?.count?.(ctx || {}, 'alert_circuit_open_total', 1);
    } catch {}
  }
  return { setBudgets, maybeAlertLatency, circuitOpened };
})();
