/**
 * Validates and clamps LLM configuration values to ensure sane bounds.
 * Returns a normalized copy instead of mutating input.
 * @param {Object} config - The LLM configuration object to validate
 * @param {number} [config.maxRetries] - Maximum retry attempts (clamped to 1-10, default 3)
 * @param {number} [config.retryBaseMs] - Base retry delay in milliseconds (clamped to 100-5000, default 500)
 * @param {number} [config.rateLimitPerSecond] - Rate limit per second (clamped to 1-100, default 10)
 * @param {number} [config.maxCallsPerMessage] - Max calls per message (clamped to 1-50, default 5)
 * @param {number} [config.maxResponseMs] - Max response timeout in milliseconds (clamped to 500-60000, default 10000)
 * @returns {Object} - Normalized LLM config copy
 */
const validateLLMConfig = (config) => {
  try {
    // Using global clamp helper defined at top-level

    const src = config || {};
    const normalized = {
      maxRetries: clamp(src.maxRetries, 1, 10, 3),
      retryBaseMs: clamp(src.retryBaseMs, 100, 5000, 500),
      rateLimitPerSecond: clamp(src.rateLimitPerSecond, 1, 100, 10),
      maxCallsPerMessage: clamp(src.maxCallsPerMessage, 1, 50, 5),
      maxResponseMs: clamp(src.maxResponseMs, 500, 60000, 10000)
    };
    return normalized;
  } catch (err) {
    handleError(undefined, err, "catch.all");
    return {
      maxRetries: 3,
      retryBaseMs: 500,
      rateLimitPerSecond: 10,
      maxCallsPerMessage: 5,
      maxResponseMs: 10000
    };
  }
};

