// === DEBUG LOGGER ===
/**
 * Logs structured messages with level-based transports (console in dev, file in prod)
 * @param {Context} context - The game context object
 * @param {string} message - Message to log
 * @param {string} [level="DEBUG"] - One of: "DEBUG", "INFO", "WARN", "ERROR"
 * @returns {void}
 */
const logDebug = (context, message, level = "DEBUG", component) => {
  const tsIso = new Date().toISOString();
  const lvl = String(level || "DEBUG").toUpperCase();
  const severity = { DEBUG: 10, INFO: 20, WARN: 30, ERROR: 40 }[lvl] || 10;
  // Optional suppression of INFO in test environments for cleaner CI logs
  const suppressInfoInTests = ((typeof IS_TEST_ENV !== "undefined") && IS_TEST_ENV) && !!(globalThis.CONFIG?.logging?.suppressInfoInTests);
  if (lvl === "INFO" && suppressInfoInTests) {
    return;
  }

  // Log level gate (honors CONFIG.logging.level || ENV LOG_LEVEL)
  const levelMap = { DEBUG: 0, INFO: 1, WARN: 2, ERROR: 3 };
  const effectiveLevel = String((globalThis.CONFIG?.logging?.level) || (globalThis.LOG_LEVEL) || "INFO").toUpperCase();
  const threshold = levelMap[effectiveLevel] ?? levelMap.INFO;
  const current = levelMap[lvl] ?? levelMap.DEBUG;
  if (current < threshold) {
    return;
  }

  const envTag = ((typeof IS_TEST_ENV !== "undefined") && IS_TEST_ENV)
    ? "test"
    : String(process.env.NODE_ENV || "").toLowerCase() === "production"
      ? "prod"
      : "dev";
  const entry = {
    ts: tsIso,
    level: lvl,
    env: envTag,
    component: component !== undefined ? String(component) : undefined,
    message: String(message ?? ""),
    turn: context && typeof context.turn === "number" ? context.turn : undefined,
    id: context && context.id !== undefined ? context.id : undefined,
    sessionId: context && context.sessionId !== undefined ? context.sessionId : undefined,
    sessionName: context && context.sessionName !== undefined ? context.sessionName : undefined
  };

  // Keep an in-memory trail for debugging and tests
  try {
    if (context) {
      context.memory = context.memory || {};
      context.memory.lastDebug ??= [];
      safePush(
        context.memory.lastDebug,
        { ts: (globalThis.MessageClock?.now?.() ?? Date.now()), level: lvl, msg: entry.message }, 
        (globalThis.CONFIG?.contextCaps?.logs ?? 100)
      );
    }
  } catch (err) {
    safeLog(() => handleError(context, err, "logDebug.lastDebug", "DEBUG"));
  }

  // Minimal error telemetry: capture WARN/ERROR into context.errors
  try {
    if ((lvl === "WARN" || lvl === "ERROR") && context) {
      context.errors ??= [];
      safePush(
        context.errors,
        { ts: (globalThis.MessageClock?.now?.() ?? Date.now()), level: lvl, msg: entry.message }, 
        (globalThis.CONFIG?.contextCaps?.logs ?? 100)
      );
    }
  } catch (err) {
    safeLog(() => handleError(context, err, "logDebug.context.errors", "DEBUG"));
  }

  // Environment-based transports
  const isProd = String(process.env.NODE_ENV || "").toLowerCase() === "production";
  const logToConsole = !isProd;
  const logToFile = isProd;

  // Honor DEBUG_MODE for noisy levels, but never swallow WARN/ERROR
  const allowEmit = ((typeof DEBUG_MODE !== "undefined" ? DEBUG_MODE : (globalThis.DEBUG_MODE ?? false)) || severity >= 30); // WARN/ERROR always emit even if DEBUG_MODE=false
  if (!allowEmit) {
    return;
  }

  try {
    if (logToConsole) {
      // Lightweight formatting: only stringify for WARN/ERROR
      const turnStr = entry.turn !== undefined ? ` turn=${entry.turn}` : ""; 
      const idStr = entry.id !== undefined ? ` id=${entry.id}` : ""; 
      const sidStr = entry.sessionId !== undefined ? ` sid=${entry.sessionId}` : ""; 
      const snameStr = entry.sessionName !== undefined ? ` sname=${entry.sessionName}` : ""; 
      const envStr = entry.env ? ` env=${entry.env}` : ""; 
      const compStr = entry.component !== undefined ? ` comp=${entry.component}` : ""; 
      const line =
        lvl === "ERROR" || lvl === "WARN"
          ? JSON.stringify(entry)
          : `${entry.ts} [${entry.level}]${turnStr}${idStr}${sidStr}${snameStr}${envStr}${compStr} ${entry.message}`; 
      const Log = (globalThis.Logger || console);
      if (lvl === "ERROR") {
        Log.error(line);
      } else if (lvl === "WARN") {
        Log.warn(line);
      } else {
        Log.info(line);
      }
    } else if (logToFile) {
      // File logging disabled in bundled build; fall back to console formatting
      const turnStr = entry.turn !== undefined ? ` turn=${entry.turn}` : "";
      const idStr = entry.id !== undefined ? ` id=${entry.id}` : "";
      const sidStr = entry.sessionId !== undefined ? ` sid=${entry.sessionId}` : "";
      const snameStr = entry.sessionName !== undefined ? ` sname=${entry.sessionName}` : "";
      const envStr = entry.env ? ` env=${entry.env}` : "";
      const compStr = entry.component !== undefined ? ` comp=${entry.component}` : "";
      const text =
        lvl === "ERROR" || lvl === "WARN"
          ? JSON.stringify(entry)
          : `${entry.ts} [${entry.level}]${turnStr}${idStr}${sidStr}${snameStr}${envStr}${compStr} ${entry.message}`;
      try {
        (globalThis.Logger || console).info(text);
      } catch (err) {
        try { process.stderr.write(`[DEBUG] logDebug file-fallback failed: ${err?.stack || err}\n`); } catch {}
      }
    }
  } catch (err) {
    try {
      process.stderr.write(`[DEBUG] catch.empty logDebug outer: ${err?.stack || err}\n`); 
    } catch (err) { try { (globalThis.Logger || console).error('Caught error', err); } catch {} }
  }
};

