// Centralized secrets/prereqs checker for LLM providers referenced by env
// Returns an object: { ok: boolean, missing: string[], providers: string[] }
function checkSecrets() {
  try {
    const env = (typeof process !== 'undefined' && process.env) ? process.env : {};
    const names = new Set();
    const add = (v) => { const s = String(v || '').trim().toLowerCase(); if (s) names.add(s); };
    // Collect possible providers from env (base and A/B variants)
    add(env.URGA_PROVIDER); add(env.URGA_PROVIDER_A); add(env.URGA_PROVIDER_B);
    add(env.ECHO_PROVIDER); add(env.ECHO_PROVIDER_A); add(env.ECHO_PROVIDER_B);
    add(env.DREAMS_PROVIDER); add(env.DREAMS_PROVIDER_A); add(env.DREAMS_PROVIDER_B);
    // Fallback: if none specified, do not fail closed
    const providers = Array.from(names);
    const missing = new Set();
    // Base secrets: API keys or hosts per provider
    for (const name of providers) {
      if (!name || name === 'unknown-provider') continue;
      if (name.startsWith('stub')) continue; // test stubs do not require secrets
      if (name === 'openai') { if (!String(env.OPENAI_API_KEY || '').trim()) missing.add('OPENAI_API_KEY'); }
      else if (name === 'openrouter') { if (!String(env.OPENROUTER_API_KEY || '').trim()) missing.add('OPENROUTER_API_KEY'); }
      else if (name === 'together') { if (!String(env.TOGETHER_API_KEY || '').trim()) missing.add('TOGETHER_API_KEY'); }
      else if (name === 'fireworks') { if (!String(env.FIREWORKS_API_KEY || '').trim()) missing.add('FIREWORKS_API_KEY'); }
      else if (name === 'ollama') { if (!String(env.OLLAMA_HOST || '').trim()) missing.add('OLLAMA_HOST'); }
      else if (name === 'vllm') { if (!String(env.VLLM_HOST || '').trim()) missing.add('VLLM_HOST'); }
      else if (name === 'lmstudio') { if (!String(env.LMSTUDIO_HOST || '').trim()) missing.add('LMSTUDIO_HOST'); }
      else if (name === 'koboldcpp') { if (!String(env.KOBOLD_HOST || '').trim()) missing.add('KOBOLD_HOST'); }
      // Unknown names: assume external and do not gate here
    }

    // Optional model-specific assertions (opt-in to avoid breaking default setups)
    const strictModels = String(env.SECRETS_VALIDATE_MODELS || env.STRICT_MODEL_VALIDATION || '').toLowerCase();
    const doModelChecks = strictModels in { '1':1, 'true':1, 'yes':1 };
    if (doModelChecks) {
      const has = (x) => { const s = String(x || '').trim(); return !!s && s.toLowerCase() !== 'unknown-provider'; };
      const variant = String(env.LLM_AB_VARIANT || '').toUpperCase();
      const pick = (engine) => {
        const E = engine === 'echo' ? 'ECHO' : (engine === 'dreams' ? 'DREAMS' : 'URGA');
        if (variant === 'A') {
          if (has(env[`${E}_PROVIDER_A`])) return String(env[`${E}_PROVIDER_A`]).toLowerCase();
        } else if (variant === 'B') {
          if (has(env[`${E}_PROVIDER_B`])) return String(env[`${E}_PROVIDER_B`]).toLowerCase();
        }
        if (has(env[`${E}_PROVIDER`])) return String(env[`${E}_PROVIDER`]).toLowerCase();
        // Fallback precedence mirrors env probes: prefer engine-specific, else others
        if (engine !== 'urga' && has(env.URGA_PROVIDER)) return String(env.URGA_PROVIDER).toLowerCase();
        if (engine !== 'echo' && has(env.ECHO_PROVIDER)) return String(env.ECHO_PROVIDER).toLowerCase();
        if (engine !== 'dreams' && has(env.DREAMS_PROVIDER)) return String(env.DREAMS_PROVIDER).toLowerCase();
        return '';
      };
      const modelKeysFor = (engine, provider) => {
        const E = engine === 'echo' ? 'ECHO' : (engine === 'dreams' ? 'DREAMS' : 'URGA');
        const P = String(provider || '').toUpperCase();
        const keys = [];
        if (!P) return keys;
        if (P === 'OPENAI') {
          // Support both ECHO_OPENAI_MODEL and OPENAI_ECHO_MODEL forms
          keys.push(`${E}_OPENAI_MODEL`, `${E}_OPENAI_MODEL_A`, `${E}_OPENAI_MODEL_B`);
          keys.push(`OPENAI_${E}_MODEL`, `OPENAI_${E}_MODEL_A`, `OPENAI_${E}_MODEL_B`);
        } else if (P === 'KOBOLDCPP') {
          // KoboldCPP does not use per-engine model envs; skip checks
        } else {
          keys.push(`${E}_${P}_MODEL`, `${E}_${P}_MODEL_A`, `${E}_${P}_MODEL_B`);
        }
        return keys;
      };
      const engines = ['echo','dreams','urga'];
      for (const eng of engines) {
        const prov = pick(eng);
        if (!prov || prov.startsWith('stub') || prov === 'unknown-provider') continue;
        const keys = modelKeysFor(eng, prov);
        if (keys.length) {
          const anySet = keys.some((k) => has(env[k]));
          if (!anySet) {
            for (const k of keys) missing.add(k);
          }
        }
      }
    }

    const out = { ok: missing.size === 0, missing: Array.from(missing), providers };
    try { const M = resolveDep('Metrics', Metrics); M?.count?.({}, 'secrets_ok', out.ok ? 1 : 0); } catch {}
    return out;
  } catch { return { ok: true, missing: [], providers: [] }; }
}

// === Tool Registry & Runner ===
// Adapter: run a tool spec inside the isolated worker with FS/NET allowlists
async function runToolInIsolation(context, spec) {
  const pathMod = await import('node:path');
  const childMod = await import('node:child_process');
  const workerPath = pathMod.join(process.cwd(), 'scripts', 'tool_isolation_worker.mjs');
  const envMode = String(process.env.NODE_ENV || 'dev').toLowerCase();
  const defaultMem = envMode === 'production' ? 128 : (envMode === 'test' ? 64 : 96);
  const defaultTimeout = envMode === 'production' ? 5000 : (envMode === 'test' ? 2000 : 3000);
  const memMb = Math.max(32, Number(process.env.TOOL_MEMORY_MB || defaultMem));
  const timeoutMs = Math.max(500, Number((spec?.toolTimeoutMs != null ? spec.toolTimeoutMs : process.env.TOOL_TIMEOUT_MS) || defaultTimeout));
  const op = String(spec?.op || 'mark');
  const env = {
    ...process.env,
    TOOL_OP: op,
    TOOL_FAIL_CLOSED: String(spec?.failClosed ?? process.env.TOOL_FAIL_CLOSED ?? '1'),
    TOOL_FS_ALLOWLIST: Array.isArray(spec?.fsAllowlist) ? JSON.stringify(spec.fsAllowlist) : String(process.env.TOOL_FS_ALLOWLIST || ''),
    TOOL_NET_ALLOWLIST: Array.isArray(spec?.netAllowlist) ? JSON.stringify(spec.netAllowlist) : String(process.env.TOOL_NET_ALLOWLIST || ''),
  };
  const args = spec?.args || {};
  // Map args to worker env by op
  if (op === 'fetch_url') env.TOOL_FETCH_URL = String(args.url || args.href || '');
  else if (op === 'post_json') {
    env.TOOL_POST_URL = String(args.url || args.href || '');
    const body = args.body;
    env.TOOL_POST_BODY_JSON = typeof body === 'string' ? body : JSON.stringify(body ?? {});
  } else if (op === 'read_file') env.TOOL_READ_PATH = String(args.path || '');
  else if (op === 'write_file') {
    env.TOOL_WRITE_PATH = String(args.path || '');
    const b64 = args.content_b64 ?? (typeof args.content === 'string' ? Buffer.from(args.content, 'utf8').toString('base64') : '');
    env.TOOL_WRITE_CONTENT_B64 = String(b64 || '');
  } else if (op === 'read_json') env.TOOL_READ_JSON_PATH = String(args.path || '');
  else if (op === 'net_probe') env.TOOL_NET_PROBE = String(args.url || args.href || '');
  // Per-request net timeout override
  if (spec?.netTimeoutMs != null) env.TOOL_NET_TIMEOUT_MS = String(spec.netTimeoutMs);
  // Protect against missing required envs
  const requiredMap = {
    'mark': ['TOOL_ID','TOOL_DIR'],
    'fetch_url': ['TOOL_FETCH_URL'],
    'post_json': ['TOOL_POST_URL'],
    'read_file': ['TOOL_READ_PATH'],
    'write_file': ['TOOL_WRITE_PATH'],
    'read_json': ['TOOL_READ_JSON_PATH'],
    'net_probe': ['TOOL_NET_PROBE']
  };
  // Allow caller to set these if needed
  if (op === 'mark') {
    env.TOOL_ID = String(args.id || '');
    env.TOOL_DIR = String(args.dir || '');
  }
  const child = childMod.spawn(process.execPath, [
    `--max-old-space-size=${memMb}`,
    workerPath
  ], { stdio: ['ignore','pipe','pipe'], env });
  let stdout = '';
  let stderr = '';
  child.stdout.on('data', (d) => { stdout += d.toString(); });
  child.stderr.on('data', (d) => { stderr += d.toString(); });
  const res = await new Promise((resolve) => {
    const to = setTimeout(() => { try { child.kill('SIGKILL'); } catch {} ; resolve({ code: -1, stdout, stderr, timeout: true }); }, timeoutMs);
    child.on('exit', (code) => { clearTimeout(to); resolve({ code, stdout, stderr, timeout: false }); });
  });
  let payload = {};
  try { payload = JSON.parse(String(res.stdout || '{}')); } catch {}
  // Optional one retry for retryable network errors
  if (res.code !== 0 && payload && payload.retryable && !spec?.noRetry) {
    const res2 = await new Promise((resolve) => {
      const c2 = childMod.spawn(process.execPath, [`--max-old-space-size=${memMb}`, workerPath], { stdio: ['ignore','pipe','pipe'], env });
      let so = '';
      let se = '';
      c2.stdout.on('data', (d) => { so += d.toString(); });
      c2.stderr.on('data', (d) => { se += d.toString(); });
      const to2 = setTimeout(() => { try { c2.kill('SIGKILL'); } catch {} ; resolve({ code: -1, stdout: so, stderr: se, timeout: true }); }, timeoutMs);
      c2.on('exit', (code) => { clearTimeout(to2); resolve({ code, stdout: so, stderr: se, timeout: false }); });
    });
    try { payload = JSON.parse(String(res2.stdout || '{}')); } catch {}
    return Object.assign({ ok: res2.code === 0 }, payload, { exit_code: res2.code, stderr: res2.stderr });
  }
  return Object.assign({ ok: res.code === 0 }, payload, { exit_code: res.code, stderr: res.stderr });
}
const _ToolRegistry = (() => {
  const byName = new Map();
  const validators = new Map();
  const rateLimiters = new Map();
  const simpleValidate = (schema, input) => {
    try {
      if (!schema || typeof schema !== 'object') return { ok: true };
      const required = Array.isArray(schema.required) ? schema.required : [];
      for (const k of required) { if (!(k in input)) return { ok: false, error: `missing ${k}` }; }
      if (schema.properties && typeof schema.properties === 'object') {
        for (const [k, def] of Object.entries(schema.properties)) {
          if (input[k] == null) continue;
          const t = typeof input[k];
          if (def.type && def.type !== t && !(def.type === 'array' && Array.isArray(input[k]))) {
            return { ok: false, error: `type mismatch for ${k}: expected ${def.type}, got ${t}` };
          }
        }
      }
      return { ok: true };
    } catch (err) { return { ok: false, error: String(err && err.message || err) }; }
  };
  const register = (tool) => {
    const name = String(tool?.name || '').trim(); if (!name) return false;
    const description = String(tool?.description || '');
    const input_json_schema = tool?.input_json_schema || {};
    const handler = tool?.handler;
    const budget_ms = Number(tool?.budget_ms ?? 1000);
    const sandbox = !!tool?.sandbox;
    byName.set(name, { name, description, input_json_schema, handler, budget_ms, sandbox });
    validators.set(name, (input) => simpleValidate(input_json_schema, input));
    return true;
  };
  const allow = async (ctx, name, key = '') => {
    rateLimiters.set(name, rateLimiters.get(name) || createSharedRateLimiter({ limit: 3, windowMs: 1000 }));
    try { return await rateLimiters.get(name).allow(key || (ctx?.vars?.tenant || 'tenant')); } catch { return { ok: false, rate_limited: true }; }
  };
  const run = async (ctx, name, input, { invocation_id = null } = {}) => {
    const t = byName.get(name); if (!t || typeof t.handler !== 'function') return { ok: false, error: 'unknown_tool' };
    const valid = validators.get(name)?.(input || {});
    if (!valid?.ok) return { ok: false, error: 'schema_invalid', detail: valid?.error || '' };
    const gate = await allow(ctx, name, String(invocation_id || name));
    if (!gate?.ok) return { ok: false, rate_limited: true };
    ctx.memory ??= {}; ctx.memory.toolResultsCache ??= new Map();
    if (invocation_id && ctx.memory.toolResultsCache.has(invocation_id)) {
      return Object.assign({ ok: true, idempotent: true }, ctx.memory.toolResultsCache.get(invocation_id));
    }
    const start = MessageClock.now();
    let result;
    const exec = async () => t.handler(input, ctx);
    try {
      result = await withTimeout(exec(), t.budget_ms, { ok: false, error: 'timeout' });
    } catch (err) {
      result = { ok: false, error: String(err && err.message || err) };
    }
    // If tool is marked sandboxed and handler returned a worker spec, run it in isolation
    if (t.sandbox && result && typeof result === 'object' && (result.op || result.TOOL_OP)) {
      const spec = {
        op: String(result.op || result.TOOL_OP),
        args: Object.assign({}, result.args || {}),
        fsAllowlist: Array.isArray(result.fsAllowlist) ? result.fsAllowlist : undefined,
        netAllowlist: Array.isArray(result.netAllowlist) ? result.netAllowlist : undefined,
        failClosed: result.failClosed,
        toolTimeoutMs: Number(result.toolTimeoutMs ?? t.budget_ms),
        netTimeoutMs: result.netTimeoutMs != null ? Number(result.netTimeoutMs) : undefined,
        noRetry: !!result.noRetry
      };
      try {
        result = await runToolInIsolation(ctx, spec);
      } catch (err) {
        result = { ok: false, error: String(err && err.message || err) };
      }
    }
    const out = (result && typeof result === 'object') ? result : { ok: true, output: result };
    const payload = { tool: name, ok: !!out.ok, latency_ms: MessageClock.now() - start };
    try { ensureCoreDeps(ctx).Metrics.log(ctx, 'tool_call', payload); } catch {}
    try { ctx.io?.events?.emit && ctx.io.events.emit('tool.progress', payload); } catch {}
    if (invocation_id) ctx.memory.toolResultsCache.set(invocation_id, out);
    return out;
  };
  return { register, run };
})();

// === Memory Store (short/mid/long-term) ===
const ConversationMemory = (() => {
  const shortWindow = (ctx, tokenBudget = 2048) => {
    const conv = ctx.conversation?.history || [];
    let acc = [];
    for (let i = conv.length - 1; i >= 0; i--) {
      const m = conv[i];
      const segs = [].concat(m.content || []);
      for (let j = segs.length - 1; j >= 0; j--) {
        const s = String(segs[j] || '');
        acc.unshift(s);
        const tok = TokenCounter.estimate(acc.join('\n'));
        if (tok > tokenBudget) { acc.shift(); return acc.join('\n'); }
      }
    }
    return acc.join('\n');
  };
  const midState = (ctx) => {
    ctx.memory ??= {}; ctx.memory.state ??= { facts: {}, goals: {}, prefs: {}, ttl_ms: Number(CONFIG?.memory?.mid?.ttl_ms ?? 3600000), updated_at: MessageClock.now() };
    return ctx.memory.state;
  };
  const setMidState = (ctx, patch) => { const st = midState(ctx); Object.assign(st, patch || {}); st.updated_at = MessageClock.now(); return st; };
  // Simple in-memory vector store
  const vsEnsure = (ctx) => { ctx.memory ??= {}; ctx.memory.vectors ??= []; return ctx.memory.vectors; };
  const embed = (text) => {
    const words = String(text || '').toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
    const bag = new Map(); for (const w of words) bag.set(w, (bag.get(w) || 0) + 1);
    return bag;
  };
  const cosine = (a, b) => {
    const keys = new Set([...a.keys(), ...b.keys()]);
    let dot = 0, na = 0, nb = 0;
    for (const k of keys) { const va = a.get(k) || 0; const vb = b.get(k) || 0; dot += va * vb; na += va * va; nb += vb * vb; }
    const denom = Math.sqrt(na) * Math.sqrt(nb); return denom > 0 ? dot / denom : 0;
  };
  const ingest = (ctx, doc) => {
    const v = vsEnsure(ctx);
    const id = String(doc.id || 'doc_' + Math.random().toString(36).slice(2));
    const vec = embed(String(doc.text || ''));
    v.push({ id, tenant: String(doc.tenant || ctx?.vars?.tenant || 'tenant'), vec, text: String(doc.text || ''), ts: MessageClock.now(), freshness: Number(doc.freshness || 0) });
    return id;
  };
  const retrieve = (ctx, query, { max_k = 5, recency_bias = 0.1, tenant = null } = {}) => {
    const v = vsEnsure(ctx);
    const q = embed(String(query || ''));
    const now = MessageClock.now();
    const rows = [];
    for (const d of v) {
      if (tenant && String(d.tenant) !== String(tenant)) continue;
      const sim = cosine(q, d.vec);
      const rec = Math.max(0, Math.min(1, recency_bias)) * Math.max(0, 1 - Math.min(1, (now - d.ts) / (7 * 24 * 60 * 60 * 1000)));
      rows.push({ id: d.id, score: sim + rec, text: d.text });
    }
    rows.sort((a, b) => b.score - a.score);
    return rows.slice(0, max_k);
  };
  const cite = (items) => items.map((r, i) => `[${i + 1}](${r.id})`).join(' ');
  return { shortWindow, midState, setMidState, ingest, retrieve, cite };
})();

// === Persona Manager ===
const PersonaManager = (() => {
  const packs = new Map();
  const register = (name, data) => { packs.set(String(name), Object.assign({ persona_v: 1, prompt_v: 1 }, data || {})); };
  const apply = (ctx, name) => { const p = packs.get(String(name)) || {}; ctx.persona = p; try { ensureCoreDeps(ctx).Metrics.log(ctx, 'persona.apply', { name, persona_v: p.persona_v, prompt_v: p.prompt_v }); } catch {} return p; };
  const get = (name) => packs.get(String(name)) || null;
  return { register, apply, get };
})();

// === Evaluation Harness ===
const EvalHarness = (() => {
  const runPromptDeterminism = (ctx, turn) => {
    const h1 = ConversationContract.promptHashForTurn(ctx, turn);
    const h2 = ConversationContract.promptHashForTurn(ctx, turn);
    const ok = h1 === h2;
    try { ensureCoreDeps(ctx).Metrics.log(ctx, 'eval.prompt_determinism', { ok }); } catch {}
    return { ok, hash: h1 };
  };
  const runFunctionSchemaValidation = async (ctx) => {
    const out = await _ToolRegistry.run(ctx, '__nonexistent__', {});
    return { ok: out.ok === false };
  };
  const runStreamingContractTest = async (ctx) => {
    let acc = '';
    ctx.io.events.on('stream.delta', (p) => { acc += String(p?.text || ''); });
    const adapter = new ModelAdapter(ctx);
    const final = await adapter.generate({ prompt: 'test stream' }, { stream: true });
    const ok = acc === final && Buffer.from(acc, 'utf8').toString('utf8') === acc;
    try { ensureCoreDeps(ctx).Metrics.log(ctx, 'eval.streaming_contract', { ok }); } catch {}
    return { ok };
  };
  const runTokenBudgetGuard = (ctx) => {
    const huge = new Array(10000).fill('x').join(' ');
    const trimmed = TokenCounter.trim(huge, 256);
    const ok = TokenCounter.estimate(trimmed) <= 256;
    try { ensureCoreDeps(ctx).Metrics.log(ctx, 'eval.token_budget_guard', { ok }); } catch {}
    return { ok };
  };
  const runPersonaDriftTest = (ctx, seed = 'hello') => {
    PersonaManager.register('p1', { name: 'A', system: 'be short', prompt_v: 1, persona_v: 1 });
    PersonaManager.register('p2', { name: 'B', system: 'be long', prompt_v: 2, persona_v: 1 });
    const c1 = ConversationContract.appendMessage(ctx, { role: 'user', content: seed, turn: 1 });
    PersonaManager.apply(ctx, 'p1'); const h1 = ConversationContract.promptHashForTurn(ctx, 1);
    PersonaManager.apply(ctx, 'p2'); const h2 = ConversationContract.promptHashForTurn(ctx, 1);
    const ok = h1 !== h2; try { ensureCoreDeps(ctx).Metrics.log(ctx, 'eval.persona_drift', { ok }); } catch {}
    return { ok };
  };
  return { runPromptDeterminism, runFunctionSchemaValidation, runStreamingContractTest, runTokenBudgetGuard, runPersonaDriftTest };
})();

// === Observability Helpers ===
const AIMetrics = {
  tokens(ctx, dir, n) { try { ensureCoreDeps(ctx).Metrics.log(ctx, 'tokens_' + String(dir), { count: Number(n || 0) }); } catch {} },
  cost(ctx, usd) { try { ensureCoreDeps(ctx).Metrics.log(ctx, 'cost_usd', { usd: Number(usd || 0) }); } catch {} },
  toolDist(ctx, name) { try { ensureCoreDeps(ctx).Metrics.log(ctx, 'tool_calls_total', { tool: String(name || '') }); } catch {} }
};

/**
 * Runs tasks concurrently with error aggregation and optional failure handling
 * @param {Context} context - The game context object
 * @param {Array<function|*>} [tasks=[]] - Array of functions || values to execute
 * @param {Object} [options={}] - Configuration options
 * @param {string} [options.label='concurrent'] - Label for logging purposes
 * @param {boolean} [options.critical=false] - Whether to throw on any failures
 * @param {function|null} [options.onError=null] - Error callback function
 * @returns {Promise<Array>} Promise resolving to array of results (null for failed tasks)
 * @throws {Error} - Throws if critical=true and any tasks fail
 */
async function auditAll(
  context,
  tasks = [],
  { label = "concurrent", critical = false, onError = null } = {}
) {
  const fns = tasks.map((t) => (typeof t === "function" ? t : () => t));

  // Serial mode: execute tasks in order, awaiting only when needed
  if (label === "serial") {
    const out = new Array(fns.length);
    let failureCount = 0;
    for (let i = 0; i < fns.length; i++) {
      try {
        const res = fns[i]();
        out[i] = res && typeof res.then === "function" ? await res : res;
      } catch (err) {
        failureCount++;
        out[i] = null;
        const lvlForItem = critical || process?.env?.URGA_AUDIT_STRICT === "1" ? "ERROR" : "WARN";
        try {
          logDebug(context, String(err?.message || err || "Unknown error"), lvlForItem);
        } catch (logErr) {
          handleError(context, logErr, `auditAll.logDebug.${label}`);
        }
        try {
          if (typeof onError === "function") {
            onError({ context, label, index: i, error: err, task: tasks[i] });
          }
        } catch (cbErr) {
          handleError(context, cbErr, `auditAll.onError.${label}`);
        }
        if (critical) {
          throw new Error(`${label} failed ${failureCount}/${fns.length}`); 
        }
      }
    }
    if (failureCount) {
      const alertThreshold = toNum(CONFIG?.audit?.failureAlertThreshold, 3);
      const strict = process?.env?.URGA_AUDIT_STRICT === "1";
      const level = strict && failureCount >= alertThreshold ? "ERROR" : "WARN";
      try {
        logDebug(context, `[${label}] ${failureCount} task(s) failed`, level);
      } catch (err) {
        handleError(context, err, `auditAll.summary.${label}`);
      }
      if (strict && failureCount >= alertThreshold && !critical) {
        try {
          handleError(
            context,
            new Error(`${label} exceeded failure threshold: ${failureCount}/${fns.length}`), 
            `auditAll.threshold.${label}`
          );
        } catch (err) {
          try {
            process.stderr.write(
              `[DEBUG] auditAll.threshold.${label}: ${String((err && err.message) || err)}\n` 
            );
          } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
        }
      }
    }
    return out;
  }

  // Concurrent mode: avoid extra Promise chaining for sync tasks
  const scheduled = fns.map((fn, i) => {
    // Wrap each task with profiling
    return profileAsync(
      context,
      `audit.${label}task.${i}`,
      async () => {
        try {
          return fn(); // may return value || promise; sync errors caught below
        } catch (err) {
          // propagate rejection to be handled by allSettled
          throw err;
        }
      },
      { label, index: i }
    );
  });

  const batchStart = MessageClock.now();
  const results = await Promise.allSettled(scheduled);
  const batchMs = MessageClock.now() - batchStart;
  try {
    ensureCoreDeps(context).Metrics.log(context, "profile.batch", {
      name: `audit.${label}`,
      ms: batchMs,
      count: results.length
    });
  } catch (err) {
    safeLog(() => handleError(context, err, "auditAll.profile.batch", "DEBUG"));
  }

  let failureCount = 0;
  results.forEach((r, i) => {
    if (r.status === "rejected") {
      failureCount++;
      {
        const lvlForItem = critical || process?.env?.URGA_AUDIT_STRICT === "1" ? "ERROR" : "WARN";
        try {
          logDebug(context, String(r.reason?.message || r.reason || "Unknown error"), lvlForItem);
        } catch (err) {
          handleError(context, err, `auditAll.logDebug.${label}`);
        }
      }
      try {
        if (typeof onError === "function") {
          onError({
            context,
            label,
            index: i,
            error: r.reason,
            task: tasks[i]
          });
        }
      } catch (err) {
        handleError(context, err, `auditAll.onError.${label}`);
      }
    }
  });
  if (failureCount) {
    const alertThreshold = Number(CONFIG?.audit?.failureAlertThreshold ?? 3);
    const strict = process?.env?.URGA_AUDIT_STRICT === "1";
    const level = strict && failureCount >= alertThreshold ? "ERROR" : "WARN";
    try {
      logDebug(context, `[${label}] ${failureCount} task(s) failed`, level);
    } catch (err) {
      handleError(context, err, `auditAll.summary.${label}`);
    }
    if (critical || (strict && failureCount >= alertThreshold)) {
      throw new Error(`${label} failed ${failureCount}/${results.length}`); 
    }
  }
  return results.map((r) => (r.status === "fulfilled" ? r.value : null));
}

// Numeric helper toNum moved earlier

// === RNG INITIALIZATION GUARD ===
// Helper: derive combined reseed key from messageCount + turn using weighted prime-mix
// Rationale:
// - Historically, 31 is a classic small prime used in polynomial hashing (e.g., Java's String#hashCode).
//   It keeps overflow behavior predictable and yields decent distribution for short sequences.
// - To reduce collision likelihood across varied (msgCount, turn) pairs, we switch to a 32-bit
//   multiplicative mix using FNV-1a prime (16777619) via Math.imul. This preserves speed in JS.
// - `CONFIG.rng.reseedWeight` remains overrideable; defaults to 16777619 when not set.
const getReseedKey = (context) => {
  const msgCount = toNum(context?.memory?.messageCount) >>> 0;
  const turn = toNum(context?.turn ?? context?.memory?.turn) >>> 0;
  const fnvPrime = 16777619 >>> 0; // FNV-1a prime
  const weight = toNum(CONFIG?.rng?.reseedWeight, fnvPrime) >>> 0;
  // FNV-1a style mixing for two integers (msgCount, turn)
  let h = 2166136261 >>> 0; // FNV offset basis
  h ^= msgCount;
  h = Math.imul(h, weight);
  h ^= turn;
  h = Math.imul(h, weight);
  return Number(h >>> 0);
};
// Secure seed generator: prefers crypto random, falls back gracefully
const getSecureSeed = () => {
  try {
    const buf = crypto.randomBytes(4);
    const val = buf.readUInt32BE(0);
    return val > 0 ? val : MessageClock.now();
  } catch (err) {
    try {
      if (globalThis.crypto && typeof globalThis.crypto.getRandomValues === "function") {
        const arr = new Uint32Array(1);
        globalThis.crypto.getRandomValues(arr);
        return arr[0] > 0 ? arr[0] : MessageClock.now();
      }
    } catch (err) {
      try {
        process.stderr.write(`[DEBUG] catch.empty getSecureSeed: ${err?.stack || err}\n`); 
      } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
    }
    return MessageClock.now();
  }
};
// Helper: choose seed based on deterministic flag and base seed
const chooseSeed = (context, deterministic) => {
  const baseSeed = Number(context?.memory?.randomSeed ?? getSecureSeed());
  return deterministic ? Math.max(1, getReseedKey(context)) : baseSeed;
};
/**
 * Ensures context has a valid seeded RNG function
 * @param {Context} context - Game context to initialize RNG for
 * @returns {Function} The RNG function
 */
const ensureRNG = (context, opts = {}) => {
  try {
    const reseedFlag = !!(
      opts?.reseedWithMessageCount ||
      context?.flags?.reseedRNGWithMessageCount ||
      context?.flags?.deterministicReplay
    );
    const baseSeed = Number(context?.memory?.randomSeed ?? getSecureSeed());
    ensureDeps(context);
    const RNGimpl = getDep(context, "RNG", RNG);
    const reseedKey = getReseedKey(context);
    const lastReseedKey = Number(context.memory?.__rngLastReseedKey ?? -1);
    const shouldReseedThisStep = reseedFlag && reseedKey !== lastReseedKey;
    const msgCount = toNum(context?.memory?.messageCount);
    if (context.rng == null || typeof context.rng !== "function") {
      const seed = chooseSeed(context, shouldReseedThisStep);
      context.rng = RNGimpl.seeded(seed);
      context.memory ??= {};
      // Initialize event bus and recent lines map defaults
      context.io ??= {};
      context.io.events ??=
        typeof EventEmitter !== "undefined" ? new EventEmitter() : { emit: () => {} };
      context._recentLines ??= new RecentLinesMap();
      context.memory.randomSeed ??= baseSeed;
      if (shouldReseedThisStep) {
        context.memory.__rngLastReseedKey = reseedKey;
      }
    } else if (shouldReseedThisStep) {
      const seed = chooseSeed(context, true);
      context.rng = RNGimpl.seeded(seed);
      context.memory.__rngLastReseedKey = reseedKey;
    }
    if (typeof context.rng !== "function") {
      throw new Error("Invalid RNG function");
    }
    const sample = Number(context.rng());
    if (!Number.isFinite(sample) || sample < 0 || sample >= 1) {
      logDebug(context, `[RNG RESEED] due to invalid sample (sample=${sample})`, "ERROR");
      const baseSeed = Number(context.memory?.randomSeed ?? getSecureSeed());
      const seed = shouldReseedThisStep
        ? Math.max(1, Math.abs((baseSeed ^ Math.imul(msgCount + 1, 0x9e3779b1)) % 2147483647))
        : baseSeed;
      context.rng = RNGimpl.seeded(seed);
      context.memory ??= {};
      context.memory.randomSeed ??= baseSeed;
      if (shouldReseedThisStep) {
        context.memory.__rngLastReseedMsg = msgCount;
      }
      logDebug(
        context,
        `RNG reseeded due to invalid sample [msg=${toNum(context?.memory?.messageCount)}, turn=${toNum(context?.turn)}, seed=${seed}]`, 
        "WARN"
      );
    }
  } catch (err) {
    const baseSeed = Number(context.memory?.randomSeed ?? getSecureSeed());
    const msgCount = toNum(context?.memory?.messageCount);
    const seed = Math.max(
      1,
      Math.abs((baseSeed ^ Math.imul(msgCount + 1, 0x9e3779b1)) % 2147483647)
    );
    context.memory ??= {};
    context.memory.randomSeed = baseSeed;
    context.memory.__rngLastReseedMsg = msgCount;
    ensureDeps(context);
    const RNGimpl = getDep(context, "RNG", RNG);
    context.rng = RNGimpl.seeded(seed);
    logDebug(
      context,
      `RNG fallback reseed [msg=${toNum(context?.memory?.messageCount)}, turn=${toNum(context?.turn)}, seed=${seed}]: ${err && err.message ? err.message : String(err)}`, 
      "ERROR"
    );
  }
  return context.rng;
};

// === UTILITIES ===
/**
 * Caps an array to a maximum length by trimming from the front
 * @param {Array} arr - Target array to cap
 * @param {number} [max=100] - Maximum allowed length
 * @returns {void}
 */
const capArray = (arr, max = 100) => {
  if (!Array.isArray(arr)) {
    return;
  }
  if (arr.length > max) {
    arr.splice(0, arr.length - max);
  }
};

// Defensive push that maintains a hard cap without intermediate overshoot
/**
 * Pushes an item onto an array while enforcing a maximum length
 * @param {Array} arr - Target array to push into
 * @param {*} item - Item to push
 * @param {number} [max=100] - Maximum allowed length
 * @returns {void}
 */
const safePush = (arr, item, max = 100) => {
  if (!Array.isArray(arr)) {
    return;
  }
  const cap = Number(max) || 0;
  if (cap <= 0) {
    return;
  }
  // Pre-trim to avoid temporary overshoot under concurrent pushes
  while (arr.length >= cap) {
    arr.shift();
  }
  arr.push(item);
  // Safety trim in case concurrent operations overshot between checks
  if (arr.length > cap) {
    arr.splice(0, arr.length - cap);
  }
};

/**
 * Pushes multiple items onto an array while enforcing a maximum length
 * @param {Array} arr - Target array to push into
 * @param {Array|*} [items=[]] - Items || single item to push
 * @param {number} [max=100] - Maximum allowed length
 * @returns {void}
 */
const safePushMany = (arr, items = [], max = 100) => {
  if (!Array.isArray(arr)) {
    return;
  }
  const list = Array.isArray(items) ? items : [items];
  const cap = Number(max) || 0;
  if (cap <= 0) {
    return;
  }
  // Pre-trim to make room for incoming items without overshoot
  const needRoom = Math.max(0, arr.length + list.length - cap);
  if (needRoom > 0) {
    arr.splice(0, needRoom);
  }
  for (const it of list) {
    arr.push(it);
  }
  // Final trim to cap in case of interleaving operations
  if (arr.length > cap) {
    arr.splice(0, arr.length - cap);
  }
};

// === Memory Pressure & Circuit Breaker ===
const computeMemoryPressure = (context) => {
  try {
    const stats = typeof v8.getHeapStatistics === "function" ? v8.getHeapStatistics() : {};
    const mu = typeof process.memoryUsage === "function" ? process.memoryUsage() : {};
    let limit = toNum(stats?.heap_size_limit);
    const heapUsed = toNum(mu?.heapUsed);
    if (!limit || limit <= 0) {
      const rss = toNum(mu?.rss);
      limit = rss > 0 ? rss : 1024 * 1024 * 1024; // 1GB fallback
    }
    const pressure = limit > 0 ? Math.min(1, heapUsed / limit) : 0;
    try {
      context.memoryPressure = pressure;
      context.vars ??= {};
      context.vars.__lastMemoryPressure = {
        heapUsed,
        heapLimit: limit,
        rss: toNum(mu?.rss),
        external: toNum(mu?.external),
        arrayBuffers: toNum(mu?.arrayBuffers)
      };
    } catch (err) {
      try {
        process.stderr.write(
          `[DEBUG] catch.empty computeMemoryPressure vars update: ${err?.stack || err}\n` 
        );
      } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
    }
    return pressure;
  } catch (err) {
    try {
      handleError(context, err, "computeMemoryPressure", "WARN");
    } catch (e2) {
      try {
        process.stderr.write(
          `[DEBUG] catch.empty computeMemoryPressure handleError: ${e2?.stack || e2}\n` 
        );
      } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
    }
    return toNum(context?.memoryPressure);
  }
};

// Per-type memory pressure helper used for adaptive caps
const getTypePressure = (context) => {
  const C = CONFIG?.contextCaps || {};
  const m = context?.memory || {};
  const ratio = (arr, cap) => {
    const len = Array.isArray(arr) ? arr.length : 0;
    const c = Number(cap) || 0;
    return c > 0 ? len / c : 0;
  };
  return {
    interactionHistory: ratio(m?.interactionHistory, C?.interactionHistory),
    dreamHistory: ratio(m?.dreamHistory, C?.dreamHistory),
    playerMemory: ratio(m?.playerMemory, C?.playerMemory),
    betrayalJournal: ratio(m?.betrayalJournal, C?.betrayalJournal),
    echoHistory: ratio(m?.echoHistory, C?.echoHistory),
    hallucinationEvents: ratio(m?.hallucinationEvents, C?.hallucinationEvents),
    corruptionTraits: ratio(m?.corruptionTraits, C?.corruptionTraits),
    worldEvents: ratio(m?.worldEvents, C?.worldEvents),
    telemetryMetrics: ratio(m?.telemetry?.metrics, C?.telemetryMetrics),
    narrativeTraces: ratio(m?.narrativeTraces, C?.narrativeTraces),
    prophecies: ratio(m?.prophecies, C?.prophecies)
  };
};

// Record per-type prune deltas for validation and tuning
const recordPruneDelta = (context, key, before, after, phase = "prune") => {
  try {
    const removed = Math.max(0, toNum(before) - toNum(after));
    if (removed <= 0) {
      return;
    }
    context.vars ??= {};
    context.vars.pruneCounters ??= {};
    const ctr = (context.vars.pruneCounters[key] ??= {
      totalRemoved: 0,
      samples: 0
    });
    ctr.totalRemoved += removed;
    ctr.samples += 1;
    ctr.lastPhase = phase;
    // Emit lightweight event for external observers
    context.io?.events?.emit &&
      context.io.events.emit("memory.prune.delta", {
        key,
        before,
        after,
        removed,
        phase
      });
    // Log metric defensively
    try {
      ensureCoreDeps(context).Metrics.log(context, "memory.prune_delta", {
        key,
        before,
        after,
        removed,
        phase
      });
    } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
  } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
};

const capArrayWithDelta = (arr, cap, context, key, phase) => {
  const before = Array.isArray(arr) ? arr.length : 0;
  capArray(arr, cap);
  const after = Array.isArray(arr) ? arr.length : 0;
  recordPruneDelta(context, key, before, after, phase);
};

const emergencyPrune = (context) => {
  try {
    ensureMemory(context);
    const P = CONFIG?.memoryPressure || {};
    const C = CONFIG?.contextCaps || {};
    const pressure = toNum(context?.memoryPressure);
    const threshold = toNum(P?.emergencyThreshold, 0.95);
    if (!(pressure > threshold)) {
      return false;
    }

    const now = MessageClock.now();
    const last = toNum(context?.memory?.lastEmergencyPruneAt);
    context.memory.lastEmergencyPruneAt = now;
    try {
      ensureCoreDeps(context).Metrics.log(context, "memory.emergency_prune", {
        pressure,
        ts: now,
        heapUsed: context?.vars?.__lastMemoryPressure?.heapUsed,
        heapLimit: context?.vars?.__lastMemoryPressure?.heapLimit
      });
    } catch (err) {
      safeLog(() => handleError(context, err, "memory.emergency_prune.metrics", "DEBUG"));
    }

    const hardFactor = toNum(P?.hardReductionFactor, 0.3);
    const typePressure = getTypePressure(context);
    const factorFor = (ratio) => {
      // Stronger reduction for higher per-type pressure; keep a floor
      const r = Math.max(0, Math.min(1, toNum(ratio)));
      const dynamic = hardFactor * (0.6 + 0.6 * r); // scale between 0.6x and 1.2x of baseline
      return Math.max(0.15, dynamic);
    };
    const capHardType = (val, key) =>
      Math.max(10, Math.floor(toNum(val) * factorFor(typePressure[key])));

    const m = context.memory || {};
    capArrayWithDelta(
      m.interactionHistory,
      capHardType(C.interactionHistory, "interactionHistory"),
      context,
      "interactionHistory",
      "emergencyPrune"
    );
    capArrayWithDelta(
      m.dreamHistory,
      capHardType(C.dreamHistory, "dreamHistory"),
      context,
      "dreamHistory",
      "emergencyPrune"
    );
    capArrayWithDelta(
      m.betrayalJournal,
      capHardType(C.betrayalJournal, "betrayalJournal"),
      context,
      "betrayalJournal",
      "emergencyPrune"
    );
    capArrayWithDelta(
      m.echoHistory,
      capHardType(C.echoHistory, "echoHistory"),
      context,
      "echoHistory",
      "emergencyPrune"
    );
    capArrayWithDelta(
      m.echoInfluence,
      capHardType(C.echoInfluence, "echoHistory"),
      context,
      "echoHistory",
      "emergencyPrune"
    );
    capArrayWithDelta(
      m.characterNotes,
      capHardType(C.characterNotes, "playerMemory"),
      context,
      "playerMemory",
      "emergencyPrune"
    );
    capArrayWithDelta(
      m.lastFallbacks,
      capHardType(C.lastFallbacks, "echoHistory"),
      context,
      "echoHistory",
      "emergencyPrune"
    );
    capArrayWithDelta(
      m.lies,
      capHardType(C.lies, "betrayalJournal"),
      context,
      "betrayalJournal",
      "emergencyPrune"
    );
    capArrayWithDelta(
      m.weaknesses,
      capHardType(C.weaknesses, "betrayalJournal"),
      context,
      "betrayalJournal",
      "emergencyPrune"
    );
    capArrayWithDelta(
      m.itemsBought,
      capHard(C.itemsBought),
      context,
      "playerMemory",
      "emergencyPrune"
    );
    capArrayWithDelta(
      m.corruptionTraits,
      capHard(C.corruptionTraits),
      context,
      "corruptionTraits",
      "emergencyPrune"
    );
    if (Array.isArray(m.prophecies)) {
      capArrayWithDelta(
        m.prophecies,
        capHard(C.prophecies),
        context,
        "prophecies",
        "emergencyPrune"
      );
    }

    if (Array.isArray(context.playerMemory)) {
      capArray(context.playerMemory, capHard(C.playerMemory));
    }

    if (Array.isArray(context.telemetry?.metrics)) {
      const hardMetricsCap = Math.max(
        25,
        Math.floor((CONFIG.contextCaps.metrics || 200) * hardFactor)
      );
      capArray(context.telemetry.metrics, hardMetricsCap);
      try {
        rebuildMetricsIndex?.(context);
      } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
    }
    if (
      Array.isArray(context.telemetry?.metricsArchive) &&
      context.telemetry.metricsArchive.length > 0
    ) {
      const removeCount = Math.floor(context.telemetry.metricsArchive.length / 2);
      if (removeCount > 0) {
        context.telemetry.metricsArchive.splice(0, removeCount); (globalThis.__URGA_assertCaps&&globalThis.__URGA_assertCaps(context));
      }
    }

    if (context.vars?.llmTrace?.metrics && Array.isArray(context.vars.llmTrace.metrics)) {
      const hardTraceCap = Math.max(
        25,
        Math.floor((CONFIG.contextCaps.llmTraceMetrics || 200) * hardFactor)
      );
      capArray(context.vars.llmTrace.metrics, hardTraceCap);
    }

    capArray(context.logs, Math.max(50, Math.floor((CONFIG.contextCaps.logs || 200) * hardFactor)));
    if (Array.isArray(context._llmQueue)) {
      capArray(context._llmQueue, Math.max(25, Math.floor(200 * hardFactor)));
    }

    if (context._recentLines) {
      try {
        context._recentLines.cleanup(context.memory?.messageCount || 0);
        context._recentLines.trim();
      } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
    }

    try {
      CacheManager._clearAllCaches?.();
    } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
    try {
      promptCache?.evict?.();
    } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
    return true;
  } catch (err) {
    safeLog(() => handleError(context, err, "memory.emergencyPrune", "ERROR"));
    return false;
  }
};
