/**
 * @typedef {Object} UrgaContext
 * @property {{active?: Map<string, {weight?: number, behavior?: Object, lastTouch?: number}>}} [gods]
 * @property {{messageCount?: number, godInfluences?: Array<{domain: string, appliedAtMessage?: number, effect?: string}>}} [memory]
 */
/**
 * Returns a ranked list of currently active gods, limited by `limit`.
 * @public
 * @param {UrgaContext} context - Session context with `gods` and `memory`.
 * @param {number} [limit=3] - Maximum number of gods to return.
 * @returns {ActiveGod[]} Active gods sorted by descending weight.
 */
function getAllActiveGods(context, limit = 3) {
  ensureMemory(context);
  // Prefer consolidated gods.active map
  if (context.gods?.active instanceof Map) {
    const out = [];
    for (const [domain, rec] of context.gods.active.entries()) {
      if ((rec?.weight || 0) <= 0) {
        continue;
      }
      const behavior = rec?.behavior || getGodBehaviors(context)[domain] || {};
      out.push({
        name: behavior?.name || domain,
        domain,
        weight: toNum(rec?.weight),
        influence: toNum(rec?.weight),
        effect: behavior?.effect || "",
        effects: behavior,
        appliedAtMessage: rec?.lastTouch || context.memory?.messageCount || 0
      });
    }
    out.sort((a, b) => b.weight - a.weight);
    return out.slice(0, limit);
  }
  // Fallback to legacy array
  const currentMsg = context.memory.messageCount || 0;
  const gods = (context.memory.godInfluences || [])
    .sort((a, b) => (b.appliedAtMessage || 0) - (a.appliedAtMessage || 0))
    .slice(0, limit)
    .map((g) => {
      const behavior = getGodBehaviors(context)[g.domain] || {};
      const ageMsgs = currentMsg - (g.appliedAtMessage ?? currentMsg);
      const decayWindow = typeof GOD_DECAY_MESSAGES === "number" ? GOD_DECAY_MESSAGES : 30;
      const weight = Math.max(0, 1 - Math.min(1, ageMsgs / decayWindow));

      return {
        ...g,
        effect: g.effect || behavior.effect || "",
        effects: behavior,
        weight,
        influence: weight
      };
    })
    .filter((g) => g.weight > 0);

  return gods;
}

/**
 * Returns the highest-weight active god from the current session.
 * @public
 * @param {UrgaContext} context - Session context with active gods.
 * @returns {ActiveGod|null} Dominant god || `null` if none active.
 */
function getDominantGod(context) {
  const active = Gods.getActive(context);
  const list = Array.isArray(active) ? active.filter((g) => g && typeof g.weight === "number") : [];
  if (!list.length) {
    return null;
  }

  return list.reduce((a, b) => (b.weight > a.weight ? b : a));
}

