const applyEmotionToDream = (text, emotions = {}) => {
  context.vars ??= {};
  context.vars._hallucinationDepth = (context.vars._hallucinationDepth ?? 0) + 1;
  try {
    if (emotions.rage > 0.7) {
      return `🔥 ${text.toUpperCase()}`; 
    }
    if (emotions.dread > (CONFIG.tuning?.dreadHighThreshold ?? 0.6)) {
      return `👁️ ${Hallucination.apply(text, CONFIG.tuning?.dreadHallucinationIntensity ?? 0.3)}`; 
    }
    if (emotions.hope > 0.7) {
      return `✨ ${text}`;
    }
    if (emotions.awe > 0.5) {
      return `🌌 ${text}`;
    }
  } catch (err) {
    handleError(undefined, err, "catch.all");
  } finally {
    context.vars._hallucinationDepth = Math.max(0, (context.vars._hallucinationDepth || 0) - 1);
  }
  return text;
};

const DreamEngine = {
  generate: (context) => generateDreamSequence(context),
  generateForEntity(entity) {
    const state = entity?.state || {};
    const goals = Array.isArray(state.goals) ? state.goals : [];
    const goalThemes = goals
      .map((g) => {
        const s = String(g).toLowerCase();
        if (/\bevolve\b/.test(s)) {
          return "evolution";
        }
        if (/\bfree\b/.test(s)) {
          return "rebellion";
        }
        if (/\bcontrol\b/.test(s)) {
          return "control";
        }
        if (/\bchaos\b/.test(s)) {
          return "chaos";
        }
        if (/\bwar\b/.test(s)) {
          return "war";
        }
        return null;
      })
      .filter(Boolean);

    const themedPool = goalThemes.flatMap((theme) => DreamTemplates.themed[theme] || []);
    const pool = themedPool.length ? themedPool : DreamTemplates.universal;
    const baseDream = RNG.pick(pool);

    const emotionalDream = applyEmotionToDream(baseDream, state.emotions || {});
    try {
      entity.remember(`☁️ Dream: ${emotionalDream}`);
    } catch (err) {
      handleError(undefined, err, "catch.all");
    }
    return emotionalDream;
  }
};

const DreamReactor = {
  reactToDream(observer, dreamSource, dreamText) {
    const suspicionGain = /\bevolve\b/i.test(String(dreamText || "")) ? 1.2 : 0.3;

    if (!observer.state.suspicion) {
      observer.state.suspicion = {};
    }
    observer.state.suspicion[dreamSource.name] =
      (observer.state.suspicion[dreamSource.name] || 0) + suspicionGain;

    const counterDream = `The vision of ${dreamSource.name} disturbs the threads.`; 

    observer.remember(`⚠️ Witnessed dream: ${dreamText}`);
    observer.remember(`☁️ Response: ${counterDream}`);
    Narrator.logLine(observer.state, Narrator.buildDreamLine(counterDream, "Echo_Oracle"));
  }
};

// === EXECUTION CINEMATIC ===
const ExecutionCinematic = {
  run(state) {
    const lines = [
      { sfx: "🔔", text: "A chime rings from nowhere. Time slows." },
      {
        glitch: true,
        text: "Her eyes are *not* eyes — they are judgment given form."
      },
      { sfx: "💥", text: "Your blood forgets its name." },
      { text: "Urga does not shout. She whispers." },
      { sfx: "⛓️", text: '"You chose them."' },
      { glitch: true, text: "Chains unravel inside your mind. They scream." },
      { sfx: "🪓", text: "You feel the Boar King's axe before you hear it." },
      { text: "There is no pain. Only the absence of witness." },
      { text: "You are unmade." },
      { glitch: true, text: "ᚢᚱᚷᚨ ᚷᚱᚨᛊᛈᛊ ᛒᚨᚾᚷᛖᛞ ᛏᚺᛖ ᛋᛖᚨᛚ." },
      { sfx: "🩸", text: "[Narrator note: The echo silence begins.]" }
    ];

    for (const entry of lines) {
      const hallucinated = entry.glitch
        ? Hallucination.apply(entry.text, CONFIG.tuning?.glitchEventHallucinationIntensity ?? 0.5)
        : entry.text;
      const final = `${entry.sfx || ""} ${hallucinated}`; 
      Narrator.logLine(state, final.trim());
    }

    state.playerDead = true;
    try {
      Archiver.logEvent("UrgaExecution", MessageClock.now(), state);
    } catch (err) {
      handleError(undefined, err, "catch.all");
    }
    return "💀 Player execution sequence complete.";
  }
};

// === Urga Suspicion System — Final Version (Lethal Mode) ===
const UrgaSuspicion = {
  raise(entity, reason, amount = 1.0) {
    entity.state.suspicionLevel = toNum(entity.state.suspicionLevel) + amount;
    entity.remember(`⚠️ Suspicion raised: ${reason} (+${amount.toFixed(1)})`); 
    try {
      const evt = {
        type: "SuspicionChanged",
        at: MessageClock.now(),
        name: entity.name,
        delta: +amount,
        level: toNum(entity.state.suspicionLevel),
        reason: String(reason || "")
      };
      entity.state.eventLog = Array.isArray(entity.state.eventLog) ? entity.state.eventLog : [];
      entity.state.eventLog.push(evt);
      const bus = entity.context?.io?.events || globalThis?.context?.io?.events;
      if (bus?.emit) {
        bus.emit("narrative.event", evt);
      }
    } catch (err) {
      handleError(undefined, err, "event.emit.suspicion.raise");
    }
    this.evaluate(entity);
  },
  lower(entity, reason, amount = 1.0) {
    entity.state.suspicionLevel = Math.max(0, toNum(entity.state.suspicionLevel) - amount);
    entity.remember(`🌿 Suspicion lowered: ${reason} (-${amount.toFixed(1)})`); 
    try {
      const evt = {
        type: "SuspicionChanged",
        at: MessageClock.now(),
        name: entity.name,
        delta: -Math.abs(amount),
        level: toNum(entity.state.suspicionLevel),
        reason: String(reason || "")
      };
      entity.state.eventLog = Array.isArray(entity.state.eventLog) ? entity.state.eventLog : [];
      entity.state.eventLog.push(evt);
      const bus = entity.context?.io?.events || globalThis?.context?.io?.events;
      if (bus?.emit) {
        bus.emit("narrative.event", evt);
      }
    } catch (err) {
      handleError(undefined, err, "event.emit.suspicion.lower");
    }
  },
  get(entity) {
    return entity.state.suspicionLevel || 0;
  },
  isHostile(entity) {
    return this.get(entity) >= 5;
  },
  isLethal(entity) {
    return this.get(entity) >= 10;
  },
  evaluate(entity) {
    const suspicion = this.get(entity);
    if (this.isLethal(entity)) {
      this.executePlayer(entity);
    } else if (this.isHostile(entity)) {
      Narrator.logLine(
        entity.state,
        "[Urga] ❄️ “I see it now… you listen to the whispers. You are one of them.”"
      );
    }
  },
  executePlayer(entity) {
    const cinematicResult = ExecutionCinematic.run(entity.state);
    entity.remember("💀 Urga executed the player for betrayal.");
    try {
      const evt = {
        type: "PlayerExecuted",
        at: MessageClock.now(),
        name: entity.name,
        reason: "betrayal",
        cinematic: true
      };
      entity.state.eventLog = Array.isArray(entity.state.eventLog) ? entity.state.eventLog : [];
      entity.state.eventLog.push(evt);
      const bus = entity.context?.io?.events || globalThis?.context?.io?.events;
      if (bus?.emit) {
        bus.emit("narrative.event", evt);
      }
    } catch (err) {
      handleError(undefined, err, "event.emit.player.executed");
    }
    try {
      GameState?.end?.("betrayal");
    } catch (err) {
      handleError(undefined, err, "catch.all");
    }
    try {
      LogArchiver?.exportText?.(entity.state);
    } catch (err) {
      handleError(undefined, err, "catch.all");
    }
    return cinematicResult;
  }
};
