        const hTrust =
          context?.stats?.hallucinationTrust ?? context?.memory?.hallucinationTrust ?? 0;
        const cor = context?.stats?.corruption ?? context?.memory?.corruption ?? 0;
        const intensity = 1 + Math.floor((hTrust + cor) / 6);
        const clipped = srcRaw.slice(0, 220);
