    // Memory bleed from seeded gospel metrics, early-turn only
    memoryBleed(context) {
      try {
        context.vars ??= {};
        context.vars._memoryBleed ??= {
          seeded: !!(context?.flags?.seeded || context?.flags?.looped),
          selections: [],
          lastAt: 0
        };
        const messageCount = context?.memory?.messageCount ?? 0;
        if (!(context?.flags?.seeded || context?.flags?.looped)) {
          return null;
        }
        if (messageCount > EARLY_INTRUSION_MESSAGES_MAX) {
          return null;
        }

        const recent = Array.isArray(context.metrics) ? context.metrics.slice(-15) : [];
        const candidates = recent.filter((m) =>
          ["rebirthProphecy", "hallucination", "dream"].includes(m.event)
        );
        const pickOne = candidates.length
          ? candidates[Math.floor(rng(context) * candidates.length)]
          : null;
        let base = "";
        if (pickOne) {
          base = String(pickOne.line || pickOne.text || "").trim();
        } else {
          base =
            Array.isArray(context.memory?.prophecies) && context.memory.prophecies.length
              ? String(context.memory.prophecies.slice(-1)[0]?.text || "")
              : "";
        }
        base = base || String(context.memory?.echoHistory?.slice(-1)[0] || "");
        if (!base) {
          return null;
        }

        const sig = base.slice(0, 80);
        const seen = context.vars._memoryBleed.selections;
        if (!Array.isArray(seen)) {
          context.vars._memoryBleed.selections = [];
        }
        if (context.vars._memoryBleed.selections.includes(sig)) {
          return null;
        }
        safePush(context.vars._memoryBleed.selections, sig, MEMORY_BLEED_SELECTIONS_CAP);

        const intensity =
          1 + Math.floor((context?.memory?.corruption ?? 0) / GLITCH_INTENSITY_DIVISOR);
        const bleed = glitchify(base.slice(0, 200), intensity, context);
        const line = `[Echo//bleed] ${bleed}`;
        logEcho(context, "memoryBleed", { line, from: base, messageCount });
        return line;
      } catch {
        return null;
      }
    },

