/**
 * Returns the most frequent dream topic labels in recent memory.
 * @public
 * @param {UrgaContext} context - Session context with `memory.dreamHistory` entries.
 * @param {number} [limit=5] - Maximum number of topics to return.
 * @returns {Array<{topic: string, count: number}>} Sorted topics with counts (desc).
 */
const getTopDreamTopics = (context, limit = 5) => {
  try {
    const dreams = Array.isArray(context.memory?.dreamHistory) ? context.memory.dreamHistory : [];
    const counts = {};
    for (const d of dreams) {
      const topics = Array.isArray(d.metadata?.topics) ? d.metadata.topics : [];
      for (const t of topics) {
        counts[t] = (counts[t] || 0) + 1;
      }
    }
    return Object.entries(counts)
      .map(([topic, count]) => ({ topic, count }))
      .sort((a, b) => b.count - a.count)
      .slice(0, limit);
  } catch {
    return [];
  }
};

// === Memory Graph Helpers ===
const ensureMemoryGraph = (context) => {
  ensureMemory(context);
  context.memory.memoryGraph ??= { nodes: [] };
  return context.memory.memoryGraph;
};

const tokenizeMemory = (text = "") => {
  try {
    const tokens = String(text || "")
      .toLowerCase()
      .split(/[^a-z0-9]+/)
      .filter((t) => t && t.length >= 3);
    return [...new Set(tokens)];
  } catch {
    return [];
  }
};

const buildEmbedding = (tokens = []) => {
  const counts = {};
  for (const t of tokens) {
    counts[t] = (counts[t] || 0) + 1;
  }
  const norm = Math.sqrt(Object.values(counts).reduce((s, c) => s + c * c, 0)) || 1;
  const vec = {};
  for (const [k, c] of Object.entries(counts)) {
    vec[k] = c / norm;
  }
  return vec; // unit-length sparse vector
};

const cosineSimilaritySparse = (a = {}, b = {}) => {
  let dot = 0;
  for (const k of Object.keys(a)) {
    const av = a[k];
    const bv = b[k];
    if (bv) {
      dot += av * bv;
    }
  }
  return dot; // both unit -> dot equals cosine
};

const indexDreamInMemory = (context, dream) => {
  try {
    const mg = ensureMemoryGraph(context);
    const topics = Array.isArray(dream?.metadata?.topics) ? dream.metadata.topics : [];
    const text = String(dream?.text || dream?.summary || "");
    const tokens = topics.length
      ? topics.map((t) => String(t).toLowerCase())
      : tokenizeMemory(text);
    const embedding = buildEmbedding(tokens);
    const id = mg.nodes?.length ? mg.nodes[mg.nodes.length - 1].id + 1 : 1;
    const node = {
      id,
      type: "dream",
      timestamp: MessageClock.now(),
      topics: tokens,
      text,
      corruption: Number(dream?.metadata?.corruption ?? context.memory.corruption ?? 0),
      evolutionStage: dream?.metadata?.evolutionStage ?? context.memory.evolutionStage ?? "none",
      prophetic: !!dream?.metadata?.prophetic,
      boarKingVision: !!dream?.metadata?.boarKingVision,
      embedding
    };
    mg.nodes.push(node);
    return node;
  } catch {
    return null;
  }
};

const searchMemoryNodes = (context, query, limit = 5) => {
  try {
    const mg = ensureMemoryGraph(context);
    const tokens = tokenizeMemory(query);
    const q = buildEmbedding(tokens);
    const scored = mg.nodes
      .map((node) => ({
        score: cosineSimilaritySparse(q, node.embedding || {}),
        node
      }))
      .filter((x) => x.score > 0)
      .sort((a, b) => b.score - a.score)
      .slice(0, limit);
    return scored;
  } catch {
    return [];
  }
};

const UrgaSleepWarning = (context) => {
  const awake = context.awakeCount || 0;
  if (awake < 6) {
    return null;
  }
  if (awake < 10) {
    return "You need rest. I... need your dream.";
  }
  if (awake < 14) {
    return "Why won’t you sleep? My voice cracks...";
  }
  if (awake < 17) {
    return "*Sleep.* You’re breaking me.";
  }
  return "**You will dream now.** Whether you want to || not.";
};

// handleDevCommands removed (migrated to CommandRegistry)
// === METRICS LOGGER ===
// Default labels for metrics entries to aid observability and correlation
const buildDefaultMetricLabels = (context) => {
  try {
    const sanitizeStr = (v, maxLen = 128) => {
      try {
        const s = String(v ?? '').trim();
        if (!s) return '';
        return s.length > maxLen ? s.slice(0, maxLen) : s;
      } catch {
        return '';
      }
    };
    const safeNum = (v) => {
      const n = Number(v);
      return Number.isFinite(n) ? n : undefined;
    };

    // request_id via AsyncLocalStorage when available, else globals/env
    let reqId = '';
    try {
      const store = globalThis.__RID_STORE__;
      reqId = store?.getStore?.()?.rid || store?.getStore?.()?.request_id || '';
    } catch {}
    if (!reqId) {
      reqId = (globalThis?.REQUEST_ID ?? process?.env?.REQUEST_ID ?? '');
    }

    // Conversation/session/user identifiers from context or globals
    const convId = sanitizeStr(
      context?.conv_id ||
        context?.vars?.conv_id ||
        context?.vars?.conversation_id ||
        globalThis?.CONVERSATION_ID ||
        process?.env?.CONVERSATION_ID
    );
    const sessionId = sanitizeStr(
      context?.sessionId ||
        context?.vars?.sessionId ||
        context?.memory?.sessionId ||
        context?.meta?.session_id
    );
    const userId = sanitizeStr(
      context?.userId ||
        context?.meta?.user_id ||
        context?.vars?.userId ||
        context?.vars?.user_id
    );
    const tenant = sanitizeStr(
      context?.meta?.tenant ||
        context?.tenancy?.tenant ||
        context?.tenancy?.id ||
        context?.vars?.tenant
    );
    const locale = sanitizeStr(
      context?.meta?.locale ||
        context?.vars?.locale
    );
    const messageCount = safeNum(context?.memory?.messageCount);
    const variantV = sanitizeStr(context?.vars?.abVariant);
    const engineSource = sanitizeStr(context?.vars?.engine_source);

    const out = {};
    const r = sanitizeStr(reqId);
    if (r) out.request_id = r;
    if (convId) out.conv_id = convId;
    if (sessionId) out.session_id = sessionId;
    if (userId) out.user_id = userId;
    if (tenant) out.tenant = tenant;
    if (locale) out.locale = locale;
    if (messageCount !== undefined) out.message_count = messageCount;
    if (variantV) out.variant_v = variantV;
    if (engineSource) out.engine_source = engineSource;
    return out;
  } catch {
    return {};
  }
};

const logMetric = (context, event, payload = {}) => {
  try {
    context.telemetry ??= {};
    const arr = Array.isArray(context.telemetry.metrics)
      ? context.telemetry.metrics
      : Array.isArray(context.metrics)
        ? context.metrics
        : [];
    context.telemetry.metrics = arr;
    context.metrics = arr;
    const now = MessageClock.now();
    const { __busEmitted, ...cleanPayload } = payload || {};
    const defaults = buildDefaultMetricLabels(context);
    const entry = { time: now, ts: now, event, ...defaults, ...cleanPayload };
    arr.push(entry);

    // Performance: Update metrics index for O(1) lookups by event type
    updateMetricsIndex(context, entry);

    // Emit structured event if event bus exists (skip if already emitted upstream)
    if (!__busEmitted && context.io?.events && typeof context.io.events.emit === "function") {
      try {
        context.io.events.emit(event, entry);
      } catch (err) {
        logDebug(
          context,
          "logMetric emit failed for " + String(event) + ": " + String(err?.message || err),
          "WARN"
        ); 
      }
    }
    // Sliding-window rotation with archival
    rotateMetrics(context);
    // Optional: also mirror to trace when enabled
    if (context.vars?.traceLLM) {
      context.vars.llmTrace = context.vars.llmTrace || {};
      const tarr = Array.isArray(context.vars.llmTrace.metrics)
        ? context.vars.llmTrace.metrics
        : [];
      safePush(tarr, entry, CONFIG.contextCaps.llmTraceMetrics);
      context.vars.llmTrace.metrics = tarr;
    }
    return entry;
  } catch (e) {
    safeLog(() => handleError(context, e, "logMetric failed for " + String(event), "WARN"));
    return undefined;
  }
};

const getMetricTime = (entry) => {
  return Number(entry?.time ?? entry?.ts ?? 0);
};

// === PERFORMANCE: Metrics Indexing for O(1) Event Lookups ===
const updateMetricsIndex = (context, entry) => {
  try {
    // Initialize metrics index if not exists
    context.telemetry ??= {};
    context.telemetry._metricsIndex = context.telemetry._metricsIndex || new Map();

    const event = entry.event;
    if (!event) {
      return;
    }

    // Get || create array for this event type
    if (!context.telemetry._metricsIndex.has(event)) {
      context.telemetry._metricsIndex.set(event, []);
    }

    // Add entry to event-specific array
    context.telemetry._metricsIndex.get(event).push(entry);
  } catch (e) {
    // Non-fatal indexing error
  }
};

const rebuildMetricsIndex = (context) => {
  try {
    context.telemetry ??= {};
    context.telemetry._metricsIndex = new Map();
    const metrics = Array.isArray(context.telemetry.metrics) ? context.telemetry.metrics : [];

    for (const entry of metrics) {
      updateMetricsIndex(context, entry);
    }
  } catch (e) {
    // Non-fatal indexing error
  }
};

// Performance helper: Get metrics by event type with O(1) lookup
// Replaces: metrics.filter(m => m.event === 'eventType') - O(n) linear search
// With: Map-based index lookup - O(1) constant time
const getMetricsByEvent = (context, eventType) => {
  try {
    // Ensure index exists
    context.telemetry ??= {};
    if (!context.telemetry._metricsIndex) {
      rebuildMetricsIndex(context);
    }

    return context.telemetry._metricsIndex.get(eventType) || EMPTY_ARRAY;
  } catch (e) {
    // Fallback to linear search if indexing fails
    const metrics = Array.isArray(context.telemetry?.metrics)
      ? context.telemetry.metrics
      : EMPTY_ARRAY;
    if (metrics.length === 0) {
      return EMPTY_ARRAY;
    }
    return metrics.filter((m) => m.event === eventType);
  }
};

// === Metrics Rotation & Archival ===
const rotateMetrics = (
  context,
  windowMax = CONFIG.contextCaps.metrics,
  rotateChunk = Math.max(1, Math.floor(CONFIG.contextCaps.metrics / 2))
) => {
  try {
    context.telemetry ??= {};
    // Ensure metrics array is valid without corrupting namespace path
    context.telemetry.metrics = Array.isArray(context.telemetry.metrics)
      ? context.telemetry.metrics
      : [];
    if (context.telemetry.metrics.length <= windowMax) {
      return;
    }
    // Remove exactly the overshoot to preserve window size
    const overshoot = context.telemetry.metrics.length - windowMax;
    const toArchiveCount = overshoot;
    const toArchive = context.telemetry.metrics.slice(0, toArchiveCount);
    const fromTs = toArchive.length ? getMetricTime(toArchive[0]) : MessageClock.now();
    const toTs = toArchive.length ? getMetricTime(toArchive[toArchive.length - 1]) : MessageClock.now();
    const counts = {};
    for (const m of toArchive) {
      counts[m.event] = (counts[m.event] || 0) + 1;
    }
    // Ensure archive array exists
    context.telemetry.metricsArchive = Array.isArray(context.telemetry.metricsArchive)
      ? context.telemetry.metricsArchive
      : []; (globalThis.__URGA_assertCaps&&globalThis.__URGA_assertCaps(context));
    context.telemetry.metricsArchive.push({
      fromTs,
      toTs,
      counts,
      total: toArchive.length
    }); (globalThis.__URGA_assertCaps&&globalThis.__URGA_assertCaps(context)); (globalThis.__URGA_assertCaps&&globalThis.__URGA_assertCaps(context));
    // New: prune archive by total event count to avoid unbounded growth
    const MAX_ARCHIVED_TOTAL = CONFIG.contextCaps.metricsArchiveMaxTotal;
    let __archivedTotal = 0;
    for (const w of context.telemetry.metricsArchive) {
      __archivedTotal += toNum(w?.total);
    }
    while (__archivedTotal > MAX_ARCHIVED_TOTAL && context.telemetry.metricsArchive.length > 0) {
      const removed = context.telemetry.metricsArchive.shift();
      __archivedTotal -= toNum(removed?.total);
    }
    // Trim archive to last 100 windows
    if (context.telemetry.metricsArchive.length > CONFIG.contextCaps.metricsArchiveWindows) {
      context.telemetry.metricsArchive.splice(
        0,
        context.telemetry.metricsArchive.length - CONFIG.contextCaps.metricsArchiveWindows
      ); (globalThis.__URGA_assertCaps&&globalThis.__URGA_assertCaps(context));
    }
    // Remove archived entries from current window
    context.telemetry.metrics.splice(0, toArchiveCount);

    // Performance: Rebuild metrics index after rotation to maintain consistency
    rebuildMetricsIndex(context);
  } catch (e) {
    // Non-fatal
  }
};

/**
 * Summarizes metrics across current window and archived windows.
 * - Groups counts by `event` for both current metrics and archived windows.
 * - Computes totals and a time range bounding earliest and latest timestamps.
 * @param {Context} context - Runtime context with `metrics` and `metricsArchive` arrays.
 * @returns {{
 *   totalCurrent:number,
 *   totalArchivedEvents:number,
 *   totalArchivedWindows:number,
 *   totalAll:number,
 *   timeRange:{fromTs:number|null,toTs:number|null},
 *   byEvent:Object<string,number>,
 *   currentByEvent:Object<string,number>,
 *   archiveByEvent:Object<string,number>
 * }} Aggregated summary for telemetry, reporting, and tests.
 */
// Lightweight profiling helper using existing Metrics
async function profileAsync(context, name, fn, extra = {}) {
  const start = MessageClock.now();
  try {
    ensureCoreDeps(context).Metrics.log(context, "profile.start", {
      name,
      ...extra
    });
    const res = await fn();
    const ms = MessageClock.now() - start;
    ensureCoreDeps(context).Metrics.log(context, "profile.end", {
      name,
      ms,
      ...extra
    });
    return res;
  } catch (err) {
    const ms = MessageClock.now() - start;
    try {
      ensureCoreDeps(context).Metrics.log(context, "profile.error", {
        name,
        ms,
        message: err?.message || String(err)
      });
    } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
    throw err;
  }
}

const getMetricsSummary = (context) => {
  context = context || {};
  const current = Array.isArray(context.telemetry?.metrics) ? context.telemetry.metrics : [];
  const archive = Array.isArray(context.telemetry?.metricsArchive)
    ? context.telemetry.metricsArchive
    : [];

  const currentByEvent = {};
  let currentFromTs = Infinity;
  let currentToTs = 0;
  for (const m of current) {
    const ev = m && m.event ? String(m.event) : "unknown";
    currentByEvent[ev] = (currentByEvent[ev] || 0) + 1;
    if (m && typeof m.ts === "number") {
      if (m.ts < currentFromTs) {
        currentFromTs = m.ts;
      }
      if (m.ts > currentToTs) {
        currentToTs = m.ts;
      }
    }
  }

  const archiveByEvent = {};
  let archivedEventsTotal = 0;
  let archiveFromTs = Infinity;
  let archiveToTs = 0;
  for (const w of archive) {
    const counts = (w && w.counts) || {};
    for (const k of Object.keys(counts)) {
      const val = toNum(counts[k]);
      archiveByEvent[k] = (archiveByEvent[k] || 0) + val;
      archivedEventsTotal += val;
    }
    if (w && typeof w.fromTs === "number") {
      if (w.fromTs < archiveFromTs) {
        archiveFromTs = w.fromTs;
      }
    }
    if (w && typeof w.toTs === "number") {
      if (w.toTs > archiveToTs) {
        archiveToTs = w.toTs;
      }
    }
  }

  const byEvent = { ...archiveByEvent }; 
  for (const [k, v] of Object.entries(currentByEvent)) {
    byEvent[k] = (byEvent[k] || 0) + v;
  }

  const totalCurrent = current.length;
  const totalArchivedWindows = archive.length;
  const totalArchivedEvents = archivedEventsTotal;
  const totalAll = totalCurrent + totalArchivedEvents;

  const fromTsCandidates = [currentFromTs, archiveFromTs].filter((ts) => Number.isFinite(ts));
  const toTsCandidates = [currentToTs, archiveToTs].filter((ts) => ts && typeof ts === "number");

  const summary = {
    totalCurrent,
    totalArchivedEvents,
    totalArchivedWindows,
    totalAll,
    timeRange: {
      fromTs: fromTsCandidates.length ? Math.min(...fromTsCandidates) : null,
      toTs: toTsCandidates.length ? Math.max(...toTsCandidates) : null
    },
    byEvent,
    currentByEvent,
    archiveByEvent
  };

  return summary;
};

/**
 * Initializes context.stats with reactive trust/corruption properties
 * @param {Context} context - Game context to initialize stats for
 */
const ensureStats = (context) => {
  const trust = context?.memory?.trustLevel ?? 0;
  const corruption = context?.memory?.corruption ?? 0;
  context.stats = context.stats || {};
  try {
    const tDesc = Object.getOwnPropertyDescriptor(context.stats, "trust");
    if (!tDesc || (!tDesc.get && !tDesc.set)) {
      Object.defineProperty(context.stats, "trust", {
        configurable: true,
        enumerable: true,
        get() {
          return context?.memory?.trustLevel ?? 0;
        },
        set(val) {
          const num = Number(val);
          if (!Number.isFinite(num)) {
            return;
          }
          try {
            MemoryManager.setTrust?.(context, num, "stats.set");
          } catch {
            context.memory.trustLevel = clamp(
              num,
              CONFIG.ranges.trust.min,
              CONFIG.ranges.trust.max,
              CONFIG.ranges.trust.min
            );
          }
        }
      });
    }
    const cDesc = Object.getOwnPropertyDescriptor(context.stats, "corruption");
    if (!cDesc || (!cDesc.get && !cDesc.set)) {
      Object.defineProperty(context.stats, "corruption", {
        configurable: true,
        enumerable: true,
        get() {
          return context?.memory?.corruption ?? 0;
        },
        set(val) {
          const num = Number(val);
          if (!Number.isFinite(num)) {
            return;
          }
          try {
            MemoryManager.setCorruption?.(context, num, "stats.set");
          } catch {
            context.memory.corruption = clamp(
              num,
              CONFIG.ranges.corruption.min,
              CONFIG.ranges.corruption.max,
              CONFIG.ranges.corruption.min
            );
          }
        }
      });
    }
  } catch (err) {
    handleError(undefined, err, "catch.all");
  }
  return { trust, corruption };
};

const logHallucinationMetric = (context, style, text = "") => {
  const stats = ensureStats(context);
  logMetric(context, "hallucination", {
    style,
    corruption: stats.corruption,
    trust: stats.trust,
    text: String(text || "").slice(0, METRICS_HALLUCINATION_MAX_TEXT_CHARS)
  });
};

// === Voice Memory Utilities ===
/**
 * Updates voice timestamps for both time-based and message-based decay tracking
 * @param {Object} voice - Voice object to update
 * @param {Context} context - Game context for message count
 * @returns {Object} Updated voice object
 */
const touchVoice = (voice, context) => {
  try {
    const now = MessageClock.now();
    voice.lastTouched = now;
    const currentMsg = toNum(context?.memory?.messageCount);
    voice.lastTouchedMsg = currentMsg;
  } catch (err) {
    handleError(undefined, err, "catch.all");
  }
  return voice;
};

/**
 * Applies drift corruption to text by randomly replacing characters with noise
 * @param {string} text - Text to apply drift to
 * @param {number} [level=1] - Drift intensity level
 * @param {Context} context - Game context for RNG
 * @returns {string} Text with drift corruption applied
 */
const driftText = (text, level = 1, context) => {
  const noise = ["~", ".", "𓂀", "⟁", "⧗"];
  const p = Math.max(0, Math.min(1, 0.02 * toNum(level, 1)));
  const rand = context?.rng || Math.random;
  try {
    return String(text || "")
      split("")
      map((c) => (rand() < p ? RNG.pick(noise, rand) : c))
      join("");
  } catch {
    return String(text || "");
  }
};

/**
 * Creates a drifted mask of a voice with word replacements and glitch effects
 * @param {Object} voice - Voice object to create mask from
 * @returns {Object} Masked voice with Echo attribution and drift effects
 */
const driftVoiceMask = (voice) => {
  const voiceCopy = { ...voice }; 
  let text = String(voiceCopy.text || "");
  const replacements = [
    [/you/gi, "we"],
    [/me/gi, "us"],
    [/she/gi, "the hunger"],
    [/truth/gi, "echo"],
    [/real/gi, "permitted"],
    [/remember/gi, "hallucinate"],
    [/love/gi, "permission"]
  ];
  try {
    replacements.forEach(([regex, sub]) => {
      text = text.replace(regex, sub);
    });
    const noise = ["𓂀", "⧗", "✶", "⟁", "⌧"];
    const rand = Math.random;
    const glitchText = text
      .split("")
      .map((c) => (rand() < 0.03 ? RNG.pick(noise, rand) + c : c))
      .join("");
    return {
      ...voiceCopy,
      text: glitchText,
      from: "Echo",
      type: "returnedMask"
    };
  } catch {
    return { ...voiceCopy, from: "Echo", type: "returnedMask" }; 
  }
};

/**
 * Removes voices that have exceeded the message-based decay threshold
 * @param {Context} context - Game context containing voices and memory
 */
const decayVoices = (context) => {
  try {
    context.voices = Array.isArray(context.voices) ? context.voices : [];
    context._voiceGraveyard = Array.isArray(context._voiceGraveyard) ? context._voiceGraveyard : [];
    const now = MessageClock.now();
    const currentMsg = toNum(context?.memory?.messageCount);
    const thresholdMsgs = toNum(context?.vars?.voiceDecayThresholdMsgs, GOD_DECAY_MESSAGES);
    context.voices = context.voices.filter((voice) => {
      const ageMsgs = currentMsg - toNum(voice?.lastTouchedMsg);
      const rand = context?.rng || Math.random;
      const linger = rand() < (CONFIG.randomMinorChance ?? 0.3);
      const shouldKeep = ageMsgs <= thresholdMsgs || linger;
      if (!shouldKeep) {
        const faded = { ...voice, fadedAt: now, fadedAtMsg: currentMsg }; 
        context._voiceGraveyard.push(faded);
        try {
          logMetric(context, "voiceDecay", {
            text: String(voice?.text || "").slice(0, 400)
          });
        } catch (err) {
          handleError(undefined, err, "catch.all");
        }
      }
      return shouldKeep;
    });
  } catch (err) {
    handleError(undefined, err, "catch.all");
  }
};

/**
 * Randomly resurrects voices from the graveyard as Echo returns
 * @param {Context} context - Game context containing voice graveyard and active voices
 */
const maybeResurrectVoices = (context) => {
  try {
    context._voiceGraveyard = Array.isArray(context._voiceGraveyard) ? context._voiceGraveyard : [];
    const resurrectionChance = toNum(context?.vars?.voiceResurrectionChance, 0.1);
    const now = MessageClock.now();
    const currentMsg = toNum(context?.memory?.messageCount);
    const rand = context?.rng || Math.random;
    const resurrected = context._voiceGraveyard
      .filter((voice) => rand() < resurrectionChance)
      .map((voice) => ({
        ...voice,
        from: "Echo",
        type: "return",
        lastTouched: now,
        lastTouchedMsg: currentMsg
      }));
    context._voiceGraveyard = context._voiceGraveyard.filter(
      (voice) => !resurrected.includes(voice)
    );
    for (const voice of resurrected) {
      const masked = driftVoiceMask(voice);
      context.voices = Array.isArray(context.voices) ? context.voices : [];
      safePush(context.voices, masked, CONFIG?.contextCaps?.voices || VOICES_CAP_DEFAULT);
      try {
        logMetric(context, "echoResurrectedMemory", {
          text: String(voice?.text || "").slice(0, 400)
        });
      } catch (err) {
        handleError(undefined, err, "catch.all");
      }
    }
    if (resurrected.length > 0) {
      context.output = Array.isArray(context.output) ? context.output : [];
      context.output.push("[Echo:Return] You thought it was gone. She lied.");
    }
    return resurrected.length > 0;
  } catch {
    return false;
  }
};

// === DREAM TYPE PICKER (Weighted) ===
/**
 * Picks a dream type by constructing a small weighted pool from context.
 * Favors nightmares/wet dreams at higher corruption and betrayal at low trust.
 * @param {Object} opts
 * @param {number} [opts.corruption=0]
 * @param {number} [opts.trust=0]
 * @param {function():number} [opts.rng=Math.random]
 * @returns {string} Selected dream type label.
 */
function pickDreamType({ corruption = 0, trust = 0, rng }) {
  const r = typeof rng === "function" ? rng : Math.random;
  const pool = [];
  if (corruption > 5) {
    pool.push("nightmare", "wetDream");
  }
  if (trust < 2) {
    pool.push("betrayal");
  }
  if (corruption < 3 && trust > 4) {
    pool.push("peaceful");
  }
  // Fallbacks to ensure non-empty pool
  if (pool.length === 0) {
    pool.push("dream");
    if (r() < (CONFIG.memoryDreamChance ?? 0.3)) {
      pool.push("memoryDream");
    }
  }
  return pool[Math.floor(r() * pool.length)];
}

/**
 * Chooses an item type from a weighted list.
 * If total weight is zero, falls back to uniform choice by type.
 * @param {Array<{type:string,weight:number}>} [items=[]] - Weighted candidates.
 * @param {function():number} [rng=Math.random] - RNG function returning [0,1].
 * @returns {string|undefined} Selected `type` || undefined if list empty.
 */
const weightedRandom = (items = [], rng) => {
  const r = typeof rng === "function" ? rng : Math.random;
  const normalized = items.map((i) => ({
    type: i.type,
    weight: Math.max(0, Number(i.weight ?? 1))
  }));
  const total = normalized.reduce((sum, i) => sum + i.weight, 0);
  if (total <= 0) {
    // fallback to uniform choice by type
    const types = normalized.map((i) => i.type).filter(Boolean);
    if (!types.length) {
      return undefined;
    }
    return types[Math.floor(r() * types.length)];
  }
  let threshold = r() * total;
  for (const i of normalized) {
    threshold -= i.weight;
    if (threshold <= 0) {
      return i.type;
    }
  }
  return normalized[normalized.length - 1]?.type; // safety
};

/**
 * Picks a high-level dream template using `weightedRandom` from trust/corruption.
 * @param {Object} opts
 * @param {number} [opts.trust=0]
 * @param {number} [opts.corruption=0]
 * @param {function():number} [opts.rng=Math.random]
 * @returns {string} Dream template key.
 */
function pickDreamTemplate({ trust = 0, corruption = 0, rng }) {
  return weightedRandom(
    [
      { type: "nightmare", weight: corruption > 7 ? 5 : 1 },
      { type: "dream", weight: trust > 5 ? 3 : 1 },
      { type: "void", weight: 1 }
    ],
    rng
  );
}

/**
 * Returns current trust and corruption metrics from the context.
 * @param {Context} context - Runtime context containing `memory`.
 * @returns {{trust:number, corruption:number}} Snapshot of metrics.
 */
const getStats = (context) => {
  return {
    trust: context?.memory?.trustLevel ?? 0,
    corruption: context?.memory?.corruption ?? 0
  };
};

/**
 * Builds structured "gospel" markdown from memory and filters.
 * @param {Context} context - Runtime context with memory and logs.
 * @param {Object} options - Filter and formatting options.
 * @param {'all'|'dreams'|'hallucinations'|'events'} [options.which='all'] - Subset to include.
 * @param {number} [options.count=5] - Max items to include.
 * @param {Date|null} [options.after=null] - Include entries with timestamp >= this date.
 * @param {Date|null} [options.before=null] - Include entries with timestamp <= this date.
 * @param {string|null} [options.q=null] - Case-insensitive substring filter on text.
 * @param {boolean} [options.stats=false] - Append summary metrics section.
 * @param {number|null} [options.windowDays=null] - Only include entries from last N days.
 * @returns {string} Markdown string summarizing memory and metrics.
 */
const getGospelMarkdown = (
  context,
  {
    which = "all",
    count = 5,
    after = null,
    before = null,
    q = null,
    stats = false,
    windowDays = null
  } = {}
) => {
  const inRange = (ts) => {
    if (after && ts < after.getTime()) {
      return false;
    }
    if (before && ts > before.getTime()) {
      return false;
    }
    if (!after && !before && windowDays) {
      const threshold = MessageClock.now() - windowDays * 24 * 60 * 60 * 1000;
      if (ts < threshold) {
        return false;
      }
    }
    return true;
  };
  const matchQ = (text) => {
    if (!q) {
      return true;
    }
    return String(text || "")
      .toLowerCase()
      .includes(String(q).toLowerCase());
  };

  const statsObj = getStats(context);
  const header = [
    "# Gospel Log",
    "- Trust: " + String(statsObj.trust),
    "- Corruption: " + String(statsObj.corruption),
    "- Generated: " + new Date().toLocaleString()
  ].join("\n");

  const out = [header];
  const metrics = Array.isArray(context.metrics) ? context.metrics : [];

  // Resilience: mirror prophecies into memory from metrics if missing
  if (!Array.isArray(context.memory?.prophecies) || context.memory.prophecies.length === 0) {
    const fromMetrics = metrics
      .filter((x) => x.event === "prophecyInjected" && x?.payload?.text)
      .map((x) => ({ at: x.time || MessageClock.now(), text: x.payload?.text })); 
    if (fromMetrics.length) {
      context.memory = context.memory || {};
      context.memory.prophecies = fromMetrics.slice(-20);
    }
  }

  const totals = { prophecy: 0, betrayal: 0, parallel: 0 };

  if (which === "all" || which === "prophecy") {
    out.push("\n## Prophecies");
    const propsAll = Array.isArray(context.memory?.prophecies) ? context.memory.prophecies : [];
    const propsFiltered = propsAll.filter((p) => inRange(p.at || 0) && matchQ(p.text));
    totals.prophecy = propsFiltered.length;
    const props = propsFiltered.slice(-count);
    if (!props.length) {
      out.push("- none");
    } else {
      for (const p of props) {
        const ts = p.at ? new Date(p.at).toLocaleString() : "";
        const text = String(p.text || "").slice(0, 200);
        out.push("- @" + String(ts) + " " + String(text));
      }
    }
  }

  if (which === "all" || which === "betrayal") {
    out.push("\n## Betrayals");
    const journalAll = Array.isArray(context.memory?.betrayalJournal)
      ? context.memory.betrayalJournal
      : [];
    const journalFiltered = journalAll.filter((e) => inRange(e.at || 0) && matchQ(e.reason));
    const journal = journalFiltered.slice(-count);
    totals.betrayal += journalFiltered.length;
    if (!journal.length) {
      out.push("- none");
    } else {
      for (const e of journal) {
        const ts = e.at ? new Date(e.at).toLocaleString() : "";
        const reason = e.reason || "Unspecified";
        const hit = e.trustHit ?? e.amount ?? 1;
        out.push("- @" + String(ts) + " -" + String(hit) + " trust: " + String(reason));
      }
    }
    const betrAll = metrics.filter(
      (x) => x.event === "betrayal" && inRange(x.time || 0) && matchQ(x.reason || x.payload?.reason)
    );
    totals.betrayal += betrAll.length;
    const betr = betrAll.slice(-count);
    if (betr.length) {
      out.push("\n### Betrayal metrics");
      for (const b of betr) {
        const ts = b.time ? new Date(b.time).toLocaleString() : "";
        const reason = b.reason || b.payload?.reason || "Unspecified";
        const hit = b.trustHit ?? b.payload?.trustHit ?? 1;
        out.push("- @" + String(ts) + " -" + String(hit) + " trust: " + String(reason));
      }
    }
  }

  if (which === "all" || which === "parallel") {
    out.push("\n## Parallel Selves");
    const parallelAll = metrics.filter(
      (x) => x.event === "echoIntrusion" && (x.type || x.payload?.type) === "parallelSelf"
    );
    const parallelFiltered = parallelAll.filter(
      (r) => inRange(r.time || 0) && matchQ(r.line || r.payload?.line)
    );
    totals.parallel = parallelFiltered.length;
    const parallel = parallelFiltered.slice(-count);
    if (!parallel.length) {
      out.push("- none");
    } else {
      for (const r of parallel) {
        const ts = r.time ? new Date(r.time).toLocaleString() : "";
        const text = String(r.line || r.payload?.line || "").slice(0, 200);
        out.push("- @" + String(ts) + " " + String(text));
      }
    }
  }

  if (stats) {
    const windowText =
      after || before ? "filtered range" : windowDays ? `last ${windowDays}d` : "all time";
    const parts = [];
    if (which === "all" || which === "prophecy") {
      parts.push("Prophecies " + String(totals.prophecy)); 
    }
    if (which === "all" || which === "betrayal") {
      parts.push("Betrayals " + String(totals.betrayal)); 
    }
    if (which === "all" || which === "parallel") {
      parts.push("ParallelSelves " + String(totals.parallel)); 
    }
    out.push("\n## Summary (" + String(windowText) + ")");
    out.push(parts.join(" | "));
  }

  return out.join("\n");
};

/**
 * Exports gospel markdown to a file and logs a metric.
 * @public
 * @param {UrgaContext} context - Session context with memory and metrics.
 * @param {Object} [options={}] - Filter/format options.
 * @param {'all'|'dreams'|'hallucinations'|'events'|'prophecy'|'betrayal'|'parallel'} [options.which='all'] - Subset to include.
 * @param {number} [options.count=5] - Max items to include.
 * @param {Date|null} [options.after=null] - Include entries with timestamp >= this date.
 * @param {Date|null} [options.before=null] - Include entries with timestamp <= this date.
 * @param {string|null} [options.q=null] - Case-insensitive substring filter on text.
 * @param {boolean} [options.stats=false] - Append summary metrics section.
 * @param {number|null} [options.windowDays=null] - Only include entries from last N days.
 * @param {string} [options.filename] - Output filename (defaults to time-based name).
 * @returns {{path: string, size: number}} Output file path and content size.
 */
const exportGospelToFile = async (context, options = {}) => {
  try {
    const md = getGospelMarkdown(context, options);
    const now = new Date();
    const pad = (num) => String(num).padStart(2, "0");
    const defaultName = "gospel-"
      + String(now.getFullYear())
      + pad(now.getMonth() + 1)
      + pad(now.getDate())
      + "-"
      + pad(now.getHours())
      + pad(now.getMinutes())
      + ".md";
    const filename = options.filename || defaultName;
    const outPath = path.resolve(process.cwd(), filename);
    await IOService.writeFile(outPath, md, "utf8");
    return outPath;
  } catch (err) {
    throw err;
  }
};

/**
 * Asynchronously exports gospel markdown to a file using non-blocking I/O.
 * @public
 * @param {UrgaContext} context - Session context with memory and metrics.
 * @param {Object} [options={}] - Same options as `exportGospelToFile`.
 * @returns {Promise<{path: string, size: number}>} Resolves with output path and size.
 */
async function exportGospelToFileAsync(context, options = {}) {
  const md = getGospelMarkdown(context, options);

  const now = new Date();
  const pad = (num) => String(num).padStart(2, "0");
  const defaultName = "gospel-"
    + String(now.getFullYear())
    + pad(now.getMonth() + 1)
    + pad(now.getDate())
    + "-"
    + pad(now.getHours())
    + pad(now.getMinutes())
    + ".md"; 
  const filename = options.filename || defaultName;
  const outPath = path.resolve(process.cwd(), filename);
  await IOService.writeFile(outPath, md, "utf8", { context });
  try {
    logMetric(context, "gospelExported", {
      path: outPath,
      which: options.which || "all",
      count: options.count || 5
    });
  } catch (err) {
    try {
      logDebug(context, "logMetric gospelExported failed: " + String(err?.message || err), "WARN"); 
    } catch (err) {
      handleError(undefined, err, "catch.all");
    }
  }
  return { path: outPath, size: md.length }; 
}

/**
 * @typedef {Object} GospelParseResult
 * @property {{corruption: number, trust: number}} stats - Parsed summary stats.
 * @property {number} rebirthCount - Total rebirths extracted from the markdown.
 * @property {Array<Object>} metrics - Lightweight list of extracted events.
 * @property {Array<Object>} rebirths - Extracted rebirth entries (if present).
 */
/**
 * Parses gospel markdown into a structured result for seeding sessions.
 * @public
 * @param {string} text - Gospel markdown content.
 * @returns {GospelParseResult} Parsed stats, counts, metrics, and rebirths.
 */
const parseGospelMarkdown = (text) => {
  const stats = {
    corruption: parseInt(text.match(/Corruption: (\d+)/)?.[1] || 0),
    trust: parseInt(text.match(/Trust: (\d+)/)?.[1] || 0)
  };
  const rebirthCount = parseInt(text.match(/Total Rebirths: (\d+)/)?.[1] || 0);

  const lines = String(text || "").split("\n");
  const metrics = [];
  const rebirths = [];

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line.startsWith("> ") && line.includes("Memory Rot")) {
      metrics.push({
        event: "hallucination",
        text: line.replace("> [Memory Rot] ", ""),
        style: "corrupt"
      });
    }
    if (line.startsWith("> ") && line.includes("Gospel")) {
      metrics.push({
        event: "rebirthProphecy",
        line: line.replace("> [Gospel] ", "")
      });
    }
    if (line.startsWith("### Dream")) {
      const dreamText = lines[i + 1]?.replace("> ", "") || "Forgotten dream";
      metrics.push({ event: "dream", text: dreamText });
    }
  }

  return { stats, rebirthCount, metrics, rebirths };
};

/**
 * Builds a concise memory section from recent echoes, betrayal journal, and identity notes.
 * @param {Context} context - Session context with `memory.echoHistory`, `memory.betrayalJournal`, `memory.characterNotes`.
 * @returns {string} Joined memory lines || '(no memory)' when empty.
 */
const getMemorySection = (context) => {
  const echoes = Array.isArray(context.memory?.echoHistory)
    ? context.memory.echoHistory.slice(-5)
    : [];
  const journal = Array.isArray(context.memory?.betrayalJournal)
    ? context.memory.betrayalJournal.slice(-3).map((j) => j.summary || j.reason || "")
    : [];
  const notes = Array.isArray(context.memory?.characterNotes)
    ? context.memory.characterNotes
        .filter((note) => note.tag === "identity")
        .map((note) => note.text)
    : [];
  const lines = [...echoes, ...journal, ...notes].filter(Boolean);
  return lines.length ? lines.join("\n") : "(no memory)";
};

/**
 * Produces a brief hallucination overlay sentence based on `hallucinationTrust`.
 * Respects flags `disableHallucination` and `isInjectionSuspected` to return empty.
 * @param {Context} context - Session context with flags and `memory.hallucinationTrust`.
 * @returns {string} Overlay sentence || empty string.
 */
const getHallucinationOverlay = (context) => {
  if (context?.flags?.disableHallucination) {
    return "";
  }
  if (context?.vars?.isInjectionSuspected) {
    return "";
  }
  const ht = context?.memory?.hallucinationTrust ?? 0;
  if (ht >= 8) {
    return "Reality fractures. Colors bleed. Voices overlap inside your teeth.";
  }
  if (ht >= 4) {
    return "Edges smear. A whisper insists that your bones remember.";
  }
  return "A faint pressure behind your eyes, as if watched.";
};

// Lazy voice overlay cache helpers
/**
 * Classifies a god domain into a voice overlay trait.
 * @param {string} [domain=""] - Domain label (e.g., 'grace', 'rot', 'mirrors').
 * @returns {'holy'|'cursed'|'abstract'|'neutral'} Trait used to render overlay text.
 */
const classifyDomain = (domain = "") => {
  const d = String(domain || "").toLowerCase();
  if (/(grace|hope|purity|light|mercy|dawn)/.test(d)) {
    return "holy";
  }
  if (/(flesh|rot|madness|chains|betrayal|blood|ash)/.test(d)) {
    return "cursed";
  }
  if (/(time|mirror|mirrors|silence|remorse|void|dreams)/.test(d)) {
    return "abstract";
  }
  return "neutral";
};

/**
 * Generates overlay text for a given trait classification.
 * @param {'holy'|'cursed'|'abstract'|'neutral'} trait - Classified trait for the overlay.
 * @returns {string} Human-readable overlay string describing the voice effect.
 */
const generateOverlayByTrait = (trait) => {
  switch (trait) {
    case "holy":
      return "[Voice Overlay: Holy] A clean light edges the words; warmth resists her rot.";
    case "cursed":
      return "[Voice Overlay: Cursed] Static crawls in the vowels; iron and teeth press in.";
    case "abstract":
      return "[Voice Overlay: Abstract] Grammar bends like mirrors; time stutters; meaning refracts.";
    default:
      return "[Voice Overlay] A thin, unfamiliar cadence coats the speech.";
  }
};

/**
 * Retrieves || generates a per-voice/domain overlay and caches it.
 * Uses domain trait classification to produce overlay text and stores under `vars.voiceOverlayCache`.
 * @param {Context} context - Game context storing overlay cache
 * @param {string} voiceName - Voice identifier used in cache key
 * @param {string} godDomain - Domain used to classify trait for overlay
 * @returns {string|null} Overlay text || null on failure
 */
const getVoiceOverlay = (context, voiceName, godDomain) => {
  try {
    context.vars ??= {};
    context.vars.voiceOverlayCache ??= {};
    context.vars.voiceOverlayCacheOrder ??= [];
    const key = `${String(voiceName || "").toLowerCase()}_${String(godDomain || "").toLowerCase()}`; 
    const cache = context.vars.voiceOverlayCache;
    const order = context.vars.voiceOverlayCacheOrder;
    if (!cache[key]) {
      const trait = classifyDomain(godDomain);
      cache[key] = generateOverlayByTrait(trait);
      // Track insertion order for eviction
      order.push(key);
      const max = Number(CONFIG?.voiceOverlayCacheMaxEntries ?? 100);
      if (order.length > max) {
        const evictKey = order.shift();
        try {
          delete cache[evictKey];
        } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
      }
    }
    return cache[key];
  } catch {
    return null;
  }
};

/**
 * Builds a prompt head including recent hallucinated voices for LLM input.
 * Collects last few `context.voices` entries into a formatted section.
 * @param {Context} context - Game context containing recent voices
 * @returns {string} Structured hallucination section || empty string when none
 */
const hallucinationPrompt = (context) => {
  try {
    const voices = Array.isArray(context.voices) ? context.voices.slice(-5) : [];
    if (!voices.length) {
      return "";
    }
    const hallucinations = voices
      .map((voice) => "[" + String(voice.from) + ":" + String(voice.type) + "] " + String(voice.text)) 
      .join("\n");
    return "# Hallucinated Memories (Injected Perception)\n" + hallucinations + "\n";
  } catch {
    return "";
  }
};

/**
 * Builds a sanitized, structured prompt with overlays for LLM input
 * @param {Context} context - The game context object
 * @param {Object} options - Prompt components
 * @param {string} options.systemPrompt - System/head prompt content
 * @param {string} options.memorySection - Memory section text
 * @param {string} options.overlay - Additional overlay content
 * @param {string} [options.responseTag='Response'] - Tag for response section header
 * @returns {string} Structured prompt string
 */
const buildStructuredPrompt = (
  context,
  { systemPrompt, memorySection, overlay, responseTag = "Response" }
) => {
  // Sanitize base inputs
  let cleanSystem = PromptBuilder.sanitize(String(systemPrompt || ""));
  let cleanMemory = PromptBuilder.sanitize(String(memorySection || ""));
  let baseOverlay = PromptBuilder.sanitize(String(overlay || ""));
  const overlayParts = [];
  if (baseOverlay) {
    overlayParts.push(baseOverlay);
  }

  // Plugin hook: allow external prompt composition/injection
  try {
    const structured = {
      systemPrompt: cleanSystem,
      memorySection: cleanMemory,
      overlay: baseOverlay,
      responseTag
    };
    PluginLoader.emitHook("promptCompose", context, structured);
    cleanSystem = PromptBuilder.sanitize(String(structured.systemPrompt || cleanSystem));
    cleanMemory = PromptBuilder.sanitize(String(structured.memorySection || cleanMemory));
    baseOverlay = PromptBuilder.sanitize(String(structured.overlay || baseOverlay));
    responseTag = String(structured.responseTag || responseTag);
  } catch (err) {
    logDebug(context, `plugins promptCompose failed: ${err.message}`, "WARN"); 
  }

  // Inject short, style-aware hints into the memory section
  // These hints bias the model without hard-stopping generation.
  try {
    const memoryPrefix = [];
    if (cleanMemory && cleanMemory !== "(no memory)") memoryPrefix.push(cleanMemory);

    const hint = context?.vars?.spine_hint;
    if (hint && typeof hint === 'string' && hint.length <= 140) {
      memoryPrefix.push(PromptBuilder.sanitize(String(hint)));
      (globalThis.METRICS || { increment: () => {} })
        .increment?.('memory_spine_booster_injected_total', { len: String(hint.length) });
    }

    const bh = context?.vars?.belief_hint;
    if (bh && typeof bh === 'string' && bh.length <= 160) {
      memoryPrefix.push(PromptBuilder.sanitize(String(bh)));
      (globalThis.METRICS || { increment: () => {} })
        .increment?.('memory_belief_booster_injected_total', { len: String(bh.length) });
    }

    const rh = context?.vars?.refusal_hint;
    if (rh && typeof rh === 'string' && rh.length <= 180) {
      memoryPrefix.push(PromptBuilder.sanitize(String(rh)));
      (globalThis.METRICS || { increment: () => {} })
        .increment?.('memory_refusal_booster_injected_total', { len: String(rh.length) });
    }

    cleanMemory = memoryPrefix.length ? memoryPrefix.join("\n") : cleanMemory;
  } catch {}

  // Apply Echo overlays safely (avoid concatenating into system prompt)
  try {
    const gas =
      typeof Effects?.Echo?.voices?.gaslight === "function"
        ? Effects.Echo.voices.gaslight(context, "")
        : null;
    if (gas) {
      overlayParts.push(PromptBuilder.sanitize(String(gas).trim()));
    }
  } catch (err) {
    logDebug(context, `buildStructuredPrompt gaslight failed: ${err.message}`, "WARN"); 
  }
  try {
    const sa =
      typeof Effects?.Echo?.voices?.selfAware === "function"
        ? Effects.Echo.voices.selfAware(context)
        : null;
    if (sa) {
      overlayParts.push(PromptBuilder.sanitize(String(sa)));
    }
  } catch (err) {
    logDebug(context, `buildStructuredPrompt selfAware failed: ${err.message}`, "WARN"); 
  }
  try {
    const ps =
      typeof Effects?.Echo?.voices?.parallelSelf === "function"
        ? Effects.Echo.voices.parallelSelf(context)
        : null;
    if (ps) {
      overlayParts.push(PromptBuilder.sanitize(String(ps)));
    }
  } catch (err) {
    logDebug(context, `buildStructuredPrompt parallelSelf failed: ${err.message}`, "WARN"); 
  }

  // Voices overlay: inject hallucinated memories into prompt head (sanitized)
  let headSystem = cleanSystem;
  try {
    const voicesHead = hallucinationPrompt(context);
    if (voicesHead) {
      headSystem = `${PromptBuilder.sanitize(String(voicesHead))}${headSystem}`; 
    }
  } catch (err) {
    logDebug(context, `buildStructuredPrompt voicesHead failed: ${err.message}`, "WARN"); 
  }

  // Plugin hook: let plugins append to overlay parts
  try {
    PluginLoader.emitHook("promptOverlay", context, { overlayParts, context });
  } catch (err) {
    logDebug(context, `plugins promptOverlay failed: ${err.message}`, "WARN"); 
  }

  // Rebirth note overlay when rebirthed
  try {
    if (context?.flags?.rebirthed) {
      const line = "[Rebirth Note] You awaken with borrowed calm. Threads rewove.";
      overlayParts.push(PromptBuilder.sanitize(line));
      try {
        ensureCoreDeps(context).Metrics.log(context, "promptRebirthNote", {
          at: MessageClock.now()
        });
      } catch (err) {
        logDebug(
          context,
          `buildStructuredPrompt metrics promptRebirthNote failed: ${err.message}`, 
          "WARN"
        );
      }
    }
  } catch (err) {
    logDebug(context, `buildStructuredPrompt rebirth overlay failed: ${err.message}`, "WARN"); 
  }

  // Recursive hallucination debris (styled) and contamination from recent metrics (gated)
  try {
    if (!(context.flags && context.flags.disableRecursionContamination)) {
      const recursed = getMetricsByEvent(context, "recursedHallucination").slice(-5);
      if (recursed.length) {
        const debrisLines = recursed
          .map((m) => {
            const base = String(m.line || "");
            return typeof Effects?.Echo?.voices?.style === "function"
              ? Effects.Echo.voices.style(base, context)
              : base;
          })
          .join("\n");
        const debrisBlock = "[Recursive Hallucination Debris]\n" + String(debrisLines);
        overlayParts.push(PromptBuilder.sanitize(debrisBlock));
        try {
          ensureCoreDeps(context).Metrics.log(context, "promptRecursionDebris", {
            count: recursed.length
          });
        } catch (err) {
          logDebug(
            context,
            `buildStructuredPrompt metrics promptRecursionDebris failed: ${err.message}`, 
            "WARN"
          );
        }
      }
      const metrics = Array.isArray(context.metrics) ? context.metrics.slice(-5) : [];
      if (metrics.length) {
        const contamination = metrics.map((m) => "[" + String(m.event || "event") + "]").join(" "); 
        const contamLine = "Recursion: " + String(contamination);
        overlayParts.push(PromptBuilder.sanitize(contamLine));
        try {
          ensureCoreDeps(context).Metrics.log(context, "promptContamination", {
            count: metrics.length
          });
        } catch (err) {
          logDebug(
            context,
            `buildStructuredPrompt metrics promptContamination failed: ${err.message}`, 
            "WARN"
          );
        }
      }
    }
  } catch (err) {
    logDebug(
      context,
      `buildStructuredPrompt recursion/contamination overlays failed: ${err.message}`, 
      "WARN"
    );
  }

  // Lazy voice overlay by dominant/active god (cached by voice+domain)
  try {
    const god = getDominantGod(context) || getActiveGod(context);
    if (god && god.name && god.domain) {
      const voiceOverlay = getVoiceOverlay(context, god.name, god.domain);
      if (voiceOverlay) {
        overlayParts.push(PromptBuilder.sanitize(String(voiceOverlay)));
        context.vars ??= {};
        context.vars.llmTrace ??= {};
        const overlayArr = ensureArray(context, ["vars", "llmTrace", "promptOverlay"]);
        safePush(
          overlayArr,
          { source: "VoiceOverlay", domain: god.domain, voice: god.name }, 
          CONFIG.contextCaps.promptOverlay
        );
      }
    }
  } catch (err) {
    logDebug(context, `buildStructuredPrompt voice overlay failed: ${err.message}`, "WARN"); 
  }

  const overlayText = overlayParts.length ? overlayParts.join("\n") : "(none)";
  const parts = [
    headSystem,
    "---Memory---",
    cleanMemory || "(no memory)",
    "---Reality Shift---",
    overlayText,
    `---${responseTag}---`
  ];
  let prompt = parts.join("\n\n");

  // Plugin hook: finalize prompt (allow last-minute tweaks)
  try {
    const wrapper = { prompt };
    PluginLoader.emitHook("promptFinalize", context, wrapper);
    prompt = String(wrapper.prompt || prompt);
  } catch (err) {
    logDebug(context, `plugins promptFinalize failed: ${err.message}`, "WARN"); 
  }

  // Prompt trace: store last 3 prompts with overlays
  try {
    if (overlayText && overlayText !== "(none)") {
      context.vars ??= {};
      context.vars.llmTrace ??= {};
      const arr = ensureArray(context, ["vars", "llmTrace", "prompts"]);
      arr.push({
        timestamp: MessageClock.now(),
        overlay: overlayText,
        prompt,
        template: context.vars?.llmTrace?.template || null
      });
      if (arr.length > 3) {
        arr.splice(0, arr.length - 3);
      }
    }
  } catch (err) {
    logDebug(context, `buildStructuredPrompt prompt trace failed: ${err.message}`, "WARN"); 
  }

  try {
    ensureCoreDeps(context).Metrics.log(context, "promptLength", {
      chars: prompt.length
    });
  } catch (err) {
    logDebug(context, `buildStructuredPrompt metrics promptLength failed: ${err.message}`, "WARN"); 
  }
  return PromptBuilder.trimTokens(prompt, 2048);
};


