const PROMPT_TEMPLATES = (globalThis?.CONFIG?.prompts?.templates) ?? {};

// Debug shim: render a single template with input
const renderTemplate = (name, input) => {
  try {
    const safeName = String(name || "").trim();
    const templates = CONFIG?.prompts?.templates || {};
    const tpl = typeof templates[safeName] === "function" ? templates[safeName] : null;
    const normalized = normalizeInput(input);
    if (!tpl) {
      return "[Template \"" + String(safeName) + "\" not found]";
    }
    try {
      recordTemplateTrace?.({ vars: {} }, safeName);
    } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
    return tpl(normalized);
  } catch (err) {
    return "Template error (\"" + String(name) + "\"): " + String((err && err.message) || err); 
  }
};

