// === RECENT LINES MAP (per-user) ===
// Message-count TTL for recency
const RECENT_LINES_TTL_MESSAGES = (globalThis?.CONFIG?.recentLines?.ttlMessages ?? 20);

/**
 * Tracks recently generated lines with per-message TTL and bounded size.
 * Prevents immediate repeats and trims/cleans in batches to avoid O(n) hot paths.
 * @class RecentLinesMap
 * @param {number} [ttlMessages] - Message TTL before an entry expires.
 * @param {number} [maxSize] - Max unique line hashes to retain.
 */
class RecentLinesMap {
  constructor(ttlMessages = RECENT_LINES_TTL_MESSAGES, maxSize = RECENT_LINES_MAX) {
    this.ttlMessages = Number(ttlMessages) || 20;
    this.maxSize = Number(maxSize) || 500;
    this.map = new Map();
    this.opsSinceCleanup = 0;
    this.cleanupInterval = Number((globalThis?.CONFIG?.recentLines?.cleanupInterval ?? 50));
    // Batch limits for gradual cleanup and trimming
    this.cleanupBatchSize = Number(CONFIG?.recentLines?.cleanupBatch ?? 25);
    this.trimBatchSize = Number(CONFIG?.recentLines?.trimBatch ?? 25);
  }

  set(line, currentMessageIndex = 0) {
    const hash = hashPrompt(line);
    this.map.set(hash, Number(currentMessageIndex) || 0);
    this.opsSinceCleanup++;
    if (this.opsSinceCleanup >= this.cleanupInterval) {
      this.cleanup(currentMessageIndex);
      this.opsSinceCleanup = 0;
    }
    this.trim();
  }

  has(line, currentMessageIndex = 0) {
    const hash = hashPrompt(line);
    const idx = this.map.get(hash);
    if (typeof idx === "number") {
      const nowIndex = Number(currentMessageIndex) || 0;
      if (this.ttlMessages > 0 && nowIndex - idx > this.ttlMessages) {
        this.map.delete(hash);
        return false;
      }
      return true;
    }
    // Opportunistic batch cleanup only occasionally to avoid O(n) per call
    this.opsSinceCleanup++;
    if (this.opsSinceCleanup >= this.cleanupInterval) {
      this.cleanup(currentMessageIndex);
      this.opsSinceCleanup = 0;
    }
    return false;
  }

  cleanup(currentMessageIndex = 0) {
    const nowIndex = Number(currentMessageIndex) || 0;
    let deletes = 0;
    for (const [line, index] of this.map.entries()) {
      if (this.ttlMessages > 0 && nowIndex - index > this.ttlMessages) {
        this.map.delete(line);
        deletes++;
        if (deletes >= this.cleanupBatchSize) {
          break;
        }
      }
    }
  }

  trim() {
    if (this.map.size <= this.maxSize) {
      return;
    }
    const entries = Array.from(this.map.entries()).sort((a, b) => a[1] - b[1]);
    const over = entries.length - this.maxSize;
    const limit = Math.min(over, this.trimBatchSize);
    for (let i = 0; i < limit; i++) {
      this.map.delete(entries[i][0]);
    }
  }

  clear() {
    this.map.clear();
  }
  size(currentMessageIndex = 0) {
    // Batch cleanup to avoid O(n) on every call
    this.opsSinceCleanup++;
    if (this.opsSinceCleanup >= this.cleanupInterval) {
      this.cleanup(currentMessageIndex);
      this.opsSinceCleanup = 0;
    }
    return this.map.size;
  }
}

// === PROMPT CACHE (FIX: Improved with proper timestamp tracking) ===
class LRUCache {
  constructor(
    maxSize = (globalThis?.CONFIG?.cache?.maxSize ?? 500),
    ttlMessages = (globalThis?.CONFIG?.cache?.ttlMessages ?? 50)
  ) {
    this.maxSize = Number(maxSize) || 500;
    this.ttlMessages = Number(ttlMessages) || 50;
    this.map = new Map();
  }
  set(key, value, currentMessageIndex = 0) {
    const nowIndex = Number(currentMessageIndex) || 0;
    if (this.map.has(key)) {
      this.map.delete(key);
    }
    this.map.set(key, { value, index: nowIndex });
    if (this.map.size > this.maxSize) {
      this.evict();
    }
  }
  get(key, currentMessageIndex = 0) {
    const entry = this.map.get(key);
    if (!entry) {
      return null;
    }
    const nowIndex = Number(currentMessageIndex) || 0;
    if (this.ttlMessages > 0 && nowIndex - entry.index > this.ttlMessages) {
      this.map.delete(key);
      return null;
    }
    this.map.delete(key);
    this.map.set(key, { value: entry.value, index: nowIndex }); 
    return entry.value;
  }
  evict() {
    const removeCount = Math.max(1, Math.ceil(this.maxSize * 0.1));
    for (let i = 0; i < removeCount; i++) {
      const oldestKey = this.map.keys().next().value;
      if (oldestKey === undefined) {
        break;
      }
      this.map.delete(oldestKey);
    }
  }
  clear() {
    this.map.clear();
  }
  size() {
    return this.map.size;
  }
}
/**
 * LRU cache for prompt results keyed by hash with message-index TTL.
 * Capacity: `PROMPT_CACHE_MAX`, TTL in messages: `PROMPT_CACHE_TTL_MESSAGES`.
 */
const promptCache = new LRUCache(
  (globalThis?.CONFIG?.cache?.maxSize ?? 500),
  (globalThis?.CONFIG?.cache?.ttlMessages ?? 50)
);
if ((typeof IS_TEST_ENV !== 'undefined') && IS_TEST_ENV) {
  try {
    promptCache._getStats = function () {
      try {
        return {
          size: this.size(),
          maxSize: this.maxSize,
          ttlMessages: this.ttlMessages,
          keys: Array.from(this.map.keys())
        };
      } catch {
        return { size: this.size() }; 
      }
    };
  } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
}

