// Inlined flavor helpers (monolith)
/**
 * Generates a short flavored line using budgeted engines (echo, suspicion, wake, etc.).
 * Applies per-engine turn budgets, logs metrics, and falls back safely when over budget.
 * @param {Context} context - Runtime context used for budgets and RNG.
 * @param {string|Object} prompt - Prompt text || structured parts.
 * @param {Object} [options={}] - Flavor options like `engine`, `purpose`, `tone`.
 * @param {Object} [core={}] - Injected core fns for testing (`generateLine`, `getRandomFallback`, `logMetric`).
 * @returns {Promise<string>} Generated line || fallback.
 */
/**
 * Generates a short flavored line using budgeted engines (echo, suspicion, wake, etc.).
 * Applies per-engine turn budgets, logs metrics, and falls back safely when over budget.
 * @param {Context} context - Runtime context used for budgets and RNG.
 * @param {string|Object} prompt - Prompt text || structured parts.
 * @param {Object} [options={}] - Flavor options like `engine`, `purpose`, `tone`.
 * @param {Object} [core={}] - Injected core fns for testing (`generateLine`, `getRandomFallback`, `logMetric`).
 * @returns {Promise<string>} Generated line || fallback.
 */
async function generateFlavorLine(context, prompt, options = {}, core = {}) {
  const generateLineFn = core.generateLine || generateLine;
  const getRandomFallbackFn = core.getRandomFallback || getRandomFallback;
  const logMetricFn = core.logMetric || logMetric;

  options = options || {};
  const engine = String(options.engine || options.purpose || "default").toLowerCase();

  context.vars ??= {};
  context.vars.llmFlavorTurnBudget ??= {
    summary: 1,
    prophecy: 1,
    echo: 2,
    wake: 1,
    suspicion: 1,
    open: 1,
    confession: 1,
    god_whisper: 1,
    nsfw: 1,
    hallucination: 1,
    intent: 1,
    default: 2
  };
  context.vars.llmFlavorUsage ??= {};
  context.vars.llmFlavorSkips ??= 0;

  const budget =
    context.vars.llmFlavorTurnBudget[engine] ?? context.vars.llmFlavorTurnBudget.default;
  const used = context.vars.llmFlavorUsage[engine] ?? 0;

  if (options.critical === true) {
    const line = await generateLineFn(context, prompt, options.llmOptions);
    context.vars.llmFlavorUsage[engine] = used + 1;
    try {
      logMetricFn(context, "llmFlavorCall", { engine, critical: true });
    } catch (err) {
      handleError(undefined, err, "catch.all");
    }
    return line;
  }

  if (used >= budget) {
    context.vars.llmFlavorSkips += 1;
    try {
      logMetricFn(context, "llmFlavorSkip", { engine });
    } catch (err) {
      handleError(undefined, err, "catch.all");
    }
    return getRandomFallbackFn(context);
  }

  // Fast path: in dry-run, skip LLM entirely for non-critical flavor
  if ((CONFIG.dryRun.enabled || context?.flags?.dryRun) && options.critical !== true) {
    context.vars.llmFlavorUsage[engine] = used + 1;
    try {
      logMetricFn(context, "llmFlavorSkip", {
        engine,
        reason: "dryRunFastPath"
      });
    } catch (err) {
      handleError(undefined, err, "catch.all");
    }
    return getRandomFallbackFn(context);
  }

  const line = await generateLineFn(context, prompt, options.llmOptions);
  context.vars.llmFlavorUsage[engine] = used + 1;
  try {
    logMetricFn(context, "llmFlavorCall", { engine, critical: false });
  } catch (err) {
    handleError(undefined, err, "catch.all");
  }
  return line;
}

/**
 * Summarizes per-engine LLM flavor usage and current turn budget.
 * @param {Context} context - Runtime context storing flavor counters.
 * @returns {{flavorCallsByEngine:Object<string,number>, flavorSkips:number, totalFlavorCalls:number, turnBudget:Object<string,number>}}
 *          Aggregated usage metrics and budgets.
 */
const getLLMBudgetSummary = (context) => {
  context.vars ??= {};
  const usage = context.vars.llmFlavorUsage || {};
  const budget = context.vars.llmFlavorTurnBudget || {};
  const flavorSkips = toNum(context.vars.llmFlavorSkips);

  const flavorCallsByEngine = {};
  for (const [key, val] of Object.entries(usage)) {
    flavorCallsByEngine[key] = toNum(val);
  }

  const totalFlavorCalls = Object.values(flavorCallsByEngine).reduce((a, b) => a + b, 0);
  return {
    flavorCallsByEngine,
    flavorSkips,
    totalFlavorCalls,
    turnBudget: budget
  };
};

/**
 * Hashes a prompt string to a reproducible cache key.
 * Uses a fast non-cryptographic hash for memoization only.
 * @param {string} prompt - Prompt content.
 * @returns {string} Deterministic hash key.
 */
const hashPrompt = (prompt) => {
  // Persist maps across calls using function properties (no globals required)
  const byCanonical = (hashPrompt._byCanonical ||= new Map());
  const byHash = (hashPrompt._byHash ||= new Map());
  const collisionCount = (hashPrompt._collisionCount ||= new Map());
  // Lightweight hashing metrics
  const stats = (hashPrompt._stats ||= { totalCalls: 0, collisionEvents: 0 });
  stats.totalCalls += 1;

  const canonicalize = (value) => {
    if (value === null || value === undefined) {
      return String(value);
    }
    const t = typeof value;
    if (t === "string") {
      return TextUtils.normalize(value);
    }
    if (t === "number" || t === "boolean" || t === "bigint") {
      return String(value);
    }
    if (t === "symbol") {
      return value.description || value.toString();
    }
    if (t === "function") {
      return value.name ? ("[fn:" + String(value.name) + "]") : "[fn]"; 
    }
    if (Array.isArray(value)) {
      return "[" + value.map(canonicalize).join(",") + "]"; 
    }
    if (t === "object") {
      const keys = Object.keys(value).sort();
      const entries = keys.map((k) => String(k) + ":" + canonicalize(value[k]));
      return "{" + entries.join(",") + "}"; 
    }
    try {
      return JSON.stringify(value);
    } catch {
      return String(value);
    }
  };

  // Canonicalize input to ensure structurally equivalent prompts hash the same
  const canonical = canonicalize(prompt);
  const existing = byCanonical.get(canonical);
  if (existing) {
    return existing;
  }

  // Choose hashing algorithm: default to 'sha256' for consistency across environments.
  // Allows override via `URGA_HASH_ALGO`. If the requested algorithm is unavailable
  // in this Node build, we fall back to a safe, widely available hash (sha1).
  const algo = (process?.env?.URGA_HASH_ALGO || "sha256").toLowerCase();
  let baseHash;
  try {
    baseHash = crypto.createHash(algo).update(canonical).digest("hex");
  } catch {
    // Fallback path: use 'sha1' when the requested digest is unsupported
    // to ensure deterministic caching and avoid runtime failures.
    baseHash = crypto.createHash("sha1").update(canonical).digest("hex");
  }

  // Collision handling: if a different canonical already claimed this base hash, add a counter suffix
  const claimed = byHash.get(baseHash);
  let finalHash = baseHash;
  if (claimed && claimed !== canonical) {
    let suffixIndex = Number(collisionCount.get(baseHash) || 1);
    // Find the next available suffixed key
    while (
      byHash.has(String(baseHash) + "." + String(suffixIndex)) &&
      byHash.get(String(baseHash) + "." + String(suffixIndex)) !== canonical
    ) {
      suffixIndex += 1;
    }
    finalHash = String(baseHash) + "." + String(suffixIndex);
    collisionCount.set(baseHash, suffixIndex);
    try {
      hashPrompt._stats && (hashPrompt._stats.collisionEvents += 1);
    } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
  }

  // Record mappings for determinism across calls
  byCanonical.set(canonical, finalHash);
  byHash.set(finalHash, canonical);

  return finalHash;
};

/**
 * Sets a prompt result into the cache with current message index for TTL.
 * @param {string} hash - Cache key derived from `hashPrompt(prompt)`.
 * @param {any} value - Result payload to cache.
 * @param {number} [currentMessageIndex=0] - Message index for TTL expiration.
 * @returns {void}
 */
const setPromptCache = (hash, value, currentMessageIndex = 0) => {
  promptCache.set(hash, value, currentMessageIndex);
};

/**
 * Retrieves a cached prompt result if not expired per message-index TTL.
 * @param {string} hash - Cache key.
 * @param {number} [currentMessageIndex=0] - Current message index for TTL check.
 * @returns {any|undefined} Cached value || undefined if missing/expired.
 */
const getPromptCache = (hash, currentMessageIndex = 0) => {
  return promptCache.get(hash, currentMessageIndex);
};

// Tiny retry helper for transient LLM/API hiccups
async function retryWithBackoff(fn, maxRetries = 3, delay = 250) {
  for (let i = 0; i < maxRetries; i++) {
    try {
      const res = await Promise.resolve().then(fn).catch((err)=>Logger.error(err));
      return res;
    } catch (err) {
      if (i === maxRetries - 1) {
        throw err;
      }
      await new Promise((res) => MessageClock.setTimeoutCounts(res, delay * (i + 1)));
    }
  }
}

// === PER-USER LLM QUEUE (FIX: Added locking) ===
/**
 * Enqueues a per-user LLM prompt function for serialized processing.
 * Captures meta (prompt hash, purpose/tone, queue length) for metrics and analysis.
 * @param {Context} context - Session context maintaining the per-user queue.
 * @param {Function} promptFn - Function returning a Promise for LLM call result.
 * @param {Object} [meta={}] - Optional metadata (`kind`, `promptText`, `purpose`, `tone`).
 * @returns {Promise<string>} Resolves with LLM result once processed.
 */
async function queueLLM(context, promptFn, meta = {}) {
  context._llmQueue ??= [];
  // Capture queued prompt text for analysis when available
  try {
    const text = typeof meta?.promptText === "string" ? meta.promptText : null;
    if (text) {
      context.vars ??= {};
      const queued = ensureArray(context, ["vars", "llmQueuedPrompts"]);
      const entry = {
        ts: MessageClock.now(),
        turn: toNum(context?.turn),
        messageCount: toNum(context?.memory?.messageCount),
        kind: meta?.kind || "unknown",
        text,
        hash: (() => {
          try {
            return hashPrompt(text);
          } catch {
            return null;
          }
        })(),
        overlay:
          meta?.purpose || meta?.tone
            ? { purpose: meta?.purpose || null, tone: meta?.tone || null } 
            : undefined,
        queueLen: context._llmQueue.length + 1
      };
      safePush(queued, entry, CONFIG.contextCaps.llmQueuedPrompts);
      try {
        ensureCoreDeps(context).Metrics.log(context, "llm_prompt_queued", {
          kind: entry.kind,
          queue_len: entry.queueLen
        });
      } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
    }
  } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
  return new Promise((resolve, reject) => {
    context._llmQueue.push({ promptFn, resolve, reject, meta });
    if (!context._llmProcessingPromise) {
      context._llmProcessingPromise = processUserLLMQueue(context);
    }
  });
}

/**
 * Consumes per-message LLM budget, optionally marked as critical.
 * Logs attempts, skips, and consumption; returns false if non-critical over budget.
 * @param {Context} context - Session context storing counters.
 * @param {{critical?:boolean}} [options] - Options for budget mode.
 * @returns {boolean} true if allowed to proceed; false otherwise.
 */
const consumeLLMBudget = (context, { critical = false } = {}) => {
  context.vars ??= {};
  const attempted = (context.vars.llmCalls || 0) + 1;
  context.vars.llmCalls = attempted;
  try {
    ensureCoreDeps(context).Metrics.log(context, "llm_budget_attempt", {
      used: attempted,
      critical
    });
  } catch (err) {
    handleError(context, err, "metrics.llm_budget_attempt");
  }
  if (attempted > MAX_LLM_CALLS_PER_MESSAGE && !critical) {
    try {
      ensureCoreDeps(context).Metrics.log(context, "llm_budget_skip_noncritical", {
        used: attempted
      });
    } catch (err) {
      handleError(context, err, "metrics.llm_budget_skip_noncritical");
    }
    return false;
  }
  try {
    ensureCoreDeps(context).Metrics.log(context, "llm_budget_consume", {
      used: attempted,
      critical
    });
  } catch (err) {
    handleError(context, err, "metrics.llm_budget_consume");
  }
  return true;
};
/**
 * Enqueues an LLM call on the non-critical budget path.
 * Guards with the budget lock and returns `null` if budget is exceeded.
 * @param {Context} context - Session context and budget state.
 * @param {Function} promptFn - Function that triggers the LLM prompt.
 * @param {Object} [meta={}] - Optional metadata for logging.
 * @returns {Promise<string|null>} Result string || null when skipped.
 */
async function queueLLMNonCritical(context, promptFn, meta = {}) {
  const allowed = await withLLMBudgetLock(context, async () =>
    consumeLLMBudget(context, { critical: false })
  );
  if (!allowed) {
    try {
      ensureCoreDeps(context).Metrics.log(context, "llm_noncritical_budget_skip");
    } catch (err) {
      handleError(context, err, "metrics.llm_noncritical_budget_skip");
    }
    return null;
  }
  try {
    ensureCoreDeps(context).Metrics.log(context, "llm_noncritical_enqueued");
  } catch (err) {
    handleError(context, err, "metrics.llm_noncritical_enqueued");
  }
  return queueLLM(
    context,
    () =>
      retryWithBackoff(
        () => Promise.resolve().then(promptFn),
        CONFIG.llm.maxRetries,
        CONFIG.llm.retryBaseMs
      ),
    { kind: "non_critical", ...meta } 
  ).catch((err)=>Logger.error(err));
}

/**
 * Processes the per-user LLM queue sequentially with safe state cleanup.
 * @param {Context} context - Session context where queue and processing flags live.
 * @returns {Promise<void>} Resolves when the current queue batch completes.
 */
async function processUserLLMQueue(context) {
  context.vars ??= {};

  // Coalesce: assign the actual runner promise once and return it
  const runner = async () => {
    // Token-bucket rate limiting aligned to LLM_RATE_LIMIT_PER_SECOND
    context.vars.llmQueueTokens ??= IS_TEST_ENV ? 1000 : LLM_RATE_LIMIT_PER_SECOND;
    context.vars.llmQueueLastRefill ??= MessageClock.now();
    const refill = () => {
      const now = MessageClock.now();
      const elapsedSec = (now - context.vars.llmQueueLastRefill) / 1000;
      const add = Math.floor(elapsedSec * LLM_RATE_LIMIT_PER_SECOND);
      if (add > 0) {
        context.vars.llmQueueTokens = Math.min(
          LLM_RATE_LIMIT_PER_SECOND,
          context.vars.llmQueueTokens + add
        );
        context.vars.llmQueueLastRefill = now;
      }
    };

    try {
      context._llmQueue ??= [];
      while (context._llmQueue.length > 0) {
        refill();
        if (context.vars.llmQueueTokens < 1 && !IS_TEST_ENV) {
          // Wait with jitter to avoid thundering herd
          const rng = context?.rng || Math.random;
          const waitMs = 80 + Math.floor(rng() * 120);
          try {
            ensureCoreDeps(context).Metrics.log(context, "llm_queue_rate_wait", {
              wait_ms: waitMs,
              queue_len: context._llmQueue.length
            });
          } catch (err) {
            handleError(context, err, "metrics.llm_queue_rate_wait");
          }
          await sleepUnref(waitMs);
          continue;
        }

        const { promptFn, resolve, reject, meta } = context._llmQueue[0];
        try {
          logDebug(context, "LLM Queue: Executing promptFn", "DEBUG");
          context.vars.llmQueueTokens -= 1;
          const startMs = MessageClock.now();
          let timeoutHit = false;
          const fallback = getRandomFallback(context);
          const result = await withTimeout(
            Promise.resolve(promptFn()).catch(() => fallback),
            MAX_RESPONSE_TIME_MS,
            fallback,
            () => {
              timeoutHit = true;
            }
          );
          try {
            ensureCoreDeps(context).Metrics.log(context, "llm_queue_exec", {
              response_time: MessageClock.now() - startMs,
              timeout: timeoutHit,
              kind: meta && meta.kind ? meta.kind : "critical"
            });
          } catch (err) {
            handleError(context, err, "metrics.llm_queue_exec");
          }
          resolve(result);
        } catch (err) {
          logDebug(context, `processUserLLMQueue error: ${err.message}`, "ERROR"); 
          reject(err);
        } finally {
          context._llmQueue.shift();
        }
      }
    } finally {
      // Safe cleanup: mark idle and clear the shared promise reference
      context._llmProcessing = false;
      context._llmProcessingPromise = null;
    }
  };

  const promise = context._llmProcessingPromise || (context._llmProcessingPromise = runner());
  context._llmProcessing = true;
  return promise;
}

// FIX: Changed AND to OR for more fluid progression
/**
 * Determines whether trust gain is allowed based on time || message cooldowns.
 * Uses last trust gain timestamp and message index to gate additions.
 * @param {Context} context - Runtime context with memory fields.
 * @param {number} [cooldownMinutes=TRUST_GAIN_COOLDOWN_MINUTES] - Minimum minutes between gains.
 * @param {number} [minMessages=TRUST_GAIN_MIN_MESSAGES] - Minimum messages between gains.
 * @returns {boolean} true if either cooldown has expired.
 */
const canGainTrust = (
  context,
  cooldownMinutes = TRUST_GAIN_COOLDOWN_MINUTES,
  minMessages = TRUST_GAIN_MIN_MESSAGES
) => {
  const now = MessageClock.now();
  const lastTime = context.memory.lastTrustGainTimestamp || 0;
  const lastMsg = context.memory.lastTrustGainMessageCount || 0;

  const timePassed = now - lastTime >= cooldownMinutes * 60 * 1000;
  const msgsPassed = context.memory.messageCount - lastMsg >= minMessages;

  return timePassed || msgsPassed; // FIX: Changed from && to ||
};

/**
 * Convenience wrapper to increase trust with a labeled Ur'ga reason.
 * @param {Context} context - Runtime context.
 * @param {number} [amount=1] - Trust delta to add.
 * @param {string} [reason="Unspecified"] - Human-readable reason label.
 * @returns {boolean} true if trust was increased, false if blocked by cooldown.
 */
const addUrgaTrust = (context, amount = 1, reason = "Unspecified") => {
  return MemoryManager.addTrust(context, amount, "Ur'ga: " + String(reason));
};

// FIX: Added rate limiting
/**
 * Token-bucket style rate limiter for LLM calls (leaky bucket)
 * @param {Context} context - The game context object
 * @returns {boolean} true if a token is available; false otherwise
 */
const checkLLMLeakyBucket = (context) => {
  if (IS_TEST_ENV) {
    context.vars ??= {};
    context.vars.llmLeakyTokens ??= 1;
    return true;
  }
  const now = MessageClock.now();
  const capacity =
    context.vars.llmCapacity ?? LLM_LEAKY_BUCKET_CAPACITY_MULT * LLM_RATE_LIMIT_PER_SECOND;
  const leakRate = context.vars.llmLeakRatePerSec ?? LLM_LEAKY_BUCKET_LEAK_RATE_PER_SECOND;
  context.vars.llmLeakyTokens ??= capacity;
  context.vars.llmLeakyLastTick ??= now;

  const elapsedSec = Math.max(0, (now - context.vars.llmLeakyLastTick) / 1000);
  const leaked = leakRate * elapsedSec;
  context.vars.llmLeakyTokens = Math.max(
    0,
    Math.min(capacity, context.vars.llmLeakyTokens + leaked)
  );
  context.vars.llmLeakyLastTick = now;

  if (context.vars.llmLeakyTokens < 1) {
    logDebug(
      context,
      "LLM leaky-bucket limit: tokens=" + context.vars.llmLeakyTokens.toFixed(2) + "/" + capacity,
      "WARN"
    );
    return false;
  }

  context.vars.llmLeakyTokens -= 1;
  return true;
};

// === LLM TRACE LOGGER (optional) ===
/**
 * Logs an LLM prompt/response exchange to trace sink || file
 * @param {Context} context - The game context object
 * @param {string} prompt - The sanitized/structured prompt sent to LLM
 * @param {string} llmResponse - The LLM response string
 * @returns {void}
 */
const logLLMExchange = async (context, prompt, llmResponse) => {
  try {
    context.vars ??= {};
    context.vars.llmTrace ??= {};
    const trace = context.vars.llmTrace;
    const payload = {
      timestamp: new Date().toISOString(),
      userInput: trace.userInput ?? null,
      sanitized: trace.sanitized ?? null,
      hallucinated: trace.hallucinated ?? null,
      intent: trace.intent ?? null,
      prompt,
      llmResponse,
      overlay: trace.promptOverlay ?? null
    };
    try {
      Prophecy.observe(context, prompt);
    } catch (err) {
      handleError(context, err, "prophecy.observe");
    }
    try {
      Prophecy.observe(context, llmResponse);
    } catch (err) {
      handleError(context, err, "prophecy.observe");
    }
    if (typeof context.vars.llmTraceSink === "function") {
      context.vars.llmTraceSink(payload);
    } else if (context.vars && context.vars.llmTraceFilePath) {
      try {
        await IOService.appendFile(context.vars.llmTraceFilePath, JSON.stringify(payload) + "\n", "utf8");
      } catch (e) {
        // swallow file logging errors
      }
    } else {
      logger.debug("LLM_TRACE", payload);
    }
  } catch (err) {
    logDebug(context, `LLM trace logging error: ${err?.message || err}`, "WARN"); 
  }
};

// Centralized LLM Service with retries, budgeting, rate limiting, and logging
/**
 * Centralized LLM service handling retries, budgeting, rate limits, and logging
 * @class
 */
class LLMService {
  /**
   * @param {Context} context - The game context object
   */
  constructor(context) {
    this.context = context;
    this.dryRunService = new DryRunService(CONFIG.dryRun);
  }
  // Convenience static helper to allow LLMService.call(ctx, input, options)
  static async call(context, input, options = {}) {
    try {
      if (context?.llmService && typeof context.llmService.call === 'function') {
        return await context.llmService.call(input, options);
      }
    } catch {}
    const svc = new LLMService(context);
    return await svc.call(input, options);
  }
  /**
   * Calls the LLM with sanitization, caching, rate limiting, and retries
   * @param {string} text - The prompt text to send
   * @param {Object} [options={}] - Call options
   * @param {boolean} [options.critical=true] - Whether to use critical budget path
   * @returns {Promise<string>} Resolved LLM response || fallback
   */
  async call(text, options = {}) {
    const context = this.context;
    context.io?.events?.emit && context.io.events.emit("llm.call.start", { text, options });
    const safe0 = safePromptInput(text, context.vars?.sanitizationMode || "default");
    const safe = applyMemoryPrefix(context, safe0, options?.model);
    const hash = hashPrompt(safe);
    const cached = getPromptCache(hash, context?.memory?.messageCount || 0);
    if (cached) {
      context.io?.events?.emit && context.io.events.emit("llm.call.cache_hit", { hash });
      return cached;
    }

    // Check for dry run mode
    if (CONFIG.dryRun.enabled || context?.flags?.dryRun) {
      const syntheticResponse = await this.dryRunService.generateResponse(safe, context, options);
      if (!validateLLMResponse(syntheticResponse, context)) {
        logDebug(context, "LLM response failed validation (dry-run)", "WARN");
        context.io?.events?.emit &&
          context.io.events.emit("llm.call.invalid_response", {
            mode: "dry_run"
          });
        return await getRandomFallback(context);
      }
      setPromptCache(hash, syntheticResponse, context?.memory?.messageCount || 0);
      context.io?.events?.emit &&
        context.io.events.emit("llm.call.dry_run", {
          text: safe,
          response: syntheticResponse
        });
      logDebug(context, "Dry run response: " + syntheticResponse.slice(0, 100) + "...", "INFO"); 
      return syntheticResponse;
    }

    {
      context.__llmRateMutex = context.__llmRateMutex || {
        locked: false,
        waiters: []
      };
      const __allowed = await runWithMutex(
        context.__llmRateMutex,
        async () => checkLLMLeakyBucket(context),
        {
          maxWaiters: Number(CONFIG?.llm?.mutexMaxWaiters ?? 1000),
          timeoutMs: Number(CONFIG?.llm?.mutexWaitTimeoutMs ?? 0),
          onDrop: (info) => {
            try {
              ensureCoreDeps(context).Metrics.log(context, "llmRateMutexDrop", info || {});
            } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
          }
        }
      );
      if (!__allowed) {
        context.io?.events?.emit && context.io.events.emit("llm.call.rate_limited", {});
        return await getRandomFallback(context);
      }
    }

    const critical = options?.critical !== false;

    // Tenant token budget pre-check (race-tolerant)
    let __tenantBudget = null;
    let __tenantBudgetMonthly = null;
    let __tenantBudgetRolling = null;
    let __tenantId = '';
    try { __tenantId = String(context?.vars?.tenant || context?.vars?.tenantId || context?.vars?.client_id || context?.vars?.user || '').trim(); } catch {}
    try {
      const lim = Number(process?.env?.TENANT_TOKENS_BUDGET || 0);
      const win = Number(process?.env?.TENANT_TOKENS_WINDOW_MS || (24 * 60 * 60 * 1000));
      if (__tenantId && lim > 0) {
        __tenantBudget = (LLMService.__tenantBudgetShared ||= createSharedTenantBudget({ windowMs: win, limitTokens: lim }));
        const estIn = TokenCounter.estimate(safe);
        const estOut = Math.max(1, Number(process?.env?.LLM_EXPECTED_TOKENS_OUT || 128));
        const allowBud = await __tenantBudget.allow(__tenantId, estIn + estOut);
        if (!allowBud?.ok) {
          context.io?.events?.emit && context.io.events.emit("llm.call.tenant_budget_exceeded", { tenant: __tenantId });
          try { ensureCoreDeps(context).Metrics.log(context, "fallback_path_total", { reason: "tenant_budget_exceeded" }); } catch {}
          return await getRandomFallback(context);
        }
      }
    } catch {}

    // Tenant monthly token cap pre-check
    try {
      const limMonthly = Number(process?.env?.TENANT_TOKENS_MONTHLY_BUDGET || 0);
      if (__tenantId && limMonthly > 0) {
        __tenantBudgetMonthly = (LLMService.__tenantBudgetMonthlyShared ||= createSharedTenantMonthlyBudget({ limitTokens: limMonthly }));
        const estIn = TokenCounter.estimate(safe);
        const estOut = Math.max(1, Number(process?.env?.LLM_EXPECTED_TOKENS_OUT || 128));
        const allowMon = await __tenantBudgetMonthly.allow(__tenantId, estIn + estOut);
        if (!allowMon?.ok) {
          context.io?.events?.emit && context.io.events.emit("llm.call.tenant_budget_exceeded", { tenant: __tenantId, scope: 'tenant_tokens_monthly' });
          try { ensureCoreDeps(context).Metrics.log(context, 'budget_prevented_total', { scope: 'tenant_tokens_monthly' }); ensureCoreDeps(context).Metrics.log(context, 'fallback_path_total', { reason: 'tenant_tokens_monthly_budget_exceeded' }); } catch {}
          return await getRandomFallback(context);
        }
      }
    } catch {}

    // Tenant rolling token window pre-check
    try {
      const limRoll = Number(process?.env?.TENANT_TOKENS_ROLLING_BUDGET || 0);
      const winRoll = Number(process?.env?.TENANT_TOKENS_ROLLING_WINDOW_MS || 0);
      const bucketMs = Number(process?.env?.TENANT_ROLLING_BUCKET_MS || 60000);
      if (__tenantId && limRoll > 0 && winRoll > 0) {
        __tenantBudgetRolling = (LLMService.__tenantBudgetRollingShared ||= createSharedTenantRollingBudget({ windowMs: winRoll, bucketMs, limitTokens: limRoll }));
        const estIn = TokenCounter.estimate(safe);
        const estOut = Math.max(1, Number(process?.env?.LLM_EXPECTED_TOKENS_OUT || 128));
        const allowRoll = await __tenantBudgetRolling.allow(__tenantId, estIn + estOut);
        if (!allowRoll?.ok) {
          context.io?.events?.emit && context.io.events.emit('llm.call.tenant_budget_exceeded', { tenant: __tenantId, scope: 'tenant_tokens_rolling' });
          try { ensureCoreDeps(context).Metrics.log(context, 'budget_prevented_total', { scope: 'tenant_tokens_rolling' }); ensureCoreDeps(context).Metrics.log(context, 'fallback_path_total', { reason: 'tenant_tokens_rolling_budget_exceeded' }); } catch {}
          return await getRandomFallback(context);
        }
      }
    } catch {}

    // Tenant dollar budget pre-check (estimate via USD-per-token envs)
    let __tenantUsdBudget = null;
    let __tenantUsdMonthly = null;
    let __tenantUsdRolling = null;
    try {
      const limUsd = Number(process?.env?.TENANT_DOLLARS_BUDGET || 0);
      const winUsd = Number(process?.env?.TENANT_DOLLARS_WINDOW_MS || (24 * 60 * 60 * 1000));
      if (__tenantId && limUsd > 0) {
        __tenantUsdBudget = (LLMService.__tenantUsdBudgetShared ||= createSharedTenantDollarBudget({ windowMs: winUsd, limitUsd: limUsd }));
        const estIn = TokenCounter.estimate(safe);
        const estOut = Math.max(1, Number(process?.env?.LLM_EXPECTED_TOKENS_OUT || 128));
        const usdIn = Math.max(0, Number(process?.env?.LLM_USD_PER_TOKEN_IN || 0));
        const usdOut = Math.max(0, Number(process?.env?.LLM_USD_PER_TOKEN_OUT || 0));
        const estUsd = (estIn * usdIn) + (estOut * usdOut);
        const allowUsd = await __tenantUsdBudget.allow(__tenantId, estUsd);
        if (!allowUsd?.ok) {
          context.io?.events?.emit && context.io.events.emit("llm.call.tenant_dollar_budget_exceeded", { tenant: __tenantId });
          try { ensureCoreDeps(context).Metrics.log(context, "budget_prevented_total", { scope: "tenant_dollars" }); ensureCoreDeps(context).Metrics.log(context, "fallback_path_total", { reason: "tenant_dollar_budget_exceeded" }); } catch {}
          return await getRandomFallback(context);
        }
      }
    } catch {}

    // Tenant monthly dollar cap pre-check
    try {
      const limUsdMonthly = Number(process?.env?.TENANT_DOLLARS_MONTHLY_BUDGET || 0);
      if (__tenantId && limUsdMonthly > 0) {
        __tenantUsdMonthly = (LLMService.__tenantUsdMonthlyShared ||= createSharedTenantMonthlyDollarBudget({ limitUsd: limUsdMonthly }));
        const estIn = TokenCounter.estimate(safe);
        const estOut = Math.max(1, Number(process?.env?.LLM_EXPECTED_TOKENS_OUT || 128));
        const usdIn = Math.max(0, Number(process?.env?.LLM_USD_PER_TOKEN_IN || 0));
        const usdOut = Math.max(0, Number(process?.env?.LLM_USD_PER_TOKEN_OUT || 0));
        const estUsd = (estIn * usdIn) + (estOut * usdOut);
        const allowMon = await __tenantUsdMonthly.allow(__tenantId, estUsd);
        if (!allowMon?.ok) {
          context.io?.events?.emit && context.io.events.emit('llm.call.tenant_dollar_budget_exceeded', { tenant: __tenantId, scope: 'tenant_dollars_monthly' });
          try { ensureCoreDeps(context).Metrics.log(context, 'budget_prevented_total', { scope: 'tenant_dollars_monthly' }); ensureCoreDeps(context).Metrics.log(context, 'fallback_path_total', { reason: 'tenant_dollars_monthly_budget_exceeded' }); } catch {}
          return await getRandomFallback(context);
        }
      }
    } catch {}

    // Tenant rolling dollar window pre-check
    try {
      const limUsdRoll = Number(process?.env?.TENANT_DOLLARS_ROLLING_BUDGET || 0);
      const winUsdRoll = Number(process?.env?.TENANT_DOLLARS_ROLLING_WINDOW_MS || 0);
      const bucketMs = Number(process?.env?.TENANT_ROLLING_BUCKET_MS || 60000);
      if (__tenantId && limUsdRoll > 0 && winUsdRoll > 0) {
        __tenantUsdRolling = (LLMService.__tenantUsdRollingShared ||= createSharedTenantRollingDollarBudget({ windowMs: winUsdRoll, bucketMs, limitUsd: limUsdRoll }));
        const estIn = TokenCounter.estimate(safe);
        const estOut = Math.max(1, Number(process?.env?.LLM_EXPECTED_TOKENS_OUT || 128));
        const usdIn = Math.max(0, Number(process?.env?.LLM_USD_PER_TOKEN_IN || 0));
        const usdOut = Math.max(0, Number(process?.env?.LLM_USD_PER_TOKEN_OUT || 0));
        const estUsd = (estIn * usdIn) + (estOut * usdOut);
        const allowRoll = await __tenantUsdRolling.allow(__tenantId, estUsd);
        if (!allowRoll?.ok) {
          context.io?.events?.emit && context.io.events.emit('llm.call.tenant_dollar_budget_exceeded', { tenant: __tenantId, scope: 'tenant_dollars_rolling' });
          try { ensureCoreDeps(context).Metrics.log(context, 'budget_prevented_total', { scope: 'tenant_dollars_rolling' }); ensureCoreDeps(context).Metrics.log(context, 'fallback_path_total', { reason: 'tenant_dollars_rolling_budget_exceeded' }); } catch {}
          return await getRandomFallback(context);
        }
      }
    } catch {}

    // Classify errors for smarter retry decisions
    const classifyLLMError = (err) => {
      try {
        const name = String((err && err.name) || "").toLowerCase();
        const msg = String((err && err.message) || err || "").toLowerCase();
        // Fatal: client errors except 429
        const m4 = msg.match(/http\s+(4\d{2})/);
        if (m4 && m4[1] !== "429") {
          return "fatal";
        }
        // Transient: timeouts, aborts, rate limits, server errors
        if (
          /timeout/.test(msg) ||
          /abort/.test(name) ||
          /http\s+429/.test(msg) ||
          /http\s+5\d{2}/.test(msg)
        ) {
          return "transient";
        }
        // Unknown: default to transient for safety, but log
        return "unknown";
      } catch {
        return "unknown";
      }
    };

    for (let attempt = 0; attempt <= CONFIG.llm.maxRetries; attempt++) {
      const allowed = await withLLMBudgetLock(context, async () => {
        context.vars ??= {};
        context.vars.llmCallsThisTurn ??= 0;
        context.vars.llmTurnBudget ??= context.vars?.llmTurnBudget || CONFIG.llm.maxCallsPerMessage;
        if (context.vars.llmCallsThisTurn >= context.vars.llmTurnBudget) {
          return false;
        }
        context.vars.llmCallsThisTurn++;
        consumeLLMBudget(context, { critical });
        return true;
      });
      if (!allowed) {
        logDebug(context, "Per-turn LLM budget exceeded", "WARN");
        context.io?.events?.emit && context.io.events.emit("llm.call.budget_exceeded", {});
        return await getRandomFallback(context);
      }
      try {
        const generatorFn = () => {
          try {
            context.modelAdapter ??= new ModelAdapter(context);
            if (context.modelAdapter && typeof context.modelAdapter.generate === 'function') {
              return context.modelAdapter.generate({ prompt: safe, options }, { stream: false });
            }
          } catch {}
          return context.llm?.prompt(safe);
        };
        const result = await queueLLM(context, generatorFn, {
          kind: critical ? "critical" : "noncritical",
          promptText: safe
        });
        if (!result || typeof result !== "string" || !result.trim()) {
          throw new Error("Empty LLM result");
        }
        if (!validateLLMResponse(result, context)) {
          throw new Error("Invalid LLM response");
        }
        // Tenant budget commit (actual usage)
        try {
          if (__tenantBudget && __tenantId) {
            const used = Math.max(0, Number(TokenCounter.estimate(safe)) + Number(TokenCounter.estimate(String(result || ''))));
            await __tenantBudget.commit(__tenantId, used);
            try { const M = resolveDep('Metrics', Metrics); M?.count?.({}, 'tenant_budget_consumed_total', used, { tenant: __tenantId }); } catch {}
          }
          if (__tenantBudgetMonthly && __tenantId) {
            const used = Math.max(0, Number(TokenCounter.estimate(safe)) + Number(TokenCounter.estimate(String(result || ''))));
            await __tenantBudgetMonthly.commit(__tenantId, used);
          }
          if (__tenantBudgetRolling && __tenantId) {
            const used = Math.max(0, Number(TokenCounter.estimate(safe)) + Number(TokenCounter.estimate(String(result || ''))));
            await __tenantBudgetRolling.commit(__tenantId, used);
          }
          if (__tenantUsdBudget && __tenantId) {
            const usedIn = Math.max(0, Number(TokenCounter.estimate(safe)));
            const usedOut = Math.max(0, Number(TokenCounter.estimate(String(result || ''))));
            const usdIn = Math.max(0, Number(process?.env?.LLM_USD_PER_TOKEN_IN || 0));
            const usdOut = Math.max(0, Number(process?.env?.LLM_USD_PER_TOKEN_OUT || 0));
            const usdUsed = (usedIn * usdIn) + (usedOut * usdOut);
            await __tenantUsdBudget.commit(__tenantId, usdUsed);
            try { AIMetrics.cost(context, usdUsed); } catch {}
          }
          if (__tenantUsdMonthly && __tenantId) {
            const usedIn = Math.max(0, Number(TokenCounter.estimate(safe)));
            const usedOut = Math.max(0, Number(TokenCounter.estimate(String(result || ''))));
            const usdIn = Math.max(0, Number(process?.env?.LLM_USD_PER_TOKEN_IN || 0));
            const usdOut = Math.max(0, Number(process?.env?.LLM_USD_PER_TOKEN_OUT || 0));
            const usdUsed = (usedIn * usdIn) + (usedOut * usdOut);
            await __tenantUsdMonthly.commit(__tenantId, usdUsed);
          }
          if (__tenantUsdRolling && __tenantId) {
            const usedIn = Math.max(0, Number(TokenCounter.estimate(safe)));
            const usedOut = Math.max(0, Number(TokenCounter.estimate(String(result || ''))));
            const usdIn = Math.max(0, Number(process?.env?.LLM_USD_PER_TOKEN_IN || 0));
            const usdOut = Math.max(0, Number(process?.env?.LLM_USD_PER_TOKEN_OUT || 0));
            const usdUsed = (usedIn * usdIn) + (usedOut * usdOut);
            await __tenantUsdRolling.commit(__tenantId, usdUsed);
          }
        } catch {}
        setPromptCache(hash, result, context?.memory?.messageCount || 0);
        if (context.vars?.enableLLMTrace) {
          logLLMExchange(context, safe, result);
        }
        context.io?.events?.emit && context.io.events.emit("llm.call.success", { attempt });
        context.vars.consecutiveErrors = 0;
        return result.trim();
      } catch (err) {
        const cls = classifyLLMError(err);
        context.io?.events?.emit &&
          context.io.events.emit("llm.call.error", {
            attempt,
            classification: cls,
            error: String((err && err.message) || err)
          });
        logDebug(context, "LLMService attempt " + String(attempt) + " failed (" + String(cls) + "): " + String(err && err.message), "WARN"); 
        context.vars.consecutiveErrors = (context.vars.consecutiveErrors || 0) + 1;
        if (cls === "fatal") {
          break;
        }
        const base = CONFIG.llm.retryBaseMs * Math.pow(2, attempt);
        const rng =
          typeof context.rng === "function"
            ? Math.max(0, Math.min(1, context.rng()))
            : _rng_default();
        const jitter = Math.floor(base * 0.25 * rng);
        await new Promise((r) => MessageClock.setTimeoutCounts(r, base + jitter));
      }
    }

    logDebug(context, "LLMService exhausted retries; using fallback", "WARN");
    context.io?.events?.emit && context.io.events.emit("llm.call.fallback", {});
    try { ensureCoreDeps(context).Metrics.log(context, "fallback_path_total", { reason: "retries_exhausted" }); } catch {}
    return await getRandomFallback(context);
  }

  /**
   * Streaming model call with SSE-style deltas emitted over context.io.events
   * @param {string} text - Prompt text
   * @param {Object} options - Model options
   * @returns {Promise<string>} Final concatenated response
   */
  async stream(text, options = {}) {
    const context = this.context;
    const safe0 = safePromptInput(String(text || ''), context.vars?.sanitizationMode || 'default');
    const safe = applyMemoryPrefix(context, safe0, options?.model);
    const critical = options?.critical !== false;
    const allowed = await withLLMBudgetLock(context, async () => {
      context.vars ??= {}; context.vars.llmCallsThisTurn ??= 0; context.vars.llmTurnBudget ??= context.vars?.llmTurnBudget || CONFIG.llm.maxCallsPerMessage;
      if (context.vars.llmCallsThisTurn >= context.vars.llmTurnBudget) return false;
      context.vars.llmCallsThisTurn++; consumeLLMBudget(context, { critical }); return true;
    });
    if (!allowed) { context.io?.events?.emit && context.io.events.emit('llm.call.budget_exceeded', {}); try { ensureCoreDeps(context).Metrics.log(context, 'fallback_path_total', { reason: 'budget_exceeded' }); } catch {} return await getRandomFallback(context); }
    context.modelAdapter ??= new ModelAdapter(context);
    // Tenant token budget pre-check
    let __tenantBudget = null; let __tenantBudgetMonthly = null; let __tenantBudgetRolling = null; let __tenantId = '';
    try { __tenantId = String(context?.vars?.tenant || context?.vars?.tenantId || context?.vars?.client_id || context?.vars?.user || '').trim(); } catch {}
    try {
      const lim = Number(process?.env?.TENANT_TOKENS_BUDGET || 0);
      const win = Number(process?.env?.TENANT_TOKENS_WINDOW_MS || (24 * 60 * 60 * 1000));
      if (__tenantId && lim > 0) {
        __tenantBudget = (LLMService.__tenantBudgetShared ||= createSharedTenantBudget({ windowMs: win, limitTokens: lim }));
        const estIn = TokenCounter.estimate(safe);
        const estOut = Math.max(1, Number(process?.env?.LLM_EXPECTED_TOKENS_OUT || 128));
        const allowBud = await __tenantBudget.allow(__tenantId, estIn + estOut);
        if (!allowBud?.ok) { context.io?.events?.emit && context.io.events.emit('llm.call.tenant_budget_exceeded', { tenant: __tenantId }); try { ensureCoreDeps(context).Metrics.log(context, 'fallback_path_total', { reason: 'tenant_budget_exceeded' }); } catch {} return await getRandomFallback(context); }
      }
    } catch {}
    // Tenant monthly token cap pre-check
    try {
      const limMonthly = Number(process?.env?.TENANT_TOKENS_MONTHLY_BUDGET || 0);
      if (__tenantId && limMonthly > 0) {
        __tenantBudgetMonthly = (LLMService.__tenantBudgetMonthlyShared ||= createSharedTenantMonthlyBudget({ limitTokens: limMonthly }));
        const estIn = TokenCounter.estimate(safe);
        const estOut = Math.max(1, Number(process?.env?.LLM_EXPECTED_TOKENS_OUT || 128));
        const allowMon = await __tenantBudgetMonthly.allow(__tenantId, estIn + estOut);
        if (!allowMon?.ok) { context.io?.events?.emit && context.io.events.emit('llm.call.tenant_budget_exceeded', { tenant: __tenantId, scope: 'tenant_tokens_monthly' }); try { ensureCoreDeps(context).Metrics.log(context, 'budget_prevented_total', { scope: 'tenant_tokens_monthly' }); ensureCoreDeps(context).Metrics.log(context, 'fallback_path_total', { reason: 'tenant_tokens_monthly_budget_exceeded' }); } catch {} return await getRandomFallback(context); }
      }
    } catch {}
    // Tenant rolling token window pre-check
    try {
      const limRoll = Number(process?.env?.TENANT_TOKENS_ROLLING_BUDGET || 0);
      const winRoll = Number(process?.env?.TENANT_TOKENS_ROLLING_WINDOW_MS || 0);
      const bucketMs = Number(process?.env?.TENANT_ROLLING_BUCKET_MS || 60000);
      if (__tenantId && limRoll > 0 && winRoll > 0) {
        __tenantBudgetRolling = (LLMService.__tenantBudgetRollingShared ||= createSharedTenantRollingBudget({ windowMs: winRoll, bucketMs, limitTokens: limRoll }));
        const estIn = TokenCounter.estimate(safe);
        const estOut = Math.max(1, Number(process?.env?.LLM_EXPECTED_TOKENS_OUT || 128));
        const allowRoll = await __tenantBudgetRolling.allow(__tenantId, estIn + estOut);
        if (!allowRoll?.ok) { context.io?.events?.emit && context.io.events.emit('llm.call.tenant_budget_exceeded', { tenant: __tenantId, scope: 'tenant_tokens_rolling' }); try { ensureCoreDeps(context).Metrics.log(context, 'budget_prevented_total', { scope: 'tenant_tokens_rolling' }); ensureCoreDeps(context).Metrics.log(context, 'fallback_path_total', { reason: 'tenant_tokens_rolling_budget_exceeded' }); } catch {} return await getRandomFallback(context); }
      }
    } catch {}
    // Tenant dollar budget pre-check (estimate via USD-per-token envs)
    let __tenantUsdBudget = null; let __tenantUsdMonthly = null; let __tenantUsdRolling = null;
    try {
      const limUsd = Number(process?.env?.TENANT_DOLLARS_BUDGET || 0);
      const winUsd = Number(process?.env?.TENANT_DOLLARS_WINDOW_MS || (24 * 60 * 60 * 1000));
      if (__tenantId && limUsd > 0) {
        __tenantUsdBudget = (LLMService.__tenantUsdBudgetShared ||= createSharedTenantDollarBudget({ windowMs: winUsd, limitUsd: limUsd }));
        const estIn = TokenCounter.estimate(safe);
        const estOut = Math.max(1, Number(process?.env?.LLM_EXPECTED_TOKENS_OUT || 128));
        const usdIn = Math.max(0, Number(process?.env?.LLM_USD_PER_TOKEN_IN || 0));
        const usdOut = Math.max(0, Number(process?.env?.LLM_USD_PER_TOKEN_OUT || 0));
        const estUsd = (estIn * usdIn) + (estOut * usdOut);
        const allowUsd = await __tenantUsdBudget.allow(__tenantId, estUsd);
        if (!allowUsd?.ok) {
          context.io?.events?.emit && context.io.events.emit('llm.call.tenant_dollar_budget_exceeded', { tenant: __tenantId });
          try { ensureCoreDeps(context).Metrics.log(context, 'budget_prevented_total', { scope: 'tenant_dollars' }); ensureCoreDeps(context).Metrics.log(context, 'fallback_path_total', { reason: 'tenant_dollar_budget_exceeded' }); } catch {}
          return await getRandomFallback(context);
        }
      }
    } catch {}
    // Tenant monthly dollar cap pre-check
    try {
      const limUsdMonthly = Number(process?.env?.TENANT_DOLLARS_MONTHLY_BUDGET || 0);
      if (__tenantId && limUsdMonthly > 0) {
        __tenantUsdMonthly = (LLMService.__tenantUsdMonthlyShared ||= createSharedTenantMonthlyDollarBudget({ limitUsd: limUsdMonthly }));
        const estIn = TokenCounter.estimate(safe);
        const estOut = Math.max(1, Number(process?.env?.LLM_EXPECTED_TOKENS_OUT || 128));
        const usdIn = Math.max(0, Number(process?.env?.LLM_USD_PER_TOKEN_IN || 0));
        const usdOut = Math.max(0, Number(process?.env?.LLM_USD_PER_TOKEN_OUT || 0));
        const estUsd = (estIn * usdIn) + (estOut * usdOut);
        const allowMon = await __tenantUsdMonthly.allow(__tenantId, estUsd);
        if (!allowMon?.ok) { context.io?.events?.emit && context.io.events.emit('llm.call.tenant_dollar_budget_exceeded', { tenant: __tenantId, scope: 'tenant_dollars_monthly' }); try { ensureCoreDeps(context).Metrics.log(context, 'budget_prevented_total', { scope: 'tenant_dollars_monthly' }); ensureCoreDeps(context).Metrics.log(context, 'fallback_path_total', { reason: 'tenant_dollars_monthly_budget_exceeded' }); } catch {} return await getRandomFallback(context); }
      }
    } catch {}
    // Tenant rolling dollar window pre-check
    try {
      const limUsdRoll = Number(process?.env?.TENANT_DOLLARS_ROLLING_BUDGET || 0);
      const winUsdRoll = Number(process?.env?.TENANT_DOLLARS_ROLLING_WINDOW_MS || 0);
      const bucketMs = Number(process?.env?.TENANT_ROLLING_BUCKET_MS || 60000);
      if (__tenantId && limUsdRoll > 0 && winUsdRoll > 0) {
        __tenantUsdRolling = (LLMService.__tenantUsdRollingShared ||= createSharedTenantRollingDollarBudget({ windowMs: winUsdRoll, bucketMs, limitUsd: limUsdRoll }));
        const estIn = TokenCounter.estimate(safe);
        const estOut = Math.max(1, Number(process?.env?.LLM_EXPECTED_TOKENS_OUT || 128));
        const usdIn = Math.max(0, Number(process?.env?.LLM_USD_PER_TOKEN_IN || 0));
        const usdOut = Math.max(0, Number(process?.env?.LLM_USD_PER_TOKEN_OUT || 0));
        const estUsd = (estIn * usdIn) + (estOut * usdOut);
        const allowRoll = await __tenantUsdRolling.allow(__tenantId, estUsd);
        if (!allowRoll?.ok) { context.io?.events?.emit && context.io.events.emit('llm.call.tenant_dollar_budget_exceeded', { tenant: __tenantId, scope: 'tenant_dollars_rolling' }); try { ensureCoreDeps(context).Metrics.log(context, 'budget_prevented_total', { scope: 'tenant_dollars_rolling' }); ensureCoreDeps(context).Metrics.log(context, 'fallback_path_total', { reason: 'tenant_dollars_rolling_budget_exceeded' }); } catch {} return await getRandomFallback(context); }
      }
    } catch {}
    const result = await context.modelAdapter.generate({ prompt: safe, options }, { stream: true });
    // Commit actual usage
    try {
      if (__tenantBudget && __tenantId) {
        const used = Math.max(0, Number(TokenCounter.estimate(safe)) + Number(TokenCounter.estimate(String(result || ''))));
        await __tenantBudget.commit(__tenantId, used);
        try { const M = resolveDep('Metrics', Metrics); M?.count?.({}, 'tenant_budget_consumed_total', used, { tenant: __tenantId }); } catch {}
      }
      if (__tenantBudgetMonthly && __tenantId) {
        const used = Math.max(0, Number(TokenCounter.estimate(safe)) + Number(TokenCounter.estimate(String(result || ''))));
        await __tenantBudgetMonthly.commit(__tenantId, used);
      }
      if (__tenantBudgetRolling && __tenantId) {
        const used = Math.max(0, Number(TokenCounter.estimate(safe)) + Number(TokenCounter.estimate(String(result || ''))));
        await __tenantBudgetRolling.commit(__tenantId, used);
      }
      if (__tenantUsdBudget && __tenantId) {
        const usedIn = Math.max(0, Number(TokenCounter.estimate(safe)));
        const usedOut = Math.max(0, Number(TokenCounter.estimate(String(result || ''))));
        const usdIn = Math.max(0, Number(process?.env?.LLM_USD_PER_TOKEN_IN || 0));
        const usdOut = Math.max(0, Number(process?.env?.LLM_USD_PER_TOKEN_OUT || 0));
        const usdUsed = (usedIn * usdIn) + (usedOut * usdOut);
        await __tenantUsdBudget.commit(__tenantId, usdUsed);
        try { AIMetrics.cost(context, usdUsed); } catch {}
      }
      if (__tenantUsdMonthly && __tenantId) {
        const usedIn = Math.max(0, Number(TokenCounter.estimate(safe)));
        const usedOut = Math.max(0, Number(TokenCounter.estimate(String(result || ''))));
        const usdIn = Math.max(0, Number(process?.env?.LLM_USD_PER_TOKEN_IN || 0));
        const usdOut = Math.max(0, Number(process?.env?.LLM_USD_PER_TOKEN_OUT || 0));
        const usdUsed = (usedIn * usdIn) + (usedOut * usdOut);
        await __tenantUsdMonthly.commit(__tenantId, usdUsed);
      }
      if (__tenantUsdRolling && __tenantId) {
        const usedIn = Math.max(0, Number(TokenCounter.estimate(safe)));
        const usedOut = Math.max(0, Number(TokenCounter.estimate(String(result || ''))));
        const usdIn = Math.max(0, Number(process?.env?.LLM_USD_PER_TOKEN_IN || 0));
        const usdOut = Math.max(0, Number(process?.env?.LLM_USD_PER_TOKEN_OUT || 0));
        const usdUsed = (usedIn * usdIn) + (usedOut * usdOut);
        await __tenantUsdRolling.commit(__tenantId, usdUsed);
      }
    } catch {}
    return String(result || '');
  }
}

// Export LLMService for external integration (service endpoints)
// === BELIEFS / CONSTRAINTS STORE (ESM bridge to scripts/state) ===
export const BeliefStore = (() => {
  async function listAgents() {
    try {
      const path = await import('node:path');
      const fsp = await import('node:fs/promises');
      const base = path.join(process.cwd(), 'tmp', 'urga_beliefs');
      const ents = await fsp.readdir(base, { withFileTypes: true }).catch(() => []);
      return ents
        .filter(e => (typeof e.isFile === 'function' ? e.isFile() : e.isFile) && String(e.name).toLowerCase().endsWith('.json'))
        .map(e => String(e.name).replace(/\.json$/i, ''));
    } catch { return []; }
  }
  async function getAgent(agentId) {
    try {
      const { loadBeliefs } = await import('./scripts/state/beliefs_store.mjs');
      const p = await loadBeliefs(String(agentId || 'default'));
      return { beliefs: Array.isArray(p.beliefs) ? p.beliefs.slice(0) : [], personality: String(p.personality || '') };
    } catch { return { beliefs: [], personality: '' }; }
  }
  async function setAgent(agentId, data) {
    try {
      const { upsertBeliefs } = await import('./scripts/state/beliefs_store.mjs');
      const patch = { beliefs: Array.isArray(data?.beliefs) ? data.beliefs : [], personality: String(data?.personality || '') };
      await upsertBeliefs(String(agentId || 'default'), patch);
      return getAgent(agentId);
    } catch { return getAgent(agentId); }
  }
  async function addBelief(agentId, belief) {
    try {
      const { addBeliefLine, loadBeliefs } = await import('./scripts/state/beliefs_store.mjs');
      await addBeliefLine(String(agentId || 'default'), 'beliefs', String(belief));
      const p = await loadBeliefs(String(agentId || 'default'));
      return Array.isArray(p.beliefs) ? p.beliefs.slice(0) : [];
    } catch { return []; }
  }
  async function deleteBelief(agentId, belief) {
    try {
      const { deleteBeliefLine, loadBeliefs } = await import('./scripts/state/beliefs_store.mjs');
      await deleteBeliefLine(String(agentId || 'default'), 'beliefs', String(belief));
      const p = await loadBeliefs(String(agentId || 'default'));
      return Array.isArray(p.beliefs) ? p.beliefs.slice(0) : [];
    } catch { return []; }
  }
  async function listBeliefs(agentId) {
    try {
      const { loadBeliefs } = await import('./scripts/state/beliefs_store.mjs');
      const p = await loadBeliefs(String(agentId || 'default'));
      return Array.isArray(p.beliefs) ? p.beliefs.slice(0) : [];
    } catch { return []; }
  }
  async function setPersonality(agentId, text) {
    try {
      const { upsertBeliefs, loadBeliefs } = await import('./scripts/state/beliefs_store.mjs');
      await upsertBeliefs(String(agentId || 'default'), { personality: String(text || '') });
      const p = await loadBeliefs(String(agentId || 'default'));
      return String(p.personality || '');
    } catch { return ''; }
  }
  async function getPersonality(agentId) {
    try {
      const { loadBeliefs } = await import('./scripts/state/beliefs_store.mjs');
      const p = await loadBeliefs(String(agentId || 'default'));
      return String(p.personality || '');
    } catch { return ''; }
  }
  async function listConstraints() {
    try {
      const path = await import('node:path');
      const fsp = await import('node:fs/promises');
      const base = path.join(process.cwd(), 'tmp', 'urga_beliefs');
      const ents = await fsp.readdir(base, { withFileTypes: true }).catch(() => []);
      const constraints = [];
      const seen = new Set();
      const { loadBeliefs } = await import('./scripts/state/beliefs_store.mjs');
      for (const e of ents) {
        if ((typeof e.isFile === 'function' ? e.isFile() : e.isFile) && String(e.name).toLowerCase().endsWith('.json')) {
          const id = String(e.name).replace(/\.json$/i, '');
          try {
            const p = await loadBeliefs(id);
            for (const c of p.logic_constraints || []) {
              const k = String(c).trim().toLowerCase();
              if (!seen.has(k)) { seen.add(k); constraints.push(String(c)); }
            }
          } catch {}
        }
      }
      return constraints;
    } catch { return []; }
  }
  async function addConstraint(text) {
    try {
      const { addBeliefLine } = await import('./scripts/state/beliefs_store.mjs');
      await addBeliefLine('global', 'logic_constraints', String(text));
      return listConstraints();
    } catch { return listConstraints(); }
  }
  async function deleteConstraint(text) {
    try {
      const { deleteBeliefLine } = await import('./scripts/state/beliefs_store.mjs');
      await deleteBeliefLine('global', 'logic_constraints', String(text));
      return listConstraints();
    } catch { return listConstraints(); }
  }
  return {
    listAgents, getAgent, setAgent,
    addBelief, deleteBelief, listBeliefs,
    setPersonality, getPersonality,
    listConstraints, addConstraint, deleteConstraint,
  };
})();

export async function listBeliefsForAgent(agentId) { return BeliefStore.listBeliefs(agentId || 'default'); }
export async function listLogicConstraints() { return BeliefStore.listConstraints(); }

