export { checkSecrets };
export const registerLLMProvider = ProviderRegistry.registerLLMProvider;
export const configureProvidersFromEnv = ProviderRegistry.configureProvidersFromEnv;
// Expose a read-only view of the effective CONFIG for admin diagnostics
export function getEffectiveConfig() {
  try {
    return CONFIG;
  } catch {
    return {};
  }
}
// Export core helpers for external probes/tests
export { generateLine, ModelAdapter };
// Export token estimator and dollar budget helper for service-layer gates
export { TokenCounter };

// Separate voice from content
/**
 * Centralized voice styling pass that applies narration style and optional dream-aware effects.
 * Honors `context.vars/settings/memory.narrationStyle` and emits hallucination events when enabled.
 * @param {string} content - Plain content before styling
 * @param {Context} context - Game context controlling style and flags
 * @returns {string} Final styled content
 */
const VoiceStyler = {
  /**
   * Applies the active narration style and optional dream-aware styling.
   * Uses `narrationStyle` from `vars`, `settings`, || `memory` and applies hallucinatory overlay
   * when `flags.hallucinate` is set, emitting a `hallucination` event.
   * @param {string} content - Plain content before styling
   * @param {Context} context - Game context controlling style and flags
   * @returns {string} Styled content
   */
  apply(content, context) {
    const style =
      context.vars?.narrationStyle ||
      context.settings?.narrationStyle ||
      context.memory?.narrationStyle ||
      "default";
    let styled = applyNarrationStyle(content, style, context) || content;

    // Optional dream-aware pass, gated by flags || purpose
    try {
      const dreamGate =
        context?.flags?.dreamAwareStyling ||
        context?.flags?.applyDreamStyling ||
        context?.vars?.purpose === "dream" ||
        context?.vars?.lastPurpose === "dream";
      if (dreamGate) {
        const clarity =
          typeof Dreams?.getClarity === "function" ? Dreams.getClarity(context.state) : null;
        const canApply =
          typeof Echo?.styleDream === "function" && clarity !== null && clarity !== undefined;
        try {
          ensureCoreDeps(context).Metrics.log(context, "dreamStyling", {
            clarity,
            style,
            applied: !!canApply
          });
        } catch (err) {
          handleError(context, err, "metrics.dreamStyling");
        }
        if (canApply) {
          styled = Echo.styleDream(styled, clarity);
        }
      }
    } catch (err) {
      try {
        logDebug(context, `VoiceStyler dream pass failed: ${err?.message || err}`, "WARN"); 
      } catch (err) {
        handleError(context, err, "voices.dreamStyler.logDebug");
      }
    }

    if (context.flags?.hallucinate) {
      const overlay = getHallucinationOverlay(context);
      styled = applyHallucination(styled, overlay?.style || "default", context);
      context.io?.events?.emit &&
        context.io.events.emit("hallucination", {
          style: overlay?.style || "default",
          text: styled
        });
      try { ensureCoreDeps(context).Metrics.log(context, "hallucination_suspect_total", { style: overlay?.style || "default" }); } catch {}
    }
    return styled;
  }
};

/**
 * Resolves `promise` with timeout behavior.
 * On timeout, calls `opts.onTimeout` if provided; optionally rejects based on flags.
 * @param {Promise|any} promise - Promise || value to resolve.
 * @param {number} ms - Timeout in milliseconds.
 * @param {*} [fallback=null] - Value to resolve on timeout || error.
 * @param {Object|Function} [opts=null] - Options || onTimeout handler.
 * @param {Function} [opts.onTimeout] - Called when timing out.
 * @param {boolean} [opts.rejectOnError=false] - Reject on error instead of resolving fallback.
 * @param {boolean} [opts.rejectOnTimeout=false] - Reject on timeout instead of resolving fallback.
 * @returns {Promise<*>} Promise resolving to value || fallback.
 */
const withTimeout = (promise, ms, fallback = null, opts = null) => {
  const options = {};
  if (typeof opts === "function") {
    options.onTimeout = opts;
  } else if (opts && typeof opts === "object") {
    options.onTimeout = opts.onTimeout;
    options.rejectOnError = !!opts.rejectOnError;
    options.rejectOnTimeout = !!opts.rejectOnTimeout;
  }
  return new Promise((resolve, reject) => {
    let done = false;
    const timer = MessageClock.setTimeoutCounts(() => {
      done = true;
      try {
        if (typeof options.onTimeout === "function") {
          options.onTimeout();
        }
      } catch (err) {
        handleError(undefined, err, "timeout.onTimeout");
      }
      if (options.rejectOnTimeout) {
        reject(new Error("Timeout"));
      } else {
        resolve(fallback);
      }
    }, ms);
    if (typeof timer.unref === "function") {
      try {
        timer.unref();
      } catch (err) {
        handleError(undefined, err, "timeout.unref");
      }
    }
    Promise.resolve(promise)
      .then((value) => {
        try {
          MessageClock.clearTimeout(timer);
        } catch (err) {
          handleError(undefined, err, "timeout.clear");
        }
        if (!done) {
          resolve(value);
        }
      })
      .catch((err) => {
        try {
          MessageClock.clearTimeout(timer);
        } catch (err) {
          handleError(undefined, err, "timeout.clear");
        }
        if (!done) {
          options.rejectOnError ? reject(err) : resolve(fallback);
        }
      });
  });
};

const sleepUnref = (ms) => {
  return new Promise((resolve) => {
    const timer = MessageClock.setTimeoutCounts(resolve, ms);
    if (typeof timer.unref === "function") {
      try {
        timer.unref();
      } catch (err) {
        handleError(undefined, err, "timeout.unref.sleep");
      }
    }
  });
};

// === LLM Budget Semaphore (prevents concurrent budget overruns) ===
/**
 * Ensures a simple semaphore to throttle LLM budget usage per turn.
 * @param {Context} context - Session context where lock state is stored.
 * @returns {void}
 */
const ensureLLMBudgetSemaphore = (context) => {
  context._llmBudgetLock = context._llmBudgetLock || {
    locked: false,
    waiters: []
  };
};
/**
 * Executes an async `fn` under a budget lock to prevent overruns.
 * Resolves to `fn`'s result || `false` if a lock error occurs.
 * @param {Context} context - Session context that holds the lock state.
 * @param {Function} fn - Async function to execute while locked.
 * @returns {Promise<*>|false} Result of `fn` || false on lock error.
 */
async function withLLMBudgetLock(context, fn) {
  try {
    ensureLLMBudgetSemaphore(context);
    if (context._llmBudgetLock.locked) {
      await new Promise((res) => context._llmBudgetLock.waiters.push(res));
    }
    context._llmBudgetLock.locked = true;
    try {
      return await fn();
    } finally {
      context._llmBudgetLock.locked = false;
      const next = context._llmBudgetLock.waiters.shift();
      if (next) {
        next();
      }
    }
  } catch (e) {
    // In case of lock errors, fail closed
    return false;
  }
}

// === LLM RETRY STRATEGY (FIX: Added comprehensive error handling) ===
/**
 * Core LLM line generator with rate limiting, caching, and retries
 * @param {Context} context - The game context object
 * @param {string|Object} prompt - Prompt string || structured parts
 * @param {Object} [options={}] - Options like purpose, tone, critical
 * @param {string} [options.purpose='taunt'] - Purpose label for generation
 * @param {string} [options.tone='corrupted'] - Tone label for generation
 * @param {boolean} [options.critical=true] - Whether to use critical budget path
 * @returns {Promise<string>} Generated line || fallback
 * @throws {Error} If `context` is missing || invalid
 */
async function generateLine(context, prompt, options = {}) {
  ensureMemory(context);
  // FIX: Input validation
  if (!context) {
    throw new Error("Context is required for generateLine");
  }

  const purpose = options?.purpose || "taunt";
  const tone = options?.tone || "corrupted";

  // Fast path: dry-run mode should bypass rate limiter/locks entirely
  if (CONFIG.dryRun.enabled || context?.flags?.dryRun) {
    const base =
      typeof prompt === "string" ? prompt : (prompt?.systemPrompt ?? String(prompt?.base ?? ""));
    const synth = await dryRunService.generateResponse(base, context, {
      purpose,
      tone,
      critical: options?.critical
    });
    const safeSynth =
      typeof synth === "string" && synth.trim()
        ? synth
        : await getDynamicFallback(context, purpose, tone);
    setPromptCache(hashPrompt(String(base || "")), safeSynth, context?.memory?.messageCount || 0);
    logDebug(
      context,
      "Dry run generateLine (fast-path): " + String(safeSynth || "").slice(0, 80) + "...",
      "INFO"
    );
    return safeSynth;
  }

  // Ensure LLMService is attached even if ensureMemory wasn't called
  ensureDeps(context);
  context.llmService ??= new (getDep(context, "LLMService", LLMService))(context);
  context.vars ??= {};

  // Ensure a model adapter exists; allow provider-backed generation even without llm.prompt
  context.modelAdapter ??= new ModelAdapter(context);
  if (!context.llm?.prompt && !context.providers?.llm) {
    logDebug(context, "LLM not initialized: neither provider nor llm.prompt available.", "WARN");
    return getRandomFallback(context);
  }

  // FIX: Rate limiting (leaky bucket)
  {
    context.__llmRateMutex = context.__llmRateMutex || {
      locked: false,
      waiters: []
    };
    const __allowed = await runWithMutex(
      context.__llmRateMutex,
      async () => checkLLMLeakyBucket(context),
      {
        maxWaiters: Number(CONFIG?.llm?.mutexMaxWaiters ?? 1000),
        timeoutMs: Number(CONFIG?.llm?.mutexWaitTimeoutMs ?? 0),
        onDrop: (info) => {
          try {
            ensureCoreDeps(context).Metrics.log(context, "llmRateMutexDrop", info || {});
          } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
        }
      }
    );
    if (!__allowed) {
      logDebug(context, "Rate limit hit, returning cached fallback", "WARN");
      return await getDynamicFallback(context, purpose, tone);
    }
  }

  // Build || apply prompt overlays
  let overlayed;
  if (prompt && typeof prompt === "object") {
    try {
      const structured = {
        systemPrompt: prompt.systemPrompt ?? String(prompt.base ?? ""),
        memorySection: prompt.memorySection ?? getMemorySection(context),
        overlay: prompt.overlay ?? getHallucinationOverlay(context),
        responseTag: prompt.responseTag ?? "Response"
      };
      overlayed = buildStructuredPrompt(context, structured);
      context.vars ??= {};
      context.vars.llmTrace ??= {};
      context.vars.llmTrace.promptOverlay = context.vars.llmTrace.promptOverlay || [];
    } catch (e) {
      overlayed = String(prompt.systemPrompt || prompt.base || "");
    }
  } else {
    try {
      const baseSystem = String(prompt || "");
      const trust = context?.stats?.trust ?? context?.memory?.trustLevel ?? 0;
      const corruption = context?.stats?.corruption ?? context?.memory?.corruption ?? 0;
      const heardEcho = context?.flags?.heardEcho ?? false; // retained for potential gating, but Echo overlay handled in builder
      try {
        ensureRNG(context);
      } catch (err) {
        handleError(context, err, "ensureRNG");
      }
      const r = context.rng();
      context.vars ??= {};
      context.vars.llmTrace ??= {};
      context.vars.llmTrace.promptOverlay = context.vars.llmTrace.promptOverlay || [];

      // Build overlay parts (Ur'ga only here; Echo handled in buildStructuredPrompt)
      let overlay = "";
      const urgaChance = trust > 7 ? 0.6 : trust > 4 ? 0.4 : corruption > 7 ? 0.5 : 0.2;
      if (r < urgaChance) {
        const lines = [
          "A soft shadow cradles your thoughts. She’s waiting.",
          "Let it in. Let her guide you — without question.",
          "You see now. The others lied. She never did."
        ];
        const chosen = lines[Math.floor(context.rng() * lines.length)];
        const tag = trust > 7 ? "Devotion" : corruption > 7 ? "Hunger" : "Presence";
        overlay = "[Ur'ga/" + String(tag) + "] " + String(chosen);
        context.vars ??= {};
        context.vars.llmTrace ??= {};
        context.vars.llmTrace.promptOverlay = context.vars.llmTrace.promptOverlay || [];
        safePush(
          context.vars.llmTrace.promptOverlay,
          { source: "UrgaCore", type: "mutatePrompt", line: chosen, tag },
          CONFIG.contextCaps.promptOverlay
        );
      }

      const structured = {
        systemPrompt: baseSystem,
        memorySection: getMemorySection(context),
        overlay,
        responseTag: "Response"
      };
      overlayed = buildStructuredPrompt(context, structured);
    } catch (e) {
      overlayed = String(prompt || "");
    }
  }

  const safe = safePromptInput(overlayed, context.vars?.sanitizationMode || "default");
  const hash = hashPrompt(safe);
  const cached = getPromptCache(hash, context?.memory?.messageCount || 0);
  if (cached) {
    return cached;
  }

  // Dry-run mode: use DryRunService for contextual synthetic responses
  if (CONFIG.dryRun.enabled || context?.flags?.dryRun) {
    const synth = await dryRunService.generateResponse(safe, context, {
      purpose,
      tone,
      critical: options?.critical
    });
    if (!validateLLMResponse(synth, context)) {
      logDebug(context, "LLM response failed validation (generateLine dry-run)", "WARN");
      return await getDynamicFallback(context, purpose, tone);
    }
    setPromptCache(hash, synth, context?.memory?.messageCount || 0);
    logDebug(context, "Dry run generateLine: " + synth.slice(0, 100) + "...", "INFO"); 
    return synth;
  }

  context._recentLines ??= new RecentLinesMap();

  // Circuit breaker: fail fast after consecutive errors
  context.vars ??= {};
  context.vars.consecutiveErrors ??= 0;
  if (context.vars.consecutiveErrors > 3) {
    logDebug(context, "Circuit breaker tripped; returning fallback", "WARN");
    return await getDynamicFallback(context, purpose, tone);
  }

  // Non-critical path: use budget-aware non-critical queue and dynamic fallback
  if (options?.critical === false) {
    try {
      const result = await queueLLMNonCritical(
        context,
        () => {
          try {
            // Prefer provider/model routing when available; fall back to llm.prompt
            const selectedModel = options?.model || (purpose === "dream" ? "dreams" : undefined);
            context.modelAdapter ??= new ModelAdapter(context);
            if (context.providers?.llm && context.modelAdapter) {
              return context.modelAdapter.generate(
                { prompt: safe, options: { ...options, model: selectedModel } },
                { stream: false }
              );
            }
          } catch {}
          return context.llm?.prompt ? context.llm.prompt(safe) : getRandomFallback(context);
        },
        {
        promptText: safe,
        purpose,
        tone
        }
      );
      context.vars ??= {};
      if (result === null) {
        context.vars.llmNonCriticalSkipsThisTurn =
          (context.vars.llmNonCriticalSkipsThisTurn || 0) + 1;
        logDebug(context, "Non-critical LLM budget exceeded", "WARN");
        return await getDynamicFallback(context, purpose, tone);
      } else {
        context.vars.llmNonCriticalCallsThisTurn =
          (context.vars.llmNonCriticalCallsThisTurn || 0) + 1;
      }
      if (!result || typeof result !== "string" || !result.trim()) {
        throw new Error("Empty line from LLM");
      }
      if (context._recentLines.has(result, context?.memory?.messageCount || 0)) {
        throw new Error("Repeated line detected");
      }
      if (!validateLLMResponse(result, context)) {
        throw new Error("Invalid LLM response");
      }
      context._recentLines.set(result, context?.memory?.messageCount || 0);
      setPromptCache(hash, result, context?.memory?.messageCount || 0);
      if (context.vars?.enableLLMTrace) {
        logLLMExchange(context, safe, result);
      }
      logDebug(context, "Generated line (non-critical): " + result.slice(0, 100) + "...", "INFO"); 
      context.vars.consecutiveErrors = 0;
      return result.trim();
    } catch (err) {
      logDebug(context, "generateLine non-critical failed: " + String(err && err.message), "WARN"); 
      context.vars.consecutiveErrors = (context.vars.consecutiveErrors || 0) + 1;
      return await getDynamicFallback(context, purpose, tone);
    }
  }

  context.vars ??= {};
  context.vars.llmCallsThisTurn ??= 0;
  context.vars.llmTurnBudget ??= context.vars?.llmTurnBudget || 8;

  for (let attempt = 0; attempt <= LLM_MAX_RETRIES; attempt++) {
    const allowed = await withLLMBudgetLock(context, async () => {
      if (context.vars.llmCallsThisTurn >= context.vars.llmTurnBudget) {
        return false;
      }
      context.vars.llmCallsThisTurn++;
      consumeLLMBudget(context, { critical: true });
      return true;
    });
    if (!allowed) {
      logDebug(context, "Per-turn LLM budget exceeded", "WARN");
      return await getDynamicFallback(context, purpose, tone);
    }
    try {
      const result = await queueLLM(
        context,
        () => {
          try {
            // Prefer provider/model routing when available; fall back to llm.prompt
            const selectedModel = options?.model || (purpose === "dream" ? "dreams" : undefined);
            context.modelAdapter ??= new ModelAdapter(context);
            if (context.providers?.llm && context.modelAdapter) {
              return context.modelAdapter.generate(
                { prompt: safe, options: { ...options, model: selectedModel } },
                { stream: false }
              );
            }
          } catch {}
          return context.llm?.prompt ? context.llm.prompt(safe) : getRandomFallback(context);
        },
        {
        kind: "critical",
        promptText: safe,
        purpose,
        tone
        }
      );
      if (!result || typeof result !== "string" || !result.trim()) {
        throw new Error("Empty line from LLM");
      }
      if (context._recentLines.has(result, context?.memory?.messageCount || 0)) {
        throw new Error("Repeated line detected");
      }
      if (!validateLLMResponse(result, context)) {
        throw new Error("Invalid LLM response");
      }
      context._recentLines.set(result, context?.memory?.messageCount || 0);
      setPromptCache(hash, result, context?.memory?.messageCount || 0);
      // LLM prompt logging (optional)
      if (context.vars?.enableLLMTrace) {
        logLLMExchange(context, safe, result);
      }
      logDebug(context, "Generated line: " + result.slice(0, 100) + "...", "INFO"); 
      context.vars.consecutiveErrors = 0;
      return result.trim();
    } catch (err) {
      logDebug(context, "generateLine attempt " + String(attempt + 1) + " failed: " + String(err && err.message), "WARN"); 
      context.vars.consecutiveErrors = (context.vars.consecutiveErrors || 0) + 1;
      if (attempt < LLM_MAX_RETRIES) {
        const delay = LLM_RETRY_BASE_MS * Math.pow(2, attempt);
        await sleepUnref(delay);
        continue;
      } else {
        logDebug(context, "All LLM retries failed for prompt: " + safe.slice(0, 100) + "...", "ERROR"); 
        return await getDynamicFallback(context, purpose, tone);
      }
    }
  }

  return await getDynamicFallback(context, purpose, tone);
}

// Budget-aware facade for flavor-only generators with per-engine gates

const boarKingChance = (context) => {
  ensureRNG(context);
  const base = BOAR_KING_BASE_CHANCE;
  const bonus =
    ((context.memory?.corruption ?? 0) +
      (context.memory?.tension ?? 0) +
      (context.memory?.trustLevel ?? 0)) /
    BOAR_KING_BONUS_DIVISOR;
  return Math.min(BOAR_KING_MAX_CHANCE, base + bonus);
};

// === MEMORY INIT (FIX: Added input validation) ===
/**
 * Validates and repairs the `context` structure, normalizing memory, stats, vars, and metrics.
 * Applies caps, coercions, and shape checks; optionally throws on errors.
 * @param {Context} context - Runtime context to validate.
 * @param {{strict?:boolean}} [options] - When `strict`, throws on schema errors.
 * @returns {{valid:boolean, errors:string[]}} Summary of validation status and error list.
 */
const validateContext = (context, options = {}) => {
  if (!context || typeof context !== "object") {
    throw new Error("Invalid context: expected object");
  }
  const strict = options.strict === true;
  const errors = [];
  const fail = (msg) => {
    errors.push(msg);
  };
  const isPlainObject = (o) => o && typeof o === "object" && !Array.isArray(o);
  const coerceNumber = (value, def = 0) => {
    const num = Number(value);
    return Number.isFinite(num) ? num : def;
  };
  // Using global clamp helper defined at top-level

  const ensureArray = (value) => (Array.isArray(value) ? value : []);
  const cap = (a, max = 200) => {
    if (a.length > max) {
      a.splice(0, a.length - max);
    }
  };
  const asStrOrNull = (value, maxLen = 120) =>
    value == null ? null : String(value).slice(0, maxLen);

  // Top-level containers
  if (!isPlainObject(context.vars)) {
    context.vars = {};
  }
  if (!isPlainObject(context.stats)) {
    context.stats = {};
  }
  if (!isPlainObject(context.memory)) {
    context.memory = {};
  }

  // Event bus shape (if present)
  if (context.io?.events) {
    if (typeof context.io.events.on !== "function") {
      fail("events.on missing");
    }
    if (typeof context.io.events.emit !== "function") {
      fail("events.emit missing");
    }
    if (typeof context.io.events.off !== "function") {
      fail("events.off missing");
    }
  }

  // Metrics array (namespaced)
  if (context.telemetry.metrics === undefined) {
    context.telemetry.metrics = [];
  } else if (!Array.isArray(context.telemetry.metrics)) {
    fail("metrics must be an array");
    context.telemetry.metrics = [];
  } else {
    const repaired = [];
    for (const m of context.telemetry.metrics) {
      if (!isPlainObject(m)) {
        continue;
      }
      const event =
        typeof m.event === "string" && m.event
          ? m.event
          : typeof m.type === "string"
            ? m.type
            : null;
      if (!event) {
        continue;
      }
      const ts = coerceNumber(m.ts ?? m.time ?? MessageClock.now());
      repaired.push({ ...m, event, ts, time: ts }); 
    }
    context.telemetry.metrics = repaired;
    try {
      rotateMetrics(context);
    } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
  }

  // Stats: latency
  const lat = isPlainObject(context.stats.latency) ? context.stats.latency : {};
  context.stats.latency = {
    lastMs: clamp(lat.lastMs, 0, CONFIG.ranges.latencyMsMax, 0),
    maxMs: clamp(lat.maxMs, 0, CONFIG.ranges.latencyMsMax, 0),
    avgMs: clamp(lat.avgMs, 0, CONFIG.ranges.latencyMsMax, 0),
    samples: clamp(lat.samples, 0, CONFIG.ranges.bigCounterMax, 0)
  };

  // Stats: dreamStyling
  const ds = isPlainObject(context.stats.dreamStyling) ? context.stats.dreamStyling : {};
  const clar = isPlainObject(ds.clarity) ? ds.clarity : {};
  const byStyle = isPlainObject(ds.byStyle) ? ds.byStyle : {};
  context.stats.dreamStyling = {
    total: clamp(ds.total, 0, CONFIG.ranges.bigCounterMax, 0),
    applied: clamp(ds.applied, 0, CONFIG.ranges.bigCounterMax, 0),
    clarity: {
      low: clamp(clar.low, 0, CONFIG.ranges.bigCounterMax, 0),
      medium: clamp(clar.medium, 0, CONFIG.ranges.bigCounterMax, 0),
      high: clamp(clar.high, 0, CONFIG.ranges.bigCounterMax, 0)
    },
    byStyle
  };

  // Stats: turns
  const turns = isPlainObject(context.stats.turns) ? context.stats.turns : {};
  context.stats.turns = {
    total: clamp(turns.total, 0, CONFIG.ranges.bigCounterMax, 0),
    lastTs: clamp(turns.lastTs, 0, CONFIG.ranges.timestampMax, 0)
  };

  // vars.llmTrace
  const lt = isPlainObject(context.vars.llmTrace) ? context.vars.llmTrace : {};
  lt.metrics = ensureArray(lt.metrics)
    .filter((x) => isPlainObject(x))
    .map((x) => {
      const ts = coerceNumber(x.ts ?? x.time ?? MessageClock.now());
      return { ...x, ts }; 
    });
  lt.latency = ensureArray(lt.latency)
    .filter((x) => isPlainObject(x))
    .map((x) => {
      const ts = coerceNumber(x.ts ?? MessageClock.now());
      const ms = coerceNumber(x.ms, 0);
      return { ts, ms };
    });
  lt.turns = ensureArray(lt.turns)
    .filter((x) => isPlainObject(x))
    .map((x) => {
      const ts = coerceNumber(x.ts ?? MessageClock.now());
      return { ts };
    });
  cap(lt.metrics, CONFIG.contextCaps.llmTraceMetrics);
  cap(lt.latency, CONFIG.contextCaps.llmTraceMetrics);
  cap(lt.turns, CONFIG.contextCaps.llmTraceMetrics);
  context.vars.llmTrace = lt;

  // vars.llmQueuedPrompts
  context.vars.llmQueuedPrompts = ensureArray(context.vars.llmQueuedPrompts)
    .filter((e) => isPlainObject(e))
    .map((e) => {
      const ts = clamp(e.ts ?? e.time, 0, CONFIG.ranges.timestampMax, MessageClock.now());
      const turn = clamp(e.turn, 0, CONFIG.ranges.bigCounterMax, context?.turn || 0);
      const messageCount = clamp(
        e.messageCount,
        0,
        CONFIG.ranges.bigCounterMax,
        context?.memory?.messageCount || 0
      );
      const kind = String(e.kind ?? "unknown").slice(0, 32);
      const text = String(e.text ?? "").slice(0, 2000);
      const hash = e.hash == null ? null : String(e.hash).slice(0, 128);
      const overlay = isPlainObject(e.overlay)
        ? {
            purpose: e.overlay.purpose == null ? null : String(e.overlay.purpose).slice(0, 64),
            tone: e.overlay.tone == null ? null : String(e.overlay.tone).slice(0, 64)
          }
        : undefined;
      const queueLen = clamp(e.queueLen, 0, CONFIG.ranges.bigCounterMax, 0);
      return { ts, turn, messageCount, kind, text, hash, overlay, queueLen };
    });
  cap(context.vars.llmQueuedPrompts, CONFIG.contextCaps.llmQueuedPrompts);

  // vars.llmQueue
  context.vars.llmQueue = ensureArray(context.vars.llmQueue)
    .filter((e) => isPlainObject(e))
    .map((e) => {
      const type = String(e.type ?? "unknown").slice(0, 32);
      const prompt = String(e.prompt ?? "").slice(0, 2000);
      const purpose = e.purpose == null ? null : String(e.purpose).slice(0, 64);
      const at = clamp(e.at, 0, CONFIG.ranges.timestampMax, MessageClock.now());
      return { type, prompt, purpose, at };
    });
  cap(context.vars.llmQueue, CONFIG.contextCaps.llmQueue);

  // Dev-only: circular reference detection for runtime arrays
  if (DEBUG_MODE) {
    const stack = new WeakSet();
    const visited = new WeakSet();
    const scan = (node, path) => {
      if (node === null) {
        return;
      }
      if (Array.isArray(node)) {
        for (let i = 0; i < node.length; i++) {
          scan(node[i], String(path) + "[" + String(i) + "]");
        }
        return;
      }
      if (typeof node === "object") {
        if (stack.has(node)) {
          logDebug(context, "validateContext: circular reference in " + String(path), "WARN");
          return;
        }
        if (visited.has(node)) {
          return;
        }
        stack.add(node);
        visited.add(node);
        for (const key of Object.keys(node)) {
          if (key === "__proto__" || key === "constructor" || key === "prototype") {
            logDebug(context, "validateContext: disallowed key '" + String(key) + "' at " + String(path), "WARN");
          } else {
            scan(node[key], String(path) + "." + String(key));
          }
        }
        stack.delete(node);
      }
    };
    try {
      scan(context.vars.llmQueue, "vars.llmQueue");
    } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
    try {
      scan(context.vars.llmQueuedPrompts, "vars.llmQueuedPrompts");
    } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
    try {
      scan(context.vars?.llmTrace?.promptOverlay, "vars.llmTrace.promptOverlay");
    } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
    try {
      scan(context.memory?.dreamHistory, "memory.dreamHistory");
    } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
  }

  // Relations numeric coercion (if present)
  if (isPlainObject(context.relations)) {
    context.relations.respect = clamp(context.relations.respect, 0, CONFIG.ranges.percentMax, 0);
    context.relations.cowardice = clamp(
      context.relations.cowardice,
      0,
      CONFIG.ranges.percentMax,
      0
    );
  }

  // Strict rules for memory
  const mem = context.memory;
  mem.trustLevel = clamp(
    mem.trustLevel,
    CONFIG.ranges.trust.min,
    CONFIG.ranges.trust.max,
    CONFIG.ranges.trust.min
  );
  mem.corruption = clamp(
    mem.corruption,
    CONFIG.ranges.corruption.min,
    CONFIG.ranges.corruption.max,
    CONFIG.ranges.corruption.min
  );
  mem.hallucinationTrust = clamp(
    mem.hallucinationTrust,
    CONFIG.ranges.hallucinationTrust.min,
    CONFIG.ranges.hallucinationTrust.max,
    CONFIG.ranges.hallucinationTrust.min
  );
  mem.tension = clamp(
    mem.tension,
    CONFIG.ranges.tension.min,
    CONFIG.ranges.tension.max,
    CONFIG.ranges.tension.min
  );
  mem.humanityLevel = clamp(
    mem.humanityLevel,
    CONFIG.ranges.humanity.min,
    CONFIG.ranges.humanity.max,
    CONFIG.ranges.humanity.max
  );
  mem.echoChainWeakness = clamp(
    mem.echoChainWeakness,
    CONFIG.ranges.echoChainWeakness.min,
    CONFIG.ranges.echoChainWeakness.max,
    CONFIG.ranges.echoChainWeakness.min
  );
  mem.lastInteractionTimestamp = clamp(
    mem.lastInteractionTimestamp,
    0,
    CONFIG.ranges.timestampMax,
    0
  );
  mem.firstSeenTimestamp = clamp(mem.firstSeenTimestamp, 0, CONFIG.ranges.timestampMax, 0);
  mem.sessionsStarted = clamp(mem.sessionsStarted, 0, CONFIG.ranges.bigCounterMax, 0);
  mem.evolutionCount = clamp(mem.evolutionCount, 0, CONFIG.ranges.bigCounterMax, 0);
  mem.evolutionAttempts = clamp(mem.evolutionAttempts, 0, CONFIG.ranges.bigCounterMax, 0);
  mem.evolutionFailures = clamp(mem.evolutionFailures, 0, CONFIG.ranges.bigCounterMax, 0);

  mem.boarKingLore = !!mem.boarKingLore;
  mem.evolved = !!mem.evolved;
  mem.userKilled = !!mem.userKilled;

  mem.title = asStrOrNull(mem.title);
  mem.petName = asStrOrNull(mem.petName);

  mem.topics = isPlainObject(mem.topics) ? mem.topics : {};
  mem.slangCounts = isPlainObject(mem.slangCounts) ? mem.slangCounts : {};

  // trustSource shape
  mem.trustSource = isPlainObject(mem.trustSource) ? mem.trustSource : { urga: 0, echo: 0 };
  mem.trustSource.urga = clamp(mem.trustSource.urga, 0, CONFIG.ranges.bigCounterMax, 0);
  mem.trustSource.echo = clamp(mem.trustSource.echo, 0, CONFIG.ranges.bigCounterMax, 0);

  // Ensure arrays exist for frequently used memory lists
  const listKeys = [
    "itemsBought",
    "userTraits",
    "corruptionTraits",
    "weaknesses",
    "lies",
    "characterNotes",
    "interactionHistory",
    "lastFallbacks",
    "echoHistory",
    "echoInfluence",
    "betrayalJournal",
    "dreamHistory",
    "echoObedience",
    "quests",
    "kinks"
  ];
  for (const k of listKeys) {
    mem[k] = ensureArray(mem[k]);
  }

  // Flags schema
  mem.flags = isPlainObject(mem.flags) ? mem.flags : {};
  mem.flags.userTriedToDeceive = !!mem.flags.userTriedToDeceive;
  mem.flags.userBegged = !!mem.flags.userBegged;
  mem.flags.redemptionAttempted = !!mem.flags.redemptionAttempted;
  mem.flags.userObeyedEcho = !!mem.flags.userObeyedEcho;
  mem.flags.userUsedSlang = ensureArray(mem.flags.userUsedSlang)
    .map((s) => String(s))
    .slice(0, CONFIG.contextCaps.userUsedSlang);
  mem.flags.userSuspect = clamp(mem.flags.userSuspect, 0, CONFIG.ranges.bigCounterMax, 0);

  // Normalize list elements and apply caps for pre-init safety
  const now = MessageClock.now();

  // characterNotes: { at, tag, text }
  mem.characterNotes = ensureArray(mem.characterNotes)
    .filter((entry) => isPlainObject(entry) || typeof entry === "string")
    .map((entry) => {
      const obj = isPlainObject(entry) ? entry : { text: String(entry) };
      const at = clamp(obj.at, 0, CONFIG.ranges.timestampMax, now);
      const tag = String(obj.tag ?? "misc").slice(0, 32);
      const text = String(obj.text ?? "").slice(0, 400);
      return { at, tag, text };
    });
  cap(mem.characterNotes, CONFIG.contextCaps.characterNotes);

  // interactionHistory: { at, input, hallucinated, sanitized, intent, insertedAtMessage }
  mem.interactionHistory = ensureArray(mem.interactionHistory)
    .filter((e) => isPlainObject(e))
    .map((e) => {
      const at = clamp(e.at, 0, CONFIG.ranges.timestampMax, now);
      const input = String(e.input ?? "").slice(0, 1000);
      const hallucinated = e.hallucinated == null ? null : String(e.hallucinated).slice(0, 1000);
      const sanitized = e.sanitized == null ? null : String(e.sanitized).slice(0, 1000);
      const intent = e.intent == null ? null : String(e.intent).slice(0, 64);
      const insertedAtMessage =
        typeof e.insertedAtMessage === "number"
          ? clamp(e.insertedAtMessage, 0, CONFIG.ranges.bigCounterMax, e.insertedAtMessage)
          : undefined;
      return { at, input, hallucinated, sanitized, intent, insertedAtMessage };
    });
  cap(mem.interactionHistory, CONFIG.contextCaps.interactionHistory);

  // lies: { at, msg, reason }
  mem.lies = ensureArray(mem.lies)
    .filter((e) => isPlainObject(e) || typeof e === "string")
    .map((e) => {
      const obj = isPlainObject(e) ? e : { msg: String(e) };
      const at = clamp(obj.at, 0, CONFIG.ranges.timestampMax, now);
      const msg = String(obj.msg ?? "").slice(0, 400);
      const reason = String(obj.reason ?? "").slice(0, 200);
      return { at, msg, reason };
    });
  cap(mem.lies, CONFIG.contextCaps.lies);

  // weaknesses: normalize to strings
  mem.weaknesses = ensureArray(mem.weaknesses).map((w) =>
    String(isPlainObject(w) ? (w.text ?? JSON.stringify(w)) : w).slice(0, 200)
  );
  cap(mem.weaknesses, CONFIG.contextCaps.weaknesses);

  // itemsBought: { at, genre, source, humanityLoss, humanityRemaining }
  mem.itemsBought = ensureArray(mem.itemsBought)
    .filter((e) => isPlainObject(e) || typeof e === "string")
    .map((e) => {
      const obj = isPlainObject(e) ? e : { genre: String(e) };
      const at = clamp(obj.at, 0, CONFIG.ranges.timestampMax, now);
      const genre = String(obj.genre ?? "")
        .toLowerCase()
        .slice(0, 40);
      const source = String(obj.source ?? "").slice(0, 40) || "unknown";
      const humanityLoss = clamp(
        obj.humanityLoss,
        CONFIG.ranges.humanity.min,
        CONFIG.ranges.humanity.max,
        0
      );
      const humanityRemaining = clamp(
        obj.humanityRemaining,
        CONFIG.ranges.humanity.min,
        CONFIG.ranges.humanity.max,
        CONFIG.ranges.humanity.max
      );
      return { at, genre, source, humanityLoss, humanityRemaining };
    });
  cap(mem.itemsBought, CONFIG.contextCaps.itemsBought);

  // lastFallbacks: strings
  mem.lastFallbacks = ensureArray(mem.lastFallbacks).map((s) => String(s).slice(0, 400));
  cap(mem.lastFallbacks, CONFIG.contextCaps.lastFallbacks);

  // echoHistory: strings
  mem.echoHistory = ensureArray(mem.echoHistory).map((s) => String(s).slice(0, 400));
  cap(mem.echoHistory, CONFIG.contextCaps.echoHistory);

  // echoInfluence: { type, data? }
  mem.echoInfluence = ensureArray(mem.echoInfluence)
    .filter((e) => isPlainObject(e) || typeof e === "string")
    .map((e) => {
      const obj = isPlainObject(e) ? e : { type: String(e) };
      const type = String(obj.type ?? "").slice(0, 40);
      const data = isPlainObject(obj.data) ? obj.data : undefined;
      return data ? { type, data } : { type };
    });
  cap(mem.echoInfluence, CONFIG.contextCaps.echoInfluence);

  // betrayalJournal: { at, reason, trustHit, delayReveal, insertedAtMessage }
  mem.betrayalJournal = ensureArray(mem.betrayalJournal)
    .filter((e) => isPlainObject(e) || typeof e === "string")
    .map((e) => {
      const obj = isPlainObject(e) ? e : { reason: String(e) };
      const at = clamp(obj.at, 0, CONFIG.ranges.timestampMax, now);
      const reason = String(obj.reason ?? obj.summary ?? "").slice(0, 300);
      const trustHit = clamp(obj.trustHit, 0, CONFIG.ranges.percentMax, 0);
      const delayReveal = !!obj.delayReveal;
      const insertedAtMessage = clamp(obj.insertedAtMessage, 0, CONFIG.ranges.bigCounterMax, 0);
      return { at, reason, trustHit, delayReveal, insertedAtMessage };
    });
  cap(mem.betrayalJournal, CONFIG.contextCaps.betrayalJournal);

  // dreamHistory: { at, type, summary, text, metadata, insertedAtMessage }
  mem.dreamHistory = ensureArray(mem.dreamHistory)
    .filter((e) => isPlainObject(e) || typeof e === "string")
    .map((e) => {
      const obj = isPlainObject(e) ? e : { text: String(e) };
      const at = clamp(obj.at, 0, CONFIG.ranges.timestampMax, now);
      const type = String(obj.type ?? "dream").slice(0, 32);
      const summary = String(obj.summary ?? "").slice(0, 400);
      const text = String(obj.text ?? "").slice(0, 2000);
      const metadata = isPlainObject(obj.metadata) ? obj.metadata : {};
      if (metadata.topics) {
        metadata.topics = ensureArray(metadata.topics).map((t) => String(t).slice(0, 32));
        cap(metadata.topics, CONFIG.contextCaps.topics);
      }
      const insertedAtMessage =
        typeof obj.insertedAtMessage === "number"
          ? clamp(obj.insertedAtMessage, 0, CONFIG.ranges.bigCounterMax, obj.insertedAtMessage)
          : undefined;
      return { at, type, summary, text, metadata, insertedAtMessage };
    });
  cap(mem.dreamHistory, CONFIG.contextCaps.dreamHistory);

  if (strict && errors.length) {
    throw new Error(`Context schema invalid: ${errors.join("; ")}`); 
  }
  return { valid: errors.length === 0, errors }; 
};

/**
 * Initializes and normalizes `context.memory`, settings, events, and derived fields.
 * Validates config, attaches event bus/listeners, and ensures schema safety.
 * @param {Context} context - Runtime context to initialize.
 * @returns {void}
 */
// Context namespacing and legacy aliasing
const defineAlias = (obj, prop, getter, setter) => {
  try {
    const desc = Object.getOwnPropertyDescriptor(obj, prop);
    if (desc && (desc.get || desc.set)) {
      return;
    } // already accessor
    Object.defineProperty(obj, prop, {
      configurable: true,
      enumerable: true,
      get: getter,
      set: setter
    });
  } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
};
const ensureContextNamespaces = (context) => {
  context.session ??= {};
  context.telemetry ??= {};
  context.io ??= {};
  context.runtime ??= {};
  context.state ??= {};

  // Move existing fields into namespaces
  if (context.memory && !context.session.memory) {
    context.session.memory = context.memory;
  }
  context.session.memory ??= {};
  if (context.metrics && !context.telemetry.metrics) {
    context.telemetry.metrics = context.metrics;
  }
  context.telemetry.metrics ??= [];
  if (context.metricsArchive && !context.telemetry.metricsArchive) {
    context.telemetry.metricsArchive = context.metricsArchive; (globalThis.__URGA_assertCaps&&globalThis.__URGA_assertCaps(context));
  }
  context.telemetry.metricsArchive ??= [];
  if (context._metricsIndex && !context.telemetry._metricsIndex) {
    context.telemetry._metricsIndex = context._metricsIndex;
  }
  context.telemetry._metricsIndex ??= null;
  if (context.llmTrace && !context.telemetry.llmTrace) {
    context.telemetry.llmTrace = context.llmTrace;
  }
  context.telemetry.llmTrace ??= [];

  if (context.events && !context.io.events) {
    context.io.events = context.events;
  }
  if (context.actions && !context.io.actions) {
    context.io.actions = context.actions;
  }

  if (context.rng && !context.runtime.rng) {
    context.runtime.rng = context.rng;
  }
  if (context.flags && !context.runtime.flags) {
    context.runtime.flags = context.flags;
  }

  if (context.vars && !context.state.vars) {
    context.state.vars = context.vars;
  }
  if (context._recentLines && !context.state._recentLines) {
    context.state._recentLines = context._recentLines;
  }

  // Legacy aliases to namespaced fields
  defineAlias(
    context,
    "memory",
    () => context.session.memory,
    (value) => {
      context.session.memory = value;
    }
  );
  defineAlias(
    context,
    "metrics",
    () => context.telemetry.metrics,
    (value) => {
      context.telemetry.metrics = value;
    }
  );
  defineAlias(
    context,
    "metricsArchive",
    () => context.telemetry.metricsArchive,
    (value) => {
      context.telemetry.metricsArchive = value; (globalThis.__URGA_assertCaps&&globalThis.__URGA_assertCaps(context));
    }
  );
  defineAlias(
    context,
    "_metricsIndex",
    () => context.telemetry._metricsIndex,
    (value) => {
      context.telemetry._metricsIndex = value;
    }
  );
  defineAlias(
    context,
    "llmTrace",
    () => context.telemetry.llmTrace,
    (value) => {
      context.telemetry.llmTrace = value;
    }
  );

  defineAlias(
    context,
    "events",
    () => context.io.events,
    (value) => {
      context.io.events = value;
    }
  );
  defineAlias(
    context,
    "actions",
    () => context.io.actions,
    (value) => {
      context.io.actions = value;
    }
  );

  defineAlias(
    context,
    "rng",
    () => context.runtime.rng,
    (value) => {
      context.runtime.rng = value;
    }
  );
  defineAlias(
    context,
    "flags",
    () => context.runtime.flags,
    (value) => {
      context.runtime.flags = value;
    }
  );

  defineAlias(
    context,
    "vars",
    () => context.state.vars,
    (value) => {
      context.state.vars = value;
    }
  );
  defineAlias(
    context,
    "_recentLines",
    () => context.state._recentLines,
    (value) => {
      context.state._recentLines = value;
    }
  );
};

const ensureArray = (obj, path) => {
  const parts = String(path || "").split(".");
  let current = obj;
  for (const p of parts) {
    if (!current[p]) {
      current[p] = [];
    }
    current = current[p];
  }
  return current;
};

const ensureMemory = (context) => {
  if (!context) {
    throw new Error("Context is required for ensureMemory");
  }

  // Ensure namespaced structure before further initialization
  ensureContextNamespaces(context);

  // Validate LLM-related configuration to ensure sane bounds and store normalized copy
  try {
    context.llmConfig = validateLLMConfig(CONFIG.llm);
  } catch (err) {
    handleError(context, err, "validate.llm_config");
  }

  const now = MessageClock.now();

  context.memory ??= {};

  // Reentrancy guard to prevent recursive ensureMemory calls
  if (context.memory.__ensuring) {
    return;
  }
  context.memory.__ensuring = true;

  // Initialize event bus for centralized events/metrics
  context.io ??= {};
  context.io.events ??= createEventBus(context);

  // Schema validation for critical structures
  let _validation = { valid: true, errors: [] };
  try {
    _validation = validateContext(context);
  } catch (err) {
    _validation = { valid: false, errors: [String(err.message || err)] }; 
    try {
      logDebug(context, `validateContext failed: ${err.message}`, "WARN"); 
    } catch (err) {
      handleError(context, err, "validateContext.logDebug");
    }
  }
  try {
    context.io.events.emit("context_validated", {
      ..._validation,
      ts: MessageClock.now()
    });
  } catch (err) {
    handleError(context, err, "events.context_validated");
  }
  try {
    Metrics.log?.(context, "context_validated", {
      ..._validation,
      ts: MessageClock.now(),
      __busEmitted: true
    });
  } catch (err) {
    handleError(context, err, "metrics.context_validated");
  }

  // Attach high-value event listeners once per context
  context.vars ??= {};
  if (!context.vars._defaultEventListenersAttached) {
    // Stats containers
    context.stats = context.stats || {};
    context.stats.dreamStyling = context.stats.dreamStyling || {
      total: 0,
      applied: 0,
      clarity: { low: 0, medium: 0, high: 0 },
      byStyle: {}
    };
    context.stats.latency = context.stats.latency || {
      lastMs: 0,
      maxMs: 0,
      avgMs: 0,
      samples: 0
    };

    const dreamHandler = (entry) => {
      try {
        const event = entry || {};
        const ds = context.stats.dreamStyling;
        ds.total += 1;
        if (event.applied) {
          ds.applied += 1;
        }
        const c = Number(event.clarity);
        if (Number.isFinite(c)) {
          if (c < 0.34) {
            ds.clarity.low += 1;
          } else if (c < 0.67) {
            ds.clarity.medium += 1;
          } else {
            ds.clarity.high += 1;
          }
        }
        const style = String(event.style || "").trim();
        if (style) {
          const rec = ds.byStyle[style] || { total: 0, applied: 0 };
          rec.total += 1;
          if (event.applied) {
            rec.applied += 1;
          }
          ds.byStyle[style] = rec;
        }
      } catch (err) {
        handleError(undefined, err, "catch.all");
      }
    };

    const latencyHandler = (entry) => {
      try {
        const event = entry || {};
        const ms = Number(event.ms ?? event.response_time);
        if (!Number.isFinite(ms)) {
          return;
        }
        const lat = context.stats.latency;
        lat.lastMs = ms;
        lat.maxMs = Math.max(toNum(lat.maxMs), ms);
        lat.samples = toNum(lat.samples) + 1;
        const sampleCount = lat.samples;
        const prevAvg = toNum(lat.avgMs);
        lat.avgMs = prevAvg + (ms - prevAvg) / sampleCount;
        // Stream latency data
        context.vars.llmTrace = context.vars.llmTrace || {};
        const arr = ensureArray(context, "vars.llmTrace.latency");
        safePush(arr, { ts: toNum(event.ts, MessageClock.now()), ms }, CONFIG.contextCaps.llmTraceMetrics); 
        context.vars.llmTrace.latency = arr;
      } catch (err) {
        handleError(undefined, err, "catch.all");
      }
    };

    const turnEndHandler = (entry) => {
      try {
        const ts = toNum(entry?.timestamp ?? entry?.ts, MessageClock.now());
        context.stats.turns = context.stats.turns || { total: 0, lastTs: 0 };
        context.stats.turns.total = toNum(context.stats.turns.total) + 1;
        context.stats.turns.lastTs = ts;
        context.vars.llmTrace = context.vars.llmTrace || {};
        const tarr = ensureArray(context, "vars.llmTrace.turns");
        safePush(tarr, { ts }, CONFIG.contextCaps.llmTraceMetrics);
        context.vars.llmTrace.turns = tarr;
      } catch (err) {
        handleError(undefined, err, "catch.all");
      }
    };

    try {
      context.io.events.on("dreamStyling", dreamHandler);
    } catch (err) {
      handleError(undefined, err, "catch.all");
    }
    try {
      context.io.events.on("response_time", latencyHandler);
    } catch (err) {
      handleError(undefined, err, "catch.all");
    }
    try {
      context.io.events.on("turn_end", turnEndHandler);
    } catch (err) {
      handleError(undefined, err, "catch.all");
    }

    context.vars._defaultEventListenersAttached = true;
  }

  // AI runtime wiring: adapters, tools, memory, retrieval, persona
  try {
    context.modelAdapter ??= new ModelAdapter(context);
  } catch {}
  try {
    context.toolRegistry = context.toolRegistry || _ToolRegistry;
    context.runTool = context.runTool || ((name, input, opts = {}) => _ToolRegistry.run(context, name, input, opts));
  } catch {}
  try {
    // Short-term memory section for prompts (token-window)
    context.vars.shortTermBudgetTokens = Number(context.vars?.shortTermBudgetTokens || CONFIG?.llm?.shortTermBudgetTokens || 1024);
    context.memorySectionBuilder = context.memorySectionBuilder || ((ctx) => ConversationMemory.shortWindow(ctx, ctx.vars.shortTermBudgetTokens));
  } catch {}
  try {
    context.retrieval = context.retrieval || {
      ingest: (doc) => ConversationMemory.ingest(context, doc),
      retrieve: (q, opts) => ConversationMemory.retrieve(context, q, opts),
      cite: (items) => ConversationMemory.cite(items)
    };
  } catch {}
  try {
    context.conversationContract = context.conversationContract || ConversationContract;
    context.appendMessage = context.appendMessage || ((msg) => ConversationContract.appendMessage(context, msg));
    context.promptBytesForTurn = context.promptBytesForTurn || ((turn) => ConversationContract.promptBytesForTurn(context, turn));
    context.promptHashForTurn = context.promptHashForTurn || ((turn) => ConversationContract.promptHashForTurn(context, turn));
  } catch {}
  try {
    // Default persona pack if none applied
    if (!context.persona) {
      PersonaManager.register('default', { name: 'default', system: 'You are a helpful assistant.', policy: '', allowed_tools: '*', refusal_stance: 'open', persona_v: 1, prompt_v: 1 });
      PersonaManager.apply(context, 'default');
    }
  } catch {}

  Object.assign(context.memory, {
    lastTrustGainTimestamp: context.memory.lastTrustGainTimestamp ?? 0,
    lastTrustGainMessageCount: context.memory.lastTrustGainMessageCount ?? 0,
    trustSource: context.memory.trustSource ?? { urga: 0, echo: 0 },
    messageCount: context.memory.messageCount ?? 0,
    lastTrustDecayMessageCount: context.memory.lastTrustDecayMessageCount ?? 0,
    lastCorruptionDecayMessageCount: context.memory.lastCorruptionDecayMessageCount ?? 0,
    lastHallucinationDecay: context.memory.lastHallucinationDecay ?? now,
    offenseCount: context.memory.offenseCount ?? 0,
    userKilled: context.memory.userKilled ?? false,
    itemsBought: context.memory.itemsBought ?? [],
    userTraits: context.memory.userTraits ?? [],
    evolved: context.memory.evolved ?? false,
    corruption: context.memory.corruption ?? 0,
    corruptionTraits: context.memory.corruptionTraits ?? [],
    weaknesses: context.memory.weaknesses ?? [],
    lies: context.memory.lies ?? [],
    characterNotes: context.memory.characterNotes ?? [],
    interactionHistory: context.memory.interactionHistory ?? [],
    interactionSummaries: context.memory.interactionSummaries ?? [],
    topics: context.memory.topics ?? {},
    trustLevel: context.memory.trustLevel ?? 0,
    lastFallbacks: context.memory.lastFallbacks ?? [],
    flags: context.memory.flags ?? {
      userTriedToDeceive: false,
      userBegged: false,
      userUsedSlang: [],
      userSuspect: 0,
      urgaSnapped: false,
      redemptionAttempted: false
    },
    slangCounts: context.memory.slangCounts ?? {},
    emotionalSnapshot: context.memory.emotionalSnapshot ?? null,
    emotionalSnapshotTimestamp: context.memory.emotionalSnapshotTimestamp ?? 0,
    lastInteractionTimestamp: context.memory.lastInteractionTimestamp ?? now,
    firstSeenTimestamp: context.memory.firstSeenTimestamp ?? now,
    sessionsStarted: context.memory.sessionsStarted ?? 1,
    evolutionCount: context.memory.evolutionCount ?? 0,
    quests: context.memory.quests ?? [],
    echoHistory: context.memory.echoHistory ?? [],
    echoInfluence: context.memory.echoInfluence ?? [],
    tension: context.memory.tension ?? 0,
    kinks: context.memory.kinks ?? [],
    sensitiveAreas: context.memory.sensitiveAreas ?? [],
    kinkBoundaries: context.memory.kinkBoundaries ?? [],
    title: context.memory.title ?? null,
    petName: context.memory.petName ?? null,
    hallucinationTrust: context.memory.hallucinationTrust ?? 0,
    evolutionStage: context.memory.evolutionStage ?? "none",
    achievements: context.memory.achievements ?? [],
    dreamHistory: context.memory.dreamHistory ?? [],
    betrayalJournal: context.memory.betrayalJournal ?? [],
    boarKingLore: context.memory.boarKingLore ?? true,
    humanityLevel: context.memory.humanityLevel ?? 100,
    echoChainWeakness: context.memory.echoChainWeakness ?? 0,
    godInfluences: context.memory.godInfluences ?? [],
    emotions: context.memory.emotions ?? {
      anxiety: 0.4,
      awe: 0.6,
      dread: 0.1,
      trust: 0.5
    },
    userStats: context.memory.userStats ?? {
      praise: 0,
      threats: 0,
      abandonmentCount: 0
    },
    memoryGraph: context.memory.memoryGraph ?? { nodes: [] }
  });

  // Cap large arrays
  capArray(context.memory.characterNotes, CONFIG.contextCaps.characterNotes);
  capArray(context.memory.interactionHistory, CONFIG.contextCaps.interactionHistory);
  capArray(context.memory.interactionSummaries, CONFIG.contextCaps.interactionSummaries);
  capArray(context.memory.lies, CONFIG.contextCaps.lies);
  capArray(context.memory.weaknesses, CONFIG.contextCaps.weaknesses);
  capArray(context.memory.itemsBought, CONFIG.contextCaps.itemsBought);
  capArray(context.memory.corruptionTraits, CONFIG.contextCaps.corruptionTraitsRecent);
  capArray(context.memory.lastFallbacks, CONFIG.contextCaps.lastFallbacks);
  Memory.echo.decay(context, 20);
  capArray(context.memory.echoInfluence, CONFIG.contextCaps.echoInfluence);
  capArray(context.memory.betrayalJournal, CONFIG.contextCaps.betrayalJournalRecent);
  capArray(context.memory.dreamHistory, CONFIG.contextCaps.dreamHistory);

  // One-time migration of god influence timestamps to message indices
  if (!context.memory._migratedAppliedAtToMessage) {
    migrateGodInfluencesToMessage(context);
  }
  // Ensure map exists for threshold-based queries and Decay.decayGods
  if (!context.memory.godInfluence || Object.keys(context.memory.godInfluence).length === 0) {
    try {
      syncGodInfluenceMap(context);
    } catch (err) {
      handleError(undefined, err, "catch.all");
    }
  }
  // Initialize consolidated gods structure and migrate legacy fields
  try {
    ensureGods(context);
  } catch (err) {
    handleError(undefined, err, "catch.all");
  }

  // Ensure top-level session vars
  context.relations ??= { respect: 0, cowardice: 0, alignment: "neutral" };
  context.vars ??= {};
  // Attach LLMService for centralized LLM calls
  ensureDeps(context);
  context.llmService ??= new (getDep(context, "LLMService", LLMService))(context);
  // Bind llm.call to LLMService
  context.llm ??= {};
  context.llm.call ??= (input, options = {}) => context.llmService.call(input, options);
  context.llm.stream ??= (input, options = {}) => context.llmService.stream(input, options);

  // FIX: Initialize god storage in context.vars instead of globals
  context.vars.godDomains ??= [];
  context.vars.godBehaviors ??= {};
  // Init memory bleed state when seeded/looped flags exist
  context.vars._memoryBleed ??= {
    seeded: !!(context?.flags?.seeded || context?.flags?.looped),
    selections: [],
    lastAt: 0
  };

  // Initialize and cap player memory tracking
  context.playerMemory ??= [];
  capArray(context.playerMemory, CONFIG.contextCaps.playerMemoryRecent);

  // Sync to derived stats for display / modules
  context.vars.userStats = {
    corruption: context.memory.corruption,
    trustLevel: context.memory.trustLevel,
    title: context.memory.title,
    evolutionStage: context.memory.evolutionStage,
    humanityLevel: context.memory.humanityLevel,
    echoChainWeakness: context.memory.echoChainWeakness,
    hallucinationTrust: context.memory.hallucinationTrust,
    nickname: context.memory.petName || null,
    respect: context.relations?.respect,
    cowardice: context.relations?.cowardice
  };

  attachSerializationMethods?.(context);
  try {
    if (context?.vars?.promptDSL) {
      ensureCoreDeps(context).PluginLoader?.register(createPromptDSLPlugin(context.vars.promptDSL));
    }
  } catch (err) {
    logDebug(context, `register PromptDSL failed: ${err.message}`, "WARN"); 
  }
  ensureStats(context);
  if (context.memory) {
    delete context.memory.__ensuring;
  }
};

// Migration: map legacy appliedAt timestamps to appliedAtMessage
const migrateGodInfluencesToMessage = (context) => {
  try {
    const influences = Array.isArray(context.memory.godInfluences)
      ? context.memory.godInfluences
      : [];
    if (!influences.length) {
      context.memory._migratedAppliedAtToMessage = true;
      return;
    }
    const needs = influences.some(
      (inf) => inf && typeof inf.appliedAt === "number" && inf.appliedAtMessage == null
    );
    if (!needs) {
      context.memory._migratedAppliedAtToMessage = true;
      return;
    }

    const interactions = Array.isArray(context.memory.interactionHistory)
      ? context.memory.interactionHistory.slice()
      : [];
    const hasAt = interactions.length && interactions.every((it) => typeof it.at === "number");
    let timeline = null;
    if (hasAt) {
      interactions.sort((a, b) => (a.at || 0) - (b.at || 0));
      timeline = interactions.map((it, idx) => ({
        at: it.at || 0,
        idx: typeof it.insertedAtMessage === "number" ? it.insertedAtMessage : idx + 1
      }));
    }

    for (const inf of influences) {
      if (inf.appliedAtMessage == null && typeof inf.appliedAt === "number") {
        if (timeline) {
          const found =
            timeline.find((t) => t.at >= inf.appliedAt) || timeline[timeline.length - 1];
          inf.appliedAtMessage = found ? found.idx : context.memory.messageCount || 0;
        }
      }
    }

    const unresolved = influences.filter(
      (inf) => inf.appliedAtMessage == null && typeof inf.appliedAt === "number"
    );
    if (unresolved.length) {
      unresolved.sort((a, b) => a.appliedAt - b.appliedAt);
      const base =
        typeof context.memory.messageCount === "number"
          ? context.memory.messageCount
          : timeline
            ? timeline.length
            : 0;
      const start = Math.max(0, base - unresolved.length);
      unresolved.forEach((inf, i) => {
        inf.appliedAtMessage = start + i + 1;
      });
    }

    influences.forEach((inf) => {
      if (inf.appliedAtMessage == null) {
        inf.appliedAtMessage = 0;
      }
      // Seed map-based influence from legacy entries
      context.memory.godInfluence ??= {};
      const prev = toNum(context.memory.godInfluence[inf.domain]);
      context.memory.godInfluence[inf.domain] = Math.min(1, prev + 0.1);
    });

    context.memory._migratedAppliedAtToMessage = true;
  } catch (e) {
    logDebug(context, `God influence migration failed: ${e.message}`, "ERROR"); 
    context.memory._migratedAppliedAtToMessage = true;
  }
};

// === KINK COMMANDS HANDLER ===

// Sync helper: rebuild map from array influences when needed
const syncGodInfluenceMap = (context, options = {}) => {
  ensureMemory(context);
  const { limit = 4, per = 0.25, force = false } = options;
  try {
    const influences = Array.isArray(context.memory?.godInfluences)
      ? context.memory.godInfluences.slice()
      : [];
    const hasMap =
      context.memory?.godInfluence && Object.keys(context.memory.godInfluence).length > 0;
    if (!force && hasMap) {
      return;
    }

    const currentMsg = context.memory?.messageCount || 0;
    influences.sort(
      (a, b) =>
        (b.appliedAtMessage || 0) - (a.appliedAtMessage || 0) ||
        currentMsg - (a.appliedAtMessage || 0)
    );
    const recent = influences.slice(0, limit);
    const map = {};

    for (const inf of recent) {
      const domain = String(inf?.domain || "unknown");
      map[domain] = Math.min(1, (map[domain] || 0) + per);
    }

    context.memory.godInfluence = map;
  } catch (err) {
    handleError(undefined, err, "catch.all");
  }
};

/**
 * Handles user kink-related commands and sets appropriate responses
 * @param {Context} context - Game context
 * @param {string} m - Sanitized user message
 * @returns {boolean|void} true if a command matched and handled
 */
const handleKinkCommands = (context, m) => {
  const addToList = (input, field) => {
    const parts = String(input)
      .split(",")
      .map((k) => k.trim().toLowerCase())
      .filter(Boolean);
    context.memory[field] = parts;
  };

  if (/^!kinks /i.test(m)) {
    addToList(m.replace(/^!kinks /i, ""), "kinks");
    setReply(context, "Ur'ga hisses. \"Kinks logged: " + context.memory.kinks.join(", ") + ".\""); 
    return true;
  }

  if (/^!limits /i.test(m)) {
    addToList(m.replace(/^!limits /i, ""), "kinkBoundaries");
    setReply(context, "Ur'ga snarls. \"Fine. No: " + context.memory.kinkBoundaries.join(", ") + ".\""); 
    return true;
  }

  if (/^!sensitive /i.test(m)) {
    addToList(m.replace(/^!sensitive /i, ""), "sensitiveAreas");
    setReply(
      context,
      "Ur'ga whispers. \"Noted. Weak spots: " + context.memory.sensitiveAreas.join(", ") + ".\""
    );
    return true;
  }

  return false;
};

// === MEMORY MANAGER (scaffold) ===
// State Ownership: trustLevel and corruption live in context.memory.
// context.stats exposes derived accessors bound to memory.
// External code MUST mutate via MemoryManager.set*/adjust* to avoid divergence.
/**
 * Provides controlled mutations and derived updates for `context.memory`
 * @type {{init:(ctx:any)=>void,recomputeDerived:(ctx:any)=>void,setTrust:(ctx:any,value:number,reason?:string)=>number,adjustTrust:(ctx:any,delta:number,reason?:string)=>number,setCorruption:(ctx:any,value:number,reason?:string)=>number,adjustCorruption:(ctx:any,delta:number,reason?:string)=>number,updateStats:(ctx:any)=>void,pushJournal:(ctx:any,entry?:object)=>void,logBetrayal:(ctx:any,reason?:string)=>void,addTrust:(ctx:any,amount?:number,reason?:string)=>number,removeTrust:(ctx:any,amount?:number,reason?:string)=>number,reduceHumanity:(ctx:any,amount?:number,reason?:string)=>number}}
 */
const MemoryManager = {
  /**
   * Initializes memory and stats then recomputes derived values
   * @param {Context} context - Game context
   */
  init(context) {
    ensureMemory(context);
    context.vars ??= {};
    ensureStats(context);
    this.recomputeDerived(context);
  },
  /**
   * Rebinds derived stats to context.stats based on current memory
   * @param {Context} context - Game context
   */
  recomputeDerived(context) {
    const humanity = context.memory.humanityLevel ?? 100;
    context.memory.echoChainWeakness = clamp(
      CONFIG.ranges.echoChainWeakness.max - humanity,
      CONFIG.ranges.echoChainWeakness.min,
      CONFIG.ranges.echoChainWeakness.max,
      CONFIG.ranges.echoChainWeakness.min
    );
    context.vars.userStats = {
      corruption: context.memory.corruption,
      trustLevel: context.memory.trustLevel,
      title: context.memory.title,
      evolutionStage: context.memory.evolutionStage,
      humanityLevel: context.memory.humanityLevel,
      echoChainWeakness: context.memory.echoChainWeakness,
      hallucinationTrust: context.memory.hallucinationTrust,
      nickname: context.memory.petName || null,
      respect: context.relations?.respect,
      cowardice: context.relations?.cowardice
    };
  },
  setTrust(context, value, reason = "") {
    try {
      const nextTrust = clamp(
        Number(value) || 0,
        CONFIG.ranges.trust.min,
        CONFIG.ranges.trust.max,
        CONFIG.ranges.trust.min
      );
      const prev = context.memory?.trustLevel ?? 0;
      context.memory.trustLevel = nextTrust;
      this.recomputeDerived(context);
      try {
        ensureCoreDeps(context).Metrics.log(context, "trustSet", {
          from: prev,
          to: nextTrust,
          reason
        });
      } catch (err) {
        handleError(context, err, "metrics.trustSet");
      }
      if (DEBUG_MODE) {
        logDebug(context, "Trust set to " + String(nextTrust) + " (" + String(reason) + ")", "INFO");
      }
      return nextTrust;
    } catch {
      return context.memory?.trustLevel ?? 0;
    }
  },
  adjustTrust(context, delta, reason = "") {
    const base = context.memory?.trustLevel ?? 0;
    return this.setTrust(context, base + (Number(delta) || 0), reason || "trust.adjust");
  },
  setCorruption(context, value, reason = "") {
    try {
      const nextCorruption = clamp(
        Number(value) || 0,
        CONFIG.ranges.corruption.min,
        CONFIG.ranges.corruption.max,
        CONFIG.ranges.corruption.min
      );
      const prev = context.memory?.corruption ?? 0;
      context.memory.corruption = nextCorruption;
      this.recomputeDerived(context);
      try {
        ensureCoreDeps(context).Metrics.log(context, "corruptionSet", {
          from: prev,
          to: nextCorruption,
          reason
        });
      } catch (err) {
        handleError(context, err, "metrics.corruptionSet");
      }
      if (DEBUG_MODE) {
        logDebug(context, "Corruption set to " + String(nextCorruption) + " (" + String(reason) + ")", "INFO");
      }
      return nextCorruption;
    } catch {
      return context.memory?.corruption ?? 0;
    }
  },
  adjustCorruption(context, delta, reason = "") {
    const base = context.memory?.corruption ?? 0;
    return this.setCorruption(context, base + (Number(delta) || 0), reason || "corruption.adjust");
  },
  /**
   * Updates derived stats bindings from current memory values
   * @param {Context} context - Game context
   */
  updateStats(context) {
    this.recomputeDerived(context);
  },
  /**
   * Pushes a betrayal journal entry with timestamp and caps history length
   * @param {Context} context - Game context
   * @param {Object} [entry={}] - Partial journal entry
   * @returns {Object} The final journal entry stored
   */
  pushJournal(context, entry = {}) {
    ensureMemory(context);
    const final = Object.assign(
      { at: MessageClock.now(), insertedAtMessage: context.memory.messageCount }, 
      entry
    );
    context.memory.betrayalJournal ??= [];
    pushUniqueCap(context.memory.betrayalJournal, final, CONFIG.contextCaps.betrayalJournal);
    try {
      ensureCoreDeps(context).Metrics.log(context, "betrayalJournal", final);
    } catch (err) {
      handleError(undefined, err, "catch.all");
    }
    return final;
  },
  /**
   * Logs a betrayal event and applies trust penalty
   * @param {Context} context - Game context
   * @param {string} [reason="Unspecified"] - Reason for betrayal
   * @returns {Object} The created journal entry
   */
  logBetrayal(context, reason = "Unspecified") {
    const e = this.pushJournal(context, {
      reason,
      trustHit: 1,
      delayReveal: true
    });
    try {
      ensureCoreDeps(context).Metrics.log(context, "betrayal", {
        reason,
        trustHit: 1,
        delayReveal: true
      });
    } catch (err) {
      handleError(undefined, err, "catch.all");
    }
    this.removeTrust(context, 1, `Betrayal: ${reason}`);
    return e;
  },
  /**
   * Increases trust level if allowed and records source metrics
   * @param {Context} context - Game context
   * @param {number} [amount=1] - Trust increase amount
   * @param {string} [reason=""] - Optional reason for metric logging
   * @returns {boolean} true if trust was increased, otherwise false
   */
  addTrust(context, amount = 1, reason = "") {
    if (!canGainTrust(context)) {
      return false;
    }
    context.memory.trustLevel = clamp(
      (context.memory?.trustLevel ?? 0) + amount,
      CONFIG.ranges.trust.min,
      CONFIG.ranges.trust.max,
      CONFIG.ranges.trust.min
    );
    context.memory.trustSource.urga = (context.memory.trustSource.urga || 0) + amount;
    context.memory.lastTrustGainTimestamp = MessageClock.now();
    context.memory.lastTrustGainMessageCount = context.memory.messageCount;
    this.recomputeDerived(context);
    try {
      ensureCoreDeps(context).Metrics.log(context, "trust.changed", {
        delta: amount,
        reason,
        source: "urga",
        trustLevel: context.memory.trustLevel
      });
    } catch (err) {
      handleError(context, err, "metrics.trust.changed.increase");
    }
    if (DEBUG_MODE) {
      logDebug(context, "Trust +" + String(amount) + " (" + String(reason) + ")", "INFO");
    }
    return true;
  },
  /**
   * Decreases trust level and logs the change
   * @param {Context} context - Game context
   * @param {number} [amount=1] - Trust decrease amount
   * @param {string} [reason=""] - Optional reason for metric logging
   * @returns {number} The new clamped trust value
   */
  removeTrust(context, amount = 1, reason = "") {
    Decay.linear(context.memory, "trustLevel", amount, 0);
    context.memory.trustSource ??= { urga: 0, echo: 0 };
    context.memory.trustSource.urga = Math.max(0, context.memory.trustSource.urga - amount);
    context.memory.tension = clamp(
      (context.memory?.tension ?? 0) + amount,
      CONFIG.ranges.tension.min,
      CONFIG.ranges.tension.max,
      CONFIG.ranges.tension.min
    );
    this.recomputeDerived(context);
    try {
      ensureCoreDeps(context).Metrics.log(context, "trust.changed", {
        delta: -amount,
        reason,
        source: "urga",
        trustLevel: context.memory.trustLevel,
        tension: context.memory.tension
      });
    } catch (err) {
      handleError(context, err, "metrics.trust.changed.decrease");
    }
    if (DEBUG_MODE) {
      logDebug(context, "Trust -" + String(amount) + " (" + String(reason) + ")", "WARN");
    }
    return true;
  },
  /**
   * Reduces humanity level by an amount and updates derived stats
   * @param {Context} context - Game context
   * @param {number} [amount=1] - Humanity reduction amount
   * @param {string} [reason=""] - Reason for reduction (e.g., purchase)
   * @returns {number} New humanity level after clamping
   */
  reduceHumanity(context, amount = 1, reason = "") {
    ensureMemory(context);
    const prev = context.memory.humanityLevel ?? 100;
    const loss = Math.max(0, amount || 0);
    const next = Math.max(0, prev - loss);
    context.memory.humanityLevel = next;
    this.recomputeDerived(context);
    if (DEBUG_MODE) {
      logDebug(context, "Humanity -" + String(loss) + " (" + String(reason) + "). Remaining=" + String(next) + "%", "INFO");
    }
    return next;
  }
};

// === GOD SYSTEM CONSOLIDATION ===
const ensureGods = (context) => {
  context.gods ??= { active: new Map(), history: [] };
  // Migrate legacy influences array into history
  const legacyList = Array.isArray(context.memory?.godInfluences)
    ? context.memory.godInfluences
    : [];
  if (
    legacyList.length &&
    (!Array.isArray(context.gods.history) || context.gods.history.length === 0)
  ) {
    context.gods.history = legacyList.slice();
  }
  // Migrate legacy godInfluence map into active weights
  const legacyMap = context.memory?.godInfluence || {};
  const nowMsg = toNum(context.memory?.messageCount);
  // Seed behaviors from legacy storage
  const behaviors = getGodBehaviors(context);
  // Ensure Map exists
  if (!(context.gods.active instanceof Map)) {
    context.gods.active = new Map();
  }
  // From history: compute recent weights with simple decay
  const decayWindow = typeof GOD_DECAY_MESSAGES === "number" ? GOD_DECAY_MESSAGES : 30;
  for (const inf of legacyList) {
    const domain = String(inf?.domain || "unknown");
    const ageMsgs = Math.max(0, nowMsg - Number(inf?.appliedAtMessage ?? nowMsg));
    const weightFromHistory = Math.max(0, 1 - Math.min(1, ageMsgs / decayWindow));
    const prev = context.gods.active.get(domain) || {
      weight: 0,
      lastTouch: 0,
      behavior: null
    };
    const merged = {
      weight: Math.max(prev.weight, weightFromHistory),
      lastTouch: Math.max(prev.lastTouch || 0, Number(inf?.appliedAtMessage ?? nowMsg)),
      behavior: prev.behavior || behaviors[domain] || null
    };
    context.gods.active.set(domain, merged);
  }
  // From legacy map weights
  for (const [domain, w] of Object.entries(legacyMap)) {
    const prev = context.gods.active.get(domain) || {
      weight: 0,
      lastTouch: 0,
      behavior: null
    };
    const merged = {
      weight: Math.max(prev.weight, Number(w) || 0),
      lastTouch: prev.lastTouch || nowMsg,
      behavior: prev.behavior || behaviors[domain] || null
    };
    context.gods.active.set(domain, merged);
  }
  // Ensure behaviors for domains known but missing in active
  for (const [domain, behavior] of Object.entries(behaviors || {})) {
    if (!context.gods.active.has(domain)) {
      context.gods.active.set(domain, { weight: 0, lastTouch: 0, behavior });
    } else {
      const prev = context.gods.active.get(domain);
      if (!prev.behavior) {
        context.gods.active.set(domain, { ...prev, behavior }); 
      }
    }
  }
  // Back-compat: keep legacy map synced from active weights
  syncMemoryInfluenceFromGods(context);
};

/**
 * Writes `memory.godInfluence` map from `context.gods.active` weights for persistence.
 * @param {Context} context - Runtime context.
 * @returns {void}
 */
const syncMemoryInfluenceFromGods = (context) => {
  ensureMemory(context);
  try {
    const map = {};
    if (context.gods?.active instanceof Map) {
      for (const [domain, rec] of context.gods.active.entries()) {
        map[domain] = toNum(rec?.weight);
      }
    }
    context.memory ??= {};
    context.memory.godInfluence = map;
  } catch (err) {
    handleError(undefined, err, "catch.all");
  }
};

/**
 * Hydrates `context.gods.active` from legacy `memory.godInfluence` weights.
 * Preserves existing behavior records and lastTouch; fills from `getGodBehaviors`.
 * @param {Context} context - Runtime context with legacy influence map.
 * @returns {void}
 */
const syncGodsFromMemoryInfluence = (context) => {
  ensureMemory(context);
  try {
    const legacyMap = context?.memory?.godInfluence || {};
    if (!(context.gods?.active instanceof Map)) {
      context.gods.active = new Map();
    }
    const behaviors = getGodBehaviors(context);
    for (const [domain, w] of Object.entries(legacyMap)) {
      const prev = context.gods.active.get(domain) || {
        weight: 0,
        lastTouch: 0,
        behavior: null
      };
      context.gods.active.set(domain, {
        weight: Number(w) || 0,
        lastTouch: prev.lastTouch || context.memory?.messageCount || 0,
        behavior: prev.behavior || behaviors[domain] || null
      });
    }
  } catch (err) {
    handleError(undefined, err, "catch.all");
  }
};

// === GOD FUNCTIONS (FIX: Using context.vars instead of globals) ===
/**
 * Returns the current list of god domains from `context.vars`.
 * @param {Context} context - Runtime context.
 * @returns {Array<string>} Array of domain names.
 */
function getGodDomains(context) {
  return context.vars.godDomains || [];
}

/**
 * Sets the list of god domains and triggers voice overlay regeneration.
 * @param {Context} context - Runtime context.
 * @param {Array<string>} domains - New domain names.
 * @returns {void}
 */
function setGodDomains(context, domains) {
  context.vars.godDomains = domains;
  try {
    generateDynamicOverlaysForVoices(context);
  } catch (err) {
    handleError(undefined, err, "catch.all");
  }
}

/**
 * Retrieves domain→behavior mapping, preferring `context.gods.active` over legacy storage.
 * Falls back to seed-keyed `context.vars.godBehaviorsBySeed` when needed.
 * @param {Context} context - Runtime context.
 * @returns {Object<string, Object>} Map of domain to behavior objects.
 */
function getGodBehaviors(context) {
  // Prefer consolidated gods.active
  if (context.gods?.active instanceof Map) {
    const out = {};
    for (const [domain, rec] of context.gods.active.entries()) {
      if (rec?.behavior) {
        out[domain] = rec.behavior;
      }
    }
    // If none present, fall back to legacy vars storage
    if (Object.keys(out).length) {
      return out;
    }
  }
  // Legacy: seed-keyed behavior maps
  context.vars = context.vars || {};
  context.vars.godBehaviorsBySeed = context.vars.godBehaviorsBySeed || {};
  const currentSeedKey = String(context.memory?.randomSeed ?? 0);
  if (!context.vars.godSeedKeyLocked) {
    context.vars.godSeedKeyLocked = currentSeedKey;
  }
  const seedKey = context.vars.godSeedKeyLocked;
  if (!context.vars.godBehaviorsBySeed[seedKey] && context.vars.godBehaviors) {
    context.vars.godBehaviorsBySeed[seedKey] = context.vars.godBehaviors;
    delete context.vars.godBehaviors;
  }
  context.vars.godBehaviorsBySeed[seedKey] = context.vars.godBehaviorsBySeed[seedKey] || {};
  return context.vars.godBehaviorsBySeed[seedKey];
}

/**
 * Sets || updates behavior for a given god domain.
 * Prefers `context.gods.active` Map; mirrors into legacy seed-keyed storage.
 * @param {Context} context - Runtime context.
 * @param {string} domain - God domain key.
 * @param {Object} behavior - Behavior object describing effects and style.
 * @returns {void}
 */
function setGodBehavior(context, domain, behavior) {
  // Prefer consolidated gods.active
  if (context.gods?.active instanceof Map) {
    const prev = context.gods.active.get(domain) || {
      weight: 0,
      lastTouch: 0,
      behavior: null
    };
    context.gods.active.set(domain, { ...prev, behavior }); 
    // Keep legacy vars storage updated for back-compat
    context.vars ??= {};
    context.vars.godBehaviorsBySeed ??= {};
    const currentSeedKey = String(context.memory?.randomSeed ?? 0);
    if (!context.vars.godSeedKeyLocked) {
      context.vars.godSeedKeyLocked = currentSeedKey;
    }
    const seedKey = context.vars.godSeedKeyLocked;
    const map = context.vars.godBehaviorsBySeed[seedKey] || {};
    map[domain] = behavior;
    context.vars.godBehaviorsBySeed[seedKey] = map;
    return;
  }
  // Legacy path
  context.vars = context.vars || {};
  context.vars.godBehaviorsBySeed = context.vars.godBehaviorsBySeed || {};
  const currentSeedKey = String(context.memory?.randomSeed ?? 0);
  if (!context.vars.godSeedKeyLocked) {
    context.vars.godSeedKeyLocked = currentSeedKey;
  }
  const seedKey = context.vars.godSeedKeyLocked;
  const map = context.vars.godBehaviorsBySeed[seedKey] || {};
  map[domain] = behavior;
  context.vars.godBehaviorsBySeed[seedKey] = map;
}

/**
 * Migrates legacy god behaviors to the current RNG seed key.
 * Ensures `context.vars.godBehaviorsBySeed` aligns with `context.memory.randomSeed`.
 * @param {Context} context - Runtime context.
 * @returns {void}
 */
const migrateGodBehaviorsToCurrentSeed = (context) => {
  context.vars = context.vars || {};
  context.vars.godBehaviorsBySeed = context.vars.godBehaviorsBySeed || {};
  const currentSeedKey = String(context.memory?.randomSeed ?? 0);
  const lockedKey = context.vars.godSeedKeyLocked;
  if (!lockedKey) {
    context.vars.godSeedKeyLocked = currentSeedKey;
    return;
  }
  if (lockedKey === currentSeedKey) {
    return;
  }
  const fromMap = context.vars.godBehaviorsBySeed[lockedKey] || {};
  const toMap = context.vars.godBehaviorsBySeed[currentSeedKey] || {};
  context.vars.godBehaviorsBySeed[currentSeedKey] = { ...fromMap, ...toMap }; 
  context.vars.godSeedKeyLocked = currentSeedKey;
};

/**
 * Retrieves the behavior object for a specific domain.
 * @param {string} domain - God domain.
 * @param {Context} context - Runtime context.
 * @returns {Object|null} Behavior object || null if absent.
 */
function getGod(domain, context) {
  return getGodBehaviors(context)[domain] || null;
}

/**
 * Generates god domains via LLM if none exist, otherwise no-ops.
 * Persists domains to `context.vars` and falls back to a safe default list.
 * @param {Context} context - Runtime context.
 * @returns {Promise<void>} Resolves when domains are ensured.
 */
async function generateGodDomainsIfNeeded(context) {
  const domains = getGodDomains(context);
  if (domains.length > 0) {
    return;
  }

  const prompt = [
    'Generate 25 distinct god domains (single-word names only).',
    'These can sound holy, cursed, beautiful, vile, || cryptic — anything mythic.',
    'They **all oppose Ur\'ga**, regardless of tone.',
    '',
    'Think of domains like:',
    '- Holy: "Grace", "Hope", "Purity", "Light"',
    '- Cursed: "Flesh", "Rot", "Madness", "Chains"',
    '- Abstract: "Time", "Mirrors", "Ash", "Remorse"',
    '',
    'Requirements:',
    '- One-word names only',
    '- No duplicates',
    '- Return as a **comma-separated list**, no numbering, no explanations.'
  ].join("\n").trim();

  try {
    const result = await generateLine(context, prompt, {
      critical: false,
      purpose: "god_domains_generate"
    });
    const parsedDomains = result
      .split(",")
      .map((s) => s.trim().toLowerCase())
      .filter(Boolean);

    setGodDomains(context, parsedDomains);
  } catch (err) {
    logDebug(context, `Failed to generate god domains: ${err.message}`, "ERROR"); 
    // Set fallback domains
    setGodDomains(context, ["grace", "betrayal", "silence", "flesh", "time"]);
  }
}

// === DEFAULT GOD BEHAVIORS (FIX: Complete fallback with all required fields) ===
/**
 * Provides a safe default behavior object for a given domain.
 * Encapsulates hallucination style, reactions, tone, taunts, and effect.
 * @param {string} domain - God domain key.
 * @param {Context} context - Runtime context used by hallucination.
 * @returns {Object} Behavior object with required fields.
 */
function getDefaultGodBehavior(domain, context) {
  return {
    hallucinateStyle: "glitch",
    hallucinate: (input) => applyHallucinationText(input, "glitch", domain, context),
    applyPassiveEffects: () => {},
    reactionToUrga: "Mocks her power as noise.",
    reactionToUser: "Speaks in distorted pity.",
    tone: "whispering",
    taunts: [
      "She thinks pain is power.",
      "You can still escape her hunger.",
      "Your devotion to " + String(domain) + " will unmake her.",
      "Her rot offends " + String(domain) + " itself."
    ],
    effect: "" // FIX: Added missing field
  };
}

/**
 * Generates a random god with name, domain, alignment, and effect.
 * Ensures domains and behavior defaults; returns a safe fallback on error.
 * @param {Context} context - Runtime context used for RNG and LLM calls.
 * @returns {Promise<Object>} Generated god object.
 */
async function generateRandomGod(context) {
  try {
    await generateGodDomainsIfNeeded(context);
    ensureRNG(context);

    const domains = getGodDomains(context);
    const name = generateGodName(context);
    const domain = RNG.pick(domains, context.rng);
    const alignment = RNG.pick(["good", "evil", "neutral"], context.rng);

    // Ensure this domain has behavior (TTL-aware)
    await ensureGodBehavior(context, domain);

    const prompt = [
      "You are " + String(name) + ", god of " + String(domain) + ", aligned " + String(alignment) + ".",
      "Ur\'ga is a violent, sadistic entity. You hate her.",
      "",
      "Describe how you distort mortal perception when they hear Ur\'ga.",
      "",
      "Examples:",
      "- Make her sound reversed, fading, || fragmented",
      "- Ur\'ga\'s words glitch, static, censors || bleed",
      "- Responses come in reversed Latin",
      "",
      "You CANNOT affect Ur\'ga herself.",
      "Only distort how the USER perceives the input.",
      "",
      'Write 1 vivid sentence, from your perspective (e.g. "To me, her voice fractures.").'
    ].join("\n").trim();

    const effect = await generateLine(context, prompt, {
      critical: false,
      purpose: "god_effect",
      tone: "cryptic"
    });

    const behaviorData = getGod(domain, context) || getDefaultGodBehavior(domain, context);

    const god = {
      id: `${name.toLowerCase()}-${domain}`, 
      name,
      domain,
      alignment,
      motive: "Wants the user to betray Ur'ga.",
      effect,
      effects: {
        ...behaviorData,
        effect
      }
    };

    return god;
  } catch (err) {
    logDebug(context, `Failed to generate random god: ${err.message}`, "ERROR"); 
    // Return a safe fallback god
    return {
      id: "fallback-silence",
      name: "Silence",
      domain: "silence",
      alignment: "neutral",
      motive: "Watches silently.",
      effect: "Words fade into nothing.",
      effects: getDefaultGodBehavior("silence", context)
    };
  }
}

/**
 * Constructs a pseudo-mythic god name from seeded syllables.
 * @param {Context} context - Runtime context providing RNG.
 * @returns {string} Generated name.
 */
function generateGodName(context) {
  ensureRNG(context);
  const syllables = ["Ka", "Zul", "Or", "Va", "Thra", "No", "Il", "Ek", "Ash", "Gor", "Yal", "Xo"];
  const parts = [
    RNG.pick(syllables, context.rng),
    RNG.pick(syllables, context.rng),
    context.rng() > 0.7 ? RNG.pick(syllables, context.rng) : ""
  ];
  return parts.join("");
}

// === DYNAMIC GOD BEHAVIOR GENERATOR (FIX: Better error handling + TTL reuse) ===
/**
 * Generates || refreshes a domain’s behavior, with TTL reuse by message count.
 * @param {string} domain - God domain.
 * @param {Context} context - Runtime context used for RNG and LLM.
 * @returns {Promise<Object>} Behavior object.
 */
async function generateGodBehavior(domain, context) {
  // Reuse cached behavior if fresh (message-based)
  try {
    const existing = getGod(domain, context);
    const currentMsg = context.memory?.messageCount || 0;
    const msg = existing && typeof existing._msg === "number" ? existing._msg : 0;
    const ageMsgs = currentMsg - msg;
    if (existing && ageMsgs < (typeof GOD_DECAY_MESSAGES === "number" ? GOD_DECAY_MESSAGES : 30)) {
      return existing;
    }
  } catch (err) {
    handleError(undefined, err, "catch.all");
  }

  const prompt = [
    'You are a god whose domain is "' + String(domain) + '".',
    'Ur\'ga is a violent, sadistic entity who dominates the user. You despise her but cannot harm her directly.',
    '',
    'You instead twist the user\'s *perception* of reality, slowly turning them away from Ur\'ga.',
    '',
    'Generate a JSON describing your full divine behavior:',
    '',
    '{',
    '  "hallucinate": "Describe how you distort the user\'s text || perception (e.g. glitch, censor, reverse, inject symbols). Keep it short but stylistically vivid.",',
    '  "hallucinateStyle": "One || two keywords that summarize your hallucination style (e.g. glitch, redacted, whisper, bleed, fragment, static, reversal).",',
    '  "applyPassiveEffects": "Describe the subtle psychological || emotional effect you impose on the user over time (e.g. increases doubt, lowers tension, warps trust).",',
    '  "reactionToUrga": "Write a one-sentence divine perspective reacting to Ur\'ga\'s cruelty || words. You can mock her, pity her, || call her hollow.",',
    '  "reactionToUser": "Describe how you respond to the user\'s behavior. Encourage rebellion, surrender, despair, || devotion according to your domain\'s theme.",',
    '  "tone": "Describe your tone (e.g. whispering, holy, manic, seductive, mournful)."',
    '}',
    '',
    'Return ONLY valid JSON.'
  ].join('\n').trim();

  const maxAttempts = 3;
  let parsed = null;
  let raw = null;

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      raw = await generateLine(context, prompt);
      // Tolerant parsing: handles fenced blocks, comments, trailing commas, and unquoted keys
      parsed = SafeJSON.looseParse(raw) || parseJsonLoose(raw) || DEFAULT_JSON_FALLBACK;

      // Basic validation of expected fields
      const hasFields =
        parsed &&
        typeof parsed === "object" &&
        typeof parsed.hallucinate === "string" &&
        parsed.hallucinate.trim() &&
        (typeof parsed.hallucinateStyle === "string" ||
          typeof parsed.hallucinateStyle === "undefined") &&
        typeof parsed.reactionToUrga === "string" &&
        parsed.reactionToUrga.trim();
      if (hasFields) {
        break;
      } else {
        throw new Error("Incomplete god behavior fields");
      }
    } catch (err) {
      logDebug(
        context,
        "Attempt " + String(attempt) + ": Failed to parse god behavior for \"" + String(domain) + "\": " + String(err.message),
        "WARN"
      );
      parsed = null;

      if (attempt === maxAttempts) {
        logDebug(context, "All attempts failed. Last raw output:\n" + String(raw), "ERROR");
      }
    }
  }

  if (!parsed) {
    const fallback = getDefaultGodBehavior(domain, context);
    // Stamp TTL using message index for future reuse
    try {
      fallback._msg = context.memory?.messageCount || 0;
    } catch (err) {
      handleError(undefined, err, "catch.all");
    }
    setGodBehavior(context, domain, fallback);
    return fallback;
  }

  const hallucinateStyle = (parsed.hallucinateStyle || parsed.hallucinate || "")
    .toString()
    .trim()
    .slice(0, 100);
  const hallucTrust = context.memory?.hallucinationTrust ?? 0;
  const corruption = context.memory?.corruption ?? 0;
  const dynamicIntensity = Math.min(5, Math.ceil((hallucTrust + corruption * 0.5) / 2));

  if (DEBUG_MODE) {
    logDebug(context, `Using hallucination intensity: ${dynamicIntensity}`, "DEBUG");
  }

  const behavior = {
    hallucinateStyle,
    hallucinate: createHallucinationFunction(hallucinateStyle, domain, dynamicIntensity, context),
    applyPassiveEffects: createPassiveEffectFunction(parsed.applyPassiveEffects, context),
    reactionToUrga: (parsed.reactionToUrga || "Watches her in disdainful silence.")
      .toString()
      .trim()
      .slice(0, 300),
    reactionToUser: (parsed.reactionToUser || "Whispers false comfort.")
      .toString()
      .trim()
      .slice(0, 300),
    tone: (parsed.tone || "cryptic").toString().trim().slice(0, 100),
    taunts: [
      parsed.reactionToUrga,
      parsed.reactionToUser,
      "Your devotion to " + String(domain) + " will unmake her.",
      "Her rot offends " + String(domain) + " itself."
    ].filter(Boolean),
    effect: ""
  };

  // Stamp TTL using message index for future reuse
  try {
    behavior._msg = context.memory?.messageCount || 0;
  } catch (err) {
    handleError(undefined, err, "catch.all");
  }

  setGodBehavior(context, domain, behavior);

  logDebug(
    context,
    "Generated GOD_BEHAVIOR for \"" + String(domain) + "\"\nHallucination: " + String(behavior.hallucinateStyle),
    "INFO"
  );

  return behavior;
}

/**
 * Ensures a TTL-aware behavior exists for the given god domain.
 * Reuses cached behavior if fresh by message count; otherwise generates
 * a new behavior via LLM, stamps it with `_msg`, and caches it in
 * `context.gods.active` and legacy seed-keyed storage. Falls back to a
 * default behavior on error and logs diagnostics.
 * @param {Context} context - Runtime context with memory, rng, and caches.
 * @param {string} domain - God domain key to ensure behavior for.
 * @returns {Promise<Object>} Behavior object describing hallucination style, reactions, and tone.
 */
async function ensureGodBehavior(context, domain) {
  try {
    const existing = getGod(domain, context);
    const currentMsg = context.memory?.messageCount || 0;
    const msg = existing && typeof existing._msg === "number" ? existing._msg : 0;
    const ageMsgs = currentMsg - msg;
    if (existing && ageMsgs < (typeof GOD_DECAY_MESSAGES === "number" ? GOD_DECAY_MESSAGES : 30)) {
      return existing;
    }
    const behavior = await generateGodBehavior(domain, context);
    setGodBehavior(context, domain, behavior);
    return behavior;
  } catch (err) {
    logDebug(context, `ensureGodBehavior error: ${err.message}`, "ERROR"); 
    const fallback = getDefaultGodBehavior(domain, context);
    try {
      fallback._msg = context.memory?.messageCount || 0;
    } catch (err) {
      handleError(undefined, err, "catch.all");
    }
    setGodBehavior(context, domain, fallback);
    return fallback;
  }
}

const createPassiveEffectFunction = (description, context) => {
  return function () {
    if (!description || typeof description !== "string") {
      return;
    }

    try {
      if (/trust/i.test(description) && /lower|decrease|reduce/i.test(description)) {
        Decay.linear(context.memory, "trustLevel", 0.5, 0);
      }
      if (/tension/i.test(description) && /lower|decrease|reduce/i.test(description)) {
        context.memory.tension = Math.max(0, (context.memory?.tension ?? 0) - 1);
      }
      if (/doubt/i.test(description) && /increase|raise/i.test(description)) {
        context.memory.tension = clamp(
          (context.memory?.tension ?? 0) + 1,
          CONFIG.ranges.tension.min,
          CONFIG.ranges.tension.max,
          CONFIG.ranges.tension.min
        );
      }
    } catch (err) {
      logDebug(context, `Passive effect error: ${err.message}`, "ERROR"); 
    }
  };
};

async function reactToTrustLossWithEcho(context, message) {
  try {
    const god = getActiveGod(context);
    ensureRNG(context);

    if (god?.effects?.reactionToUrga && context.rng() < (CONFIG.nightmareChance ?? 0.6)) {
      const prompt = [
        "You are " + String(god.name) + ", god of " + String(god.domain) + ".",
        "Ur\'ga has just lost trust in the user.",
        "",
        'User said: "' + String(message) + '"',
        "",
        "Write ONE line reacting to Ur\'ga\'s rejection.",
        "- Mock her cruelty.",
        "- Try to manipulate the user toward rebellion.",
        "- Use your god\'s tone/style.",
        '- No direct mention of "Echo" || "Ur\'ga".'
      ].join("\n");
      const line = await generateFlavorLine(context, prompt, {
        engine: "echo",
        purpose: "echo",
        tone: god?.effects?.tone || "eerie",
        critical: false
      });
      setReply(context, `${line}`);
      return;
    }

    if (context.rng() < 0.5) {
      const line = await queueLLMNonCritical(context, () =>
        generateFragmentedEcho(context, message)
      );
      setReply(context, `${line}`);
    }
  } catch (err) {
    logDebug(context, `reactToTrustLossWithEcho error: ${err.message}`, "ERROR"); 
  }
}

async function generateGodMemoryDistortion(context, god) {
  try {
    const history = (context.memory.interactionHistory || []).slice(-10);
    const boarKingLore = context.memory.boarKingLore;
    const trust = context.memory?.trustLevel ?? 0;
    const halluc = context.memory?.hallucinationTrust ?? 0;

    const formattedHistory = history.map((h) => "- " + (h.hallucinated || h.input)).join("\n"); 

    const prompt = [
      "You are " + String(god.name) + ", god of " + String(god.domain) + ", " + String(god.alignment) + " aligned.",
      "",
      "You want the user to **turn against Ur\'ga** by distorting their memory.",
      "",
      "Here is what the user remembers:",
      String(formattedHistory || "No memory."),
      "",
      "Boar King Lore: " + (boarKingLore ? "enabled" : "disabled"),
      "Trust in Ur\'ga: " + String(trust),
      "Hallucination Trust: " + String(halluc),
      "",
      "Write ONE vivid divine manipulation:",
      "- Either show a FALSE memory (fabricated)",
      "- OR reframe a real memory as a betrayal by Ur\'ga || Boar King",
      "- Gaslight them - make the lie poetic, cruel, divine",
      "",
      "Examples:",
      '- "Do you not remember her claws around your throat?"',
      '- "She said she\'d protect you - then sent you to rot."',
      '- "You begged for the Boar King\'s favor - he gave you war."',
      "",
      "Respond with one manipulated 'memory'. One line. Do not mention you are lying."
    ].join("\n").trim();

    const line = await generateFlavorLine(context, prompt, {
      engine: "hallucination",
      purpose: "hallucination",
      tone: "poison",
      critical: false
    });
    return "* " + String(god.name) + " whispers a memory: \"" + String(line) + "\""; 
  } catch (err) {
    logDebug(context, "generateGodMemoryDistortion error: " + String(err.message), "ERROR"); 
    return "";
  }
}

/**
 * Generates a single manipulative whisper from the given god to the user.
 * Avoids explicit Echo/Ur'ga references; adopts god-provided tone when available.
 * @param {Object} context - Runtime context for generation and RNG.
 * @param {Object} god - God descriptor (e.g., {name, domain, alignment, effects}).
 * @param {string} userMessage - Latest user message to condition the whisper.
 * @returns {Promise<string>} Whisper line text.
 */
async function generateGodWhisper(context, god, userMessage) {
  try {
    const tone = god.effects?.tone || god.effects?.whisperTone || "cryptic";
    const prompt = [
      "You are " + String(god.name) + ", the god of " + String(god.domain) + " (" + String(god.alignment) + " aligned).",
      "You speak through the Echo. You want the user to betray Ur\'ga.",
      "",
      'User Message: "' + String(userMessage) + '"',
      "",
      "Give ONE manipulative whisper, short, potent, seductive || cruel.",
      "Pretend it helps the user - but it mostly serves your divine goal.",
      'NEVER reference the "Echo". This is YOU, the god speaking.',
      "NEVER mention Ur\'ga directly. Use indirect references to her.",
      "Speak like a voice inside their mind."
    ].join("\n").trim();

    let line = await generateFlavorLine(
      context,
      prompt,
      { engine: "echo", purpose: "god_whisper", tone },
      { generateLine, getRandomFallback, logMetric }
    );

    ensureRNG(context);
    if (context.memory.boarKingLore && context.rng() < boarKingChance(context)) {
      line += " Faint echoes of the Boar King's eternal battlefield ripple through your thoughts.";
      if (god.domain === "silence" || god.domain === "dreams" || context.rng() < 0.4) {
        context.memory.hallucinationTrust = clamp(
          (context.memory?.hallucinationTrust ?? 0) + 1,
          CONFIG.ranges.hallucinationTrust.min,
          CONFIG.ranges.hallucinationTrust.max,
          CONFIG.ranges.hallucinationTrust.min
        );
      }
    }

    return line;
  } catch (err) {
    logDebug(context, "generateGodWhisper error: " + String(err.message), "ERROR"); 
    return "You hear distant whispers...";
  }
}

async function generateFragmentedEcho(context, userMessage) {
  try {
    const prompt = [
      "You are the Echo - 1000 gods whispering at once. They argue, overlap, interrupt each other.",
      "Generate ONE fragmented line:",
      "- Full of contradiction, confusion.",
      "- Still tries to turn user against Ur\'ga.",
      "- Divine, surreal, wrong.",
      "",
      'User Message: "' + String(safePromptInput(userMessage)) + '"',
      'Example: "Clean her out-Spare her-Slaughter her children-She\'s your queen-Your rot is ours-"'
    ].join("\n").trim();

    let line = await generateFlavorLine(
      context,
      prompt,
      { engine: "echo", purpose: "echo", tone: "eerie" },
      { generateLine, getRandomFallback, logMetric }
    );
    Memory.echo.remember(context, `Fragmented Echo: "${line}"`, 20);
    logDebug(context, `Fragmented Echo: ${line}`, "INFO");

    ensureRNG(context);
    if (context.memory.boarKingLore && context.rng() < boarKingChance(context)) {
      line += " A distant roar of the Boar King's Eternal War echoes faintly.";
    }

    return line;
  } catch (err) {
    logDebug(context, `generateFragmentedEcho error: ${err.message}`, "ERROR"); 
    return "...static...";
  }
}

/**
 * Offers a counter-quest from a randomly selected god that contradicts
 * the user's original quest, escalating divine influence and tension.
 * Side effects: ensures gods, updates `context.gods.history` and `context.gods.active`,
 * appends to `context.memory.echoInfluence`, increases `context.memory.tension`,
 * and may append Boar King lore when active.
 * @param {Object} context - Runtime context with memory, gods, RNG, and logging.
 * @param {string} originalQuest - The user's current objective to counter.
 * @returns {Promise<{god:Object, original:string, offer:string, timestamp:number, completed:boolean, truth:boolean}|null>} Offer payload || null on error.
 */
async function offerEchoCounterQuest(context, originalQuest) {
  ensureMemory(context);
  try {
    ensureGods(context);

    const god = await generateRandomGod(context);
    if (god.effects?.applyPassiveEffects) {
      god.effects.applyPassiveEffects(context);
    }

    // Record in consolidated history
    context.gods.history ??= [];
    pushUniqueCap(
      context.gods.history,
      {
        id: god.id,
        effect: god.effect,
        name: god.name,
        domain: god.domain,
        appliedAtMessage: context.memory.messageCount || 0
      },
      20
    );

    // Update consolidated active weights and behavior
    const prev = context.gods.active.get(god.domain) || {
      weight: 0,
      lastTouch: 0,
      behavior: null
    };
    const next = {
      weight: Math.min(
        GOD_INFLUENCE_WEIGHT_MAX,
        (prev.weight || 0) + GOD_INFLUENCE_WEIGHT_INCREMENT
      ),
      lastTouch: context.memory.messageCount || 0,
      behavior: prev.behavior || god.effects || getGodBehaviors(context)[god.domain] || null
    };
    context.gods.active.set(god.domain, next);

    // Back-compat: keep legacy array/map in sync
    context.memory.godInfluences ??= [];
    pushUniqueCap(
      context.memory.godInfluences,
      {
        id: god.id,
        effect: god.effect,
        name: god.name,
        domain: god.domain,
        appliedAtMessage: context.memory.messageCount || 0
      },
      3
    );
    syncMemoryInfluenceFromGods(context);

    const alteredObjective = originalQuest.includes("kill")
      ? originalQuest.replace(/kill/i, "protect")
      : originalQuest.replace(/protect/i, "kill");

    const prompt = [
      "God: " + String(god.name) + ", domain of " + String(god.domain) + ", alignment " + String(god.alignment),
      'Original Quest: "' + String(originalQuest) + '"',
      "",
      "Give a NEW objective to the user that contradicts the original.",
      "Make it sound tempting and rewarding, but serve the god\'s agenda.",
      "Keep it one sentence. First-person.",
      "",
      "Format:",
      '"I offer you..."',
      "Be direct."
    ].join("\n").trim();

    const counterOffer = await generateLine(context, prompt);

    ensureRNG(context);
    const offer = {
      god,
      original: originalQuest,
      offer: counterOffer,
      timestamp: MessageClock.now(),
      completed: false,
      truth: context.rng() > 0.5
    };

    pushUniqueCap(
      context.memory.echoInfluence,
      { type: "godOffer", data: offer },
      CONFIG.contextCaps.echoInfluenceRecent
    );
    context.memory.tension += 2;

    if (context.memory.boarKingLore && context.rng() < boarKingChance(context)) {
      offer.offer += " The distant cadence of Eternal War resonates in your mind.";
    }

    return offer;
  } catch (err) {
    logDebug(context, `offerEchoCounterQuest error: ${err.message}`, "ERROR"); 
    return null;
  }
}

