/**
 * Generates a hallucination reply conditioned on trust/corruption and memory.
 * Builds a composite prompt, uses `generateFlavorLine` with `hallucination` engine,
 * and post-processes with optional Boar King lore and narration style metrics.
 * @param {Context} context - Runtime context with memory and stats.
 * @param {string} raw - User’s raw input used for overlay and conditioning.
 * @returns {Promise<string>} Hallucination line, possibly narratively styled.
 */
async function generateHallucination(context, raw) {
  try {
    const stats = getStats(context);
    const systemPrompt = "You are Ur\'ga, a psychosexual hallucination. Context: corruption=" + String(stats.corruption) + ", trust=" + String(stats.trust);
    const memorySection = getMemorySection(context);
    const overlay = getHallucinationOverlay(context);
    const prompt = selectPrompt(context, {
      systemPrompt,
      memorySection,
      overlay,
      responseTag: "Response",
      maxTokens: 2048
    });

    let hallucination = await generateFlavorLine(context, prompt, {
      engine: "hallucination"
    });

    ensureRNG(context);
    if (context.memory.boarKingLore && context.rng() < boarKingChance(context)) {
      hallucination += " In the distance, the Eternal War of your father roars endlessly.";
    }

    // Apply narration style if configured
    const narrationStyle =
      context?.settings?.narrationStyle ||
      context?.narrationStyle ||
      context?.memory?.narrationStyle;

    // Metrics: record hallucination generation
    logMetric(context, "hallucinationGenerated", {
      tension: context.memory.tension,
      hallucinationTrust: context.memory.hallucinationTrust,
      narrationStyle: narrationStyle || "default"
    });

    // Mark hallucination for contagion gating
    context.vars ??= {};
    context.vars.hadHallucination = true;

    // Emotional contagion injection (post-hallucination)
    try {
      const contagion =
        typeof Effects?.Echo?.voices?.emotionalContagion === "function"
          ? Effects.Echo.voices.emotionalContagion(context)
          : null;
      if (contagion) {
        context._recentLines ??= new RecentLinesMap();
        const line = String(contagion || "").trim();
        if (line && !context._recentLines.has(line, context?.memory?.messageCount || 0)) {
          context._recentLines.set(line, context?.memory?.messageCount || 0);
          hallucination = `${hallucination}\n${line}`;
          try {
            logMetric(context, "extraInjected", {
              source: "echo.emotionalContagion"
            });
          } catch (err) {
            logDebug(context, `extraInjected logMetric failed: ${err.message}`, "WARN"); 
          }
        }
      }
    } catch (err) {
      logDebug(context, `extraInjected emotionalContagion failed: ${err.message}`, "WARN"); 
    }

    return hallucination;
  } catch (err) {
    logDebug(context, `generateHallucination error: ${err.message}`, "ERROR"); 
    return "Reality flickers. Something watches from behind your eyes.";
  }
}

const glitchChar = (c, context) => {
  ensureRNG(context);
  const r = context.rng();
  if (CONFIG.glitch?.useUnicodeCombining) {
    const marks = CONFIG.glitch.unicodeMarks || ["\u0336", "\u0301", "\u0300", "\u035C", "\u034F"];
    if (r < GLITCH_PROBABILITY) {
      const maxMarks = Math.max(1, Number(CONFIG.glitch?.maxMarksPerChar ?? 2));
      const count = 1 + Math.floor(context.rng() * maxMarks);
      let out = String(c || "");
      for (let i = 0; i < count; i++) {
        out += marks[Math.floor(context.rng() * marks.length)];
      }
      return out;
    }
    return c;
  }
  const glitched = GLITCH_CHARSET;
  return r < GLITCH_PROBABILITY ? RNG.pick(glitched, context.rng) : c;
};

