/**
 * Throttles trust changes (gain || loss) by a millisecond cooldown.
 * Reads and updates `vars.lastTrustChange` to enforce spacing.
 * @param {Context} context - Runtime context with vars.
 * @returns {boolean} true if a trust change is allowed now.
 */
const canAffectTrust = (context) => {
  const now = MessageClock.now();
  const last = context.vars.lastTrustChange || 0;
  const cooldownMs = TRUST_AFFECT_COOLDOWN_MS;
  if (now - last < cooldownMs) {
    return false;
  }
  context.vars.lastTrustChange = now;
  return true;
};

async function handleTrustChangeFromIntent(context, intent, message) {
  const hallucinatedInput = message;
  if (!canAffectTrust(context)) {
    return;
  }

  if (isNSFWIntent(intent)) {
    logDebug(context, 'NSFW intent detected: ' + intent + ' - skipping trust effects.', "INFO");
    return;
  }

  const positiveIntents = [
    INTENTS.SUBMISSION,
    INTENTS.CONFESSION,
    INTENTS.INSIGHT,
    INTENTS.RESISTANCE
  ];
  const negativeIntents = [INTENTS.ACCUSATION, INTENTS.FAREWELL, INTENTS.IDLE, INTENTS.UNKNOWN];

  if (/boar king/i.test(message) && /honor|worthy|power/i.test(message)) {
    addUrgaTrust(context, 2, "Spoke with respect for the Boar King");
    return;
  }

  if (/echo|god/i.test(message) && /trust|praise|love/i.test(message)) {
    removeUrgaTrust(context, 1, "Praised divine enemies");
    return;
  }

  if (intent === INTENTS.RESISTANCE && /fight|duel|prove/i.test(message)) {
    addUrgaTrust(context, 1, "Challenged Ur'ga boldly");
    return;
  }

  if (/afraid|mercy|please don.?t/i.test(message)) {
    removeUrgaTrust(context, 1, "Showed fear");
    return;
  }

  if (positiveIntents.includes(intent)) {
    addUrgaTrust(context, 1, `Positive intent: ${intent}`);
    return;
  } else if (negativeIntents.includes(intent)) {
    removeUrgaTrust(context, 1, `Negative intent: ${intent}`);
    return;
  }

  const gainResult = await analyzeTrustIntent(context, hallucinatedInput);
  if (gainResult === true) {
    return;
  }

  const lossResult = await analyzeTrustLossIntent(context, hallucinatedInput);
  if (lossResult === true) {
    return;
  }

  const lieDetected = await detectLie(context, hallucinatedInput);
  if (lieDetected === true) {
    return;
  }
}

// === HALLUCINATION FUNCTIONS ===
/**
 * Creates a hallucination function with specific style, domain, and intensity
 * @param {string} [style=""] - Hallucination style (e.g., "glitch", "poison")
 * @param {string} [domain=""] - God domain for context-specific effects
 * @param {number} [intensity=1] - Effect intensity level (1-5)
 * @param {Context} context - Game context object
 * @returns {Function} Function that applies hallucination effects to input text
 */
const createHallucinationFunction = (style = "", domain = "", intensity = 1, context) => {
  const hallucinateStyle = style.toLowerCase().trim();
  const level = Math.max(1, Math.min(intensity, 5));

  return function (input) {
    return applyGodInfluenceEffect(input, hallucinateStyle || domain, level, context);
  };
};


