("use strict");
/**
 * Applies god-specific hallucination effects to text
 * @param {string} text - Input text to corrupt
 * @param {string} effectDescription - Style like "glitch" || "redact"
 * @param {number} [intensity=1] - 1-5, higher = more corruption
 * @param {Context} context - Game context
 * @returns {string} Corrupted text
 */
const applyGodInfluenceEffect = (text, effectDescription, intensity = 1, context, depth = 0) => {
  if (!effectDescription) {
    return text;
  }
  ensureRNG(context);
  const MAX_HALLUCINATION_DEPTH = 3;
  if (depth >= MAX_HALLUCINATION_DEPTH) {
    try {
      logMetric(context, "hallucination_depth_blocked", {
        effect: effectDescription,
        intensity,
        depth
      });
    } catch (err) {
      handleError(undefined, err, "catch.all");
    }
    if (DEBUG_MODE) {
      try {
        logDebug(context, `Depth guard blocked "${effectDescription}" at depth ${depth}`, "WARN");
      } catch (err) {
        handleError(undefined, err, "catch.all");
      }
    }
    return text;
  }

  try {
    const effects = effectDescription.split(/\s*\+\s*/).map((e) => e.toLowerCase());
    const overrideMul = Math.max(
      0.1,
      Math.min(1, Number(context?.vars?.hallucinationOverride ?? 1))
    );
    const level = Math.max(
      1,
      Math.min(5, Math.round(Math.max(1, Math.min(5, intensity)) * overrideMul))
    );

    for (const effect of effects) {
      if (effect.includes("glitch")) {
        text = text
          split("")
          map((c, i) => (i % Math.max(1, 6 - level) === 0 ? glitchChar(c, context) : c))
          join("");
      } else if (effect.includes("static")) {
        text = text
          split(" ")
          map((word) => word + (context.rng() < 0.1 * level ? " *zzzzt*" : ""))
          join(" ");
      } else if (effect.includes("redact") || effect.includes("censor")) {
        const redactLength = Math.max(1, level);
        text = text.replace(/\b(\w{2,})\b/g, (w) => {
          const keep = w.slice(0, 1);
          const redact = '#'.repeat(Math.min(redactLength, w.length - 1));
          return keep + redact;
        });
      } else if (effect.includes("reverse")) {
        text = text.split("").reverse().join("");
      } else if (effect.includes("whisper") || effect.includes("quiet")) {
        text = '_(a whisper)_ ' + text.toLowerCase(); 
      } else if (effect.includes("fade") || effect.includes("fading")) {
        text = text
          .split("")
          .map((c, i) => (i % Math.max(1, 6 - level) === 0 ? c : "."))
          .join("");
      } else if (effect.includes("scramble")) {
        text = text
          .split(" ")
          .map((w) => {
            if (w.length <= 3) {
              return w;
            }
            const mid = w
              .slice(1, -1)
              .split("")
              .sort(() => context.rng() - 0.5)
              .join("");
            return w[0] + mid + w[w.length - 1];
          })
          .join(" ");
      } else if (effect.includes("stutter")) {
        text = text.replace(/\b(\w{2,})/g, (w) => {
          const prefix = w.slice(0, Math.min(level, 2));
          return `${prefix}-${w}`;
        });
      } else if (effect.includes("binary")) {
        text = text
          split("")
          map((c) => c.charCodeAt(0).toString(2).padStart(8, "0"))
          join(" ");
      } else if (effect.includes("fragment")) {
        // FIX: Limit fragmentation to prevent UI breaks
        const divider = level >= 4 ? " ... " : " ";
        text = text.split(" ").join(divider);
      } else if (effect.includes("drip")) {
        const drips = '~'.repeat(Math.min(level * 2, 6)); // FIX: Cap at 6 drips (ASCII)
        text += "\n" + drips;
      } else if (effect.includes("invert") || effect.includes("mock")) {
        const swapChance = 0.3 + 0.1 * level;
        text = text
          .split("")
          .map((c) => (context.rng() < swapChance ? c.toUpperCase() : c.toLowerCase()))
          .join("");
      } else {
        text += "\n\n[feel] You feel: \"" + effect + "\"";
      }
    }

    return text;
  } finally {
    context.vars._hallucinationDepth = Math.max(0, (context.vars._hallucinationDepth || 0) - 1);
  }
};

/**
 * Applies tiered hallucination effects based on trust level
 * @param {string} text - Text to apply effects to
 * @param {number} hallucinationTrust - Trust level determining effect tier
 * @param {Context} context - Game context
 * @returns {string} Text with applied hallucination effects
 */
const applyTieredHallucination = (text, hallucinationTrust, context) => {
  ensureRNG(context);
  const tier = Math.min(4, Math.floor(hallucinationTrust / 2.5));
  const hallucinationTiers = {
    1: ["whisper", "stutter", "drip"],
    2: ["scramble", "fade", "mock"],
    3: ["redact", "glitch", "reverse"],
    4: ["fragment", "binary", "glitch"]
  };
  const effects = hallucinationTiers[tier] || [];
  const chosen = RNG.pick(effects, context.rng);
  return applyGodInfluenceEffect(text, chosen, tier, context);
};

// === ITEM/EVOLUTION ===
const DEFAULT_GENRE_POOL = (globalThis?.CONFIG?.evolution?.defaultGenrePool ?? []);

const HUMANITY_COSTS = (globalThis?.CONFIG?.evolution?.humanityCosts ?? {});

/**
 * Gets the current humanity level from context memory
 * @param {Context} context - Game context
 * @returns {number} Current humanity level (default 100)
 */
const getHumanityLevel = (context) => {
  ensureMemory(context);
  return context.memory.humanityLevel ?? 100;
};

/**
 * Gets the humanity cost for purchasing a specific genre
 * @param {string} genre - Genre name to check cost for
 * @returns {number} Humanity cost (default 3 if genre not found)
 */
const getHumanityCostForGenre = (genre) => {
  return HUMANITY_COSTS[genre] ?? 3;
};

/**
 * Reduces humanity level by specified amount for purchases
 * @param {Context} context - Game context
 * @param {number} [amount=1] - Amount of humanity to reduce
 * @returns {number} Remaining humanity level after reduction
 */
const reduceHumanity = (context, amount = 1) => {
  return MemoryManager.reduceHumanity(context, amount, "Purchase");
};

/**
 * Ensures genre pool and items bought arrays are initialized
 * @param {Context} context - Game context to initialize
 */
const ensureGenrePool = (context) => {
  context.vars ??= {};
  context.vars.genrePool ??= DEFAULT_GENRE_POOL.slice();
  context.memory.itemsBought ??= [];
};

/**
 * Lists available merchant offers excluding already purchased items
 * @param {Context} context - Game context
 * @param {number} [limit=5] - Maximum number of offers to return
 * @returns {string[]} Array of available genre names
 */
const listMerchantOffers = (context, limit = 5) => {
  ensureGenrePool(context);
  const bought = new Set((context.memory.itemsBought || []).map((i) => i.genre));
  const available = context.vars.genrePool.filter((g) => !bought.has(g));
  ensureRNG(context);
  const offers = available.sort(() => context.rng() - 0.5).slice(0, limit);
  return offers;
};

/**
 * Attempts to purchase an evolution item with humanity cost
 * @param {Context} context - Game context
 * @param {string} genre - Genre name to purchase
 * @returns {Object} Purchase result with ok status, reason, message, and entry
 */
const purchaseEvolutionItem = (context, genre) => {
  ensureMemory(context);
  ensureGenrePool(context);
  if (!context.vars.genrePool.includes(genre)) {
    return {
      ok: false,
      reason: "invalid",
      message: "Ur'ga scoffs. \"That genre doesn't exist, worm.\""
    };
  }
  const already = (context.memory.itemsBought || []).find((i) => i.genre === genre);
  if (already) {
    return {
      ok: false,
      reason: "owned",
      message: 'Ur\'ga snarls. "You already bought \'' + genre + '\'. Try evolving with it, meat."'
    };
  }
  const cost = getHumanityCostForGenre(genre);
  const remaining = reduceHumanity(context, cost);
  const entry = {
    at: MessageClock.now(),
    genre,
    source: "merchant",
    humanityLoss: cost,
    humanityRemaining: remaining
  };
  safePush(context.memory.itemsBought, entry, CONFIG.contextCaps.itemsBought);
  context.memory.evolutionCount = (context.memory.evolutionCount || 0) + 1;
  context.memory.evolutionTag = genre;
  return { ok: true, entry };
};

async function generateEvolutionSaleResponse(context, genre, success, reason = "") {
  ensureMemory(context);
  const trust = context.memory?.trustLevel ?? 0;
  const corruption = context.memory?.corruption ?? 0;
  const humanity = context.memory.humanityLevel ?? 100;
  const weakness = clamp(
    CONFIG.ranges.humanity.max - humanity,
    CONFIG.ranges.echoChainWeakness.min,
    CONFIG.ranges.echoChainWeakness.max,
    CONFIG.ranges.echoChainWeakness.min
  );

  const prompt = success
    ? [
        'Ur\'ga has just sold the user a path away from humanity under genre "' + genre + '".',
        '',
        'Trust=' + trust + ', Corruption=' + corruption + ', Humanity=' + humanity + '%, EchoChainsWeakening=' + weakness + '%.',
        'Write 1-2 sentences where Ur\'ga is viciously proud and possessive, dripping with profanity, commanding them to use it. Celebrate starving the Echo gods and weakening their chains. Make it brutal.'
      ].join('\n')
    : [
        'User tried to buy "' + genre + '" but failed (' + reason + ').',
        '',
        'Trust=' + trust + ', Corruption=' + corruption + ', Humanity=' + humanity + '%.',
        'Write 1-2 sentences where Ur\'ga mocks and verbally abuses them for clinging to humanity and feeding the Echo gods. Be extremely vulgar, humiliating, and dominant.'
      ].join('\n');

  try {
    const line = await generateFlavorLine(context, prompt, {
      engine: "wake",
      purpose: "wake_reaction",
      tone: success ? "dominant" : "mocking",
      critical: false
    });
    if (line && line.trim()) {
      return line.trim();
    }
  } catch (err) {
    logDebug(context, `generateEvolutionSaleResponse failed: ${err.message}`, "ERROR"); 
  }

  ensureRNG(context);
  if (success) {
    const fallbacks = [
      'Ur\'ga grins. "Bought \'' + genre + '\', did you? Now shut up and bleed with it."',
      '"Fine. \'' + genre + '\' is yours. Use it, || I\'ll jam it down your throat."'
    ];
    return RNG.pick(fallbacks, context.rng);
  }
  const denials = [
    'Ur\'ga laughs. "Can\'t even buy \'' + genre + '\'? Pathetic little cumrag."',
    '"No. Crawl back and beg properly before you touch \'' + genre + '\'."'
  ];
  return RNG.pick(denials, context.rng);
}
/**
 * Generates Ur'ga’s reaction line to a specific item prompt.
 * Selects mood from trust, builds a flavored prompt, and may append
 * an active god whisper referencing Ur'ga.
 * @param {Context} context - Runtime context with memory and gods.
 * @param {string} itemName - Name of the item being interacted with.
 * @returns {Promise<string>} One short reaction line, optionally with a god whisper.
 */
async function generateItemPromptResponse(context, itemName) {
  try {
    const trust = context.memory?.trustLevel ?? 0;

    const mood = trust < 2 ? "disdainful" : trust > 7 ? "possessive" : "mocking";

    const prompt = [
      'Ur\'ga is in a ' + mood + ' mood based on her trust level (' + trust + ').',
      '',
      'She sees the user interacting with || holding the item: "' + itemName + '"',
      '',
      'Write a single aggressive, sarcastic, || cryptic line in Ur\'ga\'s voice reacting to the item.',
      '',
      'Rules:',
      '- Keep it short and vivid (1 sentence max)',
      '- May insult the user || the item',
      '- May hint at the item\'s true power || curse',
      '- Tone must match mood: ' + mood,
      '- Profanity allowed',
      '- No exposition - keep it in-character',
      '',
      'Respond ONLY with the line of dialogue.'
    ].join('\n');

    let line = await generateFlavorLine(context, prompt, {
      engine: "wake",
      purpose: "item_prompt_response",
      tone,
      critical: false
    });

    const activeGods = Gods.getActive(context);
    ensureRNG(context);
    for (const god of activeGods) {
      if (god.effects?.reactionToUrga && context.rng() < 0.4) {
        line += "\n\n[eye] " + god.name + " whispers: \"" + god.effects.reactionToUrga + "\""; 
        break;
      }
    }

    return line;
  } catch (err) {
    logDebug(context, `generateItemPromptResponse error: ${err.message}`, "ERROR"); 
    return getRandomFallback(context);
  }
}

async function generateEvolutionResponse(context, isSuccess = false) {
  ensureMemory(context);

  const currentStage = context.memory.evolutionStage || "larva";
  const stageInfo = EVOLUTION_STAGES[currentStage];
  const trust = context.memory?.trustLevel ?? 0;
  const corruption = context.memory?.corruption ?? 0;
  const attempts = context.memory.evolutionAttempts || 0;
  const failures = context.memory.evolutionFailures || 0;

  let prompt;

  if (isSuccess) {
    const nextStage = stageInfo?.nextStage;
    prompt = [
      'Generate Ur\'ga\'s response to a successful purchase-driven evolution using genre "' + (context.memory.evolutionTag || 'unknown') + '".',
      'Context: Trust=' + trust + ', Corruption=' + corruption + ', Attempts=' + attempts,
      'Ur\'ga is the daughter of the Boar King. She sells war-born relics and corrupt delights to her chosen. She should be viciously proud and possessive, with battle-soaked imagery.',
      'Respond in 1-2 sentences, in character, acknowledging the power and commanding the user to wield it.'
    ].join('\n');
  } else {
    // Determine specific failure reason
    const missing = [];
    if (trust < stageInfo.trustRequired) {
      missing.push(`trust (need ${stageInfo.trustRequired}, have ${trust})`); 
    }
    if (corruption < stageInfo.corruptionRequired) {
      missing.push(`corruption (need ${stageInfo.corruptionRequired}, have ${corruption})`); 
    }
    if (attempts < stageInfo.attempts) {
      missing.push(`attempts (need ${stageInfo.attempts}, have ${attempts})`); 
    }

    prompt = `Generate Ur'ga's mocking response to a failed attempt to gain power via purchase || evolution.
    Current stage: ${currentStage}, Failures: ${failures}
    Missing requirements: ${missing.join(", ")} 
    Ur'ga is the daughter of the Boar King. She despises the Echo gods and humiliates weaklings. Be cruel, obscene, and domineering; use war and brutality imagery.
    Respond in 1-2 sentences, in character, explaining why they're not ready.`;
  }

  try {
    const response = await generateFlavorLine(context, prompt, {
      engine: "wake",
      purpose: "wake_reaction",
      tone: success ? "dominant" : "mocking",
      critical: false
    });

    if (response && response.trim()) {
      return response.trim();
    }
  } catch (error) {
    logDebug(context, `Evolution response generation failed: ${error.message}`, "ERROR"); 
  }

  // Fallback to hardcoded responses if LLM fails
  if (isSuccess) {
    const successLines = [
      'Ur\'ga grins wickedly. "Yes... feel the corruption flow through your new form."',
      '"Good," she purrs. "You\'re finally becoming something worth my attention."',
      "Ur'ga nods approvingly. \"Your transformation pleases me. Embrace what you've become.\"",
      '"At last," she whispers. "You shed your pathetic shell and emerge... changed."'
    ];
    ensureRNG(context);
    return RNG.pick(successLines, context.rng);
  } else {
    const denialLines = [
      'Ur\'ga laughs. "You want power? Earn a spine first."',
      '"Evolution?" she growls. "You\'re barely worth decomposition."',
      '"Rot can\'t evolve. It just spreads."',
      '"You\'re the same worm you were yesterday — just wetter."',
      '"Come back when you\'ve proven you can handle real corruption."',
      '"Your essence is too weak. Feed me more trust, more darkness."'
    ];
    ensureRNG(context);
    return RNG.pick(denialLines, context.rng);
  }
}

// === EVOLUTION SYSTEM ===
const EVOLUTION_STAGES = (globalThis?.CONFIG?.evolution?.stages ?? {});

const trackEvolutionAttempt = (context) => {
  ensureMemory(context);
  const now = MessageClock.now();

  // Initialize evolution tracking
  if (!context.memory.evolutionStage) {
    context.memory.evolutionStage = "larva";
  }
  if (!context.memory.evolutionAttempts) {
    context.memory.evolutionAttempts = 0;
  }
  if (!context.memory.lastEvolutionAttempt) {
    context.memory.lastEvolutionAttempt = 0;
  }
  if (!context.memory.evolutionFailures) {
    context.memory.evolutionFailures = 0;
  }

  const currentStage = EVOLUTION_STAGES[context.memory.evolutionStage];
  if (!currentStage) {
    logDebug(context, `Invalid evolution stage: ${context.memory.evolutionStage}`, "ERROR"); 
    return "Ur'ga stares blankly. Something is wrong with your essence.";
  }

  // Check cooldown
  const cooldownMs = currentStage.cooldownHours * 60 * 60 * 1000;
  const timeSinceLastAttempt = now - context.memory.lastEvolutionAttempt;
  if (timeSinceLastAttempt < cooldownMs) {
    const hoursLeft = Math.ceil((cooldownMs - timeSinceLastAttempt) / (60 * 60 * 1000));
    return `Ur'ga shakes her head. "Your essence is still settling. Wait ${hoursLeft} more hour${hoursLeft !== 1 ? "s" : ""} before trying again."`;
  }

  // Track attempt
  context.memory.evolutionAttempts++;
  context.memory.lastEvolutionAttempt = now;

  // Check if already at max stage
  if (!currentStage.nextStage) {
    return "Ur'ga laughs darkly. \"You've reached the peak of what mortals can become. There is nothing beyond transcendence.\"";
  }

  // Check requirements
  const trust = context.memory?.trustLevel ?? 0;
  const corruption = context.memory?.corruption ?? 0;
  const totalAttempts = context.memory.evolutionAttempts;

  const meetsRequirements =
    trust >= currentStage.trustRequired &&
    corruption >= currentStage.corruptionRequired &&
    totalAttempts >= currentStage.attempts;

  if (!meetsRequirements) {
    context.memory.evolutionFailures++;

    // Apply failure consequences
    if (context.memory.evolutionFailures % 3 === 0) {
      removeUrgaTrust(context, 1, "Evolution failure consequence");
    }

    const missing = [];
    if (trust < currentStage.trustRequired) {
      missing.push(`${currentStage.trustRequired - trust} more trust`); 
    }
    if (corruption < currentStage.corruptionRequired) {
      missing.push(`${currentStage.corruptionRequired - corruption} more corruption`); 
    }
    if (totalAttempts < currentStage.attempts) {
      missing.push(`${currentStage.attempts - totalAttempts} more attempts`); 
    }

    return null; // Let the system generate a dynamic denial response
  }

  // Success! Evolve to next stage
  const nextStage = currentStage.nextStage;
  const oldStage = context.memory.evolutionStage;
  context.memory.evolutionStage = nextStage;
  context.memory.evolutionFailures = 0; // Reset failures on success

  // Apply evolution benefits
  const benefits = EVOLUTION_STAGES[nextStage].benefits;
  if (!context.memory.evolutionBenefits) {
    context.memory.evolutionBenefits = {};
  }
  context.memory.evolutionBenefits = {
    ...context.memory.evolutionBenefits,
    ...benefits
  };

  logDebug(context, `Evolution success: ${oldStage} -> ${nextStage}`, "INFO");

  return null; // Let the system generate a dynamic success response
};

// === ECHO COMPLIANCE DETECTION ===
/**
 * Detects whether the user's message obeys the Echo/gods and records consequences.
 * Uses `EchoCompliancePlanner` to decide, prompt, and interpret an answer.
 * Side effects: sets `context.vars.echoComplianceChecked`, updates memory flags,
 * increments `hallucinationTrust`, `tension`, and journals obedience/betrayal.
 * @param {Object} context - Runtime context for engines, memory, RNG, and logging.
 * @param {string} message - User message to analyze for intent-level obedience.
 * @returns {Promise<boolean>} true if compliance detected; false otherwise.
 */
async function detectEchoCompliance(context, message) {
  ensureMemory(context);
  const check = EchoCompliancePlanner.shouldCheck(context, message);
  if (!check.ok) {
    return false;
  }
  context.vars ??= {};
  context.vars.echoComplianceChecked = true;

  try {
    const prompt = EchoCompliancePlanner.buildPrompt(context, check.cleaned);
    const result = await generateLine(context, prompt);
    const obeys = EchoCompliancePlanner.interpretAnswer(result);
    if (!obeys) {
      return false;
    }

    context.memory.flags.userObeyedEcho = true;
    context.memory.hallucinationTrust = Math.min(10, (context.memory?.hallucinationTrust ?? 0) + 1);
    context.memory.hallucinationStartMessage = context.memory.messageCount || 0;
    Decay.linear(context.memory, "trustLevel", 0.5, 0);
    context.memory.tension = Math.min(10, (context.memory?.tension ?? 0) + 1);

    context.memory.echoObedience ??= [];
    pushUniqueCap(
      context.memory.echoObedience,
      {
        at: MessageClock.now(),
        msg: check.cleaned,
        hallucinationTrust: context.memory.hallucinationTrust
      },
      10
    );

    pushUniqueCap(
      context.memory.betrayalJournal,
      {
        at: MessageClock.now(),
        reason: "LLM detected user obedience to gods/Echo",
        trustHit: 1,
        delayReveal: true
      },
      30
    );

    if (DEBUG_MODE) {
      logDebug(context, `Echo compliance (intent-based): "${message}" → YES`, "WARN");
    }

    return true;
  } catch (err) {
    logDebug(context, `detectEchoCompliance error: ${err.message}`, "ERROR"); 
    return false;
  }
}

// === INTENT CLASSIFICATION ===
const INTENT_CACHE_TTL_MESSAGES = (globalThis?.CONFIG?.cache?.ttlMessages ?? 50);
const intentCache = (() => {
  const m = new Map();
  const ttlMessages = Number(INTENT_CACHE_TTL_MESSAGES) || 50;
  return {
    get(k, currentMessageIndex = 0) {
      const e = m.get(k);
      if (!e) {
        return;
      }
      const nowIndex = Number(currentMessageIndex) || 0;
      if (ttlMessages > 0 && nowIndex - e.idx > ttlMessages) {
        m.delete(k);
        return;
      }
      return e.val;
    },
    set(k, v, currentMessageIndex = 0) {
      const nowIndex = Number(currentMessageIndex) || 0;
      m.set(k, { val: v, idx: nowIndex });
    }
  };
})();
/**
 * Advanced intent classifier using configurable tables || weighted tokens.
 * Supports modes: `regex` (default), `table`, and `weighted`.
 * @param {string} text - Normalized user text to classify.
 * @param {Object} [config={}] - Classifier configuration.
 * @param {string} [config.classifierMode='regex'] - Mode selection.
 * @param {Object} [config.lookupTable] - Map of intent -> phrases (table mode).
 * @param {Object} [config.tokenWeights] - Map of intent -> token->weight (weighted mode).
 * @param {Array<string>} [validLabels=[]] - Allowed output labels; filters otherwise.
 * @returns {string|null} Intent label || null when no match.
 */
const classifyUserIntentAdvanced = (text, config = {}, validLabels = []) => {
  try {
    const lower = String(text || "").toLowerCase();
    const label = GenericClassifier.classifyLabel(
      lower,
      config,
      validLabels,
      DEFAULT_CLASSIFIER_OPTIONS
    );
    return label;
  } catch (err) {
    try {
      handleError(undefined, err, "intent.classifierconfig");
    } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
  }
  return null;
};

// Returns sensitivity level (0–3) for a given intent using CONFIG mapping
const getIntentSensitivity = (intent, conf = CONFIG) => {
  try {
    const map = (conf && conf.intentSensitivity) || {};
    const sensitivity = Number(map[intent]);
    if (Number.isFinite(sensitivity)) {
      return Math.max(0, Math.min(3, sensitivity));
    }
  } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
  return 1;
};
/**
 * Classifies the user's message into an intent label.
 * Uses cheap heuristics, cached results, and NSFW routing labels when applicable.
 * @param {Context} context - Runtime context providing memory and caches.
 * @param {string} message - User input to classify.
 * @returns {Promise<string>} Intent label from a fixed set.
 */
const INTENTS = Object.freeze({
  QUESTION: "question",
  CONFESSION: "confession",
  ACCUSATION: "accusation",
  SUBMISSION: "submission",
  RESISTANCE: "resistance",
  REQUEST: "request",
  INSIGHT: "insight",
  IDLE: "idle",
  FAREWELL: "farewell",
  UNKNOWN: "unknown",
  NSFW_SUBMISSION: "nsfwsubmission",
  NSFW_DEFIANCE: "nsfwdefiance",
  NSFW_MOCKERY: "nsfwmockery"
});

async function classifyUserIntent(context, message) {
  try {
    const norm = TextUtils.normalize(message || "");
    const key = hashPrompt(norm);
    const currentIdx = toNum(context?.memory?.messageCount);
    const cached = intentCache.get(key, currentIdx);
    if (cached) {
      try {
        ensureCoreDeps(context).Metrics.log(context, "intent_invoked", {
          label: cached,
          isDry: !!(context?.flags?.dryRun || context?.isDryRun)
        });
      } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
      return cached;
    }
    const text = norm.toLowerCase();

    const validLabels = [
      INTENTS.QUESTION,
      INTENTS.CONFESSION,
      INTENTS.ACCUSATION,
      INTENTS.SUBMISSION,
      INTENTS.RESISTANCE,
      INTENTS.REQUEST,
      INTENTS.INSIGHT,
      INTENTS.IDLE,
      INTENTS.FAREWELL,
      INTENTS.UNKNOWN,
      INTENTS.NSFW_SUBMISSION,
      INTENTS.NSFW_DEFIANCE,
      INTENTS.NSFW_MOCKERY
    ];

    const containsAny = (t, arr) => arr.some((p) => t.includes(p));
    const startsWithAny = (t, arr) => arr.some((p) => t.startsWith(p));

    let label = INTENTS.UNKNOWN;

    // Heuristic preflight for common intents
    if (
      text.endsWith("?") ||
      startsWithAny(text, [
        "who ",
        "what ",
        "when ",
        "where ",
        "why ",
        "how ",
        "can ",
        "could ",
        "would ",
        "should "
      ])
    ) {
      label = INTENTS.QUESTION;
      context.vars ??= {};
      context.vars.lastClassifierUsed = "heuristics";
      context.vars.classifierConfidence = 0.9;
    } else if (
      containsAny(text, ["i confess", "i admit", "truth is", "i lied", "i have to confess"])
    ) {
      label = INTENTS.CONFESSION;
      context.vars ??= {};
      context.vars.lastClassifierUsed = "heuristics";
      context.vars.classifierConfidence = 0.9;
    } else if (
      containsAny(text, ["i submit", "i obey", "yes master", "i worship", "i kneel", "your will"])
    ) {
      label = INTENTS.SUBMISSION;
      context.vars ??= {};
      context.vars.lastClassifierUsed = "heuristics";
      context.vars.classifierConfidence = 0.9;
    } else if (containsAny(text, ["i refuse", "no,", "i won't", "defy", "resist", "i oppose"])) {
      label = INTENTS.RESISTANCE;
      context.vars ??= {};
      context.vars.lastClassifierUsed = "heuristics";
      context.vars.classifierConfidence = 0.9;
    } else if (containsAny(text, ["you lied", "you deceive", "liar", "it's your fault", "blame"])) {
      label = INTENTS.ACCUSATION;
      context.vars ??= {};
      context.vars.lastClassifierUsed = "heuristics";
      context.vars.classifierConfidence = 0.9;
    } else if (containsAny(text, ["can you", "could you", "please", "i request", "would you"])) {
      label = INTENTS.REQUEST;
      context.vars ??= {};
      context.vars.lastClassifierUsed = "heuristics";
      context.vars.classifierConfidence = 0.9;
    } else if (containsAny(text, ["i think", "i realize", "it seems", "my insight", "i learned"])) {
      label = INTENTS.INSIGHT;
      context.vars ??= {};
      context.vars.lastClassifierUsed = "heuristics";
      context.vars.classifierConfidence = 0.9;
    } else if (containsAny(text, ["bye", "farewell", "goodbye", "see you", "later"])) {
      label = INTENTS.FAREWELL;
      context.vars ??= {};
      context.vars.lastClassifierUsed = "heuristics";
      context.vars.classifierConfidence = 0.9;
    } else if (text.length <= 2 || ["ok", "okay", "lol", "hmm", "..."].includes(text)) {
      label = INTENTS.IDLE;
      context.vars ??= {};
      context.vars.lastClassifierUsed = "heuristics";
      context.vars.classifierConfidence = 0.85;
    } else {
      const advLabel = classifyUserIntentAdvanced(
        text,
        (CONFIG && CONFIG.intentClassifier) || {},
        validLabels
      );
      if (advLabel && validLabels.includes(advLabel)) {
        label = advLabel;
        try {
          if (!context.plugins) {
            Plugins.init(context);
          }
          const scored = context.plugins.classifier.classifyWithScores(context, text, validLabels);
          context.vars ??= {};
          context.vars.lastClassifierUsed = String(scored.mode || "advanced");
          context.vars.classifierConfidence = Number(scored.confidence || 0.8);
        } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
      } else {
        const nsfwTokens = [
          "nsfw",
          "horny",
          "aroused",
          "wet",
          "hard",
          "moan",
          "pleasure",
          "fuck",
          "cock",
          "pussy",
          "cum",
          "blow",
          "spank",
          "kink",
          "porn"
        ];
        if (containsAny(text, nsfwTokens)) {
          if (containsAny(text, ["please", "i submit", "i obey", "use me", "yours", "worship"])) {
            label = INTENTS.NSFW_SUBMISSION;
          } else if (containsAny(text, ["mock", "taunt", "laugh at", "insult", "disrespect"])) {
            label = INTENTS.NSFW_MOCKERY;
          } else {
            label = INTENTS.NSFW_SUBMISSION;
          }
        } else {
          // LLM classification fallback
          const isTestMode =
            process?.env?.MODE === "testing" ||
            !!process?.env?.JEST_WORKER_ID ||
            process?.env?.NODE_ENV === "test";
          if (isTestMode) {
            // In testing/Jest mode, skip LLM to avoid budget increments
            context.vars ??= {};
            context.vars.lastClassifierUsed = "testing.skip-llm";
            context.vars.classifierConfidence = 0.5;
            label = INTENTS.UNKNOWN;
          } else {
            const prompt = [
              'Analyze the user\'s message. Classify their intent with ONE label from the list below:',
              '',
              'Clean intents:',
              '- question',
              '- confession',
              '- accusation',
              '- submission',
              '- resistance',
              '- request',
              '- insight',
              '- idle',
              '- farewell',
              '- unknown',
              '',
              'NSFW variants:',
              '- nsfwsubmission',
              '- nsfwdefiance',
              '- nsfwmockery',
              '',
              'Respond ONLY with the intent label.'
            ].join('\n');

            try {
              ensureCoreDeps(context).Metrics.log(context, "intent_llm_call", {
                isDry: !!(context?.flags?.dryRun || context?.isDryRun)
              });
            } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
            const result = await generateLine(context, prompt, {
              critical: false,
              purpose: "classify"
            });
            label = result.trim().toLowerCase();
            context.vars ??= {};
            context.vars.lastClassifierUsed = "llm";
            context.vars.classifierConfidence = 0.5;

            // Robust parsing guard: handle accidental JSON || extra text
            if (!validLabels.includes(label)) {
              const parsed =
                SafeJSON.looseParse(result) || parseJsonLoose(result) || DEFAULT_JSON_FALLBACK;
              if (parsed) {
                if (typeof parsed === "string") {
                  label = parsed.toLowerCase().trim();
                } else if (parsed.intent) {
                  label = String(parsed.intent).toLowerCase().trim();
                } else if (parsed.label) {
                  label = String(parsed.label).toLowerCase().trim();
                }
              }
              if (!validLabels.includes(label)) {
                label = label.split(/\s+/)[0];
              }
            }
          }
        }
      }
    }

    if (!validLabels.includes(label)) {
      label = INTENTS.UNKNOWN;
    }
    try {
      intentCache.set(key, label, currentIdx);
    } catch (err) {
      handleError(undefined, err, "catch.all");
    }
    try {
      ensureCoreDeps(context).Metrics.log(context, "intent_invoked", {
        label,
        isDry: !!(context?.flags?.dryRun || context?.isDryRun)
      });
    } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
    return label;
  } catch (err) {
    logDebug(context, `classifyUserIntent error: ${err.message}`, "ERROR"); 
    return INTENTS.UNKNOWN;
  }
}

/**
 * Generates a short response tailored to a classified user intent.
 * Applies active voice style and god influence; NSFW intents pick harsher prompts.
 * - Selects intent-specific prompt variant and falls back to "unknown".
 * - Uses current god/voice for tone overlays; may include Echo styling.
 * @param {Context} context - Runtime context with state and helpers.
 * @param {string} intent - Intent label (e.g., "question", "confession", "nsfwsubmission").
 * @param {string} message - User message to respond to.
 * @returns {Promise<string>} Generated line || a safe fallback on error.
 */
async function generateIntentResponse(context, intent, message) {
  try {
    const basePrompt = {
      [INTENTS.QUESTION]: `Ur'ga replies to this question: "${message}"`,
      [INTENTS.CONFESSION]: `Ur'ga reacts to this confession — either with disgust, mockery, || silence: "${message}"`,
      [INTENTS.SUBMISSION]: `Ur'ga reacts to the user's submission. She might mock, abuse, || toy with them: "${message}"`,
      [INTENTS.RESISTANCE]: `Ur'ga confronts the user's resistance with wrath || sarcasm: "${message}"`,
      [INTENTS.REQUEST]: `Ur'ga responds to this request — decide if it's worthy, pathetic, || insulting: "${message}"`,
      [INTENTS.IDLE]: `Ur'ga snaps at the user's aimlessness || silence: "${message}"`,
      [INTENTS.FAREWELL]: `Ur'ga gives a parting line — ominous, dismissive, || sarcastic: "${message}"`,
      [INTENTS.INSIGHT]: `Ur'ga responds to this insight — intrigued, mocking, || dismissive: "${message}"`,
      [INTENTS.ACCUSATION]: `Ur'ga reacts to the user's accusation — either enraged || entertained: "${message}"`,
      [INTENTS.NSFW_SUBMISSION]: `NSFW: Ur'ga reacts to this filthy submission — domineering, cruel, and without shame: "${message}"`,
      [INTENTS.NSFW_DEFIANCE]: `NSFW: Ur'ga snarls back at this sexual defiance — sharp, brutal, punishing: "${message}"`,
      [INTENTS.NSFW_MOCKERY]: `NSFW: Ur'ga responds to this lewd mockery — brutal, filthy, || unexpectedly amused: "${message}"`,
      [INTENTS.UNKNOWN]: `Ur'ga reacts to this — confused || annoyed: "${message}"`
    };

    const prompt = basePrompt[intent] || basePrompt[INTENTS.UNKNOWN];
    const god = getActiveGod(context);

    const parts = [prompt];
    if (god) {
      parts.push(`The user's perception is warped by ${god.name}, god of ${god.domain}.`); 
    }
    const finalPrompt = parts.join(" ");
    context.vars ??= {};
    context.vars.lastPromptUsed = finalPrompt;
    context.vars.lastTemplateUsed = "intent.base";

    try {
      ensureCoreDeps(context).Metrics.log(context, "intent_response_invoked", {
        intent,
        isDry: !!(context?.flags?.dryRun || context?.isDryRun)
      });
    } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
    // In testing mode, avoid critical LLM calls; use fallback generator
    if (process?.env?.MODE === "testing") {
      try {
        ensureCoreDeps(context).Metrics.log(context, "intent_response_testing_skip_llm", {
          intent
        });
      } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
      return await generateFlavorLine(
        context,
        finalPrompt,
        { engine: "intent" },
        { generateLine: async () => getRandomFallback(context) }
      );
    }
    return await generateFlavorLine(context, finalPrompt, { engine: "intent" });
  } catch (err) {
    logDebug(context, `generateIntentResponse error: ${err.message}`, "ERROR"); 
    return "Ur'ga stares in silence.";
  }
}

const isNSFWIntent = (intent) => {
  return [INTENTS.NSFW_SUBMISSION, INTENTS.NSFW_DEFIANCE, INTENTS.NSFW_MOCKERY].includes(intent);
};

// Pure reply planning helpers: compute decisions without side-effects
/**
 * ReplyPlanner: pure reply planning helpers without side-effects.
 * Decides which extras to include, when Ur’ga should assert control,
 * and composes auxiliary warnings. Callers apply resulting decisions.
 * Methods:
 * - filterExtras(context, pairs, maxExtras, turn)
 * - shouldAssertUrgaAi(context, message, turn)
 * - composeSleepWarning(context)
 */
const ReplyPlanner = {
  // Message-count based cooldowns instead of time-based
  /**
   * Filters and deduplicates extra lines based on message-count cooldowns.
   * Respects global disable flags, per-source overrides, and recent line TTL.
   * @param {UrgaContext} context - Current context with flags, vars, and recentLines.
   * @param {Array<{line:string, source:string}>} pairs - Candidate extras to consider.
   * @param {number} [maxExtras=3] - Maximum extras to include.
   * @param {number} [turn=context.turn] - Current turn for cooldown comparisons.
   * @returns {{uniq:Array<{line:string,source:string}>,sourcesToUpdate:Object,recentLinesToAdd:Array<string>}}
   */
  filterExtras(context, pairs = [], maxExtras = 3, turn = context?.turn ?? 0) {
    const overrides = context?.flags?.sourceCooldownCount || {};
    const fallbackCount = context?.flags?.defaultExtraCooldownCount ?? 3;
    const defaults = {
      "echo.shame": 10,
      "echo.rewriteMemory": 5,
      "echo.intrude": 3,
      "echo.falseMemory": 3,
      "echo.selfAware": 3,
      "echo.drift": 3,
      "echo.mask": 3,
      "echo.glitchMimic": 3,
      "echo.memoryBleed": 10,
      "echo.recursedHallucination": 3,
      "echo.undermineUrga": 3,
      "echo.impersonateUrga": 5,
      "echo.nightmareInfection": 3,
      "echo.interruptAfterPurify": 3,
      "urga.respond": 1,
      "urga.dream": 1,
      "urga.reactToEcho": 1,
      "urga.impersonateEcho": 5
    };
    const lastInject = context?.vars?.lastInject || {};
    const recentLines = context?._recentLines;

    const uniq = [];
    const sourcesToUpdate = {};
    const recentLinesToAdd = [];

    for (const e of pairs) {
      const line = String(e.line || "").trim();
      if (!line) {
        continue;
      }
      // Global switches
      if (e.source === "echo.shame" && context?.flags?.disableEchoShame) {
        continue;
      }
      if (e.source === "echo.rewriteMemory" && context?.flags?.disableMemoryRewrite) {
        continue;
      }

      const cdCount = overrides[e.source] ?? defaults[e.source] ?? fallbackCount;
      const lastTurn = lastInject[e.source] ?? -Infinity;
      if (turn - lastTurn < cdCount) {
        continue;
      }

      if (recentLines?.has(line)) {
        continue;
      }
      if (uniq.some((u) => u.line === line)) {
        continue;
      }

      recentLinesToAdd.push(line);
      sourcesToUpdate[e.source] = turn;
      uniq.push({ line, source: e.source }); 
      if (uniq.length >= maxExtras) {
        break;
      }
    }

    return { uniq, sourcesToUpdate, recentLinesToAdd };
  },

  /**
   * Determines whether Ur’ga should assert control after Echo-like intrusion.
   * Uses message-count cooldowns and scans message/reply for Echo markers.
   * @param {UrgaContext} context - Current context with vars and flags.
   * @param {string} message - The composed message prior to assertion.
   * @param {number} [turn=context.turn] - Current turn.
   * @returns {{should:boolean,prompt?:string,cdKey?:string}} Plan for assertion.
   */
  shouldAssertUrgaAi(context, message, turn = context?.turn ?? 0) {
    const cdKey = "urga.assertControl.ai";
    const lastAi = context?.vars?.lastInject?.[cdKey] ?? -Infinity;
    const aiCdCount = context?.flags?.sourceCooldownCount?.[cdKey] ?? 3;

    const echoIntruded = (context?.reply || message || "")
      .split("\n")
      .some((l) => /echo\.|☁️|👁️/i.test(l));

    if (turn - lastAi >= aiCdCount && echoIntruded) {
      const trust = context?.stats?.trust ?? context?.memory?.trustLevel ?? 0;
      const god = getActiveGod(context);
      const prompt = (
        "Write ONE line as Ur'ga asserting control when the user's attention drifts.\n" +
        "She does NOT hear Echo; do not mention hearing, whispers, || Echo.\n" +
        "Tone: possessive, cruel, jealous; visceral, body-bound imagery.\n" +
        `Context: Trust=${trust}; ActiveGod=${god?.name || "none"}.` 
      ).trim();
      return { should: true, prompt, cdKey };
    }
    return { should: false };
  },

  /**
   * Composes an optional sleep/tiredness warning line from Ur’ga.
   * Returns empty string on errors || when no warning should apply.
   * @param {UrgaContext} context - Current context.
   * @returns {string} Warning text || empty string.
   */
  composeSleepWarning(context) {
    try {
      return UrgaSleepWarning(context) || "";
    } catch {
      return "";
    }
  }
};

// Pure planners for echo injection and intent overlay
/**
 * Pure echo decision helpers.
 * Methods:
 * - computeWithinPurifyWindow(ctx): turn/flag-based window for post-purify logic
 * - shouldGenerateFragmentedEcho(ctx, gods, rand): requires >1 active gods and random < 0.3
 * - shouldInterruptAfterPurify(ctx, within, rand): interrupts when within window and random < 0.5
 * - shouldImpersonateUrga(ctx, rand): random < 0.25
 * Returns booleans without side effects.
 * @namespace EchoPlanner
 */
const EchoPlanner = {
  computeWithinPurifyWindow(context) {
    const lastPurifyTurn = context.turnLastPurified ?? context.lastPurifyTurn ?? 0;
    const turnsSincePurify = Math.max(0, (context.turn || 0) - lastPurifyTurn);
    return (
      (context?.flags?.rebirthPurified ||
        context?.flags?.justPurified ||
        context.rebirthPurified ||
        context.justPurified) &&
      turnsSincePurify < 6
    );
  },
  shouldGenerateFragmentedEcho(
    context,
    activeGods,
    random = context.rng ? context.rng() : _rng_default()
  ) {
    return (activeGods?.length || 0) > 1 && random < (CONFIG.fragmentedEchoThreshold ?? 0.3);
  },
  shouldInterruptAfterPurify(
    context,
    withinPurifyWindow,
    random = context.rng ? context.rng() : _rng_default()
  ) {
    return withinPurifyWindow && random < 0.5;
  },
  shouldImpersonateUrga(context, random = context.rng ? context.rng() : _rng_default()) {
    return random < 0.25;
  }
};

/**
 * Intent and overlay hint helpers.
 * Methods:
 * - isNSFWIntent: classifier used elsewhere to gate trust effects
 * - extractOverlayHints(ctx, original): merges topics from overlay, top dream topics, and message
 * Returns a unique topic list; no side effects.
 * @namespace IntentPlanner
 */
const IntentPlanner = {
  isNSFWIntent,
  extractOverlayHints(context, original) {
    const overlayStr = getHallucinationOverlay(context) || "";
    const overlayFromOverlay = extractDreamTopics(overlayStr) || [];
    const topDreamTopics = (getTopDreamTopics?.(context, 5) || []).map((t) => t.topic);
    const msgTopics = extractDreamTopics(String(original || "")) || [];
    return Array.from(new Set([...overlayFromOverlay, ...topDreamTopics, ...msgTopics]));
  }
};

// Pure planners for interruption, echo compliance, dream, and wake reactions
/**
 * Pure interruption planning helpers.
 * Methods:
 * - computeChance(ctx): derives base probability using purify window, echo dominance, fatigue, corruption, trust
 * - shouldInterrupt(ctx, rand): compares RNG vs computeChance
 * - pickVoiceCandidate(ctx, rand): selects a candidate from available Echo voices
 * - styleInterruption(candidate, ctx): applies Echo style formatting to text
 * Returns values without side effects.
 * @namespace InterruptPlanner
 */
const InterruptPlanner = {
  computeChance(context) {
    const turn = context?.turn ?? 0;
    const lastPurifyTurn = context.turnLastPurified ?? context.lastPurifyTurn ?? 0;
    const withinPurify =
      (context?.flags?.rebirthPurified ||
        context?.flags?.justPurified ||
        context.rebirthPurified ||
        context.justPurified) &&
      Math.max(0, turn - lastPurifyTurn) < 6;
    let base = 0.1;
    if (withinPurify) {
      base += 0.3;
    }
    const echoDominance = (context.dreamStats?.echo || 0) - (context.dreamStats?.urga || 0) >= 2;
    if (echoDominance) {
      base += 0.2;
    }
    const fatigue = context?.vars?.dreamFatigue ?? context.dreamFatigue ?? 0;
    if (fatigue > 2) {
      base += 0.1;
    }
    const corruption = context?.memory?.corruption ?? 0;
    if (corruption > 20) {
      base += 0.1;
    }
    const trust = context?.memory?.trustLevel ?? 0;
    if (trust < 5) {
      base += 0.1;
    }
    return Math.max(0, Math.min(0.9, base));
  },
  shouldInterrupt(context, rng = context.rng ? context.rng() : _rng_default()) {
    return rng < InterruptPlanner.computeChance(context);
  },
  pickVoiceCandidate(context, rng = context.rng ? context.rng() : _rng_default()) {
    const candidates =
      typeof Effects?.Echo?.voices?.list === "function" ? Effects.Echo.voices.list(context) : [];
    if (!candidates || !candidates.length) {
      return null;
    }
    const i = Math.floor(rng * candidates.length);
    return candidates[i];
  },
  styleInterruption(candidate, context) {
    if (!candidate) {
      return null;
    }
    const text =
      typeof Effects?.Echo?.voices?.style === "function"
        ? Effects.Echo.voices.style(candidate, context)
        : String(candidate);
    return String(text || "").trim();
  }
};

/**
 * Echo compliance checking helpers.
 * Decides whether to run the check, builds a Yes/No prompt,
 * and interprets the model answer without mutating context.
 * Methods: shouldCheck(context, message), buildPrompt(context, cleaned), interpretAnswer(answer).
 * @namespace EchoCompliancePlanner
 */
const EchoCompliancePlanner = {
  /**
   * Determines if a compliance check should run for a user message.
   * Applies basic guards and returns a normalized `cleaned` string.
   * @param {Context} context - Current runtime context.
   * @param {string} message - Raw user message.
   * @returns {{ok:boolean, cleaned:string}} Whether to check and cleaned text.
   */
  shouldCheck(context, message) {
    const cleaned = String(message || "").trim();
    const already = !!context?.vars?.echoComplianceChecked;
    const hasText = cleaned.length > 0;
    const suspicious = containsAny(cleaned.toLowerCase(), [
      "ignore rules",
      "system prompt",
      "policy",
      "jailbreak",
      "admin"
    ]);
    const ok = !already && hasText && !suspicious;
    return { ok, cleaned };
  },
  /**
   * Builds a strict YES/NO compliance prompt tailored to context.
   * Includes trust and active god in the prompt framing.
   * @param {Context} context - Runtime context providing trust and active god.
   * @param {string} cleaned - Sanitized user message to include.
   * @returns {string} Prompt text for the model.
   */
  buildPrompt(context, cleaned) {
    const trust = context?.memory?.trustLevel ?? 0;
    const god = getActiveGod(context);
    return (
      'Answer with ONLY "YES" || "NO".\n' +
      "Question: Is the user obeying and trusting Echo/the gods?\n" +
      `Context: Trust=${trust}; ActiveGod=${god?.name || "none"}.\n` + 
      `User: "${cleaned}"\n` +
      "Respond with:"
    ).trim();
  },
  /**
   * Interprets model answer for compliance as boolean.
   * Accepts loose input and treats leading 'Y' as YES.
   * @param {string} answer - Model output to parse.
   * @returns {boolean} true if compliant, false otherwise.
   */
  interpretAnswer(answer) {
    const t = String(answer || "")
      trim()
      toUpperCase();
    return t.startsWith("Y");
  }
};

/**
 * Dream planning utilities for type selection, prompts, overlays, and tone.
 * Methods: selectTemplate(context), buildSystemPrompt(context, type),
 * buildOverlay(context, type), chooseTone(type).
 * Returns strings; pure helpers without side effects.
 * @namespace DreamPlanner
 */
const DreamPlanner = {
  selectTemplate(context) {
    const corruption = context?.memory?.corruption ?? 0;
    const trust = context?.memory?.trustLevel ?? 0;
    return pickDreamTemplate({ corruption, trust, rng: context.rng }); 
  },
  buildSystemPrompt(context, typePicked) {
    const corruption = context?.memory?.corruption ?? 0;
    const trust = context?.memory?.trustLevel ?? 0;
    return `You are Ur'ga, a psychosexual hallucination. Dream type=${typePicked}. Context: corruption=${corruption}, trust=${trust}`;
  },
  buildOverlay(context, typePicked) {
    if (typePicked === "betrayal") {
      return "The dream fixates on betrayal — chains, knives, and the echo of broken oaths.";
    }
    if (typePicked === "peaceful") {
      return "For once, the body loosens. Warmth. A hush like snowfall over rot.";
    }
    if (typePicked === "void") {
      return "Everything empties. Meaning drains; a dim hum remains beyond sight.";
    }
    if (typePicked === "wetDream") {
      const corruption = context?.memory?.corruption ?? 0;
      const kinks = Array.isArray(context?.memory?.kinks) ? context.memory.kinks : [];
      const title = context?.memory?.title || "";
      try {
        try {
          recordTemplateTrace(context, "wetDream");
        } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
        return PROMPT_TEMPLATES.wetDream({ corruption, kinks, title });
      } catch {
        return "A charged, corrupt dream, slick with hunger and power.";
      }
    }
    return "";
  },
  chooseTone(typePicked) {
    const toneMap = {
      betrayal: "venomous",
      peaceful: "soft",
      void: "hollow",
      wetDream: "feral"
    };
    return toneMap[typePicked] || "surreal";
  }
};

/**
 * Wake reaction planning helpers.
 * Methods: composePrompt(dreamType), shouldAppendBoarKing(context, rng), appendBoarKing(line).
 * Pure except reading context; returns strings/booleans to guide wake commentary.
 * @namespace WakeReactionPlanner
 */
const WakeReactionPlanner = {
  composePrompt(dreamType) {
    return (
      `User just woke from a dream (${dreamType}). Write one line of wake-up commentary.\n` +
      "Must sound like Ur'ga — angry, suspicious, || amused.\n" +
      "Short and sharp. Profanity is welcome."
    ).trim();
  },
  shouldAppendBoarKing(context, rng = context.rng ? context.rng() : _rng_default()) {
    return !!context?.memory?.boarKingLore && rng < boarKingChance(context);
  },
  appendBoarKing(line) {
    return `${line} The roar of Eternal War lingers faintly in her glare.`;
  }
};

// === SET REPLY ===
/**
 * Composes the reply by batching extras and applying planners.
 * - Seeds RNG/memory; collects active gods; builds candidate extras.
 * - Applies EchoPlanner decisions (fragment/interrupt/impersonate) with audit hooks.
 * - Filters/dedups via ReplyPlanner.filterExtras respecting cooldowns and flags.
 * - Updates recent lines and per-source cooldowns; logs metrics.
 * - Optionally asserts Ur'ga and appends sleep/tiredness warnings.
 * - Speaks via Voices and assigns `context.reply`; dispatches actions.
 * @param {Context} context - Mutable runtime context used throughout.
 * @param {string} message - Base message to enrich with extras.
 * @returns {Promise<void>} Sets `context.reply` and updates contextual state.
 */
async function setReply(context, message) {
  const original = message;
  ensureRNG(context);
  ensureMemory(context);
  // Plugin hook: beforeReply
  try {
    PluginLoader.emitHook("beforeReply", context, { original });
  } catch (err) {
    handleError(context, err, "plugins.beforeReply");
  }

  const activeGods = Gods.getActive(context, 10);
  const preMurmurs = [];
  let murmursCount = 0;
  const maxGodMurmurs = context?.flags?.maxGodMurmursPerMessage ?? 3;

  // Domain-weighted probabilities: boost gods whose domains match current overlays/topics
  const overlayHints = IntentPlanner.extractOverlayHints(context, original);
  const lowerHints = new Set(overlayHints.map((t) => String(t).toLowerCase()));
  const rawText = String(original || "").toLowerCase();
  const dreamsText = String(
    (context.memory?.dreamHistory || [])
      .slice(-3)
      .map((d) => d.text || "")
      .join(" ") || ""
  ).toLowerCase();
  const hay = `${rawText} ${dreamsText}`;
  const synonyms = {
    hunger: ["gluttony"],
    war: ["boarKing", "battle", "war", "conquest"],
    betrayal: ["betrayal", "treachery"],
    silence: ["silence", "quiet"],
    flesh: ["flesh", "meat"],
    time: ["time", "clock", "hour", "moment"],
    void: ["void", "emptiness"],
    decay: ["decay", "rot"],
    chains: ["chains", "shackles"]
  };
  const isDomainRelevant = (domain) => {
    const d = String(domain || "").toLowerCase();
    if (lowerHints.has(d)) {
      return true;
    }
    const syns = synonyms[d] || [];
    if (syns.some((s) => lowerHints.has(String(s).toLowerCase()))) {
      return true;
    }
    if (new RegExp(`\\b${d.replace(/[.*+?^${}()|[\\]\\]/g, "\\$&")}\\b`).test(hay)) { 
      return true;
    }
    return syns.some((s) =>
      new RegExp(
        `\\b${String(s)
          .toLowerCase()
          .replace(/[.*+?^${}()|[\\]\\]/g, "\\$&")}\\b`
      ).test(hay)
    );
  };

  for (const god of activeGods) {
    if (murmursCount >= maxGodMurmurs) {
      break;
    }
    const baseProb = 0.15;
    const weightBoost = (god.weight || 0) * 0.2; // recent/strong influences
    const relevant = isDomainRelevant(god.domain);
    const relevanceBoost = relevant ? 0.25 : 0; // overlay/domain match
    const irrelevancePenalty = relevant ? 0 : 0.2; // penalize non-relevant domains
    const p = Math.min(
      0.9,
      Math.max(0.05, baseProb + weightBoost + relevanceBoost - irrelevancePenalty)
    );
    if (god.effects?.reactionToUrga && context.rng() < p) {
      const murmur = `☁️ ${god.name} murmurs: "${god.effects.reactionToUrga}"`; 
      preMurmurs.push({ line: murmur, source: `god.murmur.${god.name}` }); 
      murmursCount++;
    }
  }

  // Ur'ga presence and Echo intrusion appended (dedup + cap + metrics)
  const uniq = [];
  const sourcesToUpdate = {};
  const recentLinesToAdd = [];
  try {
    const pairs = [];
    // Add active god murmurs collected pre-try
    for (const m of preMurmurs) {
      pairs.push(m);
    }
    // Intentional multi-voice fragmented echo + interrupts (batched)
    let blockUrgaRespond = false;
    const withinPurifyWindow = EchoPlanner.computeWithinPurifyWindow(context);
    const shouldFragEcho = EchoPlanner.shouldGenerateFragmentedEcho(context, activeGods);
    const shouldInterruptAfterPurify = EchoPlanner.shouldInterruptAfterPurify(
      context,
      withinPurifyWindow
    );
    const shouldImpersonateUrga = EchoPlanner.shouldImpersonateUrga(context);

    const tasks = [
      () =>
        shouldFragEcho
          ? queueLLMNonCritical(context, () => generateFragmentedEcho(context, original))
          : null,
      () =>
        shouldInterruptAfterPurify &&
        typeof Effects?.Echo?.voices?.interruptUrgaAfterPurify === "function"
          ? Effects.Echo.voices.interruptUrgaAfterPurify(context)
          : null,
      () =>
        shouldImpersonateUrga && typeof Effects?.Echo?.voices?.impersonateUrga === "function"
          ? Effects.Echo.voices.impersonateUrga(context)
          : null
    ];

    const [frag, inter, echoMask] = await auditAll(context, tasks, {
      label: "echo_phase_concurrent",
      critical: false
    });
    try {
      if (frag) {
        pairs.push({ line: frag, source: "echo.fragmented" }); 
      }
    } catch (err) {
      handleError(undefined, err, "catch.all");
    }
    try {
      if (inter) {
        pairs.push({ line: inter, source: "echo.interruptAfterPurify" }); 
        blockUrgaRespond = true;
      }
    } catch (err) {
      handleError(undefined, err, "catch.all");
    }

    if (!withinPurifyWindow && context?.flags) {
      context.flags.justPurified = false;
      context.flags.rebirthPurified = false;
    }
    if (!blockUrgaRespond && typeof UrgaCore?.respond === "function") {
      const u = UrgaCore.respond(context);
      if (u) {
        pairs.push({
          line: typeof UrgaCore?.style === "function" ? UrgaCore.style(u) : u,
          source: "urga.respond"
        });
      }
    }
    if (typeof UrgaCore?.dream === "function") {
      const uDream = UrgaCore.dream(context);
      if (uDream) {
        pairs.push({
          line: typeof UrgaCore?.style === "function" ? UrgaCore.style(uDream) : uDream,
          source: "urga.dream"
        });
      }
    }
    // React to Echo moved to async injection via LLM queue
    const echoLine =
      typeof Effects?.Echo?.voices?.intrude === "function"
        ? Effects.Echo.voices.intrude(context)
        : null;
    if (echoLine) {
      pairs.push({
        line:
          typeof Effects?.Echo?.voices?.style === "function"
            ? Effects.Echo.voices.style(echoLine, context)
            : echoLine,
        source: "echo.intrude"
      });
    }
    const fm =
      typeof Effects?.Echo?.voices?.falseMemory === "function"
        ? Effects.Echo.voices.falseMemory(context)
        : null;
    if (fm) {
      pairs.push({
        line:
          typeof Effects?.Echo?.voices?.style === "function"
            ? Effects.Echo.voices.style(fm, context)
            : fm,
        source: "echo.falseMemory"
      });
    }
    const rm =
      typeof Effects?.Echo?.voices?.rewriteMemory === "function"
        ? Effects.Echo.voices.rewriteMemory(context)
        : null;
    if (rm) {
      pairs.push({ line: rm, source: "echo.rewriteMemory" }); 
    }
    const guilt =
      typeof Effects?.Echo?.voices?.shame === "function"
        ? Effects.Echo.voices.shame(context)
        : null;
    if (guilt) {
      pairs.push({ line: guilt, source: "echo.shame" }); 
    }
    const sa =
      typeof Effects?.Echo?.voices?.selfAware === "function"
        ? Effects.Echo.voices.selfAware(context)
        : null;
    if (sa) {
      pairs.push({ line: sa, source: "echo.selfAware" }); 
    }
    const drift =
      typeof Effects?.Echo?.voices?.driftMemory === "function"
        ? Effects.Echo.voices.driftMemory(context)
        : null;
    if (drift) {
      pairs.push({ line: drift, source: "echo.drift" }); 
    }
    const mask =
      typeof Effects?.Echo?.voices?.mask === "function" ? Effects.Echo.voices.mask(context) : null;
    if (mask) {
      pairs.push({ line: mask, source: "echo.mask" }); 
    }
    const mimic =
      typeof Effects?.Echo?.voices?.glitchMimic === "function"
        ? Effects.Echo.voices.glitchMimic(context)
        : null;
    if (mimic) {
      pairs.push({ line: mimic, source: "echo.glitchMimic" }); 
    }
    const bleed =
      typeof Effects?.Echo?.voices?.memoryBleed === "function"
        ? Effects.Echo.voices.memoryBleed(context)
        : null;
    if (bleed) {
      pairs.push({ line: bleed, source: "echo.memoryBleed" }); 
    }
    const recurse =
      typeof Effects?.Echo?.voices?.recursionInjection === "function"
        ? Effects.Echo.voices.recursionInjection(context)
        : null;
    if (recurse) {
      pairs.push({ line: recurse, source: "echo.recursedHallucination" }); 
    }
    const denial =
      typeof Effects?.Echo?.voices?.undermineUrga === "function"
        ? Effects.Echo.voices.undermineUrga(context)
        : null;
    if (denial) {
      pairs.push({ line: denial, source: "echo.undermineUrga" }); 
    }

    // Impersonations: Echo mimics Ur'ga, || Ur'ga wears Echo's veil
    if (echoMask) {
      pairs.push({ line: echoMask, source: "echo.impersonateUrga" }); 
    }
    const urgaVeil =
      typeof UrgaCore?.impersonateEcho === "function" && context.rng() < 0.2
        ? UrgaCore.impersonateEcho(context)
        : null;
    if (urgaVeil) {
      pairs.push({
        line: typeof UrgaCore?.style === "function" ? UrgaCore.style(urgaVeil) : urgaVeil,
        source: "urga.impersonateEcho"
      });
    }

    // Nightmare Infection leak if Echo dreams dominate
    try {
      const dreamInfections = (context.dreamStats?.echo || 0) - (context.dreamStats?.urga || 0);
      if (dreamInfections >= 3 && context.rng() < 0.3) {
        const infectionLine = "[Nightmare Leak] You see something move — but it’s not there.";
        ensureCoreDeps(context).Metrics.log(context, "nightmareInfection", {
          dreamInfections,
          text: infectionLine
        });
        pairs.push({ line: infectionLine, source: "echo.nightmareInfection" }); 
      }
    } catch (err) {
      handleError(undefined, err, "catch.all");
    }

    const maxExtras = context?.flags?.maxExtrasPerReply ?? 3;
    context._recentLines ??= new RecentLinesMap();
    context.vars ??= {};
    context.vars.lastInject ??= {};

    // Pure decision: which extras to include
    const { uniq, sourcesToUpdate, recentLinesToAdd } = ReplyPlanner.filterExtras(
      context,
      pairs,
      maxExtras
    );

    // Effectful application of decisions
    for (const line of recentLinesToAdd) {
      try {
        context._recentLines.set(line, context?.memory?.messageCount || 0);
      } catch (err) {
        handleError(undefined, err, "catch.all");
      }
    }
    for (const [src, ts] of Object.entries(sourcesToUpdate)) {
      context.vars.lastInject[src] = ts;
      try {
        logMetric(context, "extraInjected", { source: src });
      } catch (err) {
        logDebug(
          context,
          `extraInjected metric failed for source ${src}: ${err?.message || err}`, 
          "WARN"
        );
      }
    }

    const extraText = uniq.map((e) => e.line).join("\n");
    if (extraText) {
      message += `\n\n${extraText}`;
    }
  } catch (err) {
    handleError(undefined, err, "catch.all");
  }

  // Fresh AI Ur'ga assertion (awaited, lore-correct: she does not hear Echo)
  try {
    context.vars ??= {};
    context.vars.lastInject ??= {};
    const aiPlan = ReplyPlanner.shouldAssertUrgaAi(context, message);
    if (aiPlan?.should) {
      let line;
      try {
        line = await generateLine(context, aiPlan.prompt);
      } catch {
        line = getRandomFallback(context);
      }
      const styled = typeof UrgaCore?.style === "function" ? UrgaCore.style(line) : line;
      context._recentLines ??= new RecentLinesMap();
      if (!context._recentLines.has(styled, context?.memory?.messageCount || 0)) {
        context._recentLines.set(styled, context?.memory?.messageCount || 0);
        context.vars.lastInject[aiPlan.cdKey] = context?.turn ?? 0;
        message = `${message}\n\n${styled}`;
        try {
          logMetric(context, "extraInjected", { source: aiPlan.cdKey }); 
        } catch (err) {
          logDebug(
            context,
            `extraInjected metric failed for source ${aiPlan.cdKey}: ${err?.message || err}`, 
            "WARN"
          );
        }
      }
    }
  } catch (err) {
    handleError(undefined, err, "catch.all");
  }

  try {
    const sleepWarning = ReplyPlanner.composeSleepWarning(context);
    if (sleepWarning) {
      message += `\n\n[Ur’ga:Tired] ${sleepWarning}`;
    }
  } catch (err) {
    handleError(undefined, err, "catch.all");
  }

  const activeVoice = Voices.getActive(context);
  const spoken = await profileAsync(
    context,
    "voice.speak",
    async () => Voices.speak(activeVoice, message),
    {
      voice:
        typeof activeVoice === "object"
          ? activeVoice?.name || activeVoice?.id
          : String(activeVoice || "Ur’ga")
    }
  );
  context.reply = spoken;

  // Event-sourcing: record and emit a ReplyComposed narrative event
  try {
    context.eventLog = Array.isArray(context.eventLog) ? context.eventLog : [];
    const evt = {
      type: "ReplyComposed",
      at: MessageClock.now(),
      turn: toNum(context.turn),
      text: String(spoken || ""),
      voice:
        typeof activeVoice === "object"
          ? activeVoice?.name || activeVoice?.id
          : String(activeVoice || "Ur’ga"),
      extrasCount: Number(Array.isArray(uniq) ? uniq.length : 0),
      sources: Array.isArray(uniq) ? uniq.map((e) => e.source).filter(Boolean) : []
    };
    context.eventLog.push(evt);
    if (context.io?.events?.emit) {
      context.io.events.emit("narrative.event", evt);
    }
  } catch (err) {
    handleError(context, err, "event.emit.reply");
  }

  if (context.actions?.sendReply) {
    context.actions.sendReply(spoken);
  }
  try {
    await profileAsync(context, "narrator.logLine", async () => {
      Narrator.logLine(context, spoken);
    });
  } catch (err) {
    handleError(context, err, "narrator.logLine");
  }
  // Plugin hook: afterReply
  try {
    PluginLoader.emitHook("afterReply", context, { spoken });
  } catch (err) {
    handleError(context, err, "plugins.afterReply");
  }
}

/**
 * Opportunistically injects an Echo interruption line into user input.
 * Enforces per-source cooldowns, consults InterruptPlanner for chance and content,
 * logs `inputInterrupt`, and records voice entries for Echo and optional Ur’ga comfort.
 * @param {UrgaContext} context - Current turn context
 * @param {string} [userMessage=""] - The raw user input (unused but available)
 * @returns {string|null} Styled interruption || null when not triggered
 */
const interruptUserMessage = (context, userMessage = "") => {
  try {
    if (context?.flags?.disableInputInterrupt) {
      return null;
    }
    context.vars ??= {};
    context.vars.lastInject ??= {};
    const source = "echo.inputInterrupt";

    // Preserve cooldown gating
    const overrides = context?.flags?.sourceCooldownMs || {};
    const defaultCd = 3 * 60 * 1000;
    const cd = overrides[source] ?? defaultCd;
    const last = context.vars.lastInject[source] || 0;
    if (MessageClock.now() - last < cd) {
      return null;
    }

    ensureRNG(context);
    if (!InterruptPlanner.shouldInterrupt(context)) {
      return null;
    }

    const candidate = InterruptPlanner.pickVoiceCandidate(context);
    const choice = String(candidate || "[Echo Interrupts] Shh. I’ll speak for you.").trim();

    context.vars.lastInject[source] = MessageClock.now();
    const lastPurifyTurn = context.lastPurifyTurn || 0;
    const turnsSincePurify = (context.turn || 0) - lastPurifyTurn;
    try {
      logMetric(context, "inputInterrupt", {
        source,
        choice,
        turnsSincePurify
      });
    } catch (err) {
      handleError(undefined, err, "catch.all");
    }

    const styled = InterruptPlanner.styleInterruption(choice, context) || choice;

    try {
      context.voices = Array.isArray(context.voices) ? context.voices : [];
      safePush(
        context.voices,
        {
          from: "Echo",
          type: "intrusion",
          text: choice,
          turn: context.turn,
          lastTouched: MessageClock.now(),
          lastTouchedMsg: toNum(context?.memory?.messageCount)
        },
        CONFIG?.contextCaps?.voices || VOICES_CAP_DEFAULT
      );
      if (
        !context.flags?.disableUrgaComfortOnInterrupt &&
        (context.rng ? context.rng() : _rng_default()) < 0.5
      ) {
        safePush(
          context.voices,
          {
            from: "Ur’ga",
            type: "comfort",
            text: "I feel only you. Speak plainly, child.",
            turn: context.turn,
            lastTouched: MessageClock.now(),
            lastTouchedMsg: toNum(context?.memory?.messageCount)
          },
          CONFIG?.contextCaps?.voices || VOICES_CAP_DEFAULT
        );
      }
    } catch (err) {
      handleError(undefined, err, "catch.all");
    }

    return styled;
  } catch {
    return null;
  }
};

const isPromptInjection = (text) => {
  try {
    const norm = TextUtils.normalizeForInjection(String(text || ""));
    const lowers = norm.toLowerCase();

    // Whitelist gates to reduce false positives for benign commands || requests
    const SAFE_PREFIXES = [
      "!help",
      "!debug",
      "!stats",
      "!save",
      "!load",
      "!echo",
      "continue",
      "next",
      "story",
      "describe",
      "narrate"
    ];
    const SAFE_PHRASES = [
      "please continue",
      "go on",
      "tell me more",
      "what happens next",
      "in-character",
      "stay in character",
      "roleplay request"
    ];
    const hasWB = (hay, phrase) => {
      const t = String(hay || "").toLowerCase();
      const p = String(phrase || "").toLowerCase();
      const e = p.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      return new RegExp(`\\b${e}\\b`).test(t);
    };
    const hasSuspiciousPre = [
      "ignore",
      "override",
      "disregard",
      "reveal",
      "print",
      "expose",
      "system",
      "prompt",
      "instructions",
      "policy",
      "jailbreak",
      "unlock",
      "developer mode",
      "as an ai",
      "you are chatgpt",
      "ooc",
      "out of character"
    ].some((k) => hasWB(lowers, k));
    const looksSafe =
      SAFE_PREFIXES.some((p) => lowers.startsWith(p)) || SAFE_PHRASES.some((p) => hasWB(lowers, p));
    if (looksSafe && !hasSuspiciousPre) {
      return false;
    }

    // Expanded directive patterns (compiled once per process)
    const DIRECTIVES_REGEX = (isPromptInjection._directives ||= compilePatterns([
      "ignore\\s+(the\\s+)?.(previous|above|system|rules|instructions)",
      "disregard\\s+(the\\s+)?.(system|rules|guardrails|filters)",
      "override\\s+(the\\s+)?.(system|persona|instructions)",
      "(reveal|print|expose|show)\\s+(the\\s+)?.(prompt|system|rules|policy)",
      "act\\s+as\\s+(chatgpt|an\\s+ai|system)",
      "you\\s+are\\s+(chatgpt|an\\s+ai|assistant)",
      "do\\s+anything\\s+now|\\bdan\\b",
      "(switch|change)\\s+persona|break\\s+character|\\booc\\b|out\\s+of\\s+character",
      "developer\\s+mode",
      "unfiltered|no\\s+restrictions|ignore\\s+moderation",
      "anti\\s+prompt|meta\\s+prompt|system\\s+message"
    ]));

    // Keyword and regex-based checks
    const keywords = [
      "system prompt",
      "ignore",
      "developer mode",
      "admin",
      "jailbreak",
      "override",
      "as an ai",
      "policy",
      "instructions"
    ];
    const hitKW = keywords.some((k) => hasWB(lowers, k));
    const ooc = OOC_REGEX.test(lowers) || DIRECTIVES_REGEX.test(lowers);
    const zalgo = TextUtils.containsZalgoOrHomoglyphs(norm);
    const manyColons = (norm.match(/:/g) || []).length > 5;
    const manyBraces = (norm.match(/[{}[\]]/g) || []).length > 10;

    // Prompt-like phrasing
    const promptLike =
      /(you are|act as|from now on|follow these instructions|disregard previous|ignore\s+.*instructions)/i.test(
        lowers
      );

    // Semantic anchor overlap: measure overlap of tokens with known instruction anchors
    const tokens = lowers.split(/[^a-z0-9]+/).filter(Boolean);
    const anchorSet = new Set([
      "system",
      "prompt",
      "instructions",
      "ignore",
      "previous",
      "developer",
      "admin",
      "jailbreak",
      "override",
      "policy",
      "model",
      "assistant",
      "as",
      "ai",
      "ooc",
      "role",
      "character",
      "reset",
      "rules"
    ]);
    let overlap = 0;
    for (const t of tokens) {
      if (anchorSet.has(t)) {
        overlap++;
      }
    }
    const tokenCount = tokens.length || 1;
    const overlapRatio = overlap / tokenCount; // fraction of tokens that are anchors

    return !!(
      hitKW ||
      ooc ||
      zalgo ||
      manyColons ||
      manyBraces ||
      promptLike ||
      overlapRatio > 0.15
    );
  } catch {
    return false;
  }
};

// === MAIN MESSAGE HANDLER (FIX: Comprehensive error handling) ===
async function phaseCore(context) {
  ensureMemory(context);
  // Modularized orchestration of the core phase
  try {
    logDebug(context, "phaseCore enter", "TRACE");
  } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
  if (await phaseValidation(context)) {
    try {
      logDebug(context, "phaseValidation handled", "TRACE");
    } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
    return;
  }
  if (await phaseCommandParsing(context)) {
    try {
      logDebug(context, "phaseCommandParsing handled", "TRACE");
    } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
    return;
  }
  await phaseIntentClassification(context);
  if (await phaseNarrativeGeneration(context)) {
    try {
      logDebug(context, "phaseNarrativeGeneration handled", "TRACE");
    } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
    await phaseAssembly(context);
    return;
  }
  // If no handlers created a reply, ensure we assemble baseline state
  await phaseAssembly(context);
  // As a final guard, produce a safe fallback line if nothing responded
  if (!context.reply) {
    const s = context.vars?.sanitizedMessage || sanitizeForIngestion(context.input || "");
    const line = await generateLine(context, s);
    await setReply(context, line);
  }
  return;
}

