async function phaseAssembly(context) {
  ensureMemory(context);
  try {
    logDebug(context, "phaseAssembly enter", "TRACE");
  } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
  const now = MessageClock.now();
  const raw = context.input || "";
  const sanitizedMessage = context.vars?.sanitizedMessage || sanitizeForIngestion(raw);
  const hallucinatedInput = context.vars?.hallucinatedInput || sanitizedMessage;
  // Idle decay
  const prevLast =
    context.lastInteraction ||
    context.lastInteractionTime ||
    context.memory.lastInteractionTimestamp ||
    0;
  const idleSeconds = Math.floor((now - prevLast) / 1000);
  if (idleSeconds > 600) {
    context.stats = context.stats || {};
    ensureStats(context);
    const curTrust = Number(context.memory?.trustLevel ?? 0);
    const curCorruption = Number(context.memory?.corruption ?? context.stats?.corruption ?? 0);
    try {
      MemoryManager.setTrust(context, Math.max(0, curTrust - 1), "idleDecay");
      MemoryManager.setCorruption(context, curCorruption + 1, "idleDecay");
      ensureCoreDeps(context).Metrics.log(context, "idleDecay", {
        idleSeconds
      });
    } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }
  }
  // Timestamps and message tracking
  context.memory.lastInteractionTimestamp = now;
  context.lastInteractionTime = now;
  context.lastInteraction = now;
  context.memory.messageCount = (context.memory.messageCount || 0) + 1;
  context.memory.interactionHistory = context.memory.interactionHistory || [];
  safePush(
    context.memory.interactionHistory,
    {
      at: now,
      insertedAtMessage: context.memory.messageCount,
      input: raw,
      hallucinated: hallucinatedInput,
      sanitized: sanitizedMessage,
      intent: context.vars?.intent
    },
    CONFIG.contextCaps.interactionHistory
  );
  markArrayDirty(context, "interactionHistory");
  try {
    context.vars.llmTrace = {
      ...(context.vars.llmTrace || {}),
      hallucinated: hallucinatedInput
    };
  } catch (err) {
    handleError(context, err, "trace.hallucinated.write");
  }
  // TTL cleanup
  try {
    applyMemoryTTL(context);
  } catch (err) {
    handleError(context, err, "memory.ttl");
  }
  // Periodic dream injection and decay
  try {
    const lastDreamMsg = context.memory.lastDreamInjectMessageCount || 0;
    const since = Math.max(0, (context.memory.messageCount || 0) - lastDreamMsg);
    if (since >= (decayConfig.dreamInjectEvery ?? CONFIG.decay.dreamEvery)) {
      if (
        (context.rng || Math.random)() < (decayConfig.dreamInjectChance ?? CONFIG.decay.dreamChance)
      ) {
        const dream = await generateDreamSequence(context);
        context.memory.lastDreamInjectMessageCount = context.memory.messageCount;
        try {
          applyDreamEffects(context, dream);
        } catch (err) {
          handleError(context, err, "dream.applyEffects");
        }
      }
    }
  } catch (err) {
    handleError(context, err, "dream.inject.tick");
  }
  if (!(context.flags && context.flags.skipInternalDecay)) {
    const lastTrustMsg = context.memory.lastTrustDecayMessageCount || 0;
    const msgsSinceLastTrust = Math.max(0, (context.memory.messageCount || 0) - lastTrustMsg);
    updateTrustDecay(context, msgsSinceLastTrust);
    const lastCorMsg = context.memory.lastCorruptionDecayMessageCount || 0;
    const msgsSinceLastCor = Math.max(0, (context.memory.messageCount || 0) - lastCorMsg);
    updateCorruptionDecay(context, msgsSinceLastCor);
    Decay.all(context.memory);
    try {
      syncGodsFromMemoryInfluence(context);
    } catch (err) {
      handleError(context, err, "gods.syncInfluence");
    }
  }
}

async function phaseCoreCommandsLegacy(context) {
  try {
    const m = (
      context?.vars?.inputSanitized ||
      sanitizeForIngestion(context.input || context.lastUserMessage || "")
    ).trim();
    // Handle kink commands
    if (handleKinkCommands(context, m)) {
      return "handled";
    }

    // !influences
    if (CMD_REGEX?.influences?.test?.(m)) {
      const influencesSrc = Array.isArray(context?.gods?.history)
        ? context.gods.history
        : context.memory.godInfluences || [];
      const influences =
        influencesSrc
          .slice(-3)
          .map((inf) => {
            const atMsg = inf.appliedAtMessage ?? "?";
            return `• ${inf.name} (${inf.domain}) at message #${atMsg} — _"${inf.effect}"_`; 
          })
          .join("\n") || "No active god influences.";
      await setReply(context, `Active God Influences:\n${influences}`);
      context.flags ??= {};
      context.flags.skipCore = true;
      return "handled";
    }

    // !debug
    if (CMD_REGEX?.debug?.test?.(m)) {
      const clone = getMemorySnapshot(context);
      const redactKeys = ["randomSeed", "apiKey", "llmApiKey", "sessionId", "userId"];
      try {
        redactKeys.forEach((k) => {
          if (Object.prototype.hasOwnProperty.call(clone, k)) {
            clone[k] = "[REDACTED]";
          }
        });
      } catch (err) {
        handleError(undefined, err, "catch.all");
      }
      [
        "echoHistory",
        "interactionHistory",
        "dreamHistory",
        "characterNotes",
        "betrayalJournal",
        "itemsBought"
      ].forEach((k) => {
        if (Array.isArray(clone[k])) {
          clone[k] = clone[k].slice(-10);
        }
      });
      await setReply(
        context,
        `DEBUG SNAPSHOT:\n\`\`\`json\n${JSON.stringify(clone, null, 2)}\n\`\`\`` 
      );
      context.flags ??= {};
      context.flags.skipCore = true;
      return "handled";
    }

    // !seed
    const seedMatch = m.match(/^!seed(?: (?<num>\d+))?.$/i);
    if (seedMatch) {
      const seedStr = (seedMatch && seedMatch.groups && seedMatch.groups.num) || seedMatch[1];
      if (seedStr) {
        const newSeed = parseInt(seedStr, 10);
        context.memory.randomSeed = newSeed;
        context.rng = RNG.seeded(newSeed);
        await setReply(context, `🔁 Seed reset to ${newSeed}`);
      } else {
        await setReply(context, `🔢 Current RNG seed: ${context.memory.randomSeed}`); 
      }
      context.flags ??= {};
      context.flags.skipCore = true;
      return "handled";
    }

    // !history
    const histMatch = m.match(/^!history(?: (?<num>\d+))?.$/i);
    if (histMatch) {
      const numStr = (histMatch && histMatch.groups && histMatch.groups.num) || histMatch[1];
      const limit = Math.min(parseInt(numStr || "5", 10), 20);
      const entries = (context.memory.interactionHistory || []).slice(-limit).map((entry, i) => {
        const ts = new Date(entry.at).toLocaleTimeString();
        return `#${i + 1} [${ts}]\n- Intent: ${entry.intent || "?"}\n- Input: "${entry.input}"\n- Hallucinated: "${entry.hallucinated}"\n- Sanitized: "${entry.sanitized}"\n`; 
      });
      const message = entries.length
        ? `Last ${entries.length} Interactions:\n\n${entries.join("\n")}` 
        : "No interaction history found.";
      await setReply(context, message);
      context.flags ??= {};
      context.flags.skipCore = true;
      return "handled";
    }

    // Dev tools
    if (CMD_REGEX?.debugtrust?.test?.(m)) {
      const trust = context.memory.trustLevel ?? 0;
      const halluc = context.memory.hallucinationTrust ?? 0;
      const tension = context.memory.tension ?? 0;
      const corruption = context.memory.corruption ?? 0;
      const humanity = getHumanityLevel(context);
      const weakness = context.memory.echoChainWeakness ?? 0;
      await setReply(
        context,
        `Trust=${trust} | Hallucination=${halluc} | Tension=${tension} | Corruption=${corruption} | Humanity=${humanity}% | EchoWeakness=${weakness}`
      );
      return "handled";
    }

    if (CMD_REGEX?.debughallucination?.test?.(m)) {
      const s =
        context?.vars?.inputSanitized ||
        sanitizeForIngestion(context.input || context.lastUserMessage || "");
      const sample = applyTieredHallucination(s, context.memory?.hallucinationTrust ?? 0, context);
      await setReply(context, `Hallucinated sample:\n"${sample}"`);
      return "handled";
    }

    if (CMD_REGEX?.testgod?.test?.(m)) {
      const god = await generateRandomGod(context);
      const desc = god?.effects?.effect || god?.effects?.reactionToUser || god?.domain || "unknown";
      await setReply(context, `Summoned influence: ${god.name} (${god.domain}) — "${desc}"`); 
      return "handled";
    }

    return null;
  } catch (err) {
    logDebug(context, `phaseCoreCommandsLegacy error: ${err?.message || err}`, "WARN"); 
    return null;
  }
}

async function phaseCoreEvolutionShop(context) {
  ensureMemory(context);
  try {
    const m = (
      context?.vars?.inputSanitized ||
      sanitizeForIngestion(context.input || context.lastUserMessage || "")
    ).trim();
    if (/\bsell\b/i.test(String(m)) || CMD_REGEX?.shop?.test?.(m)) {
      const offers = listMerchantOffers(context, 5);
      if (offers.length === 0) {
        await setReply(context, "Ur'ga sneers. \"You've bought it all. Now suffer.\"");
        return "handled";
      }
      const offerText = offers
        .map((g) => `• ${g} (-${getHumanityCostForGenre(g)} humanity)`)
        .join("\n");
      await setReply(
        context,
        `Ur'ga hisses. "Pick your poison, meat."\n\n${offerText}\n\nType "!buy <genre>" to purchase.`
      );
      return "handled";
    }

    const buyMatch = m.match(CMD_REGEX?.buy);
    if (buyMatch) {
      const genre = buyMatch[1].toLowerCase();
      const res = purchaseEvolutionItem(context, genre);
      if (res.ok) {
        const line = await generateEvolutionSaleResponse(context, genre, true);
        await setReply(context, line);
      } else {
        const line = await generateEvolutionSaleResponse(context, genre, false, res.reason);
        await setReply(context, line);
      }
      return "handled";
    }

    if (/\bevolve\b/i.test(String(m)) || /\bpower\b/i.test(String(m))) {
      const offers = listMerchantOffers(context, 5);
      const offerText =
        offers.map((g) => `• ${g} (-${getHumanityCostForGenre(g)} humanity)`).join("\n") ||
        "Nothing left. Bleed with what you bought.";
      await setReply(context, `Ur'ga smirks. "Evolution? Buy it, worm."\n${offerText}`);
      return "handled";
    }

    return null;
  } catch (err) {
    logDebug(context, `phaseCoreEvolutionShop error: ${err?.message || err}`, "WARN"); 
    return null;
  }
}

async function phaseCoreNarrativeHooks(context) {
  ensureMemory(context);
  try {
    const s =
      context?.vars?.inputSanitized ||
      sanitizeForIngestion(context.input || context.lastUserMessage || "");
    const m = TextUtils.normalize(s);

    // Rebirth snapshot on fatal event
    try {
      const now = MessageClock.now();
      if (
        (context.stats?.corruption >= 10 || (context.flags && context.flags.hasBetrayedTooMuch)) &&
        !context._deathSnapshot
      ) {
        context._deathSnapshot = {
          playerMemory: Array.isArray(context.playerMemory) ? [...context.playerMemory] : [],
          stats: { ...(context.stats || {}) }, 
          flags: { ...(context.flags || {}) }, 
          checkpointIndex: Math.max(
            0,
            Array.isArray(context.metrics) ? context.metrics.length - 1 : 0
          ),
          timestamp: now
        };
        context.flags = context.flags || {};
        context.flags.readyForRebirth = true;
        await setReply(
          context,
          "🩸 You hear her scream as the world unravels.\nType `!rebirth` if you wish to return."
        );
        return "handled";
      }
    } catch (err) {
      handleError(undefined, err, "catch.all");
    }

    // Echo reaction detection
    if (await detectEchoCompliance(context, s)) {
      const mock = await urgaMocksEcho(context);
      await setReply(context, mock);
      return "handled";
    }

    // Goodbye / open thread
    if (/bye|thanks|done/i.test(m) && (context.rng ? context.rng() : _rng_default()) < 0.5) {
      await setReply(context, await generateOpenThread(context, m));
      return "handled";
    }

    // Confession + redemption
    if (/forgive me|i lied|i want redemption/i.test(m)) {
      const reply = await generateConfessionResponse(context);
      await setReply(context, reply);
      return "handled";
    }

    // Cleanse corruption
    if (/cleanse me|remove corruption/i.test(m)) {
      const line = await echoFailsToCleanse(context);
      await setReply(context, line);
      return "handled";
    }

    // NSFW
    if (CMD_REGEX?.nsfw?.test?.(m)) {
      if ((context.memory.trustLevel ?? 0) >= 3 && (context.memory.corruption ?? 0) >= 2) {
        await setReply(context, await generateNSFWLine(context));
      } else {
        try {
          const prompt = `User requests NSFW but is denied due to low trust (${context.memory?.trustLevel ?? 0}) and corruption (${context.memory?.corruption ?? 0}). Write ONE curt, profane denial in Ur'ga's voice. Keep it short (1 sentence). No exposition. Respond ONLY with the line.`; 
          const denyLine = await generateLine(context, prompt);
          await setReply(context, denyLine);
        } catch (err) {
          logDebug(context, `NSFW deny generation error: ${err.message}`, "ERROR"); 
          await setReply(context, getRandomFallback(context));
        }
      }
      return "handled";
    }

    // Sleep/Dream
    if (/sleep|dream|rest/i.test(m)) {
      const dreamResult = await generateDreamSequence(context);
      try {
        applyDreamEffects(context, dreamResult);
      } catch (err) {
        handleError(context, err, "dream.applyEffects");
      }
      const wakeLine = await generateWakeReaction(context, dreamResult.type);
      await setReply(
        context,
        `🌙 You drift into sleep...\n\n${dreamResult.text}\n\n💀 ${wakeLine}` 
      );
      return "handled";
    }

    // Hard reset
    if (/start over|reset me/i.test(m)) {
      const now = MessageClock.now();
      const preserved = {
        firstSeenTimestamp: context.memory.firstSeenTimestamp || now,
        sessionsStarted: (context.memory.sessionsStarted || 1) + 1,
        nameHistory: (context.memory.characterNotes || []).filter((note) => note.tag === "identity")
      };
      context.memory = {
        ...preserved,
        trustLevel: 0,
        evolutionCount: 0,
        hallucinationTrust: 0,
        echoHistory: [],
        echoInfluence: [],
        dreamHistory: [],
        itemsBought: [],
        corruption: 0,
        evolutionStage: "none",
        flags: {},
        boarKingLore: true
      };
      ensureMemory(context); // Re-initialize
      await setReply(context, 'Ur\'ga snarls. "New worm. Same stench."');
      return "handled";
    }

    // Topic-based dream recall
    const relatedDream = await findDreamRelatedToTopic(context, m);
    if (relatedDream && (context.rng ? context.rng() : _rng_default()) < 0.3) {
      const prompt = [
        'Ur\'ga realizes you\'re talking about a topic from a past dream.',
        'Topic: ' + (relatedDream.metadata?.topics),
        'Dream: ' + (relatedDream.summary),
        'Write a short, cruel line referencing the dream topic.',
        'Use her aggressive tone.'
      ].join('\n');

      const ref = await generateLine(context, prompt);
      await setReply(context, ref);
      return "handled";
    }

    // Suspicion foreshadowing
    if (!context.vars?.impendingReveal) {
      const unrevealed = (context.memory.betrayalJournal || []).filter(
        (entry) => (entry) => entry.delayReveal && !entry.revealed
      );
      if (unrevealed.length > 0 && (context.rng ? context.rng() : _rng_default()) < 0.3) {
        context.vars ??= {};
        context.vars.impendingReveal = true;
        logDebug(context, "Impending reveal foreshadowed.", "DEBUG");
      }
    }

    // Reveal delayed betrayals
    if (context.vars?.impendingReveal) {
      const reveals = checkForSuspicionReveal(context);
      if (reveals.length > 0) {
        const line = await generateSuspicionLine(context);
        delete context.vars.impendingReveal;
        await setReply(context, `Ur'ga's suspicion rises...\n\n${line}`);
        return "handled";
      }
    }

    // Lie detection — spontaneous suspicion
    if ((context.rng ? context.rng() : _rng_default()) < 0.25) {
      const lied = await detectLie(context, s);
      if (lied) {
        const suspicionLine = await generateSuspicionLine(context);
        await setReply(context, `Ur'ga pauses...\n\n${suspicionLine}`);
        return "handled";
      }
    }

    return null;
  } catch (err) {
    logDebug(context, `phaseCoreNarrativeHooks error: ${err?.message || err}`, "WARN"); 
    return null;
  }
}

