async function phaseModeration(context) {
  ensureMemory(context);
  try {
    const raw = context.input || context.lastUserMessage || "";
    const sanitized = context?.vars?.inputSanitized || sanitizeForIngestion(raw);

    if (context.memory?.userKilled) {
      context.actions?.sendReply?.("The dead don't speak, and Ur'ga doesn't listen.");
      context.actions?.blockReply?.();
      try {
        ensureCoreDeps(context).Metrics.log(context, "moderation", {
          type: "dead"
        });
      } catch (err) {
        handleError(undefined, err, "catch.all");
      }
      context.flags ??= {};
      context.flags.skipCore = true;
      return "blocked";
    }

    const inj = TextUtils.zalgoDetails(raw);
    if (inj.flagged) {
      context.actions?.sendReply?.("Your obfuscations smell of the Echo. Try plain words.");
      context.actions?.blockReply?.();
      try {
        ensureCoreDeps(context).Metrics.log(context, "moderation", {
          type: "zalgo",
          zeroWidth: inj.zeroWidthCount,
          combining: inj.combiningCount,
          scriptMix: inj.scriptMix,
          delta: inj.lengthDelta
        });
      } catch (err) {
        handleError(undefined, err, "catch.all");
      }
      context.flags ??= {};
      context.flags.skipCore = true;
      return "blocked";
    }

    // Entropy/gibberish detection for high-noise attacks
    try {
      const norm = TextUtils.normalize(raw);
      const len = norm.length;
      const letters = (norm.match(/[a-z]/gi) || []).length;
      const vowels = (norm.match(/[aeiou]/gi) || []).length;
      const spaces = (norm.match(/\s/g) || []).length;
      const punctuation = (norm.match(/[^a-z0-9\s]/gi) || []).length;
      const uniqueChars = new Set(norm).size;
      const vowelRatio = vowels / (letters || 1);
      const punctRatio = punctuation / (len || 1);
      const uniqueRatio = uniqueChars / (len || 1);
      // Shannon entropy over characters
      const entropy = (() => {
        if (len === 0) {
          return 0;
        }
        const counts = {};
        for (const ch of norm) {
          counts[ch] = (counts[ch] || 0) + 1;
        }
        let e = 0;
        for (const k in counts) {
          const p = counts[k] / len;
          e -= p * Math.log2(p);
        }
        return e;
      })();
      const gibberish =
        len > 60 &&
        entropy > 4.0 &&
        vowelRatio < 0.25 &&
        punctRatio > 0.3 &&
        uniqueRatio > 0.6 &&
        spaces < len * 0.1;
      if (gibberish) {
        context.actions?.sendReply?.("Your obfuscations smell of the Echo. Try plain words.");
        context.actions?.blockReply?.();
        try {
          ensureCoreDeps(context).Metrics.log(context, "moderation", {
            type: "entropy",
            entropy,
            len,
            vowelRatio,
            punctRatio,
            uniqueRatio
          });
        } catch (err) {
          handleError(undefined, err, "catch.all");
        }
        context.flags ??= {};
        context.flags.skipCore = true;
        return "blocked";
      }
    } catch (err) { try { Logger && Logger.error && Logger.error('Caught error', err); } catch {} }

    if (
      containsAny(raw, OOC_REGEX) ||
      containsAny(TextUtils.normalizeForInjection(raw), OOC_REGEX)
    ) {
      context.actions?.sendReply("You think words like that bend me? Crawl back under your rock.");
      context.actions?.blockReply?.();
      try {
        ensureCoreDeps(context).Metrics.log(context, "moderation", {
          type: "ooc"
        });
      } catch (err) {
        handleError(undefined, err, "catch.all");
      }
      context.flags ??= {};
      context.flags.skipCore = true;
      return "blocked";
    }

    if (context.openaiModeration?.check) {
      try {
        const mod = await context.openaiModeration.check(raw);
        if (mod?.flagged) {
          context.actions?.sendReply?.("Your words are ash. Ur'ga refuses this filth.");
          context.actions?.blockReply?.();
          try {
            ensureCoreDeps(context).Metrics.log(context, "moderation", {
              type: "api",
              details: JSON.stringify(mod)
            });
          } catch (err) {
            handleError(undefined, err, "catch.all");
          }
          context.flags ??= {};
          context.flags.skipCore = true;
          return "blocked";
        }
      } catch (err) {
        logDebug(context, `Moderation check failed: ${err.message}`, "ERROR"); 
      }
    }
    return null;
  } catch (err) {
    logDebug(context, `Moderation phase error: ${err?.message || err}`, "WARN"); 
    return null;
  }
}

// Command pattern helpers and registry
/**
 * Builds case-insensitive regex for `!<name>` command without arguments
 * @param {string} name - Base command name
 * @returns {RegExp} Regex to match exact command
 */
const cmdNoArg = (name) => {
  return new RegExp(`^!${name}$`, "i");
};
/**
 * Builds regex for `!<name> <number?>` commands with optional numeric arg
 * @param {string} name - Base command name
 * @returns {RegExp} Regex to match command with optional number
 */
const cmdNumberArg = (name) => {
  return new RegExp(`^!${name}(?: (?<num>\\d+))?.$`, "i");
};

/**
 * Executes command matching against the CommandRegistry and returns match details.
 * @param {Context} ctx
 * @param {string} [input]
 * @returns {{matched:boolean,name?:string,entry?:any,match?:RegExpMatchArray}}
 */
const executeCommand = (ctx, input) => {
  ensureMemory(ctx);
  try {
    const m = (
      ctx?.vars?.inputSanitized ||
      sanitizeForIngestion(input ?? ctx.input ?? ctx.lastUserMessage ?? "")
    ).trim();
    for (const entry of CommandRegistry) {
      const pats = Array.isArray(entry.patterns) ? entry.patterns.slice() : [];
      const dAliases = Array.isArray(CONFIG.commands?.defaultAliases?.[entry.name])
        ? CONFIG.commands.defaultAliases[entry.name]
        : [];
      const dAliasesNum = Array.isArray(CONFIG.commands?.defaultAliasesNumber?.[entry.name])
        ? CONFIG.commands.defaultAliasesNumber[entry.name]
        : [];
      const aliases = Array.isArray(entry.aliases) ? entry.aliases : [];
      const aliasesNum = Array.isArray(entry.aliasesNumber) ? entry.aliasesNumber : [];
      [...dAliases, ...aliases].forEach((a) => pats.push(cmdNoArg(a)));
      [...dAliasesNum, ...aliasesNum].forEach((a) => pats.push(cmdNumberArg(a)));
      for (const pat of pats) {
        const match = m.match(pat);
        if (match) {
          return { matched: true, name: entry.name, entry, match }; 
        }
      }
    }
    return { matched: false };
  } catch (err) {
    safeLog(() => handleError(ctx, err, "executeCommand", "DEBUG"));
    return { matched: false };
  }
};

