/**
 * Execute a rebirth if allowed by flags; sets reply and metrics.
 */
async function executeRebirth(context) {
  ensureMemory(context);
  try {
    context.flags ??= {};
    if (!context.flags.readyForRebirth) {
      await setReply(context, "You cannot rebirth now. Face what comes.");
      context.flags.skipCore = true;
      return "handled";
    }
    const mem = context.memory;
    mem.rebirthCount = toNum(mem.rebirthCount, 0) + 1;
    context.vars ??= {};
    context.vars.rebirthCount = mem.rebirthCount;
    context.flags.rebirthed = true;
    context.flags.readyForRebirth = false;
    context.flags.rebirthPurified = true;
    context.turnLastPurified = context.turn || toNum(mem.messageCount);
    await setReply(context, "🩸 You awaken—threads rewove. The world hushes, briefly.");
    try {
      ensureCoreDeps(context).Metrics.log(context, "rebirth", {
        count: mem.rebirthCount,
        turn: context.turn
      });
    } catch (e) {
      handleError(context, e, "metrics.rebirth");
    }
    context.flags.skipCore = true;
    return "handled";
  } catch (err) {
    safeLog(() => handleError(context, err, "command.rebirth"));
    await setReply(context, "The weave resists. Ur’ga denies your return.");
    context.flags ??= {};
    context.flags.skipCore = true;
    return "handled";
  }
}

// Register core rebirth command
CommandRegistry.push({
  name: "rebirth",
  patterns: [cmdNoArg("rebirth")],
  handler: async (ctx) => await executeRebirth(ctx)
});

