// ---- Monthly Budget (calendar-month fixed window) -------------------------
function __computeMonthKeyUTC(ts) {
  try {
    const d = new Date(Math.max(0, Number(ts || Date.now())));
    const y = d.getUTCFullYear();
    const m = d.getUTCMonth() + 1; // 1..12
    return String(y) + '-' + String(m).padStart(2, '0');
  } catch { return '1970-01'; }
}
function __monthStartUTC(ts) {
  try {
    const d = new Date(Math.max(0, Number(ts || Date.now())));
    return Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), 1);
  } catch { return 0; }
}

export function createFileTenantMonthlyBudgetBackend({ baseDir } = {}) {
  try {
    const tmpBase = String(process?.env?.TMPDIR || process?.env?.TEMP || process?.env?.TMP || '.');
    const budBase = baseDir && String(baseDir).length > 0 ? baseDir : path.join(tmpBase, 'urga_budget_monthly');
    const shortHash = (key) => {
      try { const h = hashPrompt(String(key || '')); return String(h || '').slice(0, 16); } catch { return Buffer.from(String(key || ''), 'utf8').toString('hex').slice(0, 16); }
    };
    const fileFor = (key) => path.join(budBase, `${shortHash(key)}.json`);
    const readCurrent = async (p) => {
      let data;
      try { const raw = await AsyncFS.readFile(p, 'utf8'); data = JSON.parse(String(raw || '{}')); } catch { data = undefined; }
      const now = Date.now();
      const monthKey = __computeMonthKeyUTC(now);
      const start = __monthStartUTC(now);
      if (!data || String(data.monthKey || '') !== String(monthKey)) data = { monthKey, windowStart: start, spentTokens: 0, lastTouch: now };
      else data.lastTouch = now;
      return data;
    };
    return {
      peek: async (key, _lim) => {
        const p = fileFor(key);
        try { await AsyncFS.mkdir(path.dirname(p), { recursive: true }); } catch {}
        const lockPath = `${p}.lock`;
        const release = await __acquireLock__(lockPath, { timeoutMs: 500, staleMs: 60000 });
        try {
          const data = await readCurrent(p);
          const lim = Number(_lim || 0);
          const spent = Number(data?.spentTokens || 0);
          return { monthKey: String(data.monthKey), windowStart: Number(data.windowStart), spentTokens: spent, limitTokens: lim, ok: !lim || (spent < lim) };
        } finally { try { await release(); } catch {} }
      },
      incr: async (key, tokens, _lim) => {
        const p = fileFor(key);
        try { await AsyncFS.mkdir(path.dirname(p), { recursive: true }); } catch {}
        const lockPath = `${p}.lock`;
        const release = await __acquireLock__(lockPath, { timeoutMs: 1000, staleMs: 60000 });
        try {
          const data = await readCurrent(p);
          data.spentTokens = Math.max(0, Number(data.spentTokens || 0)) + Math.max(0, Number(tokens || 0));
          try { await AsyncFS.writeFileAtomic(p, JSON.stringify(data), 'utf8', { lock: false, renameStrategy: 'direct' }); } catch (e) { throw e; }
          const lim = Number(_lim || 0);
          return { monthKey: String(data.monthKey), windowStart: Number(data.windowStart), spentTokens: Number(data.spentTokens), limitTokens: lim };
        } finally { try { await release(); } catch {} }
      },
      wipe: async (key) => {
        try {
          const p = fileFor(key);
          try { await fsp.rm(p, { force: true }); } catch {}
          try { await fsp.rm(`${p}.lock`, { force: true }); } catch {}
          return { ok: true };
        } catch {}
        return { ok: false };
      }
    };
  } catch {}
  return {
    peek: async () => ({ monthKey: '1970-01', windowStart: 0, spentTokens: 0, limitTokens: 0, ok: true }),
    incr: async (_k, _t, _l) => ({ monthKey: __computeMonthKeyUTC(Date.now()), windowStart: __monthStartUTC(Date.now()), spentTokens: 0, limitTokens: Number(_l || 0) })
  };
}

