// ---- Rolling Window Budget (sliding via minute buckets) -------------------
export function createFileTenantRollingBudgetBackend({ baseDir, bucketMs = 60000 } = {}) {
  try {
    const tmpBase = String(process?.env?.TMPDIR || process?.env?.TEMP || process?.env?.TMP || '.');
    const budBase = baseDir && String(baseDir).length > 0 ? baseDir : path.join(tmpBase, 'urga_budget_rolling');
    const shortHash = (key) => {
      try { const h = hashPrompt(String(key || '')); return String(h || '').slice(0, 16); } catch { return Buffer.from(String(key || ''), 'utf8').toString('hex').slice(0, 16); }
    };
    const fileFor = (key) => path.join(budBase, `${shortHash(key)}.json`);
    const readCurrent = async (p) => {
      let data;
      try { const raw = await AsyncFS.readFile(p, 'utf8'); data = JSON.parse(String(raw || '{}')); } catch { data = undefined; }
      const now = Date.now();
      if (!data || typeof data !== 'object') data = { bucketMs: Math.max(1000, Number(bucketMs || 60000)), buckets: [], lastTouch: now };
      data.bucketMs = Math.max(1000, Number(data.bucketMs || bucketMs || 60000));
      data.lastTouch = now;
      return data;
    };
    const prune = (data, windowMs) => {
      const now = Date.now();
      const cutoff = now - Math.max(0, Number(windowMs || 0));
      data.buckets = Array.isArray(data.buckets) ? data.buckets.filter((b) => Number(b.t || 0) >= cutoff) : [];
    };
    const sumBuckets = (data) => {
      let s = 0; for (const b of Array.isArray(data.buckets) ? data.buckets : []) s += Math.max(0, Number(b.v || 0)); return s;
    };
    const currentBucketStart = (data) => {
      const now = Date.now();
      const bm = Math.max(1000, Number(data.bucketMs || 60000));
      return Math.floor(now / bm) * bm;
    };
    return {
      peek: async (key, windowMs, limitTokens) => {
        const p = fileFor(key);
        try { await AsyncFS.mkdir(path.dirname(p), { recursive: true }); } catch {}
        const lockPath = `${p}.lock`;
        const release = await __acquireLock__(lockPath, { timeoutMs: 500, staleMs: 60000 });
        try {
          const data = await readCurrent(p);
          prune(data, windowMs);
          const spent = sumBuckets(data);
          const lim = Number(limitTokens || 0);
          return { windowStart: Date.now() - Math.max(0, Number(windowMs || 0)), spentTokens: spent, limitTokens: lim, bucketMs: Number(data.bucketMs || 60000), ok: !lim || (spent < lim) };
        } finally { try { await release(); } catch {} }
      },
      incr: async (key, tokens, windowMs, limitTokens) => {
        const p = fileFor(key);
        try { await AsyncFS.mkdir(path.dirname(p), { recursive: true }); } catch {}
        const lockPath = `${p}.lock`;
        const release = await __acquireLock__(lockPath, { timeoutMs: 1000, staleMs: 60000 });
        try {
          const data = await readCurrent(p);
          prune(data, windowMs);
          const start = currentBucketStart(data);
          let bucket = Array.isArray(data.buckets) ? data.buckets.find((b) => Number(b.t || 0) === start) : null;
          if (!bucket) { bucket = { t: start, v: 0 }; data.buckets.push(bucket); }
          bucket.v = Math.max(0, Number(bucket.v || 0)) + Math.max(0, Number(tokens || 0));
          try { await AsyncFS.writeFileAtomic(p, JSON.stringify(data), 'utf8', { lock: false, renameStrategy: 'direct' }); } catch (e) { throw e; }
          const lim = Number(limitTokens || 0);
          const spent = sumBuckets(data);
          return { windowStart: Date.now() - Math.max(0, Number(windowMs || 0)), spentTokens: Number(spent), limitTokens: lim, bucketMs: Number(data.bucketMs || 60000) };
        } finally { try { await release(); } catch {} }
      },
      wipe: async (key) => {
        try {
          const p = fileFor(key);
          try { await fsp.rm(p, { force: true }); } catch {}
          try { await fsp.rm(`${p}.lock`, { force: true }); } catch {}
          return { ok: true };
        } catch {}
        return { ok: false };
      }
    };
  } catch {}
  return {
    peek: async (_k, w, l) => ({ windowStart: Date.now() - Math.max(0, Number(w || 0)), spentTokens: 0, limitTokens: Number(l || 0), bucketMs: Math.max(1000, Number(bucketMs || 60000)), ok: true }),
    incr: async (_k, _t, w, l) => ({ windowStart: Date.now() - Math.max(0, Number(w || 0)), spentTokens: 0, limitTokens: Number(l || 0), bucketMs: Math.max(1000, Number(bucketMs || 60000)) })
  };
}

