// ===== Message-count rate limiting ==========================================
class _MessageRateLimiter {
  constructor({ max = 10, windowCounts = 20 } = {}) {
    this.max = Math.max(1, max|0);
    this.window = Math.max(1, windowCounts|0);
    this.events = [];
  }
  allow() {
    const now = MessageClock.now();
    // Inclusive window: retain events at the boundary so limits apply more strictly
    this.events = this.events.filter(t => t >= now - this.window);
    if (this.events.length >= this.max) return false;
    // Record at next tick to reflect outbound progression
    this.events.push(now + 1);
    return true;
  }
}

class _TokenBucket {
  constructor({ capacity = 10, refillPerCount = 1 } = {}) {
    this.capacity = Math.max(1, capacity|0);
    this.refill = Math.max(0, refillPerCount|0);
    this.tokens = this.capacity;
    this.last = MessageClock.now();
  }
  take(n = 1) {
    const now = MessageClock.now();
    const delta = now - this.last;
    this.last = now;
    this.tokens = Math.min(this.capacity, this.tokens + delta * this.refill);
    if (this.tokens < n) return false;
    this.tokens -= n;
    return true;
  }
}
