// ===== Bot runtime (message-count first) ====================================
/**
 * createBotRuntime sets up a message-count aware wrapper around your bot logic.
 * @param {Object} options
 * @param {(input:any,ctx:any)=>Promise<any>} options.respond - your bot's core async function
 * @param {Object} [options.limits] - rate limit options
 * @param {Object} [options.hooks] - { beforeEach?, afterEach?, onError? }
 */
function _createBotRuntime({ respond, limits = { max: 20, windowCounts: 40 }, hooks = {} }) {
  if (typeof respond !== 'function') throw new Error('respond must be a function');
  const limiter = new _MessageRateLimiter(limits);
  return _wrapChatHandler(async (input, ctx = {}) => {
    try {
      if (hooks.beforeEach) await hooks.beforeEach(input, ctx);
      const __respondStartMs = Date.now();
      const out = await respond(input, ctx);
      try {
        const { Metrics, Alerting } = ensureCoreDeps(ctx || {});
        const ms = Date.now() - __respondStartMs;
        Metrics.histogramMs(ctx || {}, "respond_ms", ms, { ok: true });
        Alerting?.maybeAlertLatency?.(ctx || {}, 'respond_ms', ms);
      } catch (_) {}
      if (hooks.afterEach) await hooks.afterEach(out, ctx);
      // Enforce rate limit AFTER successful respond to align with tests
      if (!limiter.allow()) {
        // Record rate limit block metric when available
        try {
          const { Metrics } = ensureCoreDeps(ctx || {});
          Metrics.count(ctx || {}, "rate_limited_total", 1, { scope: "message" });
        } catch (_) {}
        const err = new Error('rate_limited');
        if (hooks.onError) await hooks.onError(err, input, ctx);
        return { error: 'rate_limited', at: MessageClock.now() };
      }
      return out;
    } catch (err) {
      if (hooks.onError) await hooks.onError(err, input, ctx);
      try {
        const { Metrics } = ensureCoreDeps(ctx || {});
        Metrics.count(ctx || {}, "runtime_error_total", 1, { type: err?.code || err?.name || 'Error' });
      } catch (_) {}
      _logAt('error', 'respond failed', err && err.stack || err);
      return { error: 'internal_error', at: MessageClock.now() };
    }
  });
}
